// BEGIN js/runtime/shell-navigation-drawer.js

const MOBILE_ARTISTS_DRAWER_MEDIA_QUERY = '(max-width: 900px)';

function isArtistsDrawerElement(value) {
  return Boolean(
    value
    && typeof value === 'object'
    && value.classList
    && typeof value.setAttribute === 'function'
  );
}

function getArtistsDrawerElements() {
  return {
    button: document.getElementById('artists-drawer-button'),
    rail: document.getElementById('shell-navigation-rail'),
    backdrop: document.getElementById('shell-navigation-rail-backdrop'),
  };
}

function getArtistsDrawerNavigationContentKind(view = state.view || {}) {
  return String(view?.shell_layout?.slots?.navigation_rail?.content_kind || 'artists_sidebar')
    .trim()
    .toLowerCase();
}

function canUseArtistsDrawerForCurrentView() {
  return getArtistsDrawerNavigationContentKind() === 'artists_sidebar';
}

function isArtistsDrawerMobileViewport() {
  if (typeof window?.matchMedia === 'function') {
    return Boolean(window.matchMedia(MOBILE_ARTISTS_DRAWER_MEDIA_QUERY).matches);
  }
  return Number(window?.innerWidth || 0) <= 900;
}

function syncArtistsDrawerVisibility() {
  const { button, rail, backdrop } = getArtistsDrawerElements();
  const isMobile = isArtistsDrawerMobileViewport();
  const supportsArtistsDrawer = canUseArtistsDrawerForCurrentView();
  const isDrawerVisible = Boolean(isMobile && supportsArtistsDrawer);
  if (!isDrawerVisible) {
    state.ui.artistsDrawerOpen = false;
  }
  const isOpen = Boolean(isDrawerVisible && state.ui.artistsDrawerOpen);

  if (isArtistsDrawerElement(button)) {
    button.hidden = !isDrawerVisible;
    button.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
  }

  if (isArtistsDrawerElement(rail)) {
    rail.classList.toggle('is-mobile-drawer', isDrawerVisible);
    rail.classList.toggle('is-mobile-drawer-open', isOpen);
    rail.setAttribute('aria-hidden', isDrawerVisible && !isOpen ? 'true' : 'false');
  }

  if (isArtistsDrawerElement(backdrop)) {
    backdrop.hidden = !isOpen;
  }

  document.body?.classList?.toggle('artists-drawer-open', isOpen);
}

function openArtistsDrawer() {
  if (!isArtistsDrawerMobileViewport() || !canUseArtistsDrawerForCurrentView()) {
    syncArtistsDrawerVisibility();
    return false;
  }
  state.ui.artistsDrawerOpen = true;
  syncArtistsDrawerVisibility();
  return true;
}

function closeArtistsDrawer(options = {}) {
  const wasOpen = Boolean(state.ui.artistsDrawerOpen);
  state.ui.artistsDrawerOpen = false;
  syncArtistsDrawerVisibility();
  if (wasOpen && options.restoreFocus !== false) {
    document.getElementById('artists-drawer-button')?.focus?.();
  }
  return wasOpen;
}

function toggleArtistsDrawer() {
  if (state.ui.artistsDrawerOpen) {
    return closeArtistsDrawer();
  }
  return openArtistsDrawer();
}

function handleArtistsDrawerClick(event) {
  const toggleButton = event.target.closest('[data-toggle-artists-drawer="1"]');
  if (toggleButton) {
    event.preventDefault();
    toggleArtistsDrawer();
    return true;
  }

  const closeTarget = event.target.closest('[data-close-artists-drawer="1"], #shell-navigation-rail-backdrop');
  if (closeTarget) {
    event.preventDefault();
    closeArtistsDrawer();
    return true;
  }

  if (!state.ui.artistsDrawerOpen || !isArtistsDrawerMobileViewport()) {
    return false;
  }

  const { button, rail } = getArtistsDrawerElements();
  if (rail?.contains?.(event.target) || button?.contains?.(event.target)) {
    return false;
  }

  closeArtistsDrawer({ restoreFocus: false });
  return false;
}

function handleArtistsDrawerKeydown(event) {
  if (event.key !== 'Escape' || !state.ui.artistsDrawerOpen || !isArtistsDrawerMobileViewport()) {
    return false;
  }
  event.preventDefault();
  closeArtistsDrawer();
  return true;
}

// END js/runtime/shell-navigation-drawer.js

// BEGIN js/runtime/account-menu.js

// Shared disclosure menu: action ownership remains with the rendered links/forms.
function attachAccountMenu(component) {
  const trigger = component.querySelector('[data-account-menu-trigger]');
  const menu = component.querySelector('[data-account-menu]');
  if (!trigger || !menu) return;
  const disabled = (item) => item.disabled || item.getAttribute('aria-disabled') === 'true';
  const enabledItems = () => Array.from(menu.querySelectorAll('[role="menuitem"]')).filter((item) => !disabled(item));
  const close = (restoreFocus = false) => {
    menu.hidden = true;
    trigger.setAttribute('aria-expanded', 'false');
    if (restoreFocus) trigger.focus();
  };
  const open = (last = false) => {
    menu.hidden = false;
    trigger.setAttribute('aria-expanded', 'true');
    const items = enabledItems();
    (last ? items[items.length - 1] : items[0])?.focus();
  };
  const reject = (event) => {
    event.preventDefault();
    event.stopImmediatePropagation();
  };
  trigger.addEventListener('click', (event) => {
    event.preventDefault();
    if (menu.hidden) open();
    else close(true);
  });
  menu.addEventListener('click', (event) => {
    const item = event.target?.closest?.('[role="menuitem"]');
    if (!item || !menu.contains(item)) return;
    if (disabled(item)) {
      reject(event);
      return;
    }
    // Restore the opener before Settings captures focus for its modal.
    close(true);
  }, true);
  component.addEventListener('keydown', (event) => {
    const item = event.target?.closest?.('[role="menuitem"]');
    if (item && disabled(item) && ['Enter', ' ', 'Spacebar'].includes(event.key)) {
      reject(event);
      return;
    }
    if (event.altKey || event.ctrlKey || event.metaKey) return;
    if (event.target === trigger && ['ArrowDown', 'ArrowUp'].includes(event.key)) {
      event.preventDefault();
      open(event.key === 'ArrowUp');
      return;
    }
    if (menu.hidden) return;
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      close(true);
      return;
    }
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
    event.preventDefault();
    const items = enabledItems();
    const current = items.indexOf(document.activeElement);
    const next = event.key === 'Home' ? 0
      : event.key === 'End' ? items.length - 1
        : (current + (event.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
    items[next]?.focus();
  });
  document.addEventListener('click', (event) => {
    if (!component.contains(event.target)) close();
  });
  component.addEventListener('focusout', (event) => {
    if (!component.contains(event.relatedTarget)) close();
  });
}

// END js/runtime/account-menu.js

// BEGIN js/runtime/bootstrap-refocus-helpers.js

const VIEWPORT_REFOCUS_SUPPRESSION_GRACE_MS = 400;
const VIEWPORT_REFOCUS_HOVER_UNLOCK_COUNT = 2;
const VIEWPORT_REFOCUS_EXEMPT_SELECTOR = '.global-player, #track-modal, #utility-modal, #cover-lookup-modal, #cover-lookup-delete-confirm-modal, #repair-confirm-modal, #repair-progress-overlay, #tag-editor-modal, #tag-edit-confirm-modal, #loop-delete-confirm-modal, #image-lightbox, #non-album-modal, #version-picker-modal, #cover-lookup-drawer, #gallery-options-menu, #album-card-context-menu, #status-context-menu, #track-modal-version-context-menu, #recent-search-popover';
const VIEWPORT_REFOCUS_INTENT_SELECTOR = '.album-card, [data-album-key], [data-track-path], [data-version-context-key], .artist-link, .album-title-button, .button, .icon-button, .play-track-button, .gallery-options-menu-item, .related-chip, a, button, input, select, textarea, label';
const COVER_LOOKUP_REFOCUS_GUARDED_SELECTOR = '[data-select-local-cover], [data-select-pasted-cover], [data-select-remote-cover]';

function getViewportRefocusEventTarget(event) {
  return event?.target instanceof Element ? event.target : null;
}

function isViewportRefocusExemptTarget(target) {
  const coverLookupSelection = target?.closest(COVER_LOOKUP_REFOCUS_GUARDED_SELECTOR);
  if (coverLookupSelection?.closest('#cover-lookup-modal')) return false;
  return Boolean(target?.closest(VIEWPORT_REFOCUS_EXEMPT_SELECTOR));
}

function resetViewportRefocusIntentTracking() {
  state.ui.refocusHoverIntentCount = 0;
  state.ui.refocusLastHoverIntentKey = '';
}

function clearViewportRefocusSuppression() {
  state.ui.suppressNextViewportClick = false;
  state.ui.suppressClickSequenceUntil = 0;
  resetViewportRefocusIntentTracking();
}

function armViewportRefocusSuppression() {
  state.ui.suppressNextViewportClick = true;
  state.ui.suppressClickSequenceUntil = 0;
  resetViewportRefocusIntentTracking();
}

function isViewportRefocusSuppressionActive(now = Date.now()) {
  return Boolean(
    state.ui.suppressNextViewportClick
    || now <= Number(state.ui.suppressClickSequenceUntil || 0)
  );
}

function resolveViewportRefocusIntentKey(target) {
  const candidate = target?.closest?.(VIEWPORT_REFOCUS_INTENT_SELECTOR);
  if (!(candidate instanceof Element)) return '';
  if (candidate.dataset.albumKey) return `album:${candidate.dataset.albumKey}`;
  if (candidate.dataset.trackPath) return `track:${candidate.dataset.trackPath}`;
  if (candidate.dataset.versionContextKey) return `version:${candidate.dataset.versionContextKey}`;
  if (candidate.id) return `id:${candidate.id}`;
  if (candidate.className) return `class:${candidate.className}`;
  return candidate.tagName ? `tag:${candidate.tagName.toLowerCase()}` : '';
}

function noteViewportRefocusHoverIntent(event) {
  if (!state.ui.suppressNextViewportClick) return false;
  const target = getViewportRefocusEventTarget(event);
  if (!target || isViewportRefocusExemptTarget(target)) return false;
  const intentKey = resolveViewportRefocusIntentKey(target);
  if (!intentKey || intentKey === state.ui.refocusLastHoverIntentKey) return false;
  state.ui.refocusLastHoverIntentKey = intentKey;
  state.ui.refocusHoverIntentCount = Number(state.ui.refocusHoverIntentCount || 0) + 1;
  if (state.ui.refocusHoverIntentCount < VIEWPORT_REFOCUS_HOVER_UNLOCK_COUNT) {
    return false;
  }
  clearViewportRefocusSuppression();
  return true;
}

function noteViewportRefocusWheelIntent(event) {
  if (!state.ui.suppressNextViewportClick) return false;
  const target = getViewportRefocusEventTarget(event);
  if (!target || isViewportRefocusExemptTarget(target)) return false;
  clearViewportRefocusSuppression();
  return true;
}

function handleViewportRefocusVisibilityChange() {
  if (document.visibilityState === 'visible') {
    clearViewportRefocusSuppression();
    state.ui.pendingAppRefocusSuppression = false;
    return;
  }
  if (document.visibilityState === 'hidden') {
    state.ui.pendingAppRefocusSuppression = false;
  }
}

function suppressRefocusViewportInteraction(event) {
  const now = Date.now();
  if (!isViewportRefocusSuppressionActive(now)) {
    return false;
  }
  state.ui.suppressNextViewportClick = false;
  state.ui.suppressClickSequenceUntil = now + VIEWPORT_REFOCUS_SUPPRESSION_GRACE_MS;
  resetViewportRefocusIntentTracking();
  event.preventDefault();
  event.stopPropagation();
  event.stopImmediatePropagation();
  return true;
}

function suppressRefocusViewportClick(event) {
  const now = Date.now();
  if (now > Number(state.ui.suppressClickSequenceUntil || 0)) {
    return false;
  }
  event.preventDefault();
  event.stopPropagation();
  event.stopImmediatePropagation();
  state.ui.suppressClickSequenceUntil = 0;
  return true;
}

// END js/runtime/bootstrap-refocus-helpers.js

// BEGIN js/runtime/client-preferences-helpers.js

const PLAYER_APPEARANCE_STORAGE_KEY = 'albumhaven.playerAppearance.v1';
const COMBINE_SIMILAR_ARTISTS_STORAGE_KEY = 'albumhaven.combineSimilarArtists.v1';
const GALLERY_DISPLAY_PREFERENCES_STORAGE_KEY = 'albumhaven.galleryDisplayPreferences.v1';
const GALLERY_PLAYBACK_PREFERENCES_STORAGE_KEY = 'albumhaven.galleryPlaybackPreferences.v1';
const ALBUM_OPEN_MODE_STORAGE_KEY = 'albumhaven.albumOpenMode.v1';
const SHELL_LAYOUT_PREFERENCES_STORAGE_KEY = 'albumhaven.shellLayoutPreferences.v1';

function loadPersistedJsonObject(key) {
  try {
    const raw = getLocalStorageItem(key);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (_error) {
    return {};
  }
}

function getDefaultPlayerAppearance() {
  return {
    seekbarMode: 'default',
    waveformFillColor: '#dadde2',
    waveformEdgeColor: '#494950',
  };
}

function normalizeClientGalleryDisplayMode(value) {
  const normalized = String(value || '').trim().toLowerCase();
  return normalized === 'covers' || normalized === 'list' ? normalized : 'cards';
}

function normalizeClientGalleryScalePercent(value) {
  const normalized = Number(value);
  return Number.isInteger(normalized) && normalized >= 80 && normalized <= 140
    ? normalized
    : 100;
}

function getDefaultGalleryDisplayPreferences() {
  return {
    defaultGalleryDisplayMode: 'cards',
    defaultGalleryScalePercent: 100,
  };
}

function normalizeGalleryPlaybackEndBehavior(value, fallback = 'continue') {
  const normalizedFallback = String(fallback || '').trim().toLowerCase() === 'stop'
    ? 'stop'
    : 'continue';
  const normalized = String(value ?? normalizedFallback).trim().toLowerCase();
  return normalized === 'stop' || normalized === 'continue'
    ? normalized
    : normalizedFallback;
}

function getDefaultGalleryPlaybackPreferences() {
  return {
    albumTopsEndBehavior: 'continue',
    artistPagesEndBehavior: 'stop',
  };
}

function getDefaultShellLayoutPreferences() {
  return {
    contextualPaneWidthPx: 320,
    infoDrawerWidthPx: 360,
  };
}

function getDefaultAlbumOpenMode() {
  return 'modal';
}

function normalizeGalleryDisplayPreferences(input = {}) {
  const source = input && typeof input === 'object' && !Array.isArray(input) ? input : {};
  const defaults = getDefaultGalleryDisplayPreferences();
  return {
    defaultGalleryDisplayMode: normalizeClientGalleryDisplayMode(source.defaultGalleryDisplayMode),
    defaultGalleryScalePercent: normalizeClientGalleryScalePercent(
      source.defaultGalleryScalePercent ?? defaults.defaultGalleryScalePercent,
    ),
  };
}

function normalizeGalleryPlaybackPreferences(input = {}) {
  const source = input && typeof input === 'object' && !Array.isArray(input) ? input : {};
  const defaults = getDefaultGalleryPlaybackPreferences();
  return {
    albumTopsEndBehavior: normalizeGalleryPlaybackEndBehavior(
      source.albumTopsEndBehavior,
      defaults.albumTopsEndBehavior,
    ),
    artistPagesEndBehavior: normalizeGalleryPlaybackEndBehavior(
      source.artistPagesEndBehavior,
      defaults.artistPagesEndBehavior,
    ),
  };
}

function normalizeShellLayoutWidth(value, fallback) {
  const normalized = Number(value);
  return Number.isInteger(normalized) && normalized >= 240 && normalized <= 520
    ? normalized
    : fallback;
}

function normalizeShellLayoutPreferences(input = {}) {
  const source = input && typeof input === 'object' && !Array.isArray(input) ? input : {};
  const defaults = getDefaultShellLayoutPreferences();
  return {
    contextualPaneWidthPx: normalizeShellLayoutWidth(
      source.contextualPaneWidthPx,
      defaults.contextualPaneWidthPx,
    ),
    infoDrawerWidthPx: normalizeShellLayoutWidth(
      source.infoDrawerWidthPx,
      defaults.infoDrawerWidthPx,
    ),
  };
}

function normalizeAlbumOpenMode(value) {
  const normalized = String(value || getDefaultAlbumOpenMode()).trim().toLowerCase();
  return normalized === 'page' ? 'page' : 'modal';
}

function normalizePlayerAppearance(input = {}) {
  const defaults = getDefaultPlayerAppearance();
  const mode = String(input.seekbarMode || defaults.seekbarMode);
  const fill = /^#[0-9a-f]{6}$/i.test(String(input.waveformFillColor || ''))
    ? String(input.waveformFillColor)
    : defaults.waveformFillColor;
  const edge = /^#[0-9a-f]{6}$/i.test(String(input.waveformEdgeColor || ''))
    ? String(input.waveformEdgeColor)
    : defaults.waveformEdgeColor;
  return {
    seekbarMode: mode === 'waveform' ? 'waveform' : 'default',
    waveformFillColor: fill,
    waveformEdgeColor: edge,
  };
}

function loadCombineSimilarArtistsPreferences() {
  return loadPersistedJsonObject(COMBINE_SIMILAR_ARTISTS_STORAGE_KEY);
}

function loadGalleryDisplayPreferences() {
  return normalizeGalleryDisplayPreferences(
    loadPersistedJsonObject(GALLERY_DISPLAY_PREFERENCES_STORAGE_KEY),
  );
}

function loadGalleryPlaybackPreferences() {
  return normalizeGalleryPlaybackPreferences(
    loadPersistedJsonObject(GALLERY_PLAYBACK_PREFERENCES_STORAGE_KEY),
  );
}

function loadShellLayoutPreferences() {
  return normalizeShellLayoutPreferences(
    loadPersistedJsonObject(SHELL_LAYOUT_PREFERENCES_STORAGE_KEY),
  );
}

function loadAlbumOpenMode() {
  return normalizeAlbumOpenMode(getLocalStorageItem(ALBUM_OPEN_MODE_STORAGE_KEY));
}

function persistCombineSimilarArtistsPreferences() {
  setLocalStorageItem(
    COMBINE_SIMILAR_ARTISTS_STORAGE_KEY,
    JSON.stringify(state.gallery.combineSimilarArtistsByArtist || {}),
  );
}

function persistGalleryDisplayPreferences() {
  state.gallery.displayPreferences = normalizeGalleryDisplayPreferences(
    state.gallery.displayPreferences,
  );
  setLocalStorageItem(
    GALLERY_DISPLAY_PREFERENCES_STORAGE_KEY,
    JSON.stringify(state.gallery.displayPreferences),
  );
}

function persistGalleryPlaybackPreferences() {
  state.gallery.playbackPreferences = normalizeGalleryPlaybackPreferences(
    state.gallery.playbackPreferences,
  );
  setLocalStorageItem(
    GALLERY_PLAYBACK_PREFERENCES_STORAGE_KEY,
    JSON.stringify(state.gallery.playbackPreferences),
  );
}

function persistShellLayoutPreferences() {
  if (!state.ui || typeof state.ui !== 'object') {
    state.ui = {};
  }
  state.ui.shellLayoutPreferences = normalizeShellLayoutPreferences(
    state.ui.shellLayoutPreferences,
  );
  setLocalStorageItem(
    SHELL_LAYOUT_PREFERENCES_STORAGE_KEY,
    JSON.stringify(state.ui.shellLayoutPreferences),
  );
}

function persistAlbumOpenMode() {
  state.gallery.albumOpenMode = normalizeAlbumOpenMode(state.gallery?.albumOpenMode);
  setLocalStorageItem(ALBUM_OPEN_MODE_STORAGE_KEY, state.gallery.albumOpenMode);
}

function galleryPlaybackPreferenceFieldForKind(kind) {
  const normalizedKind = String(kind || '').trim().toLowerCase();
  if (normalizedKind === 'album_top') return 'albumTopsEndBehavior';
  if (normalizedKind === 'artist_page') return 'artistPagesEndBehavior';
  return '';
}

function resolveGalleryPlaybackEndBehavior(playbackContext, preferences = null) {
  const source = playbackContext && typeof playbackContext === 'object' && !Array.isArray(playbackContext)
    ? playbackContext
    : {};
  const preferenceField = galleryPlaybackPreferenceFieldForKind(source.kind);
  if (!preferenceField) {
    return normalizeGalleryPlaybackEndBehavior(source.end_behavior, 'continue');
  }
  const sourcePreferences = preferences && typeof preferences === 'object' && !Array.isArray(preferences)
    ? preferences
    : state.gallery?.playbackPreferences;
  const normalizedPreferences = normalizeGalleryPlaybackPreferences(sourcePreferences);
  return normalizedPreferences[preferenceField];
}

function setGalleryPlaybackEndBehavior(kind, endBehavior) {
  const preferenceField = galleryPlaybackPreferenceFieldForKind(kind);
  if (!preferenceField) return null;
  state.gallery.playbackPreferences = normalizeGalleryPlaybackPreferences({
    ...(state.gallery.playbackPreferences || {}),
    [preferenceField]: endBehavior,
  });
  persistGalleryPlaybackPreferences();
  return state.gallery.playbackPreferences[preferenceField];
}

function restorePlayerAppearance() {
  const raw = getLocalStorageItem(PLAYER_APPEARANCE_STORAGE_KEY);
  if (!raw) {
    state.player.appearance = normalizePlayerAppearance(state.player.appearance);
    return state.player.appearance;
  }
  try {
    state.player.appearance = normalizePlayerAppearance(JSON.parse(raw));
  } catch (_error) {
    state.player.appearance = normalizePlayerAppearance(state.player.appearance);
  }
  return state.player.appearance;
}

function persistPlayerAppearance() {
  setLocalStorageItem(PLAYER_APPEARANCE_STORAGE_KEY, JSON.stringify(state.player.appearance));
}

function restorePersistedClientPreferences() {
  state.gallery.combineSimilarArtistsByArtist = loadCombineSimilarArtistsPreferences();
  state.gallery.displayPreferences = loadGalleryDisplayPreferences();
  state.gallery.playbackPreferences = loadGalleryPlaybackPreferences();
  state.gallery.albumOpenMode = loadAlbumOpenMode();
  if (!state.ui || typeof state.ui !== 'object') {
    state.ui = {};
  }
  state.ui.shellLayoutPreferences = loadShellLayoutPreferences();
  restorePlayerAppearance();
}

restorePersistedClientPreferences();

// END js/runtime/client-preferences-helpers.js

// BEGIN js/runtime/gallery-display-preference-helpers.js

function normalizeArtistPreferenceKey(value) {
  return String(value || '').trim();
}

function getSavedGalleryDisplayPreferences() {
  const defaults = typeof getDefaultGalleryDisplayPreferences === 'function'
    ? getDefaultGalleryDisplayPreferences()
    : {
      defaultGalleryDisplayMode: 'cards',
      defaultGalleryScalePercent: 100,
    };
  const source = state.gallery?.displayPreferences;
  if (typeof normalizeGalleryDisplayPreferences === 'function') {
    return normalizeGalleryDisplayPreferences({
      ...defaults,
      ...(source && typeof source === 'object' && !Array.isArray(source) ? source : {}),
    });
  }
  const displayMode = String(source?.defaultGalleryDisplayMode || defaults.defaultGalleryDisplayMode || '')
    .trim()
    .toLowerCase();
  const normalizedScale = Number(source?.defaultGalleryScalePercent ?? defaults.defaultGalleryScalePercent);
  return {
    defaultGalleryDisplayMode: displayMode === 'covers' || displayMode === 'list' ? displayMode : 'cards',
    defaultGalleryScalePercent: Number.isInteger(normalizedScale) && normalizedScale >= 80 && normalizedScale <= 140
      ? normalizedScale
      : 100,
  };
}

function normalizeResolvedGalleryDisplayMode(value) {
  const normalized = String(value || '').trim().toLowerCase();
  return normalized === 'covers' || normalized === 'list' ? normalized : 'cards';
}

function normalizeResolvedGalleryScalePercent(value) {
  const normalized = Number(value);
  return Number.isInteger(normalized) && normalized >= 80 && normalized <= 140 ? normalized : 100;
}

function resolveGalleryDisplayPreferenceViewState(view, options = {}) {
  const source = view && typeof view === 'object' ? view : {};
  const savedPreferences = getSavedGalleryDisplayPreferences();
  return {
    ...source,
    gallery_display_mode: Boolean(options.hasExplicitGalleryDisplayOverride)
      ? normalizeResolvedGalleryDisplayMode(source.gallery_display_mode)
      : savedPreferences.defaultGalleryDisplayMode,
    gallery_scale_percent: Boolean(options.hasExplicitGalleryScaleOverride)
      ? normalizeResolvedGalleryScalePercent(source.gallery_scale_percent)
      : savedPreferences.defaultGalleryScalePercent,
  };
}

function persistCurrentGalleryDisplayPreferences(view = null) {
  const source = view && typeof view === 'object' ? view : state.view;
  const nextPreferences = typeof normalizeGalleryDisplayPreferences === 'function'
    ? normalizeGalleryDisplayPreferences({
      defaultGalleryDisplayMode: source?.gallery_display_mode,
      defaultGalleryScalePercent: source?.gallery_scale_percent,
    })
    : {
      defaultGalleryDisplayMode: normalizeResolvedGalleryDisplayMode(source?.gallery_display_mode),
      defaultGalleryScalePercent: normalizeResolvedGalleryScalePercent(source?.gallery_scale_percent),
    };
  state.gallery.displayPreferences = nextPreferences;
  if (typeof persistGalleryDisplayPreferences === 'function') {
    persistGalleryDisplayPreferences();
  }
  return nextPreferences;
}

function looksLikeCombinedArtistName(value) {
  const normalized = String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
  return /\s(?:&|and)\s/.test(normalized);
}

function combinedArtistSignature(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/\band\b/g, ' ')
    .replace(/&/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ')
    .split(' ')
    .filter(Boolean)
    .join(' ');
}

function getCurrentGalleryPreferenceArtist() {
  const selectedArtist = normalizeArtistPreferenceKey(state.view?.selected_artist);
  if (selectedArtist) return selectedArtist;
  const primaryGroups = Array.isArray(state.view?.primary_artist_groups) ? state.view.primary_artist_groups : [];
  const familyGroups = Array.isArray(state.view?.family_artist_groups) ? state.view.family_artist_groups : [];
  const fallbackGroups = !primaryGroups.length && !familyGroups.length && Array.isArray(state.view?.artist_groups)
    ? state.view.artist_groups
    : [];
  const visibleArtists = [...new Set(
    [...primaryGroups, ...familyGroups, ...fallbackGroups]
      .map((group) => normalizeArtistPreferenceKey(group?.artist))
      .filter(Boolean),
  )];
  return visibleArtists.length === 1 ? visibleArtists[0] : '';
}

function getCombineSimilarArtistsPreference(artist) {
  const key = normalizeArtistPreferenceKey(artist);
  if (!key) return false;
  return Boolean(state.gallery.combineSimilarArtistsByArtist?.[key]);
}

function setCombineSimilarArtistsPreference(artist, enabled) {
  const key = normalizeArtistPreferenceKey(artist);
  if (!key) return;
  state.gallery.combineSimilarArtistsByArtist = {
    ...(state.gallery.combineSimilarArtistsByArtist || {}),
    [key]: Boolean(enabled),
  };
  persistCombineSimilarArtistsPreferences();
}

function escapeGalleryPreferenceRegex(value) {
  return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function isSelectedArtistAliasFamilyName(selectedArtist, candidateArtist) {
  const canonicalSelectedArtist = normalizeArtistPreferenceKey(selectedArtist);
  const canonicalCandidateArtist = normalizeArtistPreferenceKey(candidateArtist);
  if (!canonicalSelectedArtist || !canonicalCandidateArtist || canonicalSelectedArtist === canonicalCandidateArtist) {
    return false;
  }
  const matcher = new RegExp(`^${escapeGalleryPreferenceRegex(canonicalSelectedArtist)}\\s+(?:&|and|with|feat\\.?|featuring)\\s+`, 'i');
  return matcher.test(canonicalCandidateArtist);
}

function compareDisplayGroupAlbums(left, right) {
  const leftYear = Number(left?.year ?? 9999);
  const rightYear = Number(right?.year ?? 9999);
  if (leftYear !== rightYear) return leftYear - rightYear;
  const leftName = String(left?.name || '');
  const rightName = String(right?.name || '');
  const nameCompare = leftName.localeCompare(rightName, undefined, { sensitivity: 'base' });
  if (nameCompare) return nameCompare;
  return String(left?.edition || '').localeCompare(String(right?.edition || ''), undefined, { sensitivity: 'base' });
}

function buildMergedDisplayArtistName(primaryGroup, groupsToMerge) {
  const baseName = String(primaryGroup?.artist_display || primaryGroup?.artist || '').trim();
  const mergedNames = [
    baseName,
    ...groupsToMerge.map((group) => String(group?.artist_display || group?.artist || '').trim()),
  ].filter(Boolean);
  const uniqueNames = [...new Set(mergedNames)];
  return uniqueNames.join(' / ');
}

function getDisplayAlbumDeduplicationKey(album) {
  const stableKey = String(
    album?.key
    || album?.album_ref
    || album?.request_key
    || album?.identity_key
    || '',
  ).trim();
  if (stableKey) return `key:${stableKey}`;
  return JSON.stringify([
    normalizeArtistPreferenceKey(album?.album_artist || album?.artist).toLocaleLowerCase(),
    String(album?.name || album?.album || '').trim().toLocaleLowerCase(),
    String(album?.year ?? '').trim(),
    String(album?.edition || '').trim().toLocaleLowerCase(),
  ]);
}

function removeFamilyAlbumDuplicatesFromPrimaryGroups(primaryGroups, familyGroups) {
  const familyAlbumKeysByArtist = new Map();
  familyGroups.forEach((group) => {
    const familyArtist = normalizeArtistPreferenceKey(group?.artist || group?.artist_display);
    if (!familyArtist) return;
    const albumKeys = familyAlbumKeysByArtist.get(familyArtist) || new Set();
    (Array.isArray(group?.albums) ? group.albums : []).forEach((album) => {
      albumKeys.add(getDisplayAlbumDeduplicationKey(album));
    });
    familyAlbumKeysByArtist.set(familyArtist, albumKeys);
  });

  return primaryGroups.map((group) => {
    const primaryArtist = normalizeArtistPreferenceKey(group?.artist || group?.artist_display);
    const albums = Array.isArray(group?.albums) ? group.albums : [];
    const uniqueAlbums = albums.filter((album) => {
      const albumArtist = normalizeArtistPreferenceKey(album?.album_artist || primaryArtist);
      if (!albumArtist || albumArtist === primaryArtist) return true;
      return !familyAlbumKeysByArtist.get(albumArtist)?.has(getDisplayAlbumDeduplicationKey(album));
    });
    return uniqueAlbums.length === albums.length ? group : { ...group, albums: uniqueAlbums };
  });
}

function buildSelectedArtistDisplayGroups(primaryGroups, familyGroups, selectedArtist) {
  const canonicalSelectedArtist = normalizeArtistPreferenceKey(selectedArtist);
  const normalizedFamilyGroups = Array.isArray(familyGroups) ? familyGroups : [];
  const normalizedPrimaryGroups = removeFamilyAlbumDuplicatesFromPrimaryGroups(
    Array.isArray(primaryGroups) ? primaryGroups : [],
    normalizedFamilyGroups,
  );
  if (
    !canonicalSelectedArtist
    || !normalizedPrimaryGroups.length
    || !normalizedFamilyGroups.length
    || !getCombineSimilarArtistsPreference(canonicalSelectedArtist)
  ) {
    return {
      primaryGroups: normalizedPrimaryGroups,
      familyGroups: normalizedFamilyGroups,
    };
  }

  const matchingPrimaryIndex = normalizedPrimaryGroups.findIndex((group) => (
    normalizeArtistPreferenceKey(group?.artist || group?.artist_display) === canonicalSelectedArtist
  ));
  if (matchingPrimaryIndex === -1) {
    return {
      primaryGroups: normalizedPrimaryGroups,
      familyGroups: normalizedFamilyGroups,
    };
  }

  const groupsToMerge = normalizedFamilyGroups.filter((group) => (
    isSelectedArtistAliasFamilyName(canonicalSelectedArtist, group?.artist || group?.artist_display)
  ));
  if (!groupsToMerge.length) {
    return {
      primaryGroups: normalizedPrimaryGroups,
      familyGroups: normalizedFamilyGroups,
    };
  }

  const mergedAlbumKeys = new Set();
  const mergedAlbums = [
    ...(Array.isArray(normalizedPrimaryGroups[matchingPrimaryIndex]?.albums) ? normalizedPrimaryGroups[matchingPrimaryIndex].albums : []),
    ...groupsToMerge.flatMap((group) => (Array.isArray(group?.albums) ? group.albums : [])),
  ].filter((album) => {
    const key = normalizeArtistPreferenceKey(album?.key || '');
    if (!key) return true;
    if (mergedAlbumKeys.has(key)) return false;
    mergedAlbumKeys.add(key);
    return true;
  }).sort(compareDisplayGroupAlbums);

  const nextPrimaryGroups = normalizedPrimaryGroups.map((group, index) => (
    index === matchingPrimaryIndex
      ? {
        ...group,
        artist_display: buildMergedDisplayArtistName(group, groupsToMerge),
        display_artist_key: `${canonicalSelectedArtist}::merged::${groupsToMerge.map((candidateGroup) => (
          normalizeArtistPreferenceKey(candidateGroup?.artist || candidateGroup?.artist_display)
        )).join('|')}`,
        albums: mergedAlbums,
      }
      : group
  ));
  const familyGroupsToRemove = new Set(groupsToMerge.map((group) => normalizeArtistPreferenceKey(group?.artist || group?.artist_display)));
  const nextFamilyGroups = normalizedFamilyGroups.filter((group) => (
    !familyGroupsToRemove.has(normalizeArtistPreferenceKey(group?.artist || group?.artist_display))
  ));

  return {
    primaryGroups: nextPrimaryGroups,
    familyGroups: nextFamilyGroups,
  };
}

function deduplicateRepeatedCompositeArtistDisplay(value) {
  const rawValue = String(value || '').trim();
  const members = rawValue.split(/\s+\/\s+/).map((member) => member.trim()).filter(Boolean);
  if (members.length < 2) return rawValue;
  const seen = new Set();
  const uniqueMembers = [];
  let foundDuplicate = false;
  members.forEach((member) => {
    const key = member.replace(/\s+/g, ' ').toLocaleLowerCase();
    if (seen.has(key)) {
      foundDuplicate = true;
      return;
    }
    seen.add(key);
    uniqueMembers.push(member);
  });
  return foundDuplicate ? uniqueMembers.join(' / ') : rawValue;
}

function splitArtistGroupForDisplay(group) {
  const canonicalArtist = normalizeArtistPreferenceKey(group?.artist);
  const albums = Array.isArray(group?.albums) ? group.albums : [];
  const defaultGroup = {
    ...group,
    artist_display: deduplicateRepeatedCompositeArtistDisplay(
      group?.artist_display || group?.artist,
    ),
    display_artist_key: canonicalArtist || String(group?.artist_display || ''),
  };
  if (!canonicalArtist || !albums.length || getCombineSimilarArtistsPreference(canonicalArtist)) {
    return [defaultGroup];
  }

  const distinctArtists = [...new Set(
    albums.map((album) => normalizeArtistPreferenceKey(album?.album_artist || canonicalArtist)).filter(Boolean),
  )];
  const distinctSignatures = [...new Set(distinctArtists.map((artist) => combinedArtistSignature(artist)).filter(Boolean))];
  if (
    distinctArtists.length < 2
    || distinctSignatures.length <= 1
    || !distinctArtists.some((artist) => looksLikeCombinedArtistName(artist))
  ) {
    return [defaultGroup];
  }

  const buckets = new Map();
  albums.forEach((album) => {
    const albumArtist = normalizeArtistPreferenceKey(album?.album_artist || canonicalArtist) || canonicalArtist;
    if (!buckets.has(albumArtist)) buckets.set(albumArtist, []);
    buckets.get(albumArtist).push(album);
  });

  const orderedArtists = [...buckets.keys()].sort((left, right) => {
    if (left === canonicalArtist) return -1;
    if (right === canonicalArtist) return 1;
    return left.localeCompare(right, undefined, { sensitivity: 'base' });
  });

  return orderedArtists.map((artistName) => ({
    ...group,
    artist: artistName,
    artist_display: deduplicateRepeatedCompositeArtistDisplay(artistName),
    albums: buckets.get(artistName) || [],
    display_artist_key: `${canonicalArtist}::${artistName}`,
  }));
}

function buildDisplayGroups(groups) {
  return (Array.isArray(groups) ? groups : []).flatMap((group) => splitArtistGroupForDisplay(group));
}

// END js/runtime/gallery-display-preference-helpers.js

// BEGIN js/runtime/playback-ownership-helpers.js

const PLAYBACK_OWNERSHIP_STORAGE_KEY = 'albumhaven.playbackOwnership.v1';
const PLAYBACK_OWNERSHIP_CHANNEL_NAME = 'albumhaven.playbackOwnership.v1';
const PLAYBACK_OWNERSHIP_LEASE_MS = 15000;
const PLAYBACK_OWNERSHIP_HEARTBEAT_MS = 5000;

function getPlaybackOwnershipState() {
  if (!state?.player) {
    return {
      tabId: '',
      lockStatus: 'unlocked',
      blockedReason: '',
      mirroredTrack: null,
      activeClaim: null,
      channel: null,
      heartbeatTimer: 0,
      initialized: false,
    };
  }
  if (!state.player.ownership || typeof state.player.ownership !== 'object') {
    state.player.ownership = {
      tabId: '',
      lockStatus: 'unlocked',
      blockedReason: '',
      mirroredTrack: null,
      activeClaim: null,
      channel: null,
      heartbeatTimer: 0,
      initialized: false,
    };
  }
  return state.player.ownership;
}

function normalizePlaybackOwnershipTrack(track) {
  if (!track || typeof track !== 'object') return null;
  const normalizedPath = String(track.path || '').trim();
  const normalizedSrc = String(track.src || '').trim();
  if (!normalizedPath && !normalizedSrc) return null;
  return {
    src: normalizedSrc,
    path: normalizedPath,
    title: String(track.title || '').trim(),
    artist: String(track.artist || '').trim(),
    album: String(track.album || '').trim(),
    coverPath: String(track.coverPath || '').trim(),
    trackNumber: String(track.trackNumber || '').trim(),
  };
}

function createPlaybackOwnershipTabId() {
  if (window?.crypto?.randomUUID) {
    return String(window.crypto.randomUUID());
  }
  return `tab-${Date.now()}-${Math.random().toString(16).slice(2, 10)}`;
}

function getPlaybackOwnershipTabId() {
  const ownership = getPlaybackOwnershipState();
  if (!ownership.tabId) {
    ownership.tabId = createPlaybackOwnershipTabId();
  }
  return ownership.tabId;
}

function parsePlaybackOwnershipRecord(raw) {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return null;
    return {
      tab_id: String(parsed.tab_id || '').trim(),
      status: String(parsed.status || '').trim().toLowerCase(),
      reason: String(parsed.reason || '').trim(),
      updated_at_ms: Number(parsed.updated_at_ms || 0) || 0,
      expires_at_ms: Number(parsed.expires_at_ms || 0) || 0,
      track: normalizePlaybackOwnershipTrack(parsed.track),
    };
  } catch (_error) {
    return null;
  }
}

function readPlaybackOwnershipRecord() {
  return parsePlaybackOwnershipRecord(getLocalStorageItem(PLAYBACK_OWNERSHIP_STORAGE_KEY));
}

function isPlaybackOwnershipRecordActive(record) {
  return Boolean(
    record
    && record.tab_id
    && record.status === 'playing'
    && Number(record.expires_at_ms || 0) > Date.now()
  );
}

function buildPlaybackOwnershipRecord(track, status = 'playing', reason = '') {
  const normalizedTrack = normalizePlaybackOwnershipTrack(track);
  const now = Date.now();
  const normalizedStatus = String(status || '').trim().toLowerCase() || 'stopped';
  return {
    tab_id: getPlaybackOwnershipTabId(),
    status: normalizedStatus,
    reason: String(reason || '').trim(),
    updated_at_ms: now,
    expires_at_ms: normalizedStatus === 'playing' ? now + PLAYBACK_OWNERSHIP_LEASE_MS : now,
    track: normalizedTrack,
  };
}

function announcePlaybackOwnership(record) {
  if (!record) return;
  setLocalStorageItem(PLAYBACK_OWNERSHIP_STORAGE_KEY, JSON.stringify(record));
  const ownership = getPlaybackOwnershipState();
  if (ownership.channel && typeof ownership.channel.postMessage === 'function') {
    ownership.channel.postMessage(record);
  }
}

function stopPlaybackOwnershipHeartbeat() {
  const ownership = getPlaybackOwnershipState();
  if (!ownership.heartbeatTimer) return;
  clearInterval(ownership.heartbeatTimer);
  ownership.heartbeatTimer = 0;
}

function refreshPlaybackOwnershipClaim(track = null) {
  const ownership = getPlaybackOwnershipState();
  const activeClaim = ownership.activeClaim;
  if (!activeClaim) return false;
  const nextTrack = normalizePlaybackOwnershipTrack(track)
    || normalizePlaybackOwnershipTrack(state?.player?.current)
    || activeClaim.track;
  const nextRecord = buildPlaybackOwnershipRecord(nextTrack, 'playing', 'active_playback');
  ownership.activeClaim = nextRecord;
  ownership.lockStatus = 'unlocked';
  ownership.blockedReason = '';
  ownership.mirroredTrack = null;
  announcePlaybackOwnership(nextRecord);
  return true;
}

function startPlaybackOwnershipHeartbeat() {
  const ownership = getPlaybackOwnershipState();
  if (ownership.heartbeatTimer || typeof setInterval !== 'function') return;
  ownership.heartbeatTimer = setInterval(() => {
    const playback = typeof getPlayerPlaybackSnapshot === 'function'
      ? getPlayerPlaybackSnapshot()
      : { paused: true, ended: false };
    if (playback.paused || playback.ended) return;
    refreshPlaybackOwnershipClaim();
  }, PLAYBACK_OWNERSHIP_HEARTBEAT_MS);
}

function clearBlockedPlaybackState() {
  const ownership = getPlaybackOwnershipState();
  ownership.lockStatus = 'unlocked';
  ownership.blockedReason = '';
  ownership.mirroredTrack = null;
}

function syncMirroredPlaybackState(record, options = {}) {
  const ownership = getPlaybackOwnershipState();
  const wasLockedByAnotherTab = ownership.lockStatus === 'locked';
  const isActive = isPlaybackOwnershipRecordActive(record);
  const sameTab = isActive && record.tab_id === getPlaybackOwnershipTabId();
  if (sameTab) {
    ownership.activeClaim = record;
    clearBlockedPlaybackState();
    startPlaybackOwnershipHeartbeat();
    return;
  }
  ownership.activeClaim = null;
  stopPlaybackOwnershipHeartbeat();
  if (isActive) {
    ownership.lockStatus = 'locked';
    ownership.blockedReason = 'playing_in_another_tab';
    ownership.mirroredTrack = normalizePlaybackOwnershipTrack(record.track);
    if (options.pauseLocalPlayback !== false && !wasLockedByAnotherTab) {
      if (typeof stopStreamingPlayback === 'function') {
        try {
          Promise.resolve(stopStreamingPlayback('ownership-takeover')).catch((error) => {
            console.warn('[AlbumHaven][Playback] Failed to stop streaming after ownership takeover.', error);
          });
        } catch (error) {
          console.warn('[AlbumHaven][Playback] Failed to stop streaming after ownership takeover.', error);
        }
      }
    }
  } else {
    clearBlockedPlaybackState();
  }
  if (typeof updatePlayerUi === 'function') {
    updatePlayerUi();
  }
}

function notifyBlockedPlaybackStart() {
  if (typeof showToast === 'function') {
    showToast('Playback is active in another tab.', 'error', 2800);
  }
}

function claimPlaybackOwnership(track, options = {}) {
  const activeRecord = readPlaybackOwnershipRecord();
  if (isPlaybackOwnershipRecordActive(activeRecord) && activeRecord.tab_id !== getPlaybackOwnershipTabId()) {
    syncMirroredPlaybackState(activeRecord);
    if (options.showBlockedToast !== false) {
      notifyBlockedPlaybackStart();
    }
    return false;
  }
  const nextRecord = buildPlaybackOwnershipRecord(
    track,
    'playing',
    String(options.reason || 'active_playback'),
  );
  const ownership = getPlaybackOwnershipState();
  ownership.activeClaim = nextRecord;
  clearBlockedPlaybackState();
  announcePlaybackOwnership(nextRecord);
  startPlaybackOwnershipHeartbeat();
  if (typeof updatePlayerUi === 'function') {
    updatePlayerUi();
  }
  return true;
}

function releasePlaybackOwnership(status = 'paused', track = null) {
  const ownership = getPlaybackOwnershipState();
  const activeRecord = ownership.activeClaim || readPlaybackOwnershipRecord();
  if (!activeRecord || activeRecord.tab_id !== getPlaybackOwnershipTabId()) {
    ownership.activeClaim = null;
    stopPlaybackOwnershipHeartbeat();
    return false;
  }
  ownership.activeClaim = null;
  stopPlaybackOwnershipHeartbeat();
  const nextRecord = buildPlaybackOwnershipRecord(
    track || state?.player?.current,
    status,
    status === 'paused' ? 'playback_paused' : 'playback_stopped',
  );
  announcePlaybackOwnership(nextRecord);
  clearBlockedPlaybackState();
  if (typeof updatePlayerUi === 'function') {
    updatePlayerUi();
  }
  return true;
}

function canRestoreActivePlayback(parsedState) {
  return claimPlaybackOwnership(parsedState?.track, {
    reason: 'restore_request',
    showBlockedToast: false,
  });
}

function canStartPlaybackInThisTab(track) {
  return claimPlaybackOwnership(track, {
    reason: 'manual_start',
    showBlockedToast: true,
  });
}

function isActivePlaybackOwner() {
  const activeRecord = readPlaybackOwnershipRecord();
  return Boolean(
    isPlaybackOwnershipRecordActive(activeRecord)
    && activeRecord.tab_id === getPlaybackOwnershipTabId()
  );
}

function canEmitPlaybackSessionSideEffects() {
  const activeRecord = readPlaybackOwnershipRecord();
  if (!isPlaybackOwnershipRecordActive(activeRecord)) return true;
  return activeRecord.tab_id === getPlaybackOwnershipTabId();
}

function isPlaybackLockedByAnotherTab() {
  const ownership = getPlaybackOwnershipState();
  return ownership.lockStatus === 'locked';
}

function getMirroredPlaybackTrack() {
  return normalizePlaybackOwnershipTrack(getPlaybackOwnershipState().mirroredTrack);
}

function handlePlaybackOwnershipEvent(record) {
  syncMirroredPlaybackState(record);
}

function initPlaybackOwnershipCoordinator() {
  const ownership = getPlaybackOwnershipState();
  if (ownership.initialized) return;
  ownership.initialized = true;
  getPlaybackOwnershipTabId();
  if (typeof window?.addEventListener === 'function') {
    window.addEventListener('storage', (event) => {
      if (event.key !== PLAYBACK_OWNERSHIP_STORAGE_KEY) return;
      handlePlaybackOwnershipEvent(parsePlaybackOwnershipRecord(event.newValue));
    });
  }
  if (typeof BroadcastChannel === 'function') {
    ownership.channel = new BroadcastChannel(PLAYBACK_OWNERSHIP_CHANNEL_NAME);
    ownership.channel.addEventListener('message', (event) => {
      handlePlaybackOwnershipEvent(parsePlaybackOwnershipRecord(JSON.stringify(event.data || null)));
    });
  }
  syncMirroredPlaybackState(readPlaybackOwnershipRecord(), { pauseLocalPlayback: false });
}

// END js/runtime/playback-ownership-helpers.js

