function invalidatePendingTrackModalLoad() {
  state.ui.pendingTrackModalLoadAlbumKey = '';
  state.ui.pendingTrackModalLoadToken = Number(state.ui.pendingTrackModalLoadToken || 0) + 1;
  return state.ui.pendingTrackModalLoadToken;
}

const trackModalAlbumDetailsLoads = new Map();
const trackModalSpeculativeAlbumDetailsLoadControllers = new Map();
const trackModalHydratedAlbumDetails = new Map();
const trackModalHydratedAlbumDetailsLru = new Map();
const TRACK_MODAL_HYDRATED_ALBUM_DETAILS_LIMIT = 10;
const TRACK_MODAL_SPECULATIVE_PREWARM_LIMIT = 2;
let trackModalActiveSpeculativePrewarms = 0;
const trackModalSpeculativePrewarmControllers = new Set();
const trackModalCoverLoadSuspensionTokens = new Set();

function albumRequiresHydration(album) {
  if (!album || typeof album !== 'object') return false;
  if (album.preview_only === true) return true;
  const tracks = Array.isArray(album.tracks) ? album.tracks : [];
  const declaredTrackCounts = [album.track_count_preview, album.track_count]
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value) && value > 0);
  return declaredTrackCounts.length > 0 && !declaredTrackCounts.includes(tracks.length);
}

function renderTrackModalLoadingState(album) {
  const els = getTrackModalElements();
  if (!els.overlay || !album) return;
  const headerParts = [album.album_artist || '', album.name || 'Album', album.year || ''].filter(Boolean);
  els.title.textContent = headerParts.join(' - ');
  els.subtitle.textContent = 'Loading album details...';
  if (els.folder) {
    els.folder.dataset.album = '';
    els.folder.dataset.albumKey = String(getAlbumRequestKey(album) || getAlbumIdentity(album) || album?.key || '');
  }
  if (els.editTags) {
    els.editTags.dataset.album = '';
    els.editTags.dataset.albumKey = String(getAlbumRequestKey(album) || getAlbumIdentity(album) || album?.key || '');
  }
  els.cover.innerHTML = `
    <div class="track-modal-cover-shell">
      <div class="cover-placeholder">Loading cover art...</div>
    </div>
  `;
  if (els.duplicateWarning) {
    els.duplicateWarning.hidden = true;
    els.duplicateWarning.innerHTML = '';
  }
  if (els.duplicateTabs) {
    els.duplicateTabs.hidden = true;
    els.duplicateTabs.innerHTML = '';
  }
  if (els.tabs) {
    els.tabs.hidden = true;
    els.tabs.innerHTML = '';
  }
  els.list.innerHTML = '<li class="track-modal-loading-row">Loading album details...</li>';
  if (els.footer) {
    els.footer.hidden = true;
    els.footer.textContent = '';
  }
}

function clearTrackModalRenderedState() {
  const els = getTrackModalElements();
  if (!els.overlay) return;
  if (els.title) {
    els.title.textContent = '';
  }
  if (els.subtitle) {
    els.subtitle.textContent = '';
  }
  if (els.cover) {
    els.cover.innerHTML = '';
  }
  if (els.duplicateWarning) {
    els.duplicateWarning.hidden = true;
    els.duplicateWarning.innerHTML = '';
  }
  if (els.duplicateTabs) {
    els.duplicateTabs.hidden = true;
    els.duplicateTabs.innerHTML = '';
  }
  if (els.list) {
    els.list.innerHTML = '';
  }
  if (els.footer) {
    els.footer.hidden = true;
    els.footer.textContent = '';
  }
  if (els.tabs) {
    els.tabs.hidden = true;
    els.tabs.innerHTML = '';
  }
  if (els.folder?.dataset) {
    els.folder.dataset.album = '';
    els.folder.dataset.albumKey = '';
  }
  if (els.editTags?.dataset) {
    els.editTags.dataset.album = '';
    els.editTags.dataset.albumKey = '';
  }
}

function openTrackModalShell(album) {
  const els = getTrackModalElements();
  if (!els.overlay || !album) return;
  state.modalReleases = [album];
  state.modalReleaseIndex = 0;
  hideVersionContextMenu();
  renderTrackModalLoadingState(album);
  els.overlay.hidden = false;
  document.body.classList.add('modal-open');
}

function suspendGalleryCoverLoadsForTrackModal() {
  if (
    typeof virtualGrid !== 'undefined'
    && virtualGrid
    && typeof virtualGrid.suspendSelectedArtistCoverLoadsForUserAction === 'function'
  ) {
    const token = virtualGrid.suspendSelectedArtistCoverLoadsForUserAction();
    if (token) trackModalCoverLoadSuspensionTokens.add(token);
    return token;
  }
  return 0;
}

function resumeGalleryCoverLoadsAfterTrackModalAction(token = 0) {
  const normalizedToken = Number(token);
  if (!normalizedToken || !trackModalCoverLoadSuspensionTokens.delete(normalizedToken)) return false;
  if (
    typeof virtualGrid !== 'undefined'
    && virtualGrid
    && typeof virtualGrid.resumeSelectedArtistCoverLoadsAfterUserAction === 'function'
  ) {
    return virtualGrid.resumeSelectedArtistCoverLoadsAfterUserAction(normalizedToken);
  }
  return false;
}

function resumeAllGalleryCoverLoadsAfterTrackModalActions() {
  Array.from(trackModalCoverLoadSuspensionTokens).forEach((token) => {
    resumeGalleryCoverLoadsAfterTrackModalAction(token);
  });
}

function getTrackModalAlbumVersionKey(album) {
  if (!album) return '';
  const normalize = (value) => String(value ?? '').trim().toLocaleLowerCase();
  return JSON.stringify([
    normalize(getAlbumRequestKey(album) || getAlbumIdentity(album)),
    normalize(album.album_artist || album.artist),
    normalize(album.name || album.album),
    normalize(album.year),
    normalize(album.edition),
  ]);
}

function cacheHydratedTrackModalAlbum(albumKey, album, options = {}) {
  if (!album) return;
  const requestedKey = String(albumKey || '').trim();
  const resolvedAlbum = attachGalleryPlaybackContextToAlbum(album);
  const liveAliases = getTrackModalAlbumKeyAliases(requestedKey, resolvedAlbum);
  const aliases = Array.from(new Set([
    ...liveAliases,
    ...Array.from(options.aliases || [], (alias) => String(alias || '').trim()),
  ].filter(Boolean)));
  const trustedAliases = new Set(
    Array.from(options.aliases || [], (alias) => String(alias || '').trim()).filter(Boolean),
  );
  const replacedAlbums = new Set(
    aliases.map((alias) => trackModalHydratedAlbumDetails.get(alias)).filter(Boolean),
  );
  const previewAlbumsByAlias = new Map();
  aliases.forEach((alias) => {
    const indexedAlbum = state?.gallery?.albumIndex instanceof Map
      ? state.gallery.albumIndex.get(alias)
      : null;
    if (albumRequiresHydration(indexedAlbum)) previewAlbumsByAlias.set(alias, indexedAlbum);
  });
  replacedAlbums.forEach((replacedAlbum) => {
    const replacedEntry = trackModalHydratedAlbumDetailsLru.get(replacedAlbum);
    replacedEntry?.previewAlbumsByAlias?.forEach((previewAlbum, alias) => {
      if (!previewAlbumsByAlias.has(alias)) previewAlbumsByAlias.set(alias, previewAlbum);
    });
  });
  aliases.forEach((alias) => {
    trackModalHydratedAlbumDetails.set(alias, resolvedAlbum);
  });
  liveAliases.forEach((alias) => {
    if (state?.gallery?.albumIndex instanceof Map) {
      state.gallery.albumIndex.set(alias, resolvedAlbum);
    }
  });
  replacedAlbums.forEach((replacedAlbum) => {
    if (replacedAlbum === resolvedAlbum) return;
    const remainsCached = Array.from(trackModalHydratedAlbumDetails.values())
      .some((cachedAlbum) => cachedAlbum === replacedAlbum);
    if (!remainsCached) trackModalHydratedAlbumDetailsLru.delete(replacedAlbum);
  });
  trackModalHydratedAlbumDetailsLru.delete(resolvedAlbum);
  trackModalHydratedAlbumDetailsLru.set(
    resolvedAlbum,
    { aliases, previewAlbumsByAlias, trustedAliases },
  );
  while (trackModalHydratedAlbumDetailsLru.size > TRACK_MODAL_HYDRATED_ALBUM_DETAILS_LIMIT) {
    const oldestAlbum = trackModalHydratedAlbumDetailsLru.keys().next().value;
    const oldestEntry = trackModalHydratedAlbumDetailsLru.get(oldestAlbum);
    trackModalHydratedAlbumDetailsLru.delete(oldestAlbum);
    trackModalHydratedAlbumDetails.forEach((cachedAlbum, alias) => {
      if (cachedAlbum === oldestAlbum) trackModalHydratedAlbumDetails.delete(alias);
    });
    if (state?.gallery?.albumIndex instanceof Map) {
      (oldestEntry?.aliases || []).forEach((alias) => {
        if (state.gallery.albumIndex.get(alias) !== oldestAlbum) return;
        const previewAlbum = oldestEntry.previewAlbumsByAlias.get(alias);
        if (previewAlbum) {
          state.gallery.albumIndex.set(alias, previewAlbum);
        } else {
          state.gallery.albumIndex.delete(alias);
        }
      });
    }
  }
}

function invalidateHydratedTrackModalAlbumDetails(albums) {
  const candidates = Array.isArray(albums) ? albums.filter(Boolean) : [];
  if (!candidates.length) return 0;
  const targetAliases = new Set();
  candidates.forEach((album) => {
    getTrackModalAlbumKeyAliases(getAlbumRequestKey(album), album).forEach((alias) => {
      targetAliases.add(alias);
    });
  });
  const invalidatedAlbums = new Set(
    Array.from(targetAliases, (alias) => trackModalHydratedAlbumDetails.get(alias))
      .filter(Boolean),
  );
  invalidatedAlbums.forEach((cachedAlbum) => {
    const cachedEntry = trackModalHydratedAlbumDetailsLru.get(cachedAlbum);
    trackModalHydratedAlbumDetails.forEach((mappedAlbum, alias) => {
      if (mappedAlbum === cachedAlbum) trackModalHydratedAlbumDetails.delete(alias);
    });
    if (state?.gallery?.albumIndex instanceof Map) {
      (cachedEntry?.aliases || []).forEach((alias) => {
        if (state.gallery.albumIndex.get(alias) !== cachedAlbum) return;
        const previewAlbum = cachedEntry.previewAlbumsByAlias.get(alias);
        if (previewAlbum) state.gallery.albumIndex.set(alias, previewAlbum);
        else state.gallery.albumIndex.delete(alias);
      });
    }
    trackModalHydratedAlbumDetailsLru.delete(cachedAlbum);
  });
  return invalidatedAlbums.size;
}

function getTrackModalAlbumKeyAliases(albumKey, album = null) {
  const normalizedAlbumKey = String(albumKey || '').trim();
  const indexedAlbum = album || getIndexedAlbum(normalizedAlbumKey);
  return Array.from(new Set([
    normalizedAlbumKey,
    String(getAlbumRequestKey(indexedAlbum) || '').trim(),
    String(getAlbumIdentity(indexedAlbum) || '').trim(),
    getTrackModalAlbumVersionKey(indexedAlbum),
  ].filter(Boolean)));
}

function trackModalAlbumsShareLogicalRelease(leftAlbum, rightAlbum) {
  if (!leftAlbum || !rightAlbum) return false;
  const normalize = (value) => String(value ?? '').trim().toLocaleLowerCase();
  return normalize(leftAlbum.album_artist || leftAlbum.artist)
      === normalize(rightAlbum.album_artist || rightAlbum.artist)
    && normalize(leftAlbum.name || leftAlbum.album)
      === normalize(rightAlbum.name || rightAlbum.album)
    && normalize(leftAlbum.year) === normalize(rightAlbum.year)
    && normalize(leftAlbum.edition) === normalize(rightAlbum.edition);
}

function trackModalAlbumsHaveCompatibleMembership(indexedAlbum, cachedAlbum) {
  if (!indexedAlbum || !cachedAlbum) return true;
  const cachedTracks = Array.isArray(cachedAlbum.tracks) ? cachedAlbum.tracks : [];
  if (albumRequiresHydration(indexedAlbum)) {
    const declaredTrackCounts = [indexedAlbum.track_count_preview, indexedAlbum.track_count]
      .map((value) => Number(value))
      .filter((value) => Number.isFinite(value) && value >= 0);
    return !declaredTrackCounts.length || declaredTrackCounts.includes(cachedTracks.length);
  }
  if (!Array.isArray(indexedAlbum.tracks)) return true;
  const trackPaths = (tracks) => new Set(
    tracks.map((track) => String(track?.path || '').trim()).filter(Boolean),
  );
  const indexedPaths = trackPaths(indexedAlbum.tracks);
  const cachedPaths = trackPaths(cachedTracks);
  return indexedPaths.size === cachedPaths.size
    && Array.from(indexedPaths).every((path) => cachedPaths.has(path));
}

function getCachedHydratedTrackModalAlbum(albumKey) {
  const normalizedAlbumKey = String(albumKey || '').trim();
  if (!normalizedAlbumKey) return null;
  const cachedAlbum = trackModalHydratedAlbumDetails.get(normalizedAlbumKey);
  if (cachedAlbum && !albumRequiresHydration(cachedAlbum)) {
    const indexedAlbum = getIndexedAlbum(normalizedAlbumKey);
    const cachedEntry = trackModalHydratedAlbumDetailsLru.get(cachedAlbum);
    const trustedAlias = cachedEntry?.trustedAliases?.has(normalizedAlbumKey);
    if (
      indexedAlbum
      && (
        !trackModalAlbumsShareLogicalRelease(indexedAlbum, cachedAlbum)
        || (!trustedAlias && !trackModalAlbumsHaveCompatibleMembership(indexedAlbum, cachedAlbum))
      )
    ) {
      return null;
    }
    trackModalHydratedAlbumDetailsLru.delete(cachedAlbum);
    trackModalHydratedAlbumDetailsLru.set(cachedAlbum, cachedEntry);
    return cachedAlbum;
  }
  return null;
}

function resolveGalleryPlaybackContext(playbackContext) {
  if (!playbackContext || typeof playbackContext !== 'object') return null;
  return playbackContext;
}

function resolveAlbumPlaybackContextFromView(album) {
  const playbackContext = state?.view?.playback_context;
  if (!playbackContext || typeof playbackContext !== 'object') return null;
  const albumRef = String(getAlbumIdentity(album) || album?.key || '').trim();
  if (!albumRef) return null;
  const orderedAlbumRefs = Array.isArray(playbackContext.ordered_album_refs)
    ? playbackContext.ordered_album_refs.map((value) => String(value || '').trim()).filter(Boolean)
    : [];
  if (!orderedAlbumRefs.includes(albumRef)) return null;
  return resolveGalleryPlaybackContext(playbackContext);
}

function attachGalleryPlaybackContextToAlbum(album) {
  if (!album || typeof album !== 'object') return album;
  const playbackContext = resolveGalleryPlaybackContext(album.playback_context)
    || resolveAlbumPlaybackContextFromView(album);
  if (!playbackContext) return album;
  return {
    ...album,
    playback_context: playbackContext,
  };
}

async function fetchTrackModalAlbumDetails(albumKey, options = {}) {
  const normalizedAlbumKey = String(albumKey || '').trim();
  if (!normalizedAlbumKey) return null;
  const response = await fetch(`/album-details?album_key=${encodeURIComponent(normalizedAlbumKey)}`, {
    headers: { Accept: 'application/json' },
    priority: options.speculative === true ? 'low' : 'high',
    ...(options.signal ? { signal: options.signal } : {}),
  });
  let payload = null;
  try {
    payload = await response.json();
  } catch (_error) {
    payload = null;
  }
  if (!response.ok || !payload?.ok || !payload?.album) {
    throw new Error(payload?.error || `Album detail request failed: ${response.status}`);
  }
  return payload.album;
}

function loadTrackModalAlbumDetails(albumKey, options = {}) {
  const normalizedAlbumKey = String(albumKey || '').trim();
  if (!normalizedAlbumKey) return Promise.resolve(null);
  const cachedAlbum = getCachedHydratedTrackModalAlbum(normalizedAlbumKey);
  if (cachedAlbum) return Promise.resolve(cachedAlbum);
  const requestAliases = getTrackModalAlbumKeyAliases(normalizedAlbumKey);
  const existingLoad = requestAliases
    .map((alias) => trackModalAlbumDetailsLoads.get(alias))
    .find(Boolean);
  if (existingLoad) {
    const speculativeController = trackModalSpeculativeAlbumDetailsLoadControllers.get(existingLoad);
    if (options.speculative === true || !speculativeController) return existingLoad;
    trackModalSpeculativeAlbumDetailsLoadControllers.delete(existingLoad);
    trackModalSpeculativePrewarmControllers.delete(speculativeController);
    return existingLoad;
  }
  let load = null;
  load = fetchTrackModalAlbumDetails(normalizedAlbumKey, options)
    .then((album) => {
      cacheHydratedTrackModalAlbum(normalizedAlbumKey, album);
      getTrackModalAlbumKeyAliases(normalizedAlbumKey, album).forEach((alias) => {
        trackModalAlbumDetailsLoads.set(alias, load);
      });
      return album;
    })
    .finally(() => {
      trackModalSpeculativeAlbumDetailsLoadControllers.delete(load);
      trackModalAlbumDetailsLoads.forEach((mappedLoad, alias) => {
        if (mappedLoad === load) trackModalAlbumDetailsLoads.delete(alias);
      });
    });
  if (options.speculative === true && options.controller) {
    trackModalSpeculativeAlbumDetailsLoadControllers.set(load, options.controller);
  }
  requestAliases.forEach((alias) => trackModalAlbumDetailsLoads.set(alias, load));
  return load;
}

function queueTrackModalAlbumDetailsPrewarm(albumKey) {
  const normalizedAlbumKey = String(albumKey || '').trim();
  if (!normalizedAlbumKey) return;
  const committedQuery = String(state?.view?.query || '');
  const draftQuery = String(state?.ui?.searchDraftQuery ?? committedQuery);
  if (
    state?.busy
    || state?.ui?.albumDetailPrewarmSearchSuspended
    || draftQuery !== committedQuery
  ) return;
  if (getCachedHydratedTrackModalAlbum(normalizedAlbumKey)) return;
  const indexedAlbum = getIndexedAlbum(normalizedAlbumKey);
  if (!albumRequiresHydration(indexedAlbum)) return;
  const existingLoad = getTrackModalAlbumKeyAliases(normalizedAlbumKey)
    .map((alias) => trackModalAlbumDetailsLoads.get(alias))
    .find(Boolean);
  if (existingLoad) {
    existingLoad.catch(() => {});
    return;
  }
  if (trackModalActiveSpeculativePrewarms >= TRACK_MODAL_SPECULATIVE_PREWARM_LIMIT) return;
  const controller = typeof AbortController === 'function' ? new AbortController() : null;
  if (controller) trackModalSpeculativePrewarmControllers.add(controller);
  trackModalActiveSpeculativePrewarms += 1;
  loadTrackModalAlbumDetails(normalizedAlbumKey, {
    controller,
    signal: controller?.signal,
    speculative: true,
  }).catch(() => {
    // User-facing errors are shown only when the user actually opens the modal.
  }).finally(() => {
    if (controller) trackModalSpeculativePrewarmControllers.delete(controller);
    trackModalActiveSpeculativePrewarms = Math.max(0, trackModalActiveSpeculativePrewarms - 1);
  });
}

function cancelTrackModalAlbumDetailsPrewarms() {
  trackModalSpeculativePrewarmControllers.forEach((controller) => controller.abort());
  trackModalSpeculativePrewarmControllers.clear();
}

function queueVisibleTrackModalAlbumDetailsPrewarm(containerEl, scrollEl, limit = 2) {
  if (!(containerEl instanceof HTMLElement) || !(scrollEl instanceof HTMLElement)) return;
  const scrollRect = scrollEl.getBoundingClientRect();
  const visibleButtons = [];
  containerEl.querySelectorAll('.album-title-button[data-open-tracklist="1"][data-album-key]').forEach((button) => {
    if (!(button instanceof HTMLElement)) return;
    const rect = button.getBoundingClientRect();
    if (!(rect.width > 0 && rect.height > 0)) return;
    if (rect.bottom <= scrollRect.top || rect.top >= scrollRect.bottom) return;
    visibleButtons.push(button);
  });
  if (!visibleButtons.length || visibleButtons.length > limit) return;
  visibleButtons.forEach((button) => {
    const albumKey = String(button.getAttribute('data-album-key') || '').trim();
    if (!albumKey) return;
    queueTrackModalAlbumDetailsPrewarm(albumKey);
  });
}

function openTrackModal(album, options = {}) {
  const els = getTrackModalElements();
  if (!els.overlay || !album) return;
  state.ui.trackModalCoverLightboxGallery = options.coverLightboxGallery !== false;
  if (typeof clearPendingSelectedArtistReconcile === 'function') {
    clearPendingSelectedArtistReconcile();
  }
  const albumWithPlaybackContext = attachGalleryPlaybackContextToAlbum(album);
  if (albumRequiresHydration(albumWithPlaybackContext)) {
    const albumKey = getAlbumRequestKey(albumWithPlaybackContext);
    const loadToken = invalidatePendingTrackModalLoad();
    state.ui.pendingTrackModalLoadAlbumKey = albumKey;
    openTrackModalShell(albumWithPlaybackContext);
    const coverLoadSuspensionToken = suspendGalleryCoverLoadsForTrackModal();
    const detailsPromise = loadTrackModalAlbumDetails(albumKey);
    detailsPromise.then((hydratedAlbum) => {
      if (loadToken !== state.ui.pendingTrackModalLoadToken) return;
      const refreshedAlbum = getIndexedAlbum(albumKey);
      const resolvedAlbum = (!refreshedAlbum || albumRequiresHydration(refreshedAlbum))
        ? hydratedAlbum
        : refreshedAlbum;
      if (loadToken !== state.ui.pendingTrackModalLoadToken) return;
      if (!resolvedAlbum || albumRequiresHydration(resolvedAlbum) || els.overlay.hidden) return;
      invalidatePendingTrackModalLoad();
      openTrackModal(resolvedAlbum, options);
    }).catch((error) => {
      if (loadToken !== state.ui.pendingTrackModalLoadToken) return;
      console.error('[AlbumHaven][AlbumDetails] Failed to load full album details.', error);
      showToast('Unable to load album details.', 'error', 3200);
    }).finally(() => {
      resumeGalleryCoverLoadsAfterTrackModalAction(coverLoadSuspensionToken);
    });
    return;
  }
  invalidatePendingTrackModalLoad();
  const releaseSet = getAlbumReleaseSet(albumWithPlaybackContext);
  state.modalReleases = releaseSet.releases;
  state.modalReleaseIndex = releaseSet.selectedIndex;
  hideVersionContextMenu();
  renderTrackModalRelease(state.modalReleases[state.modalReleaseIndex]);
  els.overlay.hidden = false;
  document.body.classList.add('modal-open');
  attachSharedPlayer();
}

function getCurrentTrackModalAlbum() {
  return state.modalReleases[state.modalReleaseIndex] || null;
}

function getTrackModalButtonAlbumKey(button) {
  if (!(button instanceof HTMLElement)) return '';
  return (typeof button.getAttribute === 'function' ? button.getAttribute('data-album-key') : '')
    || button.dataset.albumKey
    || '';
}

function getTrackModalButtonAlbumVersionKey(button) {
  if (!(button instanceof HTMLElement)) return '';
  return (typeof button.getAttribute === 'function' ? button.getAttribute('data-album-version-key') : '')
    || button.dataset.albumVersionKey
    || '';
}

function resolveTrackModalActionAlbum(button) {
  const albumKey = String(getTrackModalButtonAlbumKey(button) || '').trim();
  const albumVersionKey = String(getTrackModalButtonAlbumVersionKey(button) || '').trim();
  const currentAlbum = getCurrentTrackModalAlbum();
  if (albumVersionKey) {
    const currentAlbumVersionKey = getTrackModalAlbumVersionKey(currentAlbum);
    if (currentAlbum && !albumRequiresHydration(currentAlbum) && currentAlbumVersionKey === albumVersionKey) {
      return currentAlbum;
    }
    const cachedVersionAlbum = getCachedHydratedTrackModalAlbum(albumVersionKey);
    if (cachedVersionAlbum) return cachedVersionAlbum;
    const indexedVersionAlbum = getIndexedAlbum(albumVersionKey);
    if (indexedVersionAlbum) return indexedVersionAlbum;
  }
  if (albumKey) {
    const currentAlbumKey = String(getAlbumRequestKey(currentAlbum) || getAlbumIdentity(currentAlbum) || currentAlbum?.key || '');
    if (currentAlbum && !albumRequiresHydration(currentAlbum) && currentAlbumKey === albumKey) {
      return currentAlbum;
    }
    const cachedAlbum = getCachedHydratedTrackModalAlbum(albumKey);
    if (currentAlbum && cachedAlbum === currentAlbum) {
      return currentAlbum;
    }
    const indexedAlbum = getIndexedAlbum(albumKey);
    if (indexedAlbum) return indexedAlbum;
    if (currentAlbumKey === albumKey) {
      return currentAlbum;
    }
  }
  if (currentAlbum) return currentAlbum;
  if (!(button instanceof HTMLElement)) return null;
  try {
    const parsedAlbum = JSON.parse(button.getAttribute('data-album') || 'null');
    return parsedAlbum && typeof parsedAlbum === 'object' ? parsedAlbum : null;
  } catch (_error) {
    return null;
  }
}

function resolveTrackModalDuplicateSourceAlbum(button) {
  const album = resolveTrackModalActionAlbum(button);
  if (!album || !(button instanceof HTMLElement)) return album;
  const duplicateSources = Array.isArray(album?.duplicate_sources) ? album.duplicate_sources : [];
  const sourceIndex = Number(button.getAttribute('data-duplicate-source-index'));
  if (!Number.isInteger(sourceIndex) || sourceIndex < 0 || sourceIndex >= duplicateSources.length) {
    return album;
  }
  return {
    ...album,
    tracks: Array.isArray(duplicateSources[sourceIndex]?.tracks) ? duplicateSources[sourceIndex].tracks : [],
  };
}

function getTrackModalLightboxSourceAlbumKey(button) {
  const album = resolveTrackModalActionAlbum(button);
  if (!album || typeof album !== 'object') return '';
  if (typeof getAlbumPathSignature === 'function') {
    const signature = getAlbumPathSignature(album);
    if (signature) return signature;
  }
  return String(getAlbumIdentity(album) || album?.key || `${album?.name || ''}::${album?.album_artist || ''}`);
}

function openImageLightbox(src, alt, options = {}) {
  const els = getLightboxElements();
  if (!els.overlay || !els.image || !src) return;
  bindOverlayPointerOrigin(els.overlay);
  state.lightbox.sourceAlbumKey = String(options.sourceAlbumKey || '');
  state.lightbox.items = Array.isArray(options.items) ? options.items.filter(Boolean) : [];
  state.lightbox.currentIndex = -1;
  const itemIndex = state.lightbox.items.findIndex((item) => (
    item?.src === src || (state.lightbox.sourceAlbumKey && item?.key === state.lightbox.sourceAlbumKey)
  ));
  if (itemIndex >= 0) {
    showLightboxItem(itemIndex);
  } else {
    const standaloneItem = {
      src,
      previewSrc: String(options.previewSrc || ''),
      remoteSrc: String(options.remoteSrc || ''),
      alt: alt || 'Full-size album cover',
    };
    if (typeof showStandaloneLightboxItem === 'function') {
      showStandaloneLightboxItem(standaloneItem);
    } else {
      els.image.src = src;
      els.image.alt = standaloneItem.alt;
    }
    state.lightbox.panX = 0;
    state.lightbox.panY = 0;
    state.lightbox.dragging = false;
    setLightboxZoom(1);
    updateLightboxNavState();
  }
  els.overlay.hidden = false;
  document.body.classList.add('modal-open');
}

function closeImageLightbox() {
  const els = getLightboxElements();
  if (!els.overlay || !els.image) return;
  els.overlay.hidden = true;
  stopLightboxDrag();
  state.lightbox.panX = 0;
  state.lightbox.panY = 0;
  state.lightbox.items = [];
  state.lightbox.currentIndex = -1;
  state.lightbox.sourceAlbumKey = '';
  state.lightbox.activeSources = [];
  state.lightbox.activeSourceIndex = -1;
  state.lightbox.activeFullSource = '';
  state.lightbox.activeAlt = '';
  state.lightbox.loadToken = Number(state.lightbox.loadToken || 0) + 1;
  if (state.lightbox.activePreloader) {
    state.lightbox.activePreloader.onload = null;
    state.lightbox.activePreloader.onerror = null;
    state.lightbox.activePreloader = null;
  }
  setLightboxZoom(1);
  els.image.onload = null;
  els.image.onerror = null;
  if (els.loading) els.loading.hidden = true;
  els.image.hidden = true;
  if (els.image.classList?.remove) els.image.classList.remove('is-unavailable');
  els.image.removeAttribute('src');
  els.image.alt = '';
  if (typeof els.image.setAttribute === 'function') els.image.setAttribute('aria-hidden', 'true');
  updateLightboxNavState();
  const trackModalOpen = !document.getElementById('track-modal')?.hidden;
  const utilityModalOpen = !document.getElementById('utility-modal')?.hidden;
  if (!trackModalOpen && !utilityModalOpen) {
    document.body.classList.remove('modal-open');
  }
}

function closeTrackModal() {
  const els = getTrackModalElements();
  if (!els.overlay) return;
  els.overlay.hidden = true;
  invalidatePendingTrackModalLoad();
  resumeAllGalleryCoverLoadsAfterTrackModalActions();
  state.modalReleases = [];
  state.modalReleaseIndex = 0;
  hideVersionContextMenu();
  clearTrackModalRenderedState();
  if (typeof compactCurrentViewForIdle === 'function') {
    compactCurrentViewForIdle();
  }
  const lightboxOpen = !document.getElementById('image-lightbox')?.hidden;
  const utilityModalOpen = !document.getElementById('utility-modal')?.hidden;
  if (!lightboxOpen && !utilityModalOpen) {
    document.body.classList.remove('modal-open');
  }
}

function openTrackModalForButton(button) {
  if (!(button instanceof HTMLElement)) return false;
  const albumKey = (typeof button.getAttribute === 'function' ? button.getAttribute('data-album-key') : '')
    || button.dataset.albumKey
    || '';
  if (!albumKey) return false;
  openTrackModal(resolveTrackModalActionAlbum(button));
  return true;
}

function attachTrackButtons() {
  document.querySelectorAll('[data-open-tracklist="1"]').forEach((button) => {
    if (button.dataset.bound === '1') return;
    button.dataset.bound = '1';
    button.addEventListener('click', () => {
      openTrackModalForButton(button);
    });
  });
}

function attachModalEvents() {
  const els = getTrackModalElements();
  if (!els.overlay || els.overlay.dataset.bound === '1') return;
  els.overlay.dataset.bound = '1';
  bindOverlayPointerOrigin(els.overlay);
  els.close?.addEventListener('click', closeTrackModal);
  els.overlay.addEventListener('click', (event) => {
    if (overlayClickStartedOnOverlay(els.overlay, event) || event.target.closest('[data-close-track-modal="1"]')) {
      closeTrackModal();
    }
  });
  document.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape') return;
    const lightboxEls = getLightboxElements();
    if (lightboxEls.overlay && !lightboxEls.overlay.hidden) {
      closeImageLightbox();
      return;
    }
    const repairConfirmEls = getRepairConfirmElements();
    if (repairConfirmEls.overlay && !repairConfirmEls.overlay.hidden) {
      closeRepairConfirmModal();
      return;
    }
    const coverLookupEls = getCoverLookupModalElements();
    if (coverLookupEls.overlay && !coverLookupEls.overlay.hidden) {
      closeCoverLookupModal();
      return;
    }
    const coverLookupDeleteConfirmEls = getCoverLookupDeleteConfirmElements();
    if (coverLookupDeleteConfirmEls.overlay && !coverLookupDeleteConfirmEls.overlay.hidden) {
      closeCoverLookupDeleteConfirm();
      return;
    }
    const utilityEls = getUtilityModalElements();
    if (utilityEls.overlay && !utilityEls.overlay.hidden) {
      if (event.defaultPrevented) return;
      if (typeof cancelActiveSavedLoopCreation === 'function'
          && cancelActiveSavedLoopCreation()) {
        event.preventDefault();
        return;
      }
      closeUtilityModal();
      return;
    }
    const nonAlbumEls = getNonAlbumModalElements();
    if (nonAlbumEls.overlay && !nonAlbumEls.overlay.hidden) {
      closeNonAlbumModal();
      return;
    }
    if (!els.overlay.hidden) {
      closeTrackModal();
    }
  });
  document.addEventListener('keydown', (event) => {
    const lightboxEls = getLightboxElements();
    if (!lightboxEls.overlay || lightboxEls.overlay.hidden) return;
    if (event.key === 'ArrowLeft') {
      event.preventDefault();
      stepLightbox(-1);
      return;
    }
    if (event.key === 'ArrowRight') {
      event.preventDefault();
      stepLightbox(1);
    }
  });
}

// END js/runtime/track-modal-lightbox-helpers.js

// BEGIN js/runtime/player-waveform-peaks.js

const PLAYER_WAVEFORM_PEAK_COUNT = 280;
const PLAYER_WAVEFORM_BUSY_RETRY_DELAYS_MS = Object.freeze([50, 100, 200, 400, 800]);
const SAVED_LOOP_WAVEFORM_CACHE_LIMIT = 4;
const playerWaveformPeakCache = new Map();
const playerWaveformPeakProbes = new Map();
const savedLoopWaveformPeakCache = new Map();
let playerWaveformPeakGeneration = null;
let playerWaveformPeakController = null;
let playerWaveformPeakCurrentIdentity = null;
let playerWaveformForegroundSuspensionDepth = 0;

function trimWaveformPeakCache() {
  while (playerWaveformPeakCache.size > 2) {
    const evicted = [...playerWaveformPeakCache.keys()]
      .find((identity) => identity !== playerWaveformPeakCurrentIdentity);
    if (!evicted) return;
    playerWaveformPeakCache.delete(evicted);
  }
}

function cancelWaveformPeakLoads(generation) {
  if (playerWaveformPeakGeneration !== generation) return;
  playerWaveformPeakController?.abort();
  playerWaveformPeakController = new AbortController();
  const prefix = `${generation}\u0000`;
  for (const identity of playerWaveformPeakCache.keys()) {
    if (identity.startsWith(prefix)) playerWaveformPeakCache.delete(identity);
  }
  for (const identity of playerWaveformPeakProbes.keys()) {
    if (identity.startsWith(prefix)) playerWaveformPeakProbes.delete(identity);
  }
  if (playerWaveformPeakCurrentIdentity?.startsWith(prefix)) {
    playerWaveformPeakCurrentIdentity = null;
  }
}

function validateWaveformPeakPayload(payload, sampleCount) {
  if (!payload || payload.sampleCount !== sampleCount
      || !Array.isArray(payload.left) || !Array.isArray(payload.right)
      || payload.left.length !== sampleCount || payload.right.length !== sampleCount) {
    return null;
  }
  const validPeak = (value) => Number.isFinite(value) && value >= 0 && value <= 1;
  if (!payload.left.every(validPeak) || !payload.right.every(validPeak)) return null;
  return { sampleCount, left: [...payload.left], right: [...payload.right] };
}

function suspendPlayerWaveformPeakLoadsForForegroundView() {
  playerWaveformForegroundSuspensionDepth += 1;
  const generation = Number(state.player?.streaming?.generation) || 0;
  if (String(state.player?.current?.path || '')) {
    cancelWaveformPeakLoads(generation);
  }
  return { generation };
}

async function resumePlayerWaveformPeakLoadsAfterForegroundView(suspension) {
  if (!suspension || playerWaveformForegroundSuspensionDepth < 1) return null;
  playerWaveformForegroundSuspensionDepth -= 1;
  if (playerWaveformForegroundSuspensionDepth > 0) return null;

  const generation = Number(state.player?.streaming?.generation) || 0;
  const path = String(state.player?.current?.path || '');
  if (!path || generation !== Number(suspension.generation || 0)) return null;

  const peaks = await loadWaveformPeaks(path, PLAYER_WAVEFORM_PEAK_COUNT, generation);
  if (!peaks || playerWaveformForegroundSuspensionDepth > 0
      || Number(state.player?.streaming?.generation) !== generation
      || String(state.player?.current?.path || '') !== path) return null;
  state.player.waveform.compactPeaks = { path, generation, data: peaks };
  try {
    await updateWaveformAppearance();
  } catch (_error) {
    // Optional waveform rendering must not interrupt foreground navigation.
  }
  return peaks;
}

function trimSavedLoopWaveformPeakCache() {
  while (savedLoopWaveformPeakCache.size > SAVED_LOOP_WAVEFORM_CACHE_LIMIT) {
    const oldestIdentity = savedLoopWaveformPeakCache.keys().next().value;
    const evicted = savedLoopWaveformPeakCache.get(oldestIdentity);
    savedLoopWaveformPeakCache.delete(oldestIdentity);
    evicted?.controller?.abort();
  }
}

async function loadSavedLoopWaveformPeaks(loopId) {
  const identity = String(loopId || '').trim();
  if (!identity || identity.length > 256) return null;
  if (savedLoopWaveformPeakCache.has(identity)) {
    const cached = savedLoopWaveformPeakCache.get(identity);
    savedLoopWaveformPeakCache.delete(identity);
    savedLoopWaveformPeakCache.set(identity, cached);
    return cached.promise;
  }

  const controller = new AbortController();
  const entry = { controller, promise: null };
  entry.promise = (async () => {
    let retained = false;
    try {
      const query = new URLSearchParams({
        loop_id: identity,
        bins: String(PLAYER_WAVEFORM_PEAK_COUNT),
      });
      for (let attempt = 0; ; attempt += 1) {
        const response = await fetch(`/playback/waveform?${query}`, {
          signal: controller.signal,
        });
        if (response.status === 429 && attempt < PLAYER_WAVEFORM_BUSY_RETRY_DELAYS_MS.length) {
          await new Promise((resolve) => {
            setTimeout(resolve, PLAYER_WAVEFORM_BUSY_RETRY_DELAYS_MS[attempt]);
          });
          if (controller.signal.aborted) return null;
          continue;
        }
        if (!response.ok) return null;
        const peaks = validateWaveformPeakPayload(
          await response.json(),
          PLAYER_WAVEFORM_PEAK_COUNT,
        );
        retained = Boolean(peaks);
        return peaks;
      }
    } catch (_error) {
      return null;
    } finally {
      if (!retained && savedLoopWaveformPeakCache.get(identity) === entry) {
        savedLoopWaveformPeakCache.delete(identity);
      }
    }
  })();
  savedLoopWaveformPeakCache.set(identity, entry);
  trimSavedLoopWaveformPeakCache();
  return entry.promise;
}

async function loadWaveformPeaks(path, sampleCount = PLAYER_WAVEFORM_PEAK_COUNT, generation = 0) {
  const rawPath = String(path || '');
  if (!rawPath || sampleCount !== PLAYER_WAVEFORM_PEAK_COUNT) return null;
  if (playerWaveformForegroundSuspensionDepth > 0) return null;
  if (playerWaveformPeakGeneration !== generation) {
    playerWaveformPeakController?.abort();
    playerWaveformPeakController = new AbortController();
    playerWaveformPeakGeneration = generation;
    playerWaveformPeakCurrentIdentity = null;
  } else if (!playerWaveformPeakController) {
    playerWaveformPeakController = new AbortController();
  }
  const identity = `${generation}\u0000${rawPath}`;
  if (playerWaveformPeakCache.has(identity)) {
    const cached = playerWaveformPeakCache.get(identity);
    playerWaveformPeakCache.delete(identity);
    playerWaveformPeakCache.set(identity, cached);
    return cached;
  }
  const pendingProbe = playerWaveformPeakProbes.get(identity);
  if (pendingProbe) {
    let probed = null;
    try {
      probed = await pendingProbe;
    } catch (_error) {
      probed = null;
    }
    if (probed) return probed;
    if (playerWaveformPeakController?.signal.aborted
        || state.player.streaming.generation !== generation) return null;
  }
  const controller = playerWaveformPeakController;
  let request;
  request = (async () => {
    let retained = false;
    try {
      const query = new URLSearchParams({ path: rawPath, bins: String(sampleCount) });
      for (let attempt = 0; ; attempt += 1) {
        const response = await fetch(`/playback/waveform?${query}`, { signal: controller.signal });
        if (response.status === 429 && attempt < PLAYER_WAVEFORM_BUSY_RETRY_DELAYS_MS.length) {
          await new Promise((resolve) => {
            setTimeout(resolve, PLAYER_WAVEFORM_BUSY_RETRY_DELAYS_MS[attempt]);
          });
          if (controller.signal.aborted || state.player.streaming.generation !== generation) return null;
          continue;
        }
        if (!response.ok) return null;
        const peaks = validateWaveformPeakPayload(await response.json(), sampleCount);
        if (controller.signal.aborted || state.player.streaming.generation !== generation) return null;
        if (!peaks) return null;
        retained = true;
        return peaks;
      }
    } catch (_error) {
      return null;
    } finally {
      if (!retained && playerWaveformPeakCache.get(identity) === request) {
        playerWaveformPeakCache.delete(identity);
      }
    }
  })();
  playerWaveformPeakCache.set(identity, request);
  trimWaveformPeakCache();
  return request;
}

async function probeCachedWaveformPeaks(path, generation = 0) {
  const rawPath = String(path || '');
  if (!rawPath) return null;
  if (playerWaveformPeakGeneration !== generation) {
    playerWaveformPeakController?.abort();
    playerWaveformPeakController = new AbortController();
    playerWaveformPeakGeneration = generation;
    playerWaveformPeakCurrentIdentity = null;
  } else if (!playerWaveformPeakController) {
    playerWaveformPeakController = new AbortController();
  }
  const identity = `${generation}\u0000${rawPath}`;
  let peaks = null;
  if (playerWaveformPeakCache.has(identity)) {
    const cached = playerWaveformPeakCache.get(identity);
    playerWaveformPeakCache.delete(identity);
    playerWaveformPeakCache.set(identity, cached);
    try {
      peaks = await cached;
    } catch (_error) {
      return null;
    }
  } else if (playerWaveformPeakProbes.has(identity)) {
    try {
      peaks = await playerWaveformPeakProbes.get(identity);
    } catch (_error) {
      return null;
    }
  } else {
    const controller = playerWaveformPeakController;
    let probe;
    try {
      probe = (async () => {
        const query = new URLSearchParams({
          path: rawPath,
          bins: String(PLAYER_WAVEFORM_PEAK_COUNT),
          cachedOnly: '1',
        });
        const response = await fetch(`/playback/waveform?${query}`, { signal: controller.signal });
        if (!response.ok || response.status !== 200) return null;
        const cachedPeaks = validateWaveformPeakPayload(
          await response.json(),
          PLAYER_WAVEFORM_PEAK_COUNT,
        );
        if (!cachedPeaks || controller.signal.aborted
            || state.player.streaming.generation !== generation) return null;
        return cachedPeaks;
      })();
      playerWaveformPeakProbes.set(identity, probe);
      peaks = await probe;
      if (!peaks) return null;
      playerWaveformPeakCache.delete(identity);
      playerWaveformPeakCache.set(identity, Promise.resolve(peaks));
      trimWaveformPeakCache();
    } catch (_error) {
      return null;
    } finally {
      if (playerWaveformPeakProbes.get(identity) === probe) {
        playerWaveformPeakProbes.delete(identity);
      }
    }
  }
  if (!peaks || state.player.streaming.generation !== generation
      || String(state.player.current?.path || '') !== rawPath) return null;
  playerWaveformPeakCurrentIdentity = identity;
  trimWaveformPeakCache();
  state.player.waveform.compactPeaks = { path: rawPath, generation, data: peaks };
  try {
    await updateWaveformAppearance();
  } catch (_error) {
    // Waveform rendering remains optional and must never interrupt playback.
  }
  return peaks;
}

async function promoteWaveformPeaks(completedPath, currentPath, generation) {
  const completedIdentity = `${generation}\u0000${String(completedPath || '')}`;
  const currentIdentity = `${generation}\u0000${String(currentPath || '')}`;
  let cached = playerWaveformPeakCache.get(currentIdentity);
  let peaks = cached ? await cached : null;
  if (!peaks && state.player.streaming.generation === generation) {
    await loadWaveformPeaks(currentPath, PLAYER_WAVEFORM_PEAK_COUNT, generation);
    cached = playerWaveformPeakCache.get(currentIdentity);
    peaks = cached ? await cached : null;
  }
  if (completedIdentity !== currentIdentity) {
    playerWaveformPeakCache.delete(completedIdentity);
  }
  if (!peaks || playerWaveformPeakCache.get(currentIdentity) !== cached) return null;
  playerWaveformPeakCache.delete(currentIdentity);
  playerWaveformPeakCache.set(currentIdentity, cached);
  playerWaveformPeakCurrentIdentity = currentIdentity;
  trimWaveformPeakCache();
  state.player.waveform.compactPeaks = {
    path: String(currentPath || ''),
    generation,
    data: peaks,
  };
  return peaks;
}

// END js/runtime/player-waveform-peaks.js

// BEGIN js/runtime/loop-range-controls.js

function escapeLoopControlAttribute(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function buildLoopEditActionControl({
  ownerId = '',
  enterLabel = 'Create a loop',
  createLabel = 'Create loop',
  cancelLabel = 'Cancel loop creation',
} = {}) {
  return `
    <span class="loop-edit-actions" data-loop-action-owner="${escapeLoopControlAttribute(ownerId)}" data-loop-action-state="idle" data-loop-action-engaged="false">
      <span class="loop-edit-action-pod" data-loop-action-pod>
        <button class="loop-edit-action loop-edit-action-enter" type="button" data-loop-action="enter" aria-label="${escapeLoopControlAttribute(enterLabel)}" aria-pressed="false" title="${escapeLoopControlAttribute(enterLabel)}"><span class="loop-edit-action-icon is-scissors" aria-hidden="true"></span></button>
        <span class="loop-edit-action-expanded" data-loop-action-expanded hidden>
          <button class="loop-edit-action loop-edit-action-create" type="button" data-loop-action="create" aria-label="${escapeLoopControlAttribute(createLabel)}" title="${escapeLoopControlAttribute(createLabel)}"><span class="loop-edit-action-icon is-scissors" aria-hidden="true"></span></button>
          <span class="loop-edit-action-divider" data-loop-action-divider aria-hidden="true"></span>
          <button class="loop-edit-action loop-edit-action-cancel" type="button" data-loop-action="cancel" aria-label="${escapeLoopControlAttribute(cancelLabel)}" title="${escapeLoopControlAttribute(cancelLabel)}"><span class="loop-edit-action-icon is-cancel" aria-hidden="true"></span></button>
        </span>
      </span>
    </span>
  `;
}

function mountLoopEditActionControl({
  root,
  enabled = true,
  active = false,
  busy = false,
  disabledLabel = 'Start playing the track to edit the loop',
  onEnter,
  onCreate,
  onCancel,
} = {}) {
  if (!root) return null;
  const enter = root.querySelector('[data-loop-action="enter"]');
  const create = root.querySelector('[data-loop-action="create"]');
  const cancel = root.querySelector('[data-loop-action="cancel"]');
  const expanded = root.querySelector?.('[data-loop-action-expanded]') || null;
  const listeners = [];
  let currentEnabled = Boolean(enabled);
  let currentActive = Boolean(active);
  let currentBusy = Boolean(busy);
  let currentEngaged = false;
  let pointerWithin = false;
  let focusWithin = false;
  const listen = (target, name, listener) => {
    target?.addEventListener?.(name, listener);
    listeners.push([target, name, listener]);
  };
  const renderEngagement = () => {
    currentEngaged = currentActive && (pointerWithin || focusWithin);
    root.setAttribute?.('data-loop-action-engaged', String(currentEngaged));
  };
  const update = (next = {}) => {
    const activating = !currentActive
      && Object.prototype.hasOwnProperty.call(next, 'active')
      && Boolean(next.active);
    if (activating) {
      pointerWithin = pointerWithin || Boolean(root.matches?.(':hover'));
      const ownerDocument = root.ownerDocument
        || (typeof document !== 'undefined' ? document : null);
      const activeElement = ownerDocument?.activeElement;
      focusWithin = focusWithin || Boolean(activeElement && root.contains?.(activeElement));
    }
    if (Object.prototype.hasOwnProperty.call(next, 'enabled')) currentEnabled = Boolean(next.enabled);
    if (Object.prototype.hasOwnProperty.call(next, 'active')) currentActive = Boolean(next.active);
    if (Object.prototype.hasOwnProperty.call(next, 'busy')) currentBusy = Boolean(next.busy);
    renderEngagement();
    const unavailable = !currentEnabled;
    const disabled = unavailable || currentBusy;
    if (enter) {
      enter.hidden = currentActive;
      enter.disabled = disabled;
      enter.setAttribute('aria-pressed', String(currentActive));
      enter.setAttribute('aria-disabled', String(disabled));
      enter.setAttribute('title', unavailable ? disabledLabel : enter.getAttribute('aria-label'));
    }
    if (expanded) expanded.hidden = !currentActive;
    if (create) {
      create.hidden = !currentActive;
      create.disabled = disabled;
      create.setAttribute('aria-disabled', String(disabled));
    }
    if (cancel) {
      cancel.hidden = !currentActive;
      cancel.disabled = disabled;
      cancel.setAttribute('aria-disabled', String(disabled));
    }
    root.classList?.toggle('is-active', currentActive);
    root.classList?.toggle('is-busy', currentBusy);
    root.classList?.toggle('is-disabled', unavailable);
    root.setAttribute?.('aria-busy', String(currentBusy));
    root.setAttribute?.('data-loop-action-engaged', String(currentEngaged));
    root.setAttribute?.('data-loop-action-state', unavailable ? 'disabled' : (currentActive ? 'editing' : 'idle'));
  };
  listen(enter, 'click', () => { if (currentEnabled && !currentBusy && !currentActive) onEnter?.(); });
  listen(create, 'click', () => { if (currentEnabled && !currentBusy && currentActive) onCreate?.(); });
  listen(cancel, 'click', () => { if (currentEnabled && !currentBusy && currentActive) onCancel?.(); });
  listen(root, 'pointerenter', () => {
    pointerWithin = true;
    renderEngagement();
  });
  listen(root, 'pointerleave', () => {
    pointerWithin = false;
    renderEngagement();
  });
  listen(root, 'focusin', () => {
    focusWithin = true;
    renderEngagement();
  });
  listen(root, 'focusout', (event) => {
    focusWithin = Boolean(event?.relatedTarget && root.contains?.(event.relatedTarget));
    renderEngagement();
  });
  update({ enabled, active, busy });
  const destroy = () => {
    listeners.forEach(([target, name, listener]) => target?.removeEventListener?.(name, listener));
    listeners.length = 0;
  };
  return { update, destroy };
}

function normalizeLoopRange(range, duration) {
  const limit = Math.max(0, Number(duration) || 0);
  const minimum = Math.min(0.01, limit || 0.01);
  let startSeconds = Math.max(0, Math.min(limit, Number(range?.startSeconds) || 0));
  let endSeconds = Math.max(0, Math.min(limit, Number(range?.endSeconds) || 0));
  if (startSeconds > endSeconds) [startSeconds, endSeconds] = [endSeconds, startSeconds];
  if (endSeconds - startSeconds < minimum && limit > 0) {
    if (endSeconds + minimum <= limit) endSeconds += minimum;
    else startSeconds = Math.max(0, endSeconds - minimum);
  }
  return { startSeconds, endSeconds };
}

function createLoopRangeController({
  root,
  getDuration,
  getRange,
  onRangeInteractionStart,
  onRangePreview,
  onRangeCommit,
  onSeek,
  onCancel,
} = {}) {
  if (!root) return null;
  const surface = root.matches?.('[data-loop-range-surface]')
    ? root
    : root.querySelector('[data-loop-range-surface]');
  const handles = {
    start: root.querySelector('[data-loop-range-handle="start"]'),
    end: root.querySelector('[data-loop-range-handle="end"]'),
  };
  const times = {
    start: root.querySelector('[data-loop-range-time="start"]'),
    end: root.querySelector('[data-loop-range-time="end"]'),
  };
  let currentDuration = Math.max(0, Number(getDuration?.()) || 0);
  const initialRange = getRange?.();
  const initialRangeDuration = Math.max(0, Number(initialRange?.durationSeconds) || 0);
  const initialCandidate = initialRangeDuration > 0 && currentDuration > 0
    && Math.abs(initialRangeDuration - currentDuration) > 0.001
    ? {
      startSeconds: Number(initialRange?.startSeconds) * (currentDuration / initialRangeDuration),
      endSeconds: Number(initialRange?.endSeconds) * (currentDuration / initialRangeDuration),
    }
    : initialRange;
  let currentRange = normalizeLoopRange(initialCandidate, currentDuration);
  let drag = null;
  let pendingSurfaceGesture = null;
  let queuedClientX = null;
  let frame = 0;
  let documentDragListenersAttached = false;

  const render = (range = currentRange) => {
    const duration = Math.max(0, Number(getDuration?.()) || 0);
    let candidate = range;
    if (currentDuration > 0 && duration > 0 && Math.abs(duration - currentDuration) > 0.001) {
      const scale = duration / currentDuration;
      candidate = {
        startSeconds: Number(range?.startSeconds) * scale,
        endSeconds: Number(range?.endSeconds) * scale,
      };
    }
    currentDuration = duration;
    currentRange = normalizeLoopRange(candidate, duration);
    ['start', 'end'].forEach((role) => {
      const value = currentRange[`${role}Seconds`];
      const handle = handles[role];
      if (handle) {
        const percent = duration > 0 ? (value / duration) * 100 : 0;
        handle.style.left = `${percent}%`;
        handle.setAttribute('aria-valuemin', '0');
        handle.setAttribute('aria-valuemax', String(duration));
        handle.setAttribute('aria-valuenow', String(value));
        handle.setAttribute('aria-valuetext', `${role === 'start' ? 'Loop start' : 'Loop end'} ${formatLoopTime(value, true)}`);
      }
      if (times[role]) times[role].textContent = formatLoopTime(value, true);
    });
    root.style?.setProperty?.('--loop-range-start', `${duration > 0 ? (currentRange.startSeconds / duration) * 100 : 0}%`);
    root.style?.setProperty?.('--loop-range-end', `${duration > 0 ? (currentRange.endSeconds / duration) * 100 : 100}%`);
    return currentRange;
  };

  const clientXToSeconds = (clientX) => {
    const rect = surface?.getBoundingClientRect?.() || { left: 0, width: 1 };
    const ratio = Math.max(0, Math.min(1, (Number(clientX) - rect.left) / Math.max(1, rect.width)));
    return ratio * Math.max(0, Number(getDuration?.()) || 0);
  };

  const previewAt = (clientX) => {
    if (!drag) return;
    const value = clientXToSeconds(clientX);
    const stationaryRole = drag.role === 'start' ? 'end' : 'start';
    const stationary = currentRange[`${stationaryRole}Seconds`];
    const next = value <= stationary
      ? { startSeconds: value, endSeconds: stationary }
      : { startSeconds: stationary, endSeconds: value };
    drag.role = value <= stationary ? 'start' : 'end';
    render(next);
    onRangePreview?.({ ...currentRange });
  };

  const onPointerMove = (event) => {
    if (pendingSurfaceGesture) {
      if (event.pointerId != null && pendingSurfaceGesture.pointerId !== event.pointerId) return;
      if (Math.abs(Number(event.clientX) - pendingSurfaceGesture.originClientX) < 3) return;
      drag = {
        role: pendingSurfaceGesture.role,
        originRole: pendingSurfaceGesture.role,
        pointerId: pendingSurfaceGesture.pointerId,
      };
      root.setAttribute?.('data-loop-range-front', pendingSurfaceGesture.role);
      pendingSurfaceGesture = null;
    }
    if (!drag || (event.pointerId != null && drag.pointerId !== event.pointerId)) return;
    queuedClientX = event.clientX;
    if (frame) return;
    const schedule = typeof requestAnimationFrame === 'function' ? requestAnimationFrame : (callback) => { callback(); return 0; };
    frame = schedule(() => {
      frame = 0;
      const clientX = queuedClientX;
      queuedClientX = null;
      previewAt(clientX);
    });
  };

  const onPointerUp = (event) => {
    if (pendingSurfaceGesture
        && (event.pointerId == null || pendingSurfaceGesture.pointerId === event.pointerId)) {
      const clickClientX = pendingSurfaceGesture.originClientX;
      pendingSurfaceGesture = null;
      detachDocumentDragListeners();
      onSeek?.(clientXToSeconds(clickClientX));
      return;
    }
    finishDrag(event, false);
  };
  const onPointerCancel = (event) => {
    if (pendingSurfaceGesture
        && (event.pointerId == null || pendingSurfaceGesture.pointerId === event.pointerId)) {
      pendingSurfaceGesture = null;
      detachDocumentDragListeners();
      return;
    }
    finishDrag(event, true);
  };
  const attachDocumentDragListeners = () => {
    if (documentDragListenersAttached) return;
    documentDragListenersAttached = true;
    document.addEventListener('pointermove', onPointerMove);
    document.addEventListener('pointerup', onPointerUp);
    document.addEventListener('pointercancel', onPointerCancel);
  };
  const detachDocumentDragListeners = () => {
    if (!documentDragListenersAttached) return;
    documentDragListenersAttached = false;
    document.removeEventListener?.('pointermove', onPointerMove);
    document.removeEventListener?.('pointerup', onPointerUp);
    document.removeEventListener?.('pointercancel', onPointerCancel);
  };

  function finishDrag(event, cancelled = false) {
    if (!drag || (event?.pointerId != null && drag.pointerId !== event.pointerId)) return;
    if (!cancelled && queuedClientX != null) {
      if (frame && typeof cancelAnimationFrame === 'function') cancelAnimationFrame(frame);
      frame = 0;
      previewAt(queuedClientX);
    }
    const originRole = drag.originRole;
    drag = null;
    queuedClientX = null;
    detachDocumentDragListeners();
    if (cancelled) onCancel?.();
    else {
      root.setAttribute?.('data-loop-range-front', originRole === 'start' ? 'end' : 'start');
      onRangeCommit?.({ ...currentRange });
    }
  }

  Object.entries(handles).forEach(([role, handle]) => {
    handle?.addEventListener('pointerdown', (event) => {
      event.preventDefault?.();
      onRangeInteractionStart?.(role);
      render(currentRange);
      drag = { role, originRole: role, pointerId: event.pointerId };
      root.setAttribute?.('data-loop-range-front', role);
      attachDocumentDragListeners();
      handle.setPointerCapture?.(event.pointerId);
      handle.focus?.();
    });
    handle?.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        event.preventDefault?.();
        event.stopPropagation?.();
        onCancel?.();
        return;
      }
      if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
      event.preventDefault?.();
      onRangeInteractionStart?.(role);
      const duration = Math.max(0, Number(getDuration?.()) || 0);
      const step = event.shiftKey ? Math.max(0.1, duration / 20) : Math.max(0.01, duration / 200);
      const value = currentRange[`${role}Seconds`] + (event.key === 'ArrowRight' ? step : -step);
      const stationaryRole = role === 'start' ? 'end' : 'start';
      const stationary = currentRange[`${stationaryRole}Seconds`];
      const crossed = role === 'start' ? value > stationary : value < stationary;
      const next = normalizeLoopRange(value <= stationary
        ? { startSeconds: value, endSeconds: stationary }
        : { startSeconds: stationary, endSeconds: value }, duration);
      render(next);
      if (crossed) handles[stationaryRole]?.focus?.();
      onRangePreview?.({ ...currentRange });
      onRangeCommit?.({ ...currentRange });
    });
  });
  surface?.addEventListener('pointerdown', (event) => {
    if (event.target?.closest?.('[data-loop-range-handle]')) return;
    event.preventDefault?.();
    render(currentRange);
    const value = clientXToSeconds(event.clientX);
    const role = Math.abs(value - currentRange.startSeconds) <= Math.abs(value - currentRange.endSeconds)
      ? 'start'
      : 'end';
    pendingSurfaceGesture = {
      originClientX: Number(event.clientX),
      pointerId: event.pointerId,
      role,
    };
    attachDocumentDragListeners();
    surface.setPointerCapture?.(event.pointerId);
  });
  root.addEventListener?.('keydown', (event) => {
    if (event.key !== 'Escape') return;
    event.preventDefault?.();
    onCancel?.();
  });
  render(currentRange);
  root.setAttribute?.('data-loop-range-front', 'start');
  if (currentRange.startSeconds !== Number(getRange?.()?.startSeconds)
      || currentRange.endSeconds !== Number(getRange?.()?.endSeconds)) {
    onRangePreview?.({ ...currentRange });
  }
  return { render, getRange: () => ({ ...currentRange }) };
}

function drawCombinedLoopWaveform(canvas, waveform, progressRatio = 0) {
  if (!canvas) return;
  const width = Math.max(1, canvas.clientWidth || canvas.width || 1);
  const height = Math.max(1, canvas.clientHeight || canvas.height || 1);
  if (canvas.width !== width) canvas.width = width;
  if (canvas.height !== height) canvas.height = height;
  const context = canvas.getContext('2d');
  if (!context) return;
  context.clearRect(0, 0, width, height);
  const left = Array.isArray(waveform?.left) ? waveform.left : [];
  const right = Array.isArray(waveform?.right) ? waveform.right : [];
  const count = Math.max(left.length, right.length, 1);
  const barWidth = width / count;
  const center = Math.floor(height / 2);
  const maxHalfHeight = Math.max(0, Math.floor((height - 1) / 2));
  const fill = (typeof state !== 'undefined' && state.player?.appearance?.waveformFillColor) || '#9be18a';
  const edge = (typeof state !== 'undefined' && state.player?.appearance?.waveformEdgeColor) || '#86efac';
  context.fillStyle = fill;
  context.globalAlpha = 0.42;
  for (let index = 0; index < count; index += 1) {
    const leftPeak = Math.abs(Number(left[index] ?? right[index] ?? 0));
    const rightPeak = Math.abs(Number(right[index] ?? left[index] ?? 0));
    const peak = Math.max(0.025, Math.min(1, (leftPeak + rightPeak) / 2));
    const halfHeight = Math.min(maxHalfHeight, Math.max(1, Math.round(peak * height * 0.46)));
    context.fillRect(
      index * barWidth,
      center - halfHeight,
      Math.max(1, barWidth * 0.72),
      (2 * halfHeight) + 1,
    );
  }
  context.globalAlpha = 1;

  const clampedProgress = Math.max(0, Math.min(1, Number(progressRatio) || 0));
  const playheadX = width * clampedProgress;
  if (playheadX > 0) {
    context.save();
    context.globalCompositeOperation = 'source-atop';
    context.globalAlpha = 0.4;
    context.fillStyle = fill;
    context.beginPath();
    context.rect(0, 0, playheadX, height);
    context.fill();
    context.restore();
  }

  context.globalAlpha = 1;
  context.globalCompositeOperation = 'source-over';
  context.strokeStyle = edge;
  context.shadowColor = edge;
  context.shadowBlur = 10;
  context.lineWidth = 2.4;
  context.beginPath();
  context.moveTo(playheadX, 0);
  context.lineTo(playheadX, height);
  context.stroke();
  context.shadowBlur = 0;
  context.fillStyle = edge;
  context.beginPath();
  context.arc(playheadX, height * 0.5, 3.2, 0, Math.PI * 2);
  context.fill();
}

// END js/runtime/loop-range-controls.js

// BEGIN js/runtime/loop-edit-session-expiry.js

const LOOP_EDIT_INACTIVITY_MS = 5 * 60 * 1000;
const LOOP_EDIT_SECOND_CYCLE_GRACE_MS = 15 * 1000;

function createLoopEditSessionExpiryController(options = {}) {
  const setTimeoutFn = options.setTimeoutFn || setTimeout;
  const clearTimeoutFn = options.clearTimeoutFn || clearTimeout;
  const nowFn = options.nowFn || (() => Date.now());
  const sessions = new Map();
  let nextGeneration = 1;

  function clearSessionTimers(session) {
    if (session.inactivityTimer !== null) clearTimeoutFn(session.inactivityTimer);
    if (session.wholeRangeGraceTimer !== null) clearTimeoutFn(session.wholeRangeGraceTimer);
    session.inactivityTimer = null;
    session.wholeRangeGraceTimer = null;
  }

  function expire(session, reason) {
    if (sessions.get(session.ownerId) !== session) return false;
    sessions.delete(session.ownerId);
    clearSessionTimers(session);
    session.onExpire({ ownerId: session.ownerId, reason });
    return true;
  }

  function reconcileSession(session) {
    if (sessions.get(session.ownerId) !== session) return false;
    const now = Number(nowFn());
    if (session.wholeRangeGraceDeadlineAt !== null
        && now >= session.wholeRangeGraceDeadlineAt) {
      return expire(session, 'untouched-whole-range');
    }
    if (now >= session.inactivityDeadlineAt) return expire(session, 'inactive');
    return false;
  }

  function scheduleInactivity(session, renewDeadline = true) {
    if (session.inactivityTimer !== null) clearTimeoutFn(session.inactivityTimer);
    if (renewDeadline) {
      session.inactivityDeadlineAt = Number(nowFn()) + LOOP_EDIT_INACTIVITY_MS;
    }
    const remaining = Math.max(0, session.inactivityDeadlineAt - Number(nowFn()));
    session.inactivityTimer = setTimeoutFn(() => {
      session.inactivityTimer = null;
      if (!reconcileSession(session)) scheduleInactivity(session, false);
    }, remaining);
  }

  function stop(ownerId) {
    const normalizedOwnerId = String(ownerId || '');
    const session = sessions.get(normalizedOwnerId);
    if (!session) return false;
    sessions.delete(normalizedOwnerId);
    clearSessionTimers(session);
    return true;
  }

  function start({ ownerId, onExpire }) {
    const normalizedOwnerId = String(ownerId || '');
    if (!normalizedOwnerId) throw new Error('Loop edit expiry ownerId is required.');
    if (typeof onExpire !== 'function') throw new Error('Loop edit expiry onExpire callback is required.');
    stop(normalizedOwnerId);
    const session = {
      ownerId: normalizedOwnerId,
      onExpire,
      generation: nextGeneration,
      boundaryEdited: false,
      wholeRangeWrapObserved: false,
      inactivityDeadlineAt: 0,
      wholeRangeGraceDeadlineAt: null,
      inactivityTimer: null,
      wholeRangeGraceTimer: null,
    };
    nextGeneration += 1;
    sessions.set(normalizedOwnerId, session);
    scheduleInactivity(session);
    return session.generation;
  }

  function renewAfterBoundaryEdit(ownerId) {
    const session = sessions.get(String(ownerId || ''));
    if (!session) return false;
    session.boundaryEdited = true;
    if (session.wholeRangeGraceTimer !== null) {
      clearTimeoutFn(session.wholeRangeGraceTimer);
      session.wholeRangeGraceTimer = null;
    }
    session.wholeRangeGraceDeadlineAt = null;
    scheduleInactivity(session);
    return true;
  }

  function noteUntouchedWholeRangeWrap(ownerId) {
    const session = sessions.get(String(ownerId || ''));
    if (!session || session.boundaryEdited || session.wholeRangeWrapObserved) return false;
    session.wholeRangeWrapObserved = true;
    session.wholeRangeGraceDeadlineAt = Number(nowFn()) + LOOP_EDIT_SECOND_CYCLE_GRACE_MS;
    session.wholeRangeGraceTimer = setTimeoutFn(() => {
      session.wholeRangeGraceTimer = null;
      if (!reconcileSession(session)) {
        const remaining = Math.max(0, session.wholeRangeGraceDeadlineAt - Number(nowFn()));
        session.wholeRangeGraceTimer = setTimeoutFn(() => {
          reconcileSession(session);
        }, remaining);
      }
    }, LOOP_EDIT_SECOND_CYCLE_GRACE_MS);
    return true;
  }

  function reconcile() {
    let expiredCount = 0;
    [...sessions.values()].forEach((session) => {
      if (reconcileSession(session)) expiredCount += 1;
    });
    return expiredCount;
  }

  function has(ownerId) {
    return sessions.has(String(ownerId || ''));
  }

  return {
    start,
    renewAfterBoundaryEdit,
    noteUntouchedWholeRangeWrap,
    stop,
    has,
    reconcile,
  };
}

const loopEditSessionExpiryController = createLoopEditSessionExpiryController({
  setTimeoutFn: (...args) => setTimeout(...args),
  clearTimeoutFn: (...args) => clearTimeout(...args),
});

// END js/runtime/loop-edit-session-expiry.js

