﻿const albumTrackCollator = new Intl.Collator(undefined, {
  numeric: true,
  sensitivity: 'base',
});

function getPositiveAlbumTrackSortNumber(value) {
  const number = Number(value);
  return Number.isInteger(number) && number > 0 ? number : null;
}

function compareAlbumTrackSortNumbers(left, right) {
  if (left === right) return 0;
  if (left === null) return 1;
  if (right === null) return -1;
  return left - right;
}

function compareAlbumTrackExactText(left, right) {
  const leftText = String(left || '');
  const rightText = String(right || '');
  if (leftText === rightText) return 0;
  return leftText < rightText ? -1 : 1;
}
function getAlbumTrackFilename(track) {
  const path = String(track?.path || '');
  return path.split(/[\\/]/).pop() || String(track?.title || track?.key || '');
}

function getAlbumTrackDisplayNumber(track, index) {
  const taggedTrackNumber = getPositiveAlbumTrackSortNumber(track?.track_number);
  if (taggedTrackNumber !== null) return taggedTrackNumber;

  const filenameMatch = getAlbumTrackFilename(track).match(/^\s*(\d+)(?=\D|$)/);
  const filenameTrackNumber = getPositiveAlbumTrackSortNumber(filenameMatch?.[1]);
  if (filenameTrackNumber !== null) return filenameTrackNumber;

  return index + 1;
}

function compareAlbumTracks(left, right) {
  const discCompare = compareAlbumTrackSortNumbers(
    getPositiveAlbumTrackSortNumber(left?.disc_number),
    getPositiveAlbumTrackSortNumber(right?.disc_number),
  );
  if (discCompare) return discCompare;

  const trackCompare = compareAlbumTrackSortNumbers(
    getPositiveAlbumTrackSortNumber(left?.track_number),
    getPositiveAlbumTrackSortNumber(right?.track_number),
  );
  if (trackCompare) return trackCompare;

  const filenameCompare = albumTrackCollator.compare(
    getAlbumTrackFilename(left),
    getAlbumTrackFilename(right),
  );
  if (filenameCompare) return filenameCompare;

  const pathCompare = compareAlbumTrackExactText(left?.path, right?.path);
  if (pathCompare) return pathCompare;

  return compareAlbumTrackExactText(
    left?.key || left?.track_ref,
    right?.key || right?.track_ref,
  );
}

function orderAlbumTracks(tracks) {
  return (Array.isArray(tracks) ? tracks : []).slice().sort(compareAlbumTracks);
}

function getOrderedSelectedTrackIndexes(tracks, selectedPaths) {
  const orderedTracks = orderAlbumTracks(tracks);
  const selectedPathSet = new Set(
    (Array.isArray(selectedPaths) ? selectedPaths : [])
      .map((path) => String(path || ''))
      .filter(Boolean),
  );
  const indexes = orderedTracks
    .map((track, index) => (
      selectedPathSet.has(String(track?.path || '')) ? index : -1
    ))
    .filter((index) => index >= 0);
  return { indexes, orderedTracks, selectedPathSet };
}

function buildSelectedTrackNumberValues(tracks, selectedPaths, startAt) {
  const { indexes, orderedTracks, selectedPathSet } = getOrderedSelectedTrackIndexes(
    tracks,
    selectedPaths,
  );
  const start = Number(startAt);
  const contiguous = indexes.length >= 2
    && indexes.length === selectedPathSet.size
    && indexes.every((index, offset) => index === indexes[0] + offset);
  if (!contiguous || !Number.isInteger(start) || start < 1) return {};

  const numberedTrackCountByDisc = new Map();
  return indexes.reduce((values, index) => {
    const track = orderedTracks[index];
    const path = String(track?.path || '');
    const discKey = getPositiveAlbumTrackSortNumber(track?.disc_number);
    const discOffset = numberedTrackCountByDisc.get(discKey) || 0;
    if (path) values[path] = String(start + discOffset);
    numberedTrackCountByDisc.set(discKey, discOffset + 1);
    return values;
  }, {});
}

function deriveTagEditorAutoNumberStart(tracks, selectedPaths) {
  const { indexes, orderedTracks } = getOrderedSelectedTrackIndexes(tracks, selectedPaths);
  const firstIndex = indexes[0];
  const firstTrack = Number.isInteger(firstIndex) ? orderedTracks[firstIndex] : null;
  if (!firstTrack) return '1';
  const filenameMatch = getAlbumTrackFilename(firstTrack).match(/^\s*(\d+)(?=\D|$)/);
  const filenameNumber = getPositiveAlbumTrackSortNumber(filenameMatch?.[1]);
  if (filenameNumber !== null) return String(filenameNumber);
  return String(Number.isInteger(firstIndex) && firstIndex >= 0 ? firstIndex + 1 : 1);
}

function restoreTagEditorAutoNumberValues() {
  const snapshots = state.tagEditor.autoNumberTrackNumberSnapshots || {};
  Object.entries(snapshots).forEach(([path, snapshot]) => {
    const values = { ...(state.tagEditor.values[path] || {}) };
    if (snapshot?.hasValue) {
      values.track_number = snapshot.value;
    } else {
      delete values.track_number;
    }
    state.tagEditor.values[path] = values;
  });
  state.tagEditor.autoNumberActive = false;
  state.tagEditor.autoNumberAppliedSelectionSignature = '';
  state.tagEditor.autoNumberTrackNumberSnapshots = {};
  return Object.keys(snapshots).length > 0;
}

function syncTagEditorAutoNumberControls() {
  if (
    typeof document === 'undefined'
    || typeof document.getElementById !== 'function'
    || typeof getSelectedTagEditorPaths !== 'function'
  ) return;
  const controls = document.getElementById('tag-editor-auto-number-controls');
  const startInput = document.getElementById('tag-editor-auto-number-start');
  const button = document.getElementById('tag-editor-auto-number');
  if (!controls || !startInput || !button) return;
  const tracks = Array.isArray(state.tagEditor.tracks) ? state.tagEditor.tracks : [];
  const selectedPaths = getSelectedTagEditorPaths(tracks);
  const { indexes, orderedTracks, selectedPathSet } = getOrderedSelectedTrackIndexes(
    tracks,
    selectedPaths,
  );
  const eligible = indexes.length >= 2
    && indexes.length === selectedPathSet.size
    && indexes.every((index, offset) => index === indexes[0] + offset);
  const selectionSignature = indexes
    .map((index) => String(orderedTracks[index]?.path || ''))
    .join('\n');
  const appliedSelectionMatches = Boolean(state.tagEditor.autoNumberActive)
    && selectionSignature === String(
      state.tagEditor.autoNumberAppliedSelectionSignature || '',
    );
  controls.hidden = !eligible;
  button.disabled = !eligible;
  button.setAttribute('aria-pressed', appliedSelectionMatches ? 'true' : 'false');
  if (!eligible) {
    state.tagEditor.autoNumberSelectionSignature = '';
    return;
  }
  const selectionChanged = selectionSignature !== String(
    state.tagEditor.autoNumberSelectionSignature || '',
  );
  const rememberedStart = Number(state.tagEditor.autoNumberStartValue);
  const currentStart = Number(startInput.value);
  const preservedStart = Number.isInteger(rememberedStart) && rememberedStart > 0
    ? rememberedStart
    : currentStart;
  const nextStart = !selectionChanged && Number.isInteger(preservedStart) && preservedStart > 0
    ? String(preservedStart)
    : deriveTagEditorAutoNumberStart(tracks, selectedPaths);
  state.tagEditor.autoNumberSelectionSignature = selectionSignature;
  state.tagEditor.autoNumberStartValue = nextStart;
  startInput.value = nextStart;
}

function tagEditsExplicitlyChangeAlbumArtist(tagEdits) {
  return Boolean(
    tagEdits
    && typeof tagEdits === 'object'
    && !Array.isArray(tagEdits)
    && Object.values(tagEdits).some((edits) => (
      edits
      && typeof edits === 'object'
      && Object.prototype.hasOwnProperty.call(edits, 'album_artist')
    )),
  );
}

const MOUNTED_GALLERY_REPLACEMENT_TAG_FIELDS = new Set([
  'album',
  'album_artist',
  'year',
  'edition',
  'exception_type',
]);

function tagEditsRequireMountedGalleryChildReplacement(tagEdits) {
  return Boolean(
    tagEdits
    && typeof tagEdits === 'object'
    && !Array.isArray(tagEdits)
    && Object.values(tagEdits).some((edits) => (
      edits
      && typeof edits === 'object'
      && Object.keys(edits).some((field) => (
        MOUNTED_GALLERY_REPLACEMENT_TAG_FIELDS.has(field)
      ))
    )),
  );
}

function settleTagEditorSessionMutationClaim(tagEditor = state.tagEditor) {
  const claim = tagEditor?.sessionMutationClaim;
  if (!claim) return;
  tagEditor.sessionMutationClaim = null;
  settleTagEditViewMutation(claim);
}

function openTagEditor(album, options = {}) {
  const els = getTagEditorElements();
  if (!els.overlay || !album) return;
  bindOverlayPointerOrigin(els.overlay);
  const tracksMode = options.tracksMode || 'problematic';
  const tracks = orderAlbumTracks(getTagEditorTracks(album, tracksMode));
  if (!tracks.length) {
    showRepairAlert(tracksMode === 'all' ? 'No tracks to edit.' : 'No problematic tracks to edit.', 'error');
    return;
  }
  const values = {};
  tracks.forEach((track) => {
    const path = String(track.path || '');
    values[path] = getTrackTagInitialValues(track, album);
  });
  settleTagEditorSessionMutationClaim();
  state.tagEditor = {
    album,
    tracks,
    selectedPaths: [String(tracks[0].path || '')].filter(Boolean),
    anchorPath: String(tracks[0].path || ''),
    dragSelecting: false,
    dragAnchorPath: '',
    values,
    sessionMutationClaim: claimTagEditViewMutation(album),
    autoNumberStartValue: '',
    autoNumberSelectionSignature: '',
    autoNumberActive: false,
    autoNumberAppliedSelectionSignature: '',
    autoNumberTrackNumberSnapshots: {},
  };
  els.overlay.hidden = false;
  document.body.classList.add('modal-open');
  renderTagEditor();
  syncTagEditorAutoNumberControls();
}

function autoNumberSelectedTagEditorTracks() {
  const tracks = Array.isArray(state.tagEditor.tracks) ? state.tagEditor.tracks : [];
  const selectedPaths = getSelectedTagEditorPaths(tracks);
  const { indexes, orderedTracks } = getOrderedSelectedTrackIndexes(tracks, selectedPaths);
  const selectionSignature = indexes
    .map((index) => String(orderedTracks[index]?.path || ''))
    .join('\n');
  const appliedSelectionMatches = Boolean(state.tagEditor.autoNumberActive)
    && selectionSignature === String(
      state.tagEditor.autoNumberAppliedSelectionSignature || '',
    );
  if (appliedSelectionMatches) {
    restoreTagEditorAutoNumberValues();
    renderTagEditor({ preserveTrackList: true });
    syncTagEditorAutoNumberControls();
    return;
  }
  const els = typeof getTagEditorElements === 'function' ? getTagEditorElements() : {};
  const startInput = els.autoNumberStart || (
    typeof document !== 'undefined' && typeof document.getElementById === 'function'
      ? document.getElementById('tag-editor-auto-number-start')
      : null
  );
  const trackNumbersByPath = buildSelectedTrackNumberValues(
    tracks,
    selectedPaths,
    startInput?.value,
  );
  const numberedPaths = Object.keys(trackNumbersByPath);
  if (numberedPaths.length < 2) return;

  const trackNumberSnapshots = {};
  numberedPaths.forEach((path) => {
    const currentValues = state.tagEditor.values[path] || {};
    trackNumberSnapshots[path] = {
      hasValue: Object.prototype.hasOwnProperty.call(currentValues, 'track_number'),
      value: currentValues.track_number,
    };
    state.tagEditor.values[path] = {
      ...currentValues,
      track_number: trackNumbersByPath[path],
    };
  });
  state.tagEditor.autoNumberActive = true;
  state.tagEditor.autoNumberAppliedSelectionSignature = selectionSignature;
  state.tagEditor.autoNumberTrackNumberSnapshots = trackNumberSnapshots;
  renderTagEditor({ preserveTrackList: true });
  syncTagEditorAutoNumberControls();
}

function closeTagEditor() {
  const els = getTagEditorElements();
  if (!els.overlay) return;
  settleTagEditorSessionMutationClaim();
  els.overlay.hidden = true;
  const trackModalOpen = !document.getElementById('track-modal')?.hidden;
  const utilityModalOpen = !document.getElementById('utility-modal')?.hidden;
  const confirmOpen = !document.getElementById('tag-edit-confirm-modal')?.hidden;
  if (!trackModalOpen && !utilityModalOpen && !confirmOpen) {
    document.body.classList.remove('modal-open');
  }
}

function openTagEditConfirmModal() {
  const els = getTagEditConfirmElements();
  if (!els.overlay) return;
  const album = state.tagEditor.album;
  const updates = buildChangedTagEditorUpdates(
    album,
    state.tagEditor.tracks || [],
    state.tagEditor.values || {},
  );
  if (els.nonAlbumWarning) {
    els.nonAlbumWarning.hidden = !nonAlbumRarityWarningFingerprint(album, updates);
  }
  const galleryScroll = document.getElementById('albums-scroll');
  state.tagEditor.originGalleryScrollPosition = galleryScroll
    && Number.isFinite(Number(galleryScroll.scrollTop))
    && Number.isFinite(Number(galleryScroll.scrollLeft))
    ? {
      scrollLeft: Number(galleryScroll.scrollLeft),
      scrollTop: Number(galleryScroll.scrollTop),
    }
    : null;
  els.overlay.hidden = false;
  document.body.classList.add('modal-open');
}

function closeTagEditConfirmModal() {
  const els = getTagEditConfirmElements();
  if (!els.overlay) return;
  els.overlay.hidden = true;
  const trackModalOpen = !document.getElementById('track-modal')?.hidden;
  const utilityModalOpen = !document.getElementById('utility-modal')?.hidden;
  const tagEditorOpen = !document.getElementById('tag-editor-modal')?.hidden;
  if (!trackModalOpen && !utilityModalOpen && !tagEditorOpen) {
    document.body.classList.remove('modal-open');
  }
}

function readTagEditOriginViewStateRevision() {
  return Number(state.ui?.viewStateRevision || 0);
}

function readProblematicMutationOriginKey() {
  const utilityModal = typeof document !== 'undefined'
    && typeof document.getElementById === 'function'
    ? document.getElementById('utility-modal')
    : null;
  if (
    !utilityModal
    || utilityModal.hidden
    || state.utility?.activeTab !== 'problematic-files'
  ) return '';
  return String(state.utility?.selectedProblematicKey || '').trim();
}

function tagEditOriginStillOwnsView(originatingViewStateRevision) {
  return readTagEditOriginViewStateRevision() === Number(originatingViewStateRevision || 0);
}

async function confirmRepairSelectedAlbum() {
  const album = (state.utility.problematicFiles || []).find((item) => item.key === state.utility.pendingRepairKey) || getSelectedProblematicAlbum();
  if (!album) {
    showToast('No album selected for repair.', 'error', 3200);
    closeRepairConfirmModal();
    return;
  }
  const action = state.utility.pendingRepairAction || 'repair';
  const selectedRows = action === 'repair' ? getSelectedRepairRowKeys() : [];
  const ignoredRows = action === 'detected' ? getIgnoredRepairRowKeys() : [];
  const separateRows = action === 'separate-release' ? getSelectedSeparateReleaseKeys() : [];
  if (action === 'detected') {
    if (!ignoredRows.length) {
      showToast('No suggested actions are selected.', 'error', 3200);
      closeRepairConfirmModal();
      return;
    }
    const exclusionItems = ignoredRows.map((rowKey) => {
      if (typeof buildProblemExclusionItemFromAlbum === 'function') {
        return buildProblemExclusionItemFromAlbum(album, rowKey);
      }
      const row = (Array.isArray(album.album_problem_rows) ? album.album_problem_rows : [])
        .find((candidate) => String(candidate?.row_key || '') === String(rowKey || ''));
      return row ? {
        ...row,
        row_key: String(rowKey || ''),
        scope: 'album',
        album_key: String(album.key || ''),
        artist: String(album.album_artist || album.raw_album_artist || ''),
        album: String(album.name || album.raw_name || ''),
        year: String(album.year || ''),
        problem_reason: String(row.reason || ''),
      } : null;
    }).filter(Boolean);
    if (exclusionItems.length !== ignoredRows.length) {
      showToast('Unable to identify the selected problem exclusion.', 'error', 3200);
      closeRepairConfirmModal();
      return;
    }
    await queueProblemExclusionCreate({ album, items: exclusionItems });
    return;
  }
  const selectedPaths = new Set(selectedRows.map((value) => String(value).split('::')[0]).filter(Boolean));
  const actionPaths = new Set(selectedRows.map((value) => String(value).split('::')[0]).filter(Boolean));
  if (!selectedRows.length && !separateRows.length) {
    showToast('No suggested actions are selected.', 'error', 3200);
    closeRepairConfirmModal();
    return;
  }
  const progressCount = action === 'repair'
    ? selectedPaths.size
    : Math.max(actionPaths.size, separateRows.length ? (Array.isArray(album.tracks) ? album.tracks.length : 1) : 0);
  const originatingViewStateRevision = readTagEditOriginViewStateRevision();
  showRepairProgressOverlay(progressCount);
  try {
    const response = await fetch('/utilities/repair-album', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ confirmed: true, album, selected_rows: selectedRows, ignored_rows: [], separate_release_keys: separateRows }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to repair local tags');
    }
    closeRepairConfirmModal();
    const updatedAlbums = Array.isArray(data.updated_albums)
      ? data.updated_albums
      : [data.updated_album].filter(Boolean);
    if (tagEditOriginStillOwnsView(originatingViewStateRevision)) {
      const reconciledUpdatedAlbums = applyUpdatedAlbumsToCurrentView(
        updatedAlbums,
        { originalAlbum: album, preserveScroll: true },
      );
      updateOpenTrackModalAfterTagEdit(album, reconciledUpdatedAlbums);
    }
    const requestedFileCount = selectedPaths.size;
    const repairedCount = Number(data.changed_count || 0);
    const fileWord = requestedFileCount === 1 ? 'file' : 'files';
    const message = requestedFileCount
      ? `Applied selected repairs to ${repairedCount} of ${requestedFileCount} ${fileWord}.`
      : 'Updated ignored suggestions.';
    console.log('[AlbumHaven][Utilities] Tags repair completed.', { message, response: data });
    hideRepairProgressOverlay();
    showRepairAlert('Tag changes queued. Finalizing library view...', 'success', null);
    if (data.save_task_id) {
      watchSaveTask(data.save_task_id, {
        originalAlbum: album,
        originatingViewStateRevision,
        problematicMutationOriginKey: String(
          state.utility?.selectedProblematicKey || '',
        ).trim(),
      });
    } else if (Object.prototype.hasOwnProperty.call(data, 'updated_problematic_album')) {
      applyRepairResultToProblematicFiles(album, data.updated_problematic_album || null);
    }
  } catch (error) {
    console.error('[AlbumHaven][Utilities] Failed to repair local tags.', error);
    showRepairAlert(error.message || 'Failed to repair local tags.', 'error');
  } finally {
    hideRepairProgressOverlay();
  }
}

function buildTagEditUpdateFingerprint(updates) {
  return JSON.stringify(
    Object.keys(updates || {}).sort().map((path) => [
      path,
      Object.keys(updates[path] || {}).sort().map((field) => [
        field,
        String(updates[path]?.[field] ?? '').trim(),
      ]),
    ]),
  );
}

function nonAlbumRarityWarningFingerprint(album, updates) {
  const tracks = [
    ...(Array.isArray(state.tagEditor.tracks) ? state.tagEditor.tracks : []),
    ...(Array.isArray(album?.tracks) ? album.tracks : []),
  ];
  const albumByPath = new Map(
    tracks
      .map((track) => [
        String(track?.path || ''),
        String(track?.album || '').trim(),
      ])
      .filter(([path]) => path),
  );
  const requiresWarning = Object.entries(updates || {}).some(([path, edits]) => {
    const effectiveAlbum = Object.prototype.hasOwnProperty.call(edits || {}, 'album')
      ? String(edits?.album || '').trim()
      : String(albumByPath.get(String(path || '')) || '').trim();
    return (
      /\bnon[\s-]*album\s+rarity\b/i.test(String(edits?.exception_type || '').trim())
      && Boolean(effectiveAlbum)
    );
  });
  return requiresWarning ? buildTagEditUpdateFingerprint(updates) : '';
}

const TAG_EDIT_SAVE_TASK_WATCH_SETTLEMENT_MS = 300;
let pendingProblematicOptimisticEditGeneration = 0;

function buildInverseTagEditorUpdates(album, tracks, updates) {
  const originalTracksByPath = new Map([
    ...(Array.isArray(album?.tracks) ? album.tracks : []),
    ...(Array.isArray(tracks) ? tracks : []),
  ].map((track) => [String(track?.path || ''), track]));
  return Object.fromEntries(Object.entries(updates || {}).map(([path, edits]) => {
    const originalTrack = originalTracksByPath.get(String(path || '')) || {};
    const originalValues = getTrackTagInitialValues(originalTrack, album);
    const inverseEdits = Object.fromEntries(Object.keys(edits || {}).map((field) => [
      field,
      originalValues[field],
    ]));
    return [path, inverseEdits];
  }));
}

function registerPendingProblematicOptimisticEdit(originalAlbum, optimisticAlbums, tagEdits) {
  pendingProblematicOptimisticEditGeneration += 1;
  const utility = state.utility || (state.utility = {});
  const registry = utility.pendingProblematicSaveTasks
    || (utility.pendingProblematicSaveTasks = {});
  const key = `optimistic-tag-edit-${pendingProblematicOptimisticEditGeneration}`;
  let resolveTask;
  let resolveAccepted;
  const promise = new Promise((resolve) => {
    resolveTask = resolve;
  });
  const acceptedPromise = new Promise((resolve) => {
    resolveAccepted = resolve;
  });
  const entry = {
    promise,
    acceptedPromise,
    optimisticAlbums: Array.isArray(optimisticAlbums) ? optimisticAlbums : [],
    trackPaths: Array.from(new Set(
      Object.keys(tagEdits || {}).map((path) => String(path || '')).filter(Boolean),
    )),
  };
  registry[key] = entry;
  let accepted = false;
  let settled = false;
  return {
    entry,
    key,
    accept() {
      if (accepted) return;
      accepted = true;
      resolveAccepted();
    },
    settle() {
      if (settled) return;
      settled = true;
      if (!accepted) {
        accepted = true;
        resolveAccepted();
      }
      if (registry[key] === entry) delete registry[key];
      resolveTask();
    },
  };
}

function scheduleTagEditSaveTaskWatch(taskId, options) {
  const normalizedTaskId = String(taskId || '').trim();
  const utility = state.utility || (state.utility = {});
  const registry = utility.pendingProblematicSaveTasks
    || (utility.pendingProblematicSaveTasks = {});
  const pendingProblematicEntry = options?.pendingProblematicEntry || null;
  const trackPaths = Array.from(new Set([
    ...(Array.isArray(options?.originalAlbum?.tracks)
      ? options.originalAlbum.tracks.map((track) => String(track?.path || ''))
      : []),
    ...Object.keys(options?.tagEdits || {}).map((path) => String(path || '')),
  ].filter(Boolean)));
  let resolveTrackedTask;
  const trackedTask = pendingProblematicEntry?.entry?.promise || new Promise((resolve) => {
    resolveTrackedTask = resolve;
  });
  if (normalizedTaskId && !pendingProblematicEntry) {
    registry[normalizedTaskId] = {
      promise: trackedTask,
      trackPaths,
      optimisticAlbums: Array.isArray(options?.optimisticAlbums)
        ? options.optimisticAlbums
        : [],
    };
  }
  const startWatch = () => {
    let watchResult;
    try {
      watchResult = watchSaveTask(taskId, options);
    } catch (error) {
      watchResult = Promise.reject(error);
    }
    Promise.resolve(watchResult)
      .catch((error) => {
        console.error('[AlbumHaven][SaveTask] Unexpected save-task watcher failure.', error);
      })
      .finally(() => {
        if (!pendingProblematicEntry && registry[normalizedTaskId]?.promise === trackedTask) {
          delete registry[normalizedTaskId];
        }
        if (pendingProblematicEntry) {
          pendingProblematicEntry.settle();
        } else {
          resolveTrackedTask();
        }
      });
  };
  if (typeof scheduleBrowserAnimationFrame !== 'function') {
    startWatch();
    return;
  }
  scheduleBrowserAnimationFrame(() => {
    scheduleBrowserAnimationFrame(() => {
      if (typeof scheduleBrowserTimeout === 'function') {
        scheduleBrowserTimeout(
          startWatch,
          TAG_EDIT_SAVE_TASK_WATCH_SETTLEMENT_MS,
        );
      } else {
        startWatch();
      }
    });
  });
}

async function confirmManualTagEdit() {
  const album = state.tagEditor.album;
  const updates = buildChangedTagEditorUpdates(album, state.tagEditor.tracks || [], state.tagEditor.values || {});
  const editedPaths = Object.keys(updates).filter(Boolean);
  if (!album || !editedPaths.length) {
    showRepairAlert('No tag edits to apply.', 'error');
    closeTagEditConfirmModal();
    return;
  }

  const problematicMutationOriginKey = readProblematicMutationOriginKey();
  const inverseUpdates = buildInverseTagEditorUpdates(
    album,
    state.tagEditor.tracks || [],
    updates,
  );
  closeTagEditConfirmModal();
  const originatingViewStateRevision = readTagEditOriginViewStateRevision();
  const originatingViewRequestUrl = typeof buildApiUrl === 'function'
    ? String(buildApiUrl(state.view) || '').trim()
    : '';
  const tagEditMutationClaim = claimTagEditViewMutation(album, editedPaths, updates);
  settleTagEditorSessionMutationClaim();
  const optimisticUpdatedAlbums = buildOptimisticUpdatedAlbumsFromEdits(album, updates);
  const pendingProblematicEntry = registerPendingProblematicOptimisticEdit(
    album,
    optimisticUpdatedAlbums,
    updates,
  );
  const provisionalProblematicMutation = (
    problematicMutationOriginKey
    && typeof claimProblematicSaveTaskMutation === 'function'
  )
    ? claimProblematicSaveTaskMutation(
      pendingProblematicEntry.key,
      album,
      problematicMutationOriginKey,
    )
    : null;
  const absoluteScrollPosition = state.tagEditor.originGalleryScrollPosition
    && Number.isFinite(Number(state.tagEditor.originGalleryScrollPosition.scrollTop))
    && Number.isFinite(Number(state.tagEditor.originGalleryScrollPosition.scrollLeft))
    ? {
      scrollLeft: Number(state.tagEditor.originGalleryScrollPosition.scrollLeft),
      scrollTop: Number(state.tagEditor.originGalleryScrollPosition.scrollTop),
    }
    : null;
  const renderOptions = {
    preserveScroll: true,
    preserveAbsoluteScroll: true,
    preserveMountedGalleryChildren: true,
    ...(absoluteScrollPosition ? { absoluteScrollPosition } : {}),
  };
  closeTagEditor();
  const reconciledOptimisticAlbums = applyUpdatedAlbumsToCurrentView(
    optimisticUpdatedAlbums,
    {
      skipRender: true,
      originalAlbum: album,
      tagEdits: updates,
    },
  );
  if (typeof applyTagEditsToNonAlbumView === 'function') {
    applyTagEditsToNonAlbumView(album, updates);
  }
  updateOpenTrackModalAfterTagEdit(album, reconciledOptimisticAlbums);
  renderView(renderOptions);
  showRepairAlert('Writing tag changes...', 'success', null);
  let failedLogHistoryEntryId = '';
  try {
    const requestPayload = { confirmed: true, album, updates };
    if (problematicMutationOriginKey) {
      requestPayload.problematic_files_origin = true;
    }
    const response = await fetch('/utilities/edit-tags', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(requestPayload),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      if (data.log_entry) {
        failedLogHistoryEntryId = String(data.log_entry.id || '');
        try {
          await prependUtilityLogHistoryEntry(data.log_entry);
        } catch (historyError) {
          console.warn('[AlbumHaven][Utilities] Could not persist the failed tag edit in browser history.', historyError);
        }
      }
      throw new Error(data.error || 'Failed to apply tag edits');
    }
    const updatedAlbums = Array.isArray(data.updated_albums)
      ? data.updated_albums
      : [data.updated_album].filter(Boolean);
    const saveTaskCompleted = Boolean(data.save_task_id)
      && String(data.save_task_status || '').trim().toLowerCase() === 'completed';
    const responseIsTerminal = !data.save_task_id || saveTaskCompleted;
    const completedResponseNeedsCanonicalRefresh = saveTaskCompleted
      && Boolean(data.requires_view_refresh);
    const committedValues = data.committed_values
      && typeof data.committed_values === 'object'
      && !Array.isArray(data.committed_values)
      ? data.committed_values
      : null;
    const authoritativeTagEdits = committedValues || updates;
    const responseOwnsVisibleResources = tagEditOriginStillOwnsView(originatingViewStateRevision)
      && tagEditViewMutationStillOwnsResources(tagEditMutationClaim);
    if (committedValues && responseOwnsVisibleResources) {
      installCommittedTagValues(album, committedValues);
    }
    if (
      responseIsTerminal
      && updatedAlbums.length
      && responseOwnsVisibleResources
      && !completedResponseNeedsCanonicalRefresh
    ) {
      const reconciledUpdatedAlbums = applyUpdatedAlbumsToCurrentView(
        updatedAlbums,
        {
          skipRender: true,
          originalAlbum: album,
          preserveScroll: true,
          tagEdits: authoritativeTagEdits,
        },
      );
      updateOpenTrackModalAfterTagEdit(album, reconciledUpdatedAlbums);
      renderView(renderOptions);
    }
    const saveTaskWatchOptions = {
      originalAlbum: album,
      originatingViewStateRevision,
      originatingViewRequestUrl,
      tagEditMutationClaim,
      tagEdits: authoritativeTagEdits,
      preserveAbsoluteScroll: true,
      absoluteScrollPosition,
      problematicMutationOriginKey,
      optimisticAlbums: optimisticUpdatedAlbums,
      pendingProblematicEntry,
    };
    if (
      provisionalProblematicMutation
      && data.save_task_id
      && String(provisionalProblematicMutation.taskId || '') === pendingProblematicEntry.key
    ) {
      provisionalProblematicMutation.taskId = String(data.save_task_id);
    }
    if (completedResponseNeedsCanonicalRefresh) {
      pendingProblematicEntry.accept();
      await watchSaveTask(data.save_task_id, {
        ...saveTaskWatchOptions,
        terminalPayload: data,
      });
    } else if (data.save_task_id && !saveTaskCompleted) {
      pendingProblematicEntry.accept();
      scheduleTagEditSaveTaskWatch(data.save_task_id, saveTaskWatchOptions);
    } else if (
      Object.prototype.hasOwnProperty.call(data, 'updated_problematic_album')
      && responseOwnsVisibleResources
    ) {
      applyRepairResultToProblematicFiles(album, data.updated_problematic_album);
    }
    showRepairAlert(
      responseIsTerminal ? 'Tag changes saved.' : 'Tag changes queued. Finalizing library view...',
      'success',
      2000,
    );
    if (responseIsTerminal) {
      pendingProblematicEntry.accept();
      pendingProblematicEntry.settle();
      if (
        provisionalProblematicMutation
        && !completedResponseNeedsCanonicalRefresh
        && typeof settleProblematicSaveTaskMutation === 'function'
      ) {
        await settleProblematicSaveTaskMutation(
          String(provisionalProblematicMutation.taskId || ''),
          { reconcileSelection: true },
        );
      }
      if (!completedResponseNeedsCanonicalRefresh) {
        settleTagEditViewMutation(tagEditMutationClaim);
      }
    }
  } catch (error) {
    pendingProblematicEntry.settle();
    if (
      provisionalProblematicMutation
      && typeof settleProblematicSaveTaskMutation === 'function'
    ) {
      await settleProblematicSaveTaskMutation(
        String(provisionalProblematicMutation.taskId || ''),
      );
    }
    console.error('[AlbumHaven][Utilities] Failed to apply manual tag edits.', error);
    if (
      tagEditOriginStillOwnsView(originatingViewStateRevision)
      && tagEditViewMutationStillOwnsResources(tagEditMutationClaim)
    ) {
      const restoredAlbums = applyUpdatedAlbumsToCurrentView(
        [album],
        {
          skipRender: true,
          originalAlbum: album,
          preserveScroll: true,
          tagEdits: inverseUpdates,
        },
      );
      if (typeof applyTagEditsToNonAlbumView === 'function') {
        applyTagEditsToNonAlbumView(album, inverseUpdates);
      }
      updateOpenTrackModalAfterTagEdit(album, restoredAlbums);
      renderView(renderOptions);
    }
    showRepairAlert(
      'Failed to edit tags.',
      'error',
      null,
      {
        logHistoryEntryId: failedLogHistoryEntryId,
        logHistoryLink: Boolean(failedLogHistoryEntryId),
      },
    );
    releaseFailedTagEditViewMutation(tagEditMutationClaim);
  }
}


function flattenVisibleAlbums() {
  const sources = [state.view.primary_artist_groups, state.view.family_artist_groups, state.view.artist_groups];
  const seenGroups = new Set();
  const albums = [];
  sources.forEach((groups) => {
    (groups || []).forEach((group) => {
      const marker = `${group.artist}::${(group.albums || []).length}`;
      if (seenGroups.has(marker) && groups === state.view.artist_groups) return;
      seenGroups.add(marker);
      (group.albums || []).forEach((album) => albums.push(album));
    });
  });
  return albums;
}

function getVariantKeywordPattern() {
  return /(instrumental|remix|remaster|edition|special|deluxe|revisited|rerecord|version(?=\s*[\)\]\}]))/i;
}


function findVariantSuffixIndex(name) {
  const raw = String(name || '').trim();
  if (!raw) return -1;

  const keywordPattern = getVariantKeywordPattern();

  const bracketPatterns = [
    /\s*\(([^)]*)\)\s*$/i,
    /\s*\[([^\]]*)\]\s*$/i,
    /\s*\{([^}]*)\}\s*$/i,
  ];
  for (const pattern of bracketPatterns) {
    const match = raw.match(pattern);
    if (match && keywordPattern.test(match[1] || '')) {
      return match.index;
    }
  }

  const separatedPattern = /\s*[-:–—]\s*.*$/;
  const separatedMatch = raw.match(separatedPattern);
  if (separatedMatch && keywordPattern.test(separatedMatch[0] || '')) {
    return separatedMatch.index;
  }

  const wordPattern = /\S+/g;
  const words = [];
  let match;
  while ((match = wordPattern.exec(raw)) !== null) {
    words.push({
      text: match[0],
      index: match.index,
    });
  }

  for (let i = 1; i < words.length; i += 1) {
    const word = words[i].text || '';
    const bareWord = word.replace(/^[\(\[\{]+|[\)\]\}]+$/g, '');
    const nextWord = i + 1 < words.length ? (words[i + 1].text || '') : '';
    const startsVariant =
      keywordPattern.test(bareWord) ||
      (/^[\(\[\{]/.test(nextWord) && keywordPattern.test(nextWord));

    if (!startsVariant) continue;

    return words[i].index;
  }

  return -1;
}

function normalizeAlbumBaseName(name) {
  let text = String(name || '').trim();
  if (!text) return '';
  text = text
    .replace(/\s*\((?:19|20)\d{2}[^)]*\)$/i, '')
    .replace(/\s*\[(?:19|20)\d{2}[^\]]*\]$/i, '')
    .replace(/\s*\{(?:19|20)\d{2}[^}]*\}$/i, '');

  let previous = null;
  while (text && text !== previous) {
    previous = text;
    const suffixIndex = findVariantSuffixIndex(text);
    if (suffixIndex > 0) {
      text = text.slice(0, suffixIndex).trim();
    }
  }

  return text.replace(/\s+/g, ' ').trim().toLowerCase();
}

function isInstrumentalVariant(album) {
  const name = String((album && album.name) || '').toLowerCase();
  return /instrumental/i.test(name);
}

function extractVariantLabel(album, baseName, isFirst) {
  const yearSuffix = album.year ? ` - ${album.year}` : '';
  const instrumental = isInstrumentalVariant(album);

  const rawName = String(album.name || '').trim();
  const suffixIndex = findVariantSuffixIndex(rawName);

  let variant = '';
  if (suffixIndex > 0) {
    variant = rawName.slice(suffixIndex).trim();
  } else {
    const base = String(baseName || '').trim();
    variant = rawName;
    if (base) {
      const escapedBase = base.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      variant = variant.replace(new RegExp(`^${escapedBase}\\s*`, 'i'), '').trim();
    }
  }

  variant = variant
    .replace(/^[-:–—]+\s*/, '')
    .replace(/^\((.*)\)$/, '$1')
    .replace(/^\[(.*)\]$/, '$1')
    .replace(/^\{(.*)\}$/, '$1')
    .trim();

  const editionText = String(album.edition || '').trim();

  if (editionText) {
    if (instrumental && !/instrumental/i.test(editionText)) {
      return `${editionText} Instrumental${yearSuffix}`;
    }
    return `${editionText}${yearSuffix}`;
  }

  if (isFirst && !instrumental && !variant) {
    return `Original${yearSuffix}`;
  }

  if (!variant) {
    if (instrumental) return `Instrumental${yearSuffix}`;
    return album.year ? String(album.year) : 'Alternate Release';
  }

  return `${variant}${yearSuffix}`;
}

function isPlainAlbumVariant(album) {
  if (!album) return false;
  if (isInstrumentalVariant(album)) return false;
  if (String(album.edition || '').trim()) return false;
  return findVariantSuffixIndex(String(album.name || '').trim()) <= 0;
}

function pickOriginalAlbumVariant(albums, targetBase, rootKey = '') {
  const candidates = (albums || []).filter((item) => (
    isPlainAlbumVariant(item) && normalizeAlbumBaseName(item.name) === targetBase
  ));
  if (!candidates.length) {
    const rootedAlbum = (albums || []).find((item) => String(item?.key || '') === String(rootKey || ''));
    return rootedAlbum || null;
  }
  return sortAlbumVariants(candidates)[0] || null;
}

function compareAlbumVariants(a, b) {
  const ay = Number(a.year) || 0;
  const by = Number(b.year) || 0;
  if (ay !== by) return ay - by;

  const aPlain = isPlainAlbumVariant(a) ? 0 : 1;
  const bPlain = isPlainAlbumVariant(b) ? 0 : 1;
  if (aPlain !== bPlain) return aPlain - bPlain;

  const aReleaseDate = String(a.release_date || '');
  const bReleaseDate = String(b.release_date || '');
  if (aReleaseDate !== bReleaseDate) {
    if (!aReleaseDate) return 1;
    if (!bReleaseDate) return -1;
    return aReleaseDate.localeCompare(bReleaseDate, undefined, { sensitivity: 'base' });
  }

  const aInstrumental = isInstrumentalVariant(a) ? 1 : 0;
  const bInstrumental = isInstrumentalVariant(b) ? 1 : 0;
  if (aInstrumental !== bInstrumental) return aInstrumental - bInstrumental;

  const aEdition = String(a.edition || '');
  const bEdition = String(b.edition || '');
  const editionCmp = aEdition.localeCompare(bEdition, undefined, { sensitivity: 'base' });
  if (editionCmp !== 0) return editionCmp;

  return String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' });
}

function sortAlbumVariants(albums) {
  return [...albums].sort(compareAlbumVariants);
}

function getManualVersionLinks() {
  const links = state.view?.manual_version_links;
  return links && typeof links === 'object' ? links : {};
}

function resolveManualVersionRoot(albumKey, manualVersionLinks = getManualVersionLinks()) {
  let current = String(albumKey || '');
  const seen = new Set();
  while (current && !seen.has(current)) {
    seen.add(current);
    const parent = String(manualVersionLinks[current] || '');
    if (!parent) break;
    current = parent;
  }
  return current;
}

function getManualVersionFamilyKeys(albumKey, manualVersionLinks = getManualVersionLinks()) {
  const key = String(albumKey || '');
  if (!key) return new Set();
  const root = resolveManualVersionRoot(key, manualVersionLinks);
  const familyKeys = new Set([key, root]);
  Object.entries(manualVersionLinks).forEach(([childKey]) => {
    if (resolveManualVersionRoot(childKey, manualVersionLinks) === root) {
      familyKeys.add(String(childKey || ''));
    }
  });
  return new Set([...familyKeys].filter(Boolean));
}

function prioritizeManualVersionOrder(albums, rootKey, manualFamilyKeys) {
  const root = String(rootKey || '');
  const manualKeys = manualFamilyKeys instanceof Set ? manualFamilyKeys : new Set();
  const rootAlbums = [];
  const regularAlbums = [];
  const manualChildren = [];

  albums.forEach((item) => {
    const key = String(item?.key || '');
    if (key && key === root) {
      rootAlbums.push(item);
      return;
    }
    if (key && manualKeys.has(key)) {
      manualChildren.push(item);
      return;
    }
    regularAlbums.push(item);
  });

  return [...rootAlbums, ...regularAlbums, ...manualChildren];
}

function albumReleaseIdentity(album) {
  if (!album || typeof album !== 'object') return '';
  const key = String(album.key || '').trim();
  if (key) return `key:${key}`;
  const artist = String(album.album_artist || '').trim().toLowerCase();
  const name = String(album.name || '').trim().toLowerCase();
  const edition = String(album.edition || '').trim().toLowerCase();
  const year = String(album.year || '').trim().toLowerCase();
  return [artist, name, edition, year].some(Boolean)
    ? `fallback:${artist}::${name}::${edition}::${year}`
    : '';
}

function replaceMatchingReleaseCandidate(albums, preferredAlbum) {
  const preferredIdentity = albumReleaseIdentity(preferredAlbum);
  if (!preferredIdentity) {
    return Array.isArray(albums) ? [...albums] : [];
  }

  let replaced = false;
  const nextAlbums = (Array.isArray(albums) ? albums : []).map((item) => {
    if (albumReleaseIdentity(item) !== preferredIdentity) {
      return item;
    }
    replaced = true;
    return preferredAlbum;
  });

  if (!replaced) {
    nextAlbums.push(preferredAlbum);
  }
  return nextAlbums;
}

function getAlbumReleaseSet(album) {
  const visibleAlbums = flattenVisibleAlbums();
  const sameArtistAlbums = visibleAlbums.filter((item) => String(item.album_artist || '') === String(album.album_artist || ''));
  const ignoredVersionKeys = new Set(Array.isArray(state.view.ignored_version_keys) ? state.view.ignored_version_keys.map(String) : []);
  const manualVersionLinks = getManualVersionLinks();
  const manualFamilyKeys = getManualVersionFamilyKeys(String(album.key || ''), manualVersionLinks);
  const hasManualFamily = manualFamilyKeys.size > 1;
  if (ignoredVersionKeys.has(String(album.key || '')) && !hasManualFamily) {
    return {
      releases: [{
        ...album,
        tabLabel: extractVariantLabel(album, album.name || 'Album', true),
      }],
      selectedIndex: 0,
    };
  }
  const targetBase = normalizeAlbumBaseName(album.name);
  const grouped = [];
  if (hasManualFamily) {
    visibleAlbums.forEach((item) => {
      if (manualFamilyKeys.has(String(item.key || ''))) {
        grouped.push(item);
      }
    });
  }
  sameArtistAlbums.forEach((item) => {
    if (
      normalizeAlbumBaseName(item.name) === targetBase
      && !ignoredVersionKeys.has(String(item.key || ''))
    ) {
      grouped.push(item);
    }
  });
  const deduped = [];
  const seen = new Set();
  grouped.forEach((item) => {
    const key = item.key || `${item.album_artist}::${item.name}::${item.year || ''}::${item.edition || ''}`;
    if (!seen.has(key)) {
      seen.add(key);
      deduped.push(item);
    }
  });
  const dedupedWithPreferredAlbum = replaceMatchingReleaseCandidate(deduped, album);
  const rootKey = hasManualFamily ? resolveManualVersionRoot(String(album.key || ''), manualVersionLinks) : '';
  const sortedVariants = prioritizeManualVersionOrder(
    sortAlbumVariants(dedupedWithPreferredAlbum.length ? dedupedWithPreferredAlbum : [album]),
    rootKey,
    manualFamilyKeys,
  );
  const rootAlbum = pickOriginalAlbumVariant(sortedVariants, targetBase, rootKey) || sortedVariants[0] || album;
  const variants = [
    rootAlbum,
    ...sortedVariants.filter((item) => String(item?.key || '') !== String(rootAlbum?.key || '')),
  ];
  const baseDisplayName = rootAlbum?.name || variants[0]?.name || album.name || 'Album';
  const releases = variants.map((item, index) => ({
    ...item,
    tabLabel: extractVariantLabel(item, baseDisplayName, index === 0),
  }));
  const selectedIndex = Math.max(0, releases.findIndex((item) => item.key === album.key));
  return { releases, selectedIndex };
}

function isPlainDuplicateVersionTab(release, index, releases) {
  if (index <= 0 || !release || !Array.isArray(releases) || !releases.length) return false;
  const original = releases[0] || {};
  const releaseName = String(release.name || '').trim();
  const originalName = String(original.name || '').trim();
  if (!releaseName || releaseName.localeCompare(originalName, undefined, { sensitivity: 'base' }) !== 0) return false;
  if (String(release.edition || '').trim()) return false;
  if (isInstrumentalVariant(release)) return false;
  if (findVariantSuffixIndex(releaseName) > 0) return false;
  return true;
}

async function ignoreAlbumVersion(albumKey) {
  const key = String(albumKey || '');
  if (!key) return;
  try {
    const response = await fetch('/versions/ignore', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ album_key: key }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to update version setting');
    }
    mergeViewPayload({
      ignored_version_keys: Array.isArray(data.ignored_version_keys) ? data.ignored_version_keys : [],
    }, { trackSidebarReveal: false });
    state.utility.rulesLoaded = false;
    hideVersionContextMenu();
    const currentAlbum = state.modalReleases[state.modalReleaseIndex] || null;
    if (currentAlbum) {
      const releaseSet = getAlbumReleaseSet(currentAlbum);
      state.modalReleases = releaseSet.releases;
      state.modalReleaseIndex = Math.min(releaseSet.selectedIndex, Math.max(0, state.modalReleases.length - 1));
      renderTrackModalRelease(state.modalReleases[state.modalReleaseIndex]);
    }
    await fetchAndRender(buildApiUrl(state.view), false);
    showToast('Album will no longer be counted as a version.', 'success', 2600);
  } catch (error) {
    console.error('[AlbumHaven][Versions] Failed to ignore album version.', error);
    showToast(error.message || 'Failed to update version setting.', 'error', 3200);
  }
}

function refreshOpenTrackModalVersionState(preferredAlbumKey = '') {
  const trackModal = document.getElementById('track-modal');
  if (!trackModal || trackModal.hidden) return;
  const currentKey = String(preferredAlbumKey || state.modalReleases[state.modalReleaseIndex]?.key || '');
  const visibleAlbums = flattenVisibleAlbums();
  const currentAlbum = visibleAlbums.find((item) => String(item.key || '') === currentKey)
    || state.modalReleases[state.modalReleaseIndex]
    || visibleAlbums[0]
    || null;
  if (!currentAlbum) return;
  const releaseSet = getAlbumReleaseSet(currentAlbum);
  state.modalReleases = releaseSet.releases;
  state.modalReleaseIndex = Math.min(releaseSet.selectedIndex, Math.max(0, state.modalReleases.length - 1));
  renderTrackModalRelease(state.modalReleases[state.modalReleaseIndex]);
}

async function markAlbumVersion(albumKey, parentAlbumKey) {
  const childKey = String(albumKey || '');
  const targetKey = String(parentAlbumKey || '');
  if (!childKey || !targetKey || childKey === targetKey) return;
  try {
    const response = await fetch('/versions/mark', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ album_key: childKey, parent_album_key: targetKey }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to mark album as a version');
    }
    mergeViewPayload({
      manual_version_links: data.manual_version_links && typeof data.manual_version_links === 'object'
        ? data.manual_version_links
        : {},
    }, { trackSidebarReveal: false });
    refreshOpenTrackModalVersionState(childKey);
    await fetchAndRender(buildApiUrl(state.view), false);
    showToast('Album marked as a version.', 'success', 2600);
  } catch (error) {
    console.error('[AlbumHaven][Versions] Failed to mark album as a version.', error);
    showToast(error.message || 'Failed to mark album as a version.', 'error', 3200);
    throw error;
  }
}

async function unmarkAlbumVersion(albumKey) {
  const key = String(albumKey || '');
  if (!key) return;
  try {
    const response = await fetch('/versions/unmark', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ album_key: key }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to unmark album version');
    }
    mergeViewPayload({
      manual_version_links: data.manual_version_links && typeof data.manual_version_links === 'object'
        ? data.manual_version_links
        : {},
    }, { trackSidebarReveal: false });
    refreshOpenTrackModalVersionState(key);
    await fetchAndRender(buildApiUrl(state.view), false);
    showToast('Album is no longer manually marked as a version.', 'success', 2600);
  } catch (error) {
    console.error('[AlbumHaven][Versions] Failed to unmark album version.', error);
    showToast(error.message || 'Failed to unmark album version.', 'error', 3200);
    throw error;
  }
}

async function revertVersionException(albumKey) {
  const key = String(albumKey || '');
  if (!key) return;
  try {
    const response = await fetch('/utilities/rules/version-exceptions/revert', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ album_key: key }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to revert rule');
    }
    state.utility.rules = Array.isArray(data.rules) ? data.rules : [];
    state.utility.rulesLoaded = true;
    if (Array.isArray(data.ignored_version_keys)) {
      mergeViewPayload({
        ignored_version_keys: data.ignored_version_keys,
      }, { trackSidebarReveal: false });
    }
    renderUtilityModalContent();
    await fetchAndRender(buildApiUrl(state.view), false);
    showToast('Rule reverted.', 'success', 2400);
  } catch (error) {
    console.error('[AlbumHaven][Utilities] Failed to revert rule.', error);
    showToast(error.message || 'Failed to revert rule.', 'error', 3200);
  }
}

async function revertProblemIgnore(item) {
  if (!item || !String(item.row_key || '').trim()) return;
  await queueProblemExclusionRevert(item);
}

function renderTrackModalTabs(els) {
  if (!els.tabs) return;
  const releases = state.modalReleases || [];
  if (releases.length <= 1) {
    els.tabs.hidden = true;
    els.tabs.innerHTML = '';
    hideVersionContextMenu();
    return;
  }
  els.tabs.hidden = false;
  els.tabs.innerHTML = releases.map((release, index) => {
    const showVersionMenu = isPlainDuplicateVersionTab(release, index, releases);
    return `
      <span class="track-modal-tab-wrap">
        <button class="track-modal-tab ${index === state.modalReleaseIndex ? 'is-active' : ''}" type="button" data-track-tab-index="${index}" ${showVersionMenu ? `data-version-context-key="${escapeHtml(release.key || '')}"` : ''}>${escapeHtml(release.tabLabel)}</button>
      </span>
    `;
  }).join('');
  renderVersionContextMenu();
}

function ensureVersionContextMenu() {
  let menu = document.getElementById('track-modal-version-context-menu');
  if (menu) return menu;
  menu = document.createElement('div');
  menu.id = 'track-modal-version-context-menu';
  menu.className = 'track-modal-version-context-menu';
  menu.hidden = true;
  menu.innerHTML = '<button type="button" data-ignore-version-context="1">Don\'t count as a version</button>';
  document.body.appendChild(menu);
  return menu;
}

function renderVersionContextMenu() {
  const menu = ensureVersionContextMenu();
  const stateMenu = state.modalVersionContextMenu || {};
  if (!stateMenu.visible || !stateMenu.albumKey) {
    menu.hidden = true;
    return;
  }
  menu.style.left = `${stateMenu.x}px`;
  menu.style.top = `${stateMenu.y}px`;
  menu.dataset.albumKey = stateMenu.albumKey;
  menu.hidden = false;
}

function showVersionContextMenu(albumKey, x, y) {
  state.modalVersionContextMenu = {
    albumKey: String(albumKey || ''),
    x,
    y,
    visible: true,
  };
  renderVersionContextMenu();
}

function hideVersionContextMenu() {
  state.modalVersionContextMenu = {
    albumKey: '',
    x: 0,
    y: 0,
    visible: false,
  };
  const menu = document.getElementById('track-modal-version-context-menu');
  if (menu) menu.hidden = true;
}

function buildCoverLookupButtonIcon() {
  return `
    <span class="track-modal-cover-tool-icon track-modal-cover-tool-icon-lookup" aria-hidden="true">
      <img class="track-modal-cover-tool-icon-default" src="/static/images/cover-lookup-gallery-icon-offwhite.png" alt="">
      <img class="track-modal-cover-tool-icon-hover" src="/static/images/cover-lookup-gallery-icon.png" alt="">
    </span>
  `;
}

function buildFastCoverFetchButtonIcon() {
  return `
    <span class="track-modal-cover-tool-icon track-modal-cover-tool-icon-fast-fetch" aria-hidden="true">
      <img class="track-modal-cover-tool-icon-default" src="/static/images/quick-search-icon-offwhite.png" alt="">
      <img class="track-modal-cover-tool-icon-hover" src="/static/images/quick-search-icon.png" alt="">
    </span>
  `;
}

function buildTrackModalCoverVisualHtml({
  albumName,
  localCoverPath,
  remoteCoverUrl,
}) {
  return `
    <span class="track-modal-cover-visual is-loading">
      <span class="cover-placeholder" aria-hidden="true"></span>
      <img
        alt="Album cover for ${escapeHtml(albumName)}"
        data-cover-path="${escapeHtml(localCoverPath)}"
        data-remote-cover-url="${escapeHtml(remoteCoverUrl)}"
        data-cover-visual-state="pending"
        aria-hidden="true"
        onload="handleTrackModalCoverImageLoad(this)"
        onerror="handleAlbumDisplayCoverImageError(this)">
    </span>
  `;
}

function handleTrackModalCoverImageLoad(imageElement) {
  if (!(imageElement instanceof HTMLImageElement)) return;
  if (typeof handleAlbumDisplayCoverImageLoad === 'function') {
    handleAlbumDisplayCoverImageLoad(imageElement);
  }
  const visual = imageElement.closest('.track-modal-cover-visual');
  if (visual instanceof HTMLElement) {
    visual.classList.remove('is-loading');
  }
}

function getAlbumDuplicateSources(album) {
  return Array.isArray(album?.duplicate_sources) ? album.duplicate_sources.filter((source) => source && Array.isArray(source.tracks)) : [];
}

function getTrackModalDuplicateSourceIndex(album, duplicateSources) {
  const albumKey = String(album?.key || '');
  const savedIndex = Number(state.modalDuplicateSourceIndices?.[albumKey]);
  if (Number.isInteger(savedIndex) && savedIndex >= 0 && savedIndex < duplicateSources.length) {
    return savedIndex;
  }
  return 0;
}

function setTrackModalDuplicateSourceIndex(albumKey, sourceIndex) {
  const key = String(albumKey || '');
  if (!key) return;
  if (!state.modalDuplicateSourceIndices || typeof state.modalDuplicateSourceIndices !== 'object') {
    state.modalDuplicateSourceIndices = {};
  }
  state.modalDuplicateSourceIndices[key] = sourceIndex;
}

function getTrackModalAlbumRequestKey(album) {
  if (typeof getAlbumRequestKey === 'function') {
    return String(getAlbumRequestKey(album) || '').trim();
  }
  return String(album?.key || album?.album_ref || '').trim();
}

function getTrackModalAlbumIdentity(album) {
  if (typeof getAlbumIdentity === 'function') {
    return String(getAlbumIdentity(album) || '').trim();
  }
  return getTrackModalAlbumRequestKey(album);
}

function renderTrackModalRelease(album) {
  const els = getTrackModalElements();
  if (!els.overlay || !album) return;
  const resolvedAlbumKey = getTrackModalAlbumRequestKey(album) || getTrackModalAlbumIdentity(album) || String(album?.key || '');
  const albumKey = escapeHtml(resolvedAlbumKey);
  const candidateSnapshot = album?.cover_candidate_snapshot && typeof album.cover_candidate_snapshot === 'object'
    ? album.cover_candidate_snapshot
    : null;
  const hasUnseenAutomaticImprovement = Boolean(
    candidateSnapshot
    && String(candidateSnapshot.search_kind || '') === 'automatic'
    && candidateSnapshot.has_unseen_automatic_improvement
  );
  const coverLookupClass = hasUnseenAutomaticImprovement
    ? 'track-modal-cover-tool is-lookup has-unseen-automatic-improvement'
    : 'track-modal-cover-tool is-lookup';
  const coverLookupLabel = hasUnseenAutomaticImprovement
    ? 'Open cover art look up gallery; new automatic cover candidate available'
    : 'Open cover art look up gallery';
  const coverLookupIcon = buildCoverLookupButtonIcon();
  const fastCoverFetchIcon = buildFastCoverFetchButtonIcon();
  const coverSourceBadge = typeof buildTrackModalCoverSourceBadge === 'function'
    ? buildTrackModalCoverSourceBadge(album?.remote_cover_source || '')
    : '';
  const headerParts = [album.album_artist || '', album.name || 'Album', album.year || ''].filter(Boolean);
  els.title.textContent = headerParts.join(' - ');
  els.subtitle.textContent = '';
  if (els.folder) {
    els.folder.dataset.album = '';
    els.folder.dataset.albumKey = resolvedAlbumKey;
  }
  if (els.editTags) {
    els.editTags.dataset.album = '';
    els.editTags.dataset.albumKey = resolvedAlbumKey;
  }
  if (albumHasDisplayCover(album)) {
    const coverSrc = buildAlbumDisplayCoverUrl(album);
    const lightboxSrc = typeof buildAlbumLightboxCoverUrl === 'function'
      ? buildAlbumLightboxCoverUrl(album)
      : coverSrc;
    const canInspectHtmlElements = typeof HTMLElement !== 'undefined' && typeof HTMLImageElement !== 'undefined';
    const existingCoverImage = canInspectHtmlElements && els.cover instanceof HTMLElement
      ? els.cover.querySelector('img')
      : null;
    const existingProductionSrc = canInspectHtmlElements && existingCoverImage instanceof HTMLImageElement
      ? String(existingCoverImage.getAttribute('data-production-cover-src') || '').trim()
      : '';
    const reusableCoverImage = canInspectHtmlElements && existingCoverImage instanceof HTMLImageElement
      && (
        existingProductionSrc === coverSrc
        ||
        existingCoverImage.getAttribute('src') === coverSrc
        || existingCoverImage.currentSrc === new URL(coverSrc, window.location.href).href
      )
      ? existingCoverImage
      : null;
    const localCoverPathRaw = String(album?.cover_path || '').trim();
    const remoteCoverUrlRaw = String(album?.remote_cover_thumbnail_url || album?.remote_cover_url || '').trim();
    const localCoverPath = escapeHtml(localCoverPathRaw);
    const remoteCoverUrl = escapeHtml(remoteCoverUrlRaw);
    const lightboxGalleryAttribute = state.ui?.trackModalCoverLightboxGallery === false
      ? ''
      : ' data-lightbox-gallery="visible"';
    els.cover.innerHTML = `
      <div class="track-modal-cover-shell">
        <button class="track-modal-cover-button" type="button" data-open-lightbox="1" data-cover-src="${escapeHtml(lightboxSrc)}" data-cover-preview-src="${escapeHtml(coverSrc)}" data-cover-alt="${escapeHtml(`Album cover for ${album.name}`)}" data-album-key="${albumKey}"${lightboxGalleryAttribute}><span class="track-modal-cover-image-slot"></span></button>
        ${coverSourceBadge}
        <div class="track-modal-cover-tools">
          <button class="${coverLookupClass}" type="button" data-open-track-modal-cover-lookup="1" data-album-key="${albumKey}" aria-label="${coverLookupLabel}" title="Cover Art Look Up">
            ${coverLookupIcon}
          </button>
          <button class="track-modal-cover-tool is-fast-fetch" type="button" data-track-modal-fast-cover-fetch="1" data-album-key="${albumKey}" aria-label="Fetch cover art now" title="Fast Cover Fetch">
            ${fastCoverFetchIcon}
          </button>
        </div>
      </div>
    `;
    const coverImageSlot = typeof els.cover?.querySelector === 'function'
      ? els.cover.querySelector('.track-modal-cover-image-slot')
      : null;
    if (canInspectHtmlElements && coverImageSlot instanceof HTMLElement) {
      let modalCoverImage = null;
      if (reusableCoverImage instanceof HTMLImageElement) {
        const visual = document.createElement('span');
        visual.classList.add('track-modal-cover-visual');
        const coverIsPending = (
          reusableCoverImage.getAttribute('data-cover-visual-state') !== 'ready'
          || !reusableCoverImage.complete
          || reusableCoverImage.naturalWidth <= 0
        );
        if (coverIsPending) {
          visual.classList.add('is-loading');
          const placeholder = document.createElement('span');
          placeholder.classList.add('cover-placeholder');
          placeholder.setAttribute('aria-hidden', 'true');
          visual.appendChild(placeholder);
        }
        reusableCoverImage.setAttribute('data-cover-path', localCoverPathRaw);
        reusableCoverImage.setAttribute('data-remote-cover-url', remoteCoverUrlRaw);
        reusableCoverImage.setAttribute('alt', `Album cover for ${String(album?.name || '')}`);
        visual.appendChild(reusableCoverImage);
        coverImageSlot.replaceWith(visual);
        modalCoverImage = reusableCoverImage;
      } else {
        coverImageSlot.outerHTML = buildTrackModalCoverVisualHtml({
          albumName: String(album?.name || ''),
          localCoverPath: localCoverPathRaw,
          remoteCoverUrl: remoteCoverUrlRaw,
        });
        modalCoverImage = els.cover.querySelector('.track-modal-cover-visual img');
      }
      if (
        !reusableCoverImage
        && modalCoverImage instanceof HTMLImageElement
        && typeof loadGalleryCoverPreviewImage === 'function'
      ) {
        const ownsCurrentModalCover = () => {
          if (els.overlay.hidden || !modalCoverImage.isConnected) return false;
          if (els.cover.querySelector('.track-modal-cover-visual img') !== modalCoverImage) return false;
          const currentAlbum = state.modalReleases[state.modalReleaseIndex] || null;
          return getTrackModalAlbumRequestKey(currentAlbum) === resolvedAlbumKey;
        };
        void loadGalleryCoverPreviewImage(modalCoverImage, coverSrc, {
          isCurrent: ownsCurrentModalCover,
        }).catch((error) => {
          if (!ownsCurrentModalCover()) return;
          console.error('[AlbumHaven][Covers] Failed to load the track-modal cover preview.', error);
          handleAlbumDisplayCoverImageError(modalCoverImage);
        });
      }
    }
  } else {
    els.cover.innerHTML = `
      <div class="track-modal-cover-shell">
        <div class="cover-placeholder">No cover art</div>
        <div class="track-modal-cover-tools">
          <button class="${coverLookupClass}" type="button" data-open-track-modal-cover-lookup="1" data-album-key="${albumKey}" aria-label="${coverLookupLabel}" title="Cover Art Look Up">
            ${coverLookupIcon}
          </button>
          <button class="track-modal-cover-tool is-fast-fetch" type="button" data-track-modal-fast-cover-fetch="1" data-album-key="${albumKey}" aria-label="Fetch cover art now" title="Fast Cover Fetch">
            ${fastCoverFetchIcon}
          </button>
        </div>
      </div>
    `;
  }
  const duplicateSources = getAlbumDuplicateSources(album);
  const duplicateSourceIndex = getTrackModalDuplicateSourceIndex(album, duplicateSources);
  const activeDuplicateSource = duplicateSources[duplicateSourceIndex] || null;
  const tracks = Array.isArray(activeDuplicateSource?.tracks)
    ? activeDuplicateSource.tracks
    : (Array.isArray(album.tracks) ? album.tracks : []);
  const grouped = groupAlbumTracks(tracks);
  const bonusGroups = grouped.groups.filter((group) => group.isBonus);
  const mainGroups = grouped.groups.filter((group) => !group.isBonus);
  const mainSeconds = mainGroups.reduce((sum, group) => sum + group.tracks.reduce((inner, track) => inner + (Number(track.duration_seconds) || 0), 0), 0);
  const bonusSeconds = bonusGroups.reduce((sum, group) => sum + group.tracks.reduce((inner, track) => inner + (Number(track.duration_seconds) || 0), 0), 0);
  const totalLength = activeDuplicateSource?.total_duration_display || album.total_duration_display || formatAlbumDuration(album.total_duration_seconds);
  const mainLength = formatAlbumDuration(mainSeconds) || (mainGroups.length ? totalLength : '');
  const bonusLength = formatAlbumDuration(bonusSeconds);
  if (els.duplicateWarning && els.duplicateTabs) {
    if (duplicateSources.length > 1) {
      els.duplicateWarning.hidden = false;
      els.duplicateWarning.innerHTML = `
        <span>Album seems to have duplicate files:</span>
        <span class="track-modal-duplicate-warning-icons">
          ${duplicateSources.map((source, index) => {
            const isActive = index === duplicateSourceIndex;
            const folderTitle = escapeHtml(String(source.folder_path || source.folder_name || `Folder ${index + 1}`));
            return `
              <button
                type="button"
                class="track-modal-duplicate-folder-button ${isActive ? 'is-active' : ''}"
                data-open-track-modal-duplicate-folder="1"
                data-album-key="${albumKey}"
                data-duplicate-source-index="${index}"
                title="${folderTitle}">
                <span class="track-modal-duplicate-folder-icon" aria-hidden="true">📁</span>
                <span class="track-modal-duplicate-folder-badge">${index + 1}</span>
              </button>
            `;
          }).join('')}
        </span>
      `;
      els.duplicateTabs.hidden = false;
      els.duplicateTabs.innerHTML = duplicateSources.map((source, index) => {
        const isActive = index === duplicateSourceIndex;
        const sourceTitle = escapeHtml(String(source.folder_path || source.folder_name || `Location ${index + 1}`));
        return `
          <button
            class="track-modal-duplicate-tab ${isActive ? 'is-active' : ''}"
            type="button"
            data-track-duplicate-source-index="${index}"
            title="${sourceTitle}">
            Files ${index + 1}
          </button>
        `;
      }).join('');
    } else {
      els.duplicateWarning.hidden = true;
      els.duplicateWarning.innerHTML = '';
      els.duplicateTabs.hidden = true;
      els.duplicateTabs.innerHTML = '';
    }
  }
  els.list.innerHTML = buildTrackListHtml(tracks, album);
  if (els.footer) {
    if (bonusGroups.length > 0) {
      els.footer.innerHTML = `${mainLength ? `<div>Total Main Album Length: ${escapeHtml(mainLength)}</div>` : ''}<div>Bonus Disc Length: ${escapeHtml(bonusLength)}</div>`;
      els.footer.hidden = false;
    } else {
      els.footer.textContent = totalLength ? `Total Length: ${totalLength}` : '';
      els.footer.hidden = !totalLength;
    }
  }
  renderTrackModalTabs(els);
  refreshTrackModalPlaybackState();
}


function formatDiscDisplayLabel(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const cleaned = raw.replace(/\s+/g, ' ').trim();
  if (/\b(?:disc|cd)\b/i.test(cleaned)) {
    return cleaned;
  }
  return `${cleaned} Disc`;
}

function getTrackDiscLabel(track) {
  const raw = String((track && track.disc_number_raw) || '').trim();
  if (raw) {
    const firstPart = raw.split('/')[0].trim();
    if (firstPart) {
      if (/^\d+$/.test(firstPart)) {
        return `CD${firstPart}`;
      }
      return formatDiscDisplayLabel(firstPart);
    }
  }
  const numeric = Number(track && track.disc_number);
  if (Number.isFinite(numeric) && numeric > 0) {
    return `CD${numeric}`;
  }
  return '';
}

function isBonusDiscTrack(track) {
  const rawDisc = String((track && track.disc_number_raw) || '').trim();
  if (!rawDisc) return false;
  return /\b(bonus|extra|extras|instrumental|instrumentals|demo|demos|outtake|outtakes|rarity|rarities|interview|alternate version|alternate take)\b/i.test(rawDisc);
}


function groupAlbumTracks(tracks) {
  const safeTracks = orderAlbumTracks(tracks);

  const explicitDiscs = Array.from(new Set(
    safeTracks
      .map((track) => Number(track.disc_number))
      .filter((disc) => Number.isInteger(disc) && disc > 0)
  )).sort((a, b) => a - b);

  const explicitLabels = Array.from(new Set(
    safeTracks
      .map((track) => getTrackDiscLabel(track))
      .filter(Boolean)
  ));

  const hasExplicitCd1 = explicitDiscs.includes(1);
  const hasLaterExplicitDiscs = explicitDiscs.some((disc) => disc > 1);
  const inferredCd1FromMissingTags = hasLaterExplicitDiscs && !hasExplicitCd1;

  const groups = new Map();

  safeTracks.forEach((track) => {
    const numericDisc = Number(track.disc_number);
    let discLabel = getTrackDiscLabel(track);
    let effectiveDisc = Number.isInteger(numericDisc) && numericDisc > 0 ? numericDisc : null;

    if (!discLabel && inferredCd1FromMissingTags) {
      discLabel = 'CD1';
      effectiveDisc = 1;
    }

    const key = discLabel || (effectiveDisc ? `CD${effectiveDisc}` : 'single');
    if (!groups.has(key)) {
      groups.set(key, {
        key,
        discNumber: effectiveDisc,
        discLabel: key === 'single' ? '' : key,
        isBonus: false,
        tracks: [],
      });
    }
    const group = groups.get(key);
    group.isBonus = group.isBonus || isBonusDiscTrack(track);
    group.tracks.push(track);
  });

  const orderedKeys = Array.from(groups.keys()).sort((a, b) => {
    const ga = groups.get(a);
    const gb = groups.get(b);
    if (a === 'single') return -1;
    if (b === 'single') return 1;
    if (ga.discNumber != null && gb.discNumber != null && ga.discNumber !== gb.discNumber) {
      return ga.discNumber - gb.discNumber;
    }
    if (ga.discNumber != null && gb.discNumber == null) return -1;
    if (ga.discNumber == null && gb.discNumber != null) return 1;
    return String(ga.discLabel || '').localeCompare(String(gb.discLabel || ''), undefined, { sensitivity: 'base' });
  });

  const multiDisc = orderedKeys.length > 1;

  return {
    multiDisc,
    inferredCd1FromMissingTags,
    groups: orderedKeys.map((key) => ({
      discNumber: groups.get(key).discNumber,
      discLabel: groups.get(key).discLabel,
      isBonus: Boolean(groups.get(key).isBonus),
      tracks: groups.get(key).tracks,
    })),
  };
}


function buildTrackListHtml(tracks, album = null) {
  const grouped = groupAlbumTracks(tracks);
  const parts = [];
  const playback = getPlayerPlaybackSnapshot();
  const currentTrackPath = String(state.player.current?.path || '');
  const trackRows = Array.isArray(album?.track_rows) ? album.track_rows : [];
  const trackRowByPath = new Map(
    trackRows
      .map((row) => {
        const rowPath = String(row?.path || row?.track_ref || '').trim();
        return rowPath ? [rowPath, row] : null;
      })
      .filter(Boolean)
  );

  grouped.groups.forEach((group) => {
    const groupSeconds = group.tracks.reduce((sum, track) => sum + (Number(track.duration_seconds) || 0), 0);
    const groupLength = formatAlbumDuration(groupSeconds);

    if (grouped.multiDisc && (group.discLabel || (Number.isInteger(group.discNumber) && group.discNumber > 0))) {
      let label = group.discLabel || `CD${group.discNumber}`;
      if (group.isBonus) {
        label += ` • Bonus Disc`;
      }
      if (group.discSubtitle) {
        label += ` · ${escapeHtml(group.discSubtitle)}`;
      }
      parts.push(`<li class="track-disc-header">${label}</li>`);
    }

    group.tracks.forEach((track, index) => {
      const src = `/track?path=${encodeURIComponent(track.path)}`;
      const duration = formatTrackDuration(track.duration_seconds);
      const trackPath = String(track.path || '');
      const isCurrentTrack = currentTrackPath && currentTrackPath === trackPath;
      const isActivelyPlaying = isCurrentTrack && !playback.paused && !playback.ended;
      const currentTimeDisplay = isCurrentTrack
        ? `${formatLoopTime(playback.currentTime || 0)} / ${duration || formatTrackDuration(playback.duration) || '0:00'}`
        : duration;
      const durationMarkup = currentTimeDisplay
        ? `<span class="track-duration" data-track-duration-path="${escapeHtml(trackPath)}" data-original-duration="${escapeHtml(duration || '')}">${escapeHtml(currentTimeDisplay)}</span>`
        : (duration ? `<span class="track-duration">${escapeHtml(duration)}</span>` : '');
      const trackValue = getAlbumTrackDisplayNumber(track, index);
      const utilityJump = track.is_problematic
        ? `<button class="track-problem-link" type="button" data-open-track-problematic="1" data-track-path="${escapeHtml(track.path)}" title="Open this track in Problematic Files" aria-label="Open this track in Problematic Files">!</button>`
        : '';
      const trackRow = trackRowByPath.get(trackPath) || null;
      const displayTitle = String(trackRow?.title || track.title || '').trim();
      const secondaryArtist = String(trackRow?.secondary_artist || '').trim();
      const trackArtistLabel = secondaryArtist
        ? `<span class="track-artist-name">${escapeHtml(secondaryArtist)}</span>`
        : '';
      parts.push(`<li value="${trackValue}" data-track-row-path="${escapeHtml(trackPath)}" class="${isCurrentTrack ? 'is-current' : ''}${isActivelyPlaying ? ' is-playing' : ''}"><span class="track-number">${trackValue}.</span><button class="play-track-button" data-src="${src}" data-track-path="${escapeHtml(track.path)}" data-track-title="${escapeHtml(track.title || '')}" data-track-artist="${escapeHtml(track.artist || track.album_artist || '')}" data-track-album-artist="${escapeHtml(track.album_artist || album?.album_artist || '')}" data-track-album="${escapeHtml(track.album || '')}" data-track-cover="${escapeHtml(track.cover_path || '')}" data-track-duration-seconds="${Number(track.duration_seconds) || 0}" type="button" aria-label="${isActivelyPlaying ? 'Pause track' : 'Play track'}">${isActivelyPlaying ? '&#x23F8;' : '&#x25B6;'}</button><span class="track-title">${escapeHtml(displayTitle)}${trackArtistLabel}</span>${utilityJump}${durationMarkup}</li>`);
    });

    if (grouped.multiDisc && groupLength) {
      const lengthLabel = group.isBonus ? 'Bonus Disc Length' : 'Total Length';
      parts.push(`<li class="track-disc-total">${lengthLabel}: ${escapeHtml(groupLength)}</li>`);
    }
  });

  return parts.join('');
}

function buildPlayerTrackPayload(track, album = null) {
  if (!track) return null;
  return {
    src: `/track?path=${encodeURIComponent(track.path)}`,
    path: String(track.path || ''),
    title: track.title || 'Track',
    artist: track.artist || track.album_artist || '',
    albumArtist: track.album_artist || album?.album_artist || '',
    album: track.album || '',
    coverPath: track.cover_path || '',
    durationSeconds: Number(track.duration_seconds) || 0,
  };
}

function getAlbumPlaybackQueueRef(album) {
  if (typeof getAlbumIdentity === 'function') {
    return String(getAlbumIdentity(album) || album?.key || '').trim();
  }
  return String(album?.key || '').trim();
}

function getAlbumPlaybackContext(album) {
  if (album?.playback_context && typeof album.playback_context === 'object') {
    return album.playback_context;
  }
  const playbackContext = state?.view?.playback_context;
  if (!playbackContext || typeof playbackContext !== 'object') return null;
  const albumRef = getAlbumPlaybackQueueRef(album);
  const orderedAlbumRefs = Array.isArray(playbackContext.ordered_album_refs)
    ? playbackContext.ordered_album_refs.map((value) => String(value || '').trim()).filter(Boolean)
    : [];
  if (!albumRef || !orderedAlbumRefs.includes(albumRef)) return null;
  return playbackContext;
}

function buildQueueTracksForAlbum(album, startingTrackPath = '') {
  const tracks = Array.isArray(album?.tracks) ? album.tracks : [];
  const grouped = groupAlbumTracks(tracks);
  const matchingGroup = grouped.groups.find((group) => (
    Array.isArray(group.tracks) && group.tracks.some((track) => String(track.path || '') === String(startingTrackPath || ''))
  ));
  const fallbackGroup = grouped.groups.find((group) => Array.isArray(group.tracks) && group.tracks.length);
  const queueTracks = Array.isArray((matchingGroup || fallbackGroup)?.tracks)
    ? (matchingGroup || fallbackGroup).tracks.map((track) => buildPlayerTrackPayload(track, album)).filter(Boolean)
    : [];
  const currentIndex = queueTracks.findIndex((track) => String(track.path || '') === String(startingTrackPath || ''));
  return {
    tracks: queueTracks,
    currentIndex: currentIndex >= 0 ? currentIndex : 0,
  };
}

function buildAlbumPlaybackQueueState(album, startingTrackPath = '', playbackContext = null) {
  const queueState = buildQueueTracksForAlbum(album, startingTrackPath);
  if (!queueState.tracks.length) return null;
  return {
    tracks: queueState.tracks,
    currentIndex: queueState.currentIndex,
    playbackContext: playbackContext || null,
    albumRef: getAlbumPlaybackQueueRef(album),
    albumSnapshot: album,
  };
}

function canPlaybackContextAlbumContinue(playbackContext, albumRef) {
  const normalizedAlbumRef = String(albumRef || '').trim();
  if (!normalizedAlbumRef) return false;
  const albums = Array.isArray(playbackContext?.albums) ? playbackContext.albums : [];
  const albumEntry = albums.find((item) => String(item?.album_ref || '').trim() === normalizedAlbumRef);
  if (albumEntry) {
    return Boolean(albumEntry.can_play);
  }
  return true;
}

function findPlaybackContextAlbumByRef(albumRef) {
  const normalizedAlbumRef = String(albumRef || '').trim();
  if (!normalizedAlbumRef) return null;
  return flattenVisibleAlbums().find((album) => (
    getAlbumPlaybackQueueRef(album) === normalizedAlbumRef
  )) || null;
}

function resolveNextPlaybackContextQueue(queue) {
  const playbackContext = queue?.playbackContext;
  if (
    typeof canEmitPlaybackSessionSideEffects === 'function'
    && !canEmitPlaybackSessionSideEffects()
  ) {
    return null;
  }
  const resolvedEndBehavior = typeof resolveGalleryPlaybackEndBehavior === 'function'
    ? resolveGalleryPlaybackEndBehavior(playbackContext)
    : String(playbackContext?.end_behavior || '').trim().toLowerCase();
  if (!playbackContext || resolvedEndBehavior !== 'continue') {
    return null;
  }
  const orderedAlbumRefs = Array.isArray(playbackContext.ordered_album_refs)
    ? playbackContext.ordered_album_refs.map((value) => String(value || '').trim()).filter(Boolean)
    : [];
  if (!orderedAlbumRefs.length) return null;
  const currentAlbumRef = String(queue.albumRef || '').trim();
  const currentIndex = orderedAlbumRefs.findIndex((value) => value === currentAlbumRef);
  if (currentIndex < 0) return null;
  for (let index = currentIndex + 1; index < orderedAlbumRefs.length; index += 1) {
    const nextAlbumRef = orderedAlbumRefs[index];
    if (!canPlaybackContextAlbumContinue(playbackContext, nextAlbumRef)) {
      continue;
    }
    const nextAlbum = findPlaybackContextAlbumByRef(nextAlbumRef);
    if (!nextAlbum) {
      continue;
    }
    const nextQueue = buildAlbumPlaybackQueueState(nextAlbum, '', playbackContext);
    if (!nextQueue) {
      continue;
    }
    return nextQueue;
  }
  return null;
}

function setAlbumPlaybackQueue(album, startingTrackPath) {
  state.player.playbackQueue = buildAlbumPlaybackQueueState(
    album,
    startingTrackPath,
    getAlbumPlaybackContext(album),
  );
}

function peekNextQueuedTrack() {
  const queue = state.player.playbackQueue;
  if (!queue || !Array.isArray(queue.tracks) || !queue.tracks.length) return null;
  const currentPath = String(state.player.current?.path || '');
  const currentIndex = queue.tracks.findIndex((track) => String(track.path || '') === currentPath);
  const resolvedIndex = currentIndex >= 0 ? currentIndex : Number(queue.currentIndex) || 0;
  const nextIndex = resolvedIndex + 1;
  if (nextIndex >= queue.tracks.length) {
    return resolveNextPlaybackContextQueue(queue)?.tracks?.[0] || null;
  }
  return queue.tracks[nextIndex];
}

function getNextQueuedTrack() {
  const queue = state.player.playbackQueue;
  const nextTrack = peekNextQueuedTrack();
  if (!queue || !Array.isArray(queue.tracks) || !queue.tracks.length || !nextTrack) {
    if (queue && Array.isArray(queue.tracks)) {
      const currentPath = String(state.player.current?.path || '');
      const currentIndex = queue.tracks.findIndex((track) => String(track.path || '') === currentPath);
      const resolvedIndex = currentIndex >= 0 ? currentIndex : Number(queue.currentIndex) || 0;
      if (resolvedIndex + 1 >= queue.tracks.length) {
        state.player.playbackQueue = resolveNextPlaybackContextQueue(queue);
      }
    }
    return state.player.playbackQueue?.tracks?.[0] || null;
  }
  const currentPath = String(state.player.current?.path || '');
  const currentIndex = queue.tracks.findIndex((track) => String(track.path || '') === currentPath);
  const resolvedIndex = currentIndex >= 0 ? currentIndex : Number(queue.currentIndex) || 0;
  const nextIndex = resolvedIndex + 1;
  if (nextIndex >= queue.tracks.length) {
    state.player.playbackQueue = resolveNextPlaybackContextQueue(queue);
    return state.player.playbackQueue?.tracks?.[0] || null;
  }
  queue.currentIndex = nextIndex;
  return nextTrack;
}

function refreshTrackModalPlaybackState() {
  const trackModal = document.getElementById('track-modal');
  if (!trackModal || trackModal.hidden) return;
  const playback = getPlayerPlaybackSnapshot();
  const currentTrackPath = String(state.player.current?.path || '');
  const activeCurrent = formatTrackDuration(Math.floor(playback.currentTime || 0)) || '0:00';
  const activeDuration = formatTrackDuration(playback.duration) || '0:00';

  document.querySelectorAll('#track-modal [data-track-row-path]').forEach((row) => {
    const rowPath = String(row.getAttribute('data-track-row-path') || '');
    const isCurrentTrack = currentTrackPath && currentTrackPath === rowPath;
    const isActivelyPlaying = isCurrentTrack && !playback.paused && !playback.ended;
    row.classList.toggle('is-current', isCurrentTrack);
    row.classList.toggle('is-playing', isActivelyPlaying);

    const button = row.querySelector('.play-track-button');
    if (button) {
      button.innerHTML = isActivelyPlaying ? '&#x23F8;' : '&#x25B6;';
      button.setAttribute('aria-label', isActivelyPlaying ? 'Pause track' : 'Play track');
    }

    const durationEl = row.querySelector('[data-track-duration-path]');
    if (durationEl) {
      const originalDuration = durationEl.dataset.originalDuration || '';
      const displayedTime = isCurrentTrack ? `${activeCurrent} / ${activeDuration || originalDuration || '0:00'}` : originalDuration;
      durationEl.innerHTML = displayedTime
        ? `<span class="sep">&#8226;</span> ${escapeHtml(displayedTime)}`
        : '';
    }
  });
}

function refreshNonAlbumModalPlaybackState() {
  const nonAlbumModal = document.getElementById('non-album-modal');
  if (!nonAlbumModal || nonAlbumModal.hidden) return;
  const playback = getPlayerPlaybackSnapshot();
  const currentTrackPath = String(state.player.current?.path || '');
  const activeCurrent = formatTrackDuration(Math.floor(playback.currentTime || 0)) || '0:00';
  const activeDuration = formatTrackDuration(playback.duration) || '0:00';

  document.querySelectorAll('#non-album-modal [data-track-row-path]').forEach((row) => {
    const rowPath = String(row.getAttribute('data-track-row-path') || '');
    const isCurrentTrack = currentTrackPath && currentTrackPath === rowPath;
    const isActivelyPlaying = isCurrentTrack && !playback.paused && !playback.ended;
    row.classList.toggle('is-current', isCurrentTrack);
    row.classList.toggle('is-playing', isActivelyPlaying);

    const button = row.querySelector('.play-track-button');
    if (button) {
      button.innerHTML = isActivelyPlaying ? '&#x23F8;' : '&#x25B6;';
      button.setAttribute('aria-label', isActivelyPlaying ? 'Pause track' : 'Play track');
    }

    const durationEl = row.querySelector('[data-track-duration-path]');
    if (durationEl) {
      const originalDuration = durationEl.dataset.originalDuration || '';
      const displayedTime = isCurrentTrack ? `${activeCurrent} / ${activeDuration || originalDuration || '0:00'}` : originalDuration;
      durationEl.innerHTML = displayedTime
        ? `<span class="sep">&#8226;</span> ${escapeHtml(displayedTime)}`
        : '';
    }
  });
}

// END js/runtime/tag-editor-and-optimistic-updates.js

// BEGIN js/runtime/player-state-persistence-helpers.js

function buildPersistedPlaybackQueue(currentTrackPath) {
  const queue = state.player.playbackQueue;
  if (!queue || !Array.isArray(queue.tracks) || !queue.tracks.length) return null;
  const normalizedCurrentTrackPath = String(currentTrackPath || '');
  const queueTracks = queue.tracks
    .map((track) => {
      if (!track?.src || !track?.path) return null;
      return {
        src: String(track.src || ''),
        path: String(track.path || ''),
        title: String(track.title || ''),
        artist: String(track.artist || ''),
        ...(track.albumArtist ? { albumArtist: String(track.albumArtist) } : {}),
        album: String(track.album || ''),
        coverPath: String(track.coverPath || ''),
        ...(Number(track.durationSeconds) > 0
          ? { durationSeconds: Number(track.durationSeconds) }
          : {}),
      };
    })
    .filter(Boolean);
  if (!queueTracks.length) return null;
  const currentIndex = queueTracks.findIndex((track) => String(track.path || '') === normalizedCurrentTrackPath);
  if (currentIndex < 0) return null;
  return {
    tracks: queueTracks,
    currentIndex,
    ...(queue.albumRef ? { albumRef: String(queue.albumRef) } : {}),
    ...(queue.albumSnapshot && typeof queue.albumSnapshot === 'object' && !Array.isArray(queue.albumSnapshot)
      ? { albumSnapshot: queue.albumSnapshot }
      : {}),
  };
}

function buildPersistedPlayerState(options = {}) {
  const playback = options.playbackSnapshot || getPlayerPlaybackSnapshot();
  const current = state.player.current;
  const src = String(playback.src || current?.src || '');
  if (!current || !src) return null;
  const shouldPreservePlayingState = Boolean(options.preservePlayingState);
  const hasPlayingStateOverride = typeof options.wasPlaying === 'boolean';
  const paused = hasPlayingStateOverride
    ? Boolean(!options.wasPlaying || playback.ended)
    : (shouldPreservePlayingState
      ? Boolean(!state.player.lastKnownWasPlaying || playback.ended)
      : Boolean(playback.paused || playback.ended));
  const savedLoopStart = Number(state.player.loopStart);
  const savedLoopEnd = Number(state.player.loopEnd);
  const loopStart = Number.isFinite(savedLoopStart) ? Math.max(0, savedLoopStart) : 0;
  const loopEnd = Number.isFinite(savedLoopEnd) ? Math.max(loopStart, savedLoopEnd) : loopStart;
  const playbackDuration = Number(playback.duration);
  const currentDuration = Number(current.durationSeconds);
  const durationSeconds = playbackDuration > 0
    ? playbackDuration
    : (currentDuration > 0 ? currentDuration : 0);
  return {
    track: {
      src,
      path: String(current.path || ''),
      title: String(current.title || ''),
      artist: String(current.artist || ''),
      ...(current.albumArtist ? { albumArtist: String(current.albumArtist) } : {}),
      album: String(current.album || ''),
      coverPath: String(current.coverPath || ''),
      ...(durationSeconds > 0
        ? { durationSeconds }
        : {}),
    },
    playbackQueue: buildPersistedPlaybackQueue(current.path),
    currentTime: Math.max(0, Math.round((Number(playback.currentTime) || 0) * 100) / 100),
    paused,
    loop: {
      active: false,
      start: loopStart,
      end: loopEnd,
    },
  };
}

function restorePersistedPlaybackQueue(parsedState, currentTrackPath) {
  const tracks = Array.isArray(parsedState?.playbackQueue?.tracks)
    ? parsedState.playbackQueue.tracks
      .map((track) => {
        if (!track?.src || !track?.path) return null;
        return {
          src: String(track.src || ''),
          path: String(track.path || ''),
          title: String(track.title || ''),
          artist: String(track.artist || ''),
          ...(track.albumArtist ? { albumArtist: String(track.albumArtist) } : {}),
          album: String(track.album || ''),
          coverPath: String(track.coverPath || ''),
          ...(Number(track.durationSeconds) > 0
            ? { durationSeconds: Number(track.durationSeconds) }
            : {}),
        };
      })
      .filter(Boolean)
    : [];
  if (!tracks.length) return false;
  const normalizedCurrentTrackPath = String(currentTrackPath || '');
  const currentIndex = tracks.findIndex((track) => String(track.path || '') === normalizedCurrentTrackPath);
  if (currentIndex < 0) return false;
  state.player.playbackQueue = {
    tracks,
    currentIndex,
    ...(parsedState.playbackQueue.albumRef
      ? { albumRef: String(parsedState.playbackQueue.albumRef) }
      : {}),
    ...(parsedState.playbackQueue.albumSnapshot
      && typeof parsedState.playbackQueue.albumSnapshot === 'object'
      && !Array.isArray(parsedState.playbackQueue.albumSnapshot)
      ? { albumSnapshot: parsedState.playbackQueue.albumSnapshot }
      : {}),
  };
  return true;
}

function restoredPlaybackQueueHasValidAlbumSnapshot(currentTrackPath) {
  const queue = state.player.playbackQueue;
  const targetPath = String(currentTrackPath || '');
  const albumSnapshot = queue?.albumSnapshot;
  if (!queue || !targetPath || !albumSnapshot || typeof albumSnapshot !== 'object') return false;

  const queueAlbumRef = String(queue.albumRef || '').trim();
  const snapshotAlbumRef = typeof getAlbumIdentity === 'function'
    ? String(getAlbumIdentity(albumSnapshot) || '').trim()
    : '';
  if (!queueAlbumRef || snapshotAlbumRef !== queueAlbumRef) return false;

  const queueHasTrack = Array.isArray(queue.tracks)
    && queue.tracks.some((track) => String(track?.path || '') === targetPath);
  const snapshotTrackPaths = new Set([
    ...(Array.isArray(albumSnapshot.tracks)
      ? albumSnapshot.tracks.map((track) => String(track?.path || ''))
      : []),
    ...(Array.isArray(albumSnapshot.track_paths)
      ? albumSnapshot.track_paths.map((path) => String(path || ''))
      : []),
  ].filter(Boolean));
  return queueHasTrack && snapshotTrackPaths.has(targetPath);
}

function attachAlbumSnapshotToRestoredPlaybackQueue(album, currentTrack) {
  const queue = state.player.playbackQueue;
  const currentTrackPath = String(currentTrack?.path || '');
  const albumRef = typeof getAlbumIdentity === 'function'
    ? String(getAlbumIdentity(album) || '').trim()
    : '';
  const albumTracks = Array.isArray(album?.tracks) ? album.tracks : [];
  const albumTrackPaths = new Set(albumTracks.map((track) => String(track?.path || '')).filter(Boolean));
  const albumHasCurrentTrack = albumTrackPaths.has(currentTrackPath);
  const queueHasCurrentTrack = Array.isArray(queue?.tracks)
    && queue.tracks.some((track) => String(track?.path || '') === currentTrackPath);
  if (!queue || !albumRef || !albumHasCurrentTrack || !queueHasCurrentTrack) return false;

  queue.albumRef = albumRef;
  queue.albumSnapshot = album;
  const albumArtist = String(album.album_artist || album.artist || '').trim();
  if (albumArtist) {
    currentTrack.albumArtist = String(currentTrack.albumArtist || albumArtist);
    queue.tracks = queue.tracks.map((track) => ({
      ...track,
      ...(albumTrackPaths.has(String(track?.path || ''))
        ? { albumArtist: String(track?.albumArtist || albumArtist) }
        : {}),
    }));
  }
  return true;
}

let playerUnloadWasPlaying = null;
let playerUnloadStatePersisted = false;

function resetPlayerUnloadPersistence() {
  playerUnloadWasPlaying = null;
  playerUnloadStatePersisted = false;
}

function persistPlayerState(force = false, options = {}) {
  if (playerUnloadStatePersisted && !options.allowAfterUnload) return;
  let snapshot = '';
  try {
    const payload = buildPersistedPlayerState(options);
    if (!payload) {
      if (force) removeLocalStorageItem(PLAYER_STATE_STORAGE_KEY);
      state.player.lastPersistedSnapshot = '';
      return;
    }
    snapshot = JSON.stringify(payload);
    if (!force && snapshot === state.player.lastPersistedSnapshot) return;
    setLocalStorageItem(PLAYER_STATE_STORAGE_KEY, snapshot);
    state.player.lastPersistedSnapshot = snapshot;
  } catch (_error) {
    // Ignore storage errors so playback never breaks.
  }
}

function persistPlayerStateForUnload(reason) {
  if (playerUnloadStatePersisted) return false;
  playerUnloadStatePersisted = true;
  const playbackSnapshot = getPlayerPlaybackSnapshot();
  if (playerUnloadWasPlaying === null) {
    playerUnloadWasPlaying = Boolean(state.player.lastKnownWasPlaying);
  }
  if (typeof releasePlaybackOwnership === 'function') {
    releasePlaybackOwnership('paused', state.player.current);
  }
  flushListenSessionOnUnload(reason);
  persistPlayerState(true, {
    preservePlayingState: true,
    wasPlaying: playerUnloadWasPlaying,
    playbackSnapshot,
    allowAfterUnload: true,
  });
  return true;
}

function restorePlayerState() {
  if (state.player.restoredFromStorage) return;
  state.player.restoredFromStorage = true;
  const raw = getLocalStorageItem(PLAYER_STATE_STORAGE_KEY);
  if (!raw) return;
  let parsed = null;
  try {
    parsed = JSON.parse(raw);
  } catch (_error) {
    return;
  }
  const track = parsed?.track;
  if (!track || !track.src) return;
  const savedPaused = typeof parsed.paused === 'boolean'
    ? parsed.paused
    : !Boolean(parsed.wasPlaying);
  const canResumePlayback = !savedPaused
    && (typeof canRestoreActivePlayback !== 'function'
      || Boolean(canRestoreActivePlayback(parsed)));
  const restore = async () => {
    state.player.playbackQueue = null;
    const restoredQueue = restorePersistedPlaybackQueue(parsed, track.path);
    const restoredQueueHasAlbumSnapshot = restoredQueue
      && restoredPlaybackQueueHasValidAlbumSnapshot(track.path);
    if (restoredQueue
      && !restoredQueueHasAlbumSnapshot
      && typeof resolveAlbumForPlayerTrack === 'function') {
      const album = resolveAlbumForPlayerTrack(track);
      if (album) attachAlbumSnapshotToRestoredPlaybackQueue(album, track);
    } else if (!restoredQueue
      && typeof resolveAlbumForPlayerTrack === 'function'
      && typeof setAlbumPlaybackQueue === 'function') {
      const album = resolveAlbumForPlayerTrack(track);
      if (album) setAlbumPlaybackQueue(album, track.path);
    }

    const savedLoop = parsed.loop && typeof parsed.loop === 'object' ? parsed.loop : {};
    const trackDuration = Number(track.durationSeconds);
    const duration = Number.isFinite(trackDuration) ? Math.max(0, trackDuration) : 0;
    const maximumStart = duration > 0 ? Math.max(0, duration - 0.1) : Number.POSITIVE_INFINITY;
    const savedLoopStart = Number(savedLoop.start);
    const savedLoopEnd = Number(savedLoop.end);
    const loopStart = Math.min(
      maximumStart,
      Number.isFinite(savedLoopStart) ? Math.max(0, savedLoopStart) : 0,
    );
    const requestedLoopEnd = Math.max(
      loopStart + 0.1,
      Number.isFinite(savedLoopEnd) ? savedLoopEnd : 0.1,
    );
    const loopEnd = duration > 0 ? Math.min(duration, requestedLoopEnd) : requestedLoopEnd;
    const restoredLoopEnd = Math.max(loopStart, loopEnd);
    const restoredLoopActive = false;

    const savedTime = Math.max(0, Number(parsed.currentTime) || 0);
    const boundedTime = duration > 0
      ? Math.min(savedTime, Math.max(0, duration - 0.05))
      : savedTime;
    let autoplayCompletionHandled = false;
    const completeRestoredAutoplay = () => {
      if (!canResumePlayback || autoplayCompletionHandled) return;
      autoplayCompletionHandled = true;
      if (typeof beginStreamingPlayerListenSession === 'function') {
        beginStreamingPlayerListenSession(track, boundedTime);
      }
      updatePlayerUi();
      persistPlayerState(true);
    };
    const startRestoredRole = () => startStreamingTrack(track, {
      startSeconds: boundedTime,
      autoplay: canResumePlayback,
      ...(canResumePlayback ? {
        allowSuspendedAutoplayFallback: true,
        onAutoplayStarted: completeRestoredAutoplay,
      } : {}),
    });
    const restoredRolePromise = canResumePlayback
      && typeof window !== 'undefined'
      && typeof window.addEventListener === 'function'
      ? new Promise((resolve, reject) => {
        window.addEventListener('pageshow', () => {
          Promise.resolve().then(startRestoredRole).then(resolve, reject);
        }, { once: true });
      })
      : startRestoredRole();
    setCurrentPlayerTrack(track, { persist: false });
    state.player.loopStart = loopStart;
    state.player.loopEnd = restoredLoopEnd;
    state.player.loopActive = restoredLoopActive;
    updatePlayerUi();
    const restoredRole = await restoredRolePromise;
    if (!restoredRole) return;
    if (typeof handleStreamingPlaybackWaveformReady === 'function') {
      try {
        const waveformReady = handleStreamingPlaybackWaveformReady({
          generation: Number(restoredRole.generation) || 0,
          currentPath: String(track.path || ''),
          continuityPath: '',
        });
        if (waveformReady && typeof waveformReady.catch === 'function') {
          void waveformReady.catch((error) => {
            console.warn('[AlbumHaven][Waveform] Restored-track peak load failed.', error);
          });
        }
      } catch (error) {
        console.warn('[AlbumHaven][Waveform] Restored-track peak load failed.', error);
      }
    }
    if (!autoplayCompletionHandled) persistPlayerState(true);
  };

  void restore().catch((error) => {
    state.player.lastRestoreError = {
      name: error?.name || 'Error',
      message: error?.message || String(error),
    };
    console.error('[AlbumHaven][Player] State restore failed.', error);
  });
}

// END js/runtime/player-state-persistence-helpers.js

// BEGIN js/runtime/player-listen-session-helpers.js

const MIN_RECORDED_LISTEN_SECONDS = 10;
const LISTEN_SESSION_LONG_PAUSE_MS = 60 * 60 * 1000;

function getListenSessionDuration(session) {
  const duration = Number(session?.duration_seconds || 0);
  if (duration > 0) return duration;
  return Number(getPlayerPlaybackSnapshot().duration) || 0;
}

function getListenScrobbleThreshold(durationSeconds) {
  const duration = Math.max(0, Number(durationSeconds) || 0);
  if (!duration) return 0;
  if (duration < 600) return duration * 0.5;
  return 300;
}

function totalListenedSeconds(session) {
  return (Array.isArray(session?.segments) ? session.segments : []).reduce((sum, segment) => (
    sum + Math.max(0, Number(segment?.end_seconds || 0) - Number(segment?.start_seconds || 0))
  ), 0);
}

function longestListenedSegmentSeconds(session) {
  return (Array.isArray(session?.segments) ? session.segments : []).reduce((maxValue, segment) => {
    const span = Math.max(0, Number(segment?.end_seconds || 0) - Number(segment?.start_seconds || 0));
    return Math.max(maxValue, span);
  }, 0);
}

function shouldPersistListenSession(session) {
  return Math.max(totalListenedSeconds(session), longestListenedSegmentSeconds(session)) > MIN_RECORDED_LISTEN_SECONDS;
}

function clearListenPauseMarker(session) {
  if (!session) return;
  session.paused_at = '';
  session.paused_at_unix_ms = 0;
  session.pause_offset_seconds = 0;
}

function markListenSessionPaused(currentTime = null) {
  const session = state.player.listenSession;
  if (!session) return;
  session.paused_at = isoNow();
  session.paused_at_unix_ms = Date.now();
  session.pause_offset_seconds = Math.max(0, Number(currentTime == null ? getPlayerPlaybackSnapshot().currentTime : currentTime) || 0);
}

function hasListenSessionExceededPauseThreshold(session) {
  return Boolean(
    session
    && Number(session.paused_at_unix_ms || 0) > 0
    && (Date.now() - Number(session.paused_at_unix_ms || 0)) >= LISTEN_SESSION_LONG_PAUSE_MS
  );
}

function canScrobbleListenSession(session) {
  const duration = getListenSessionDuration(session);
  if (!duration) return false;
  const threshold = getListenScrobbleThreshold(duration);
  return totalListenedSeconds(session) >= threshold || longestListenedSegmentSeconds(session) >= threshold;
}

function buildNowPlayingPayload(track, session = null) {
  if (!track) return null;
  const activeSession = session || state.player.listenSession;
  return {
    path: String(track.path || ''),
    title: String(track.title || ''),
    artist: String(track.artist || ''),
    album: String(track.album || ''),
    album_artist: String(track.artist || ''),
    cover_path: String(track.coverPath || ''),
    duration_seconds: Math.round((Number(activeSession?.duration_seconds || getPlayerPlaybackSnapshot().duration || 0) || 0) * 1000) / 1000,
    started_at: String(activeSession?.started_at || isoNow()),
    started_at_unix: Number(activeSession?.started_at_unix || unixNowSeconds()) || unixNowSeconds(),
    track_number: String(track.trackNumber || ''),
    request_origin: buildPlaybackRequestOrigin(),
  };
}

function buildPlaybackRequestOrigin() {
  const originId = typeof getPlaybackOwnershipTabId === 'function'
    ? String(getPlaybackOwnershipTabId() || '')
    : '';
  return {
    client_kind: 'private_web',
    origin_type: 'browser_tab',
    origin_id: originId,
  };
}

async function postPlaybackSession(url, payload) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok || !data.ok) {
    throw new Error(data.error || 'Playback sync failed');
  }
  return data;
}

function ensureListenSession(track = null) {
  if (state.player.listenSession) return state.player.listenSession;
  const activeTrack = track || state.player.current;
  if (!activeTrack) return null;
  startListenSession(activeTrack);
  return state.player.listenSession;
}

async function maybeSplitListenSessionAfterLongPause(track = null) {
  const session = state.player.listenSession;
  if (!hasListenSessionExceededPauseThreshold(session)) return false;
  const finishedSession = session;
  const resumeTrack = track || finishedSession.track || state.player.current;
  state.player.listenSession = null;
  await finalizeListenSession('long-pause-timeout', {
    session: finishedSession,
    currentTime: Number(finishedSession.pause_offset_seconds || 0),
    duration: Number(finishedSession.duration_seconds || getPlayerPlaybackSnapshot().duration) || 0,
    endedAtOverride: String(finishedSession.paused_at || ''),
    skipCloseSegment: true,
  });
  if (resumeTrack) {
    startListenSession(resumeTrack);
  }
  return true;
}

async function resumeListenSessionPlayback(track = null, currentTime = null) {
  await maybeSplitListenSessionAfterLongPause(track);
  const session = ensureListenSession(track);
  if (!session) return null;
  clearListenPauseMarker(session);
  beginListenSegment(currentTime);
  return session;
}

function beginListenSegment(currentTime = null) {
  const session = ensureListenSession();
  if (!session || session.segmentActive) return;
  const startSeconds = Math.max(0, Number(currentTime == null ? getPlayerPlaybackSnapshot().currentTime : currentTime) || 0);
  session.segmentActive = true;
  session.activeSegmentStartSeconds = startSeconds;
}

function closeListenSegment(currentTime = null, session = state.player.listenSession) {
  if (!session || !session.segmentActive) return;
  const endSeconds = Math.max(0, Number(currentTime == null ? getPlayerPlaybackSnapshot().currentTime : currentTime) || 0);
  const startSeconds = Math.max(0, Number(session.activeSegmentStartSeconds || 0));
  session.segmentActive = false;
  session.activeSegmentStartSeconds = 0;
  if (endSeconds <= startSeconds) return;
  session.segments.push({
    start_seconds: Math.round(startSeconds * 1000) / 1000,
    end_seconds: Math.round(endSeconds * 1000) / 1000,
  });
}

function maybeSendNowPlaying(track, session) {
  if (session?.nowPlayingPromise) return session.nowPlayingPromise;
  if (session?.nowPlayingSent) return Promise.resolve(true);
  if (typeof canEmitPlaybackSessionSideEffects === 'function' && !canEmitPlaybackSessionSideEffects()) {
    return Promise.resolve(false);
  }
  const payload = buildNowPlayingPayload(track, session);
  if (!payload?.artist || !payload?.title) return Promise.resolve(false);
  const nowPlayingPromise = postPlaybackSession('/playback/session/now-playing', payload).then(() => {
    if (session) session.nowPlayingSent = true;
    return true;
  }).catch((error) => {
    console.warn('[AlbumHaven][Lastfm] Failed to update now playing.', error);
    return false;
  }).finally(() => {
    if (session?.nowPlayingPromise === nowPlayingPromise) {
      session.nowPlayingPromise = null;
    }
  });
  if (session) session.nowPlayingPromise = nowPlayingPromise;
  return nowPlayingPromise;
}

async function maybeScrobbleListenSession(session) {
  if (!session) return false;
  if (session.scrobblePromise) return session.scrobblePromise;
  if (session.scrobbled || !canScrobbleListenSession(session)) return false;
  if (session.scrobblePending) return false;
  if (typeof canEmitPlaybackSessionSideEffects === 'function' && !canEmitPlaybackSessionSideEffects()) return false;
  session.scrobblePending = true;
  const scrobblePromise = postPlaybackSession(
    '/playback/session/scrobble',
    buildNowPlayingPayload(session.track, session),
  ).then(() => {
    session.scrobbled = true;
    return true;
  }).catch((error) => {
    console.warn('[AlbumHaven][Lastfm] Failed to scrobble track.', error);
    return false;
  }).finally(() => {
    session.scrobblePending = false;
    if (session.scrobblePromise === scrobblePromise) {
      session.scrobblePromise = null;
    }
  });
  session.scrobblePromise = scrobblePromise;
  return scrobblePromise;
}

function startListenSession(track) {
  if (!track) {
    state.player.listenSession = null;
    return;
  }
  state.player.listenSession = {
    track: {
      path: String(track.path || ''),
      title: String(track.title || ''),
      artist: String(track.artist || ''),
      album: String(track.album || ''),
      coverPath: String(track.coverPath || ''),
      trackNumber: String(track.trackNumber || ''),
    },
    started_at: isoNow(),
    started_at_unix: unixNowSeconds(),
    ended_at: '',
    duration_seconds: 0,
    segments: [],
    segmentActive: false,
    activeSegmentStartSeconds: 0,
    paused_at: '',
    paused_at_unix_ms: 0,
    pause_offset_seconds: 0,
    scrobbled: false,
    scrobblePending: false,
    nowPlayingSent: false,
    nowPlayingPromise: null,
    completionState: '',
  };
}

async function finalizeListenSession(reason, options = {}) {
  const session = options.session || state.player.listenSession;
  if (!session || session.completionState === 'pending' || session.completionState === 'done') return;
  if (state.player.listenSession === session) {
    state.player.listenSession = null;
  }
  session.completionState = 'pending';
  if (options.skipCloseSegment !== true) {
    closeListenSegment(options.currentTime, session);
  }
  session.duration_seconds = Math.round((Number(options.duration == null ? getPlayerPlaybackSnapshot().duration : options.duration) || 0) * 1000) / 1000;
  session.ended_at = String(options.endedAtOverride || (session.segmentActive ? isoNow() : (session.paused_at || isoNow())));
  const totalListened = Math.round(totalListenedSeconds(session) * 1000) / 1000;
  const maxContiguous = Math.round(longestListenedSegmentSeconds(session) * 1000) / 1000;
  const finishedFully = Boolean(options.finishedFully);
  const skipped = !finishedFully && reason !== 'stopped';
  if (!shouldPersistListenSession(session)) {
    session.completionState = 'done';
    clearListenPauseMarker(session);
    if (state.player.listenSession === session) {
      state.player.listenSession = null;
    }
    return;
  }
  if (typeof canEmitPlaybackSessionSideEffects === 'function' && !canEmitPlaybackSessionSideEffects()) {
    session.completionState = 'done';
    clearListenPauseMarker(session);
    if (state.player.listenSession === session) {
      state.player.listenSession = null;
    }
    return;
  }
  const scrobbleEligible = canScrobbleListenSession(session);
  if (scrobbleEligible && !session.scrobbled) {
    await maybeScrobbleListenSession(session);
  }
  const payload = {
    ...buildNowPlayingPayload(session.track, session),
    ended_at: session.ended_at,
    duration_seconds: session.duration_seconds,
    total_listened_seconds: totalListened,
    max_contiguous_seconds: maxContiguous,
    finished_fully: finishedFully,
    skipped,
    completion_reason: String(reason || ''),
    scrobble_eligible: scrobbleEligible,
    scrobbled: Boolean(session.scrobbled),
    segments: session.segments.map((segment) => ({
      start_seconds: Number(segment.start_seconds || 0),
      end_seconds: Number(segment.end_seconds || 0),
    })),
  };
  try {
    await postPlaybackSession('/playback/session/complete', payload);
    session.completionState = 'done';
  } catch (error) {
    session.completionState = 'failed';
    console.warn('[AlbumHaven][Playback] Failed to persist listen session.', error);
  }
  if (state.player.listenSession === session) {
    state.player.listenSession = null;
  }
  clearListenPauseMarker(session);
}

function getTrackIdentity(track) {
  return `${String(track?.path || '')}::${String(track?.src || '')}`;
}

function flushListenSessionOnUnload(reason = 'unload') {
  const session = state.player.listenSession;
  if (!session || session.completionState === 'pending' || session.completionState === 'done') return false;
  if (typeof canEmitPlaybackSessionSideEffects === 'function' && !canEmitPlaybackSessionSideEffects()) {
    session.completionState = 'done';
    clearListenPauseMarker(session);
    state.player.listenSession = null;
    return false;
  }
  closeListenSegment();
  session.duration_seconds = Math.round((Number(getPlayerPlaybackSnapshot().duration) || Number(session.duration_seconds) || 0) * 1000) / 1000;
  session.ended_at = session.paused_at || isoNow();
  if (!shouldPersistListenSession(session)) {
    session.completionState = 'done';
    clearListenPauseMarker(session);
    state.player.listenSession = null;
    return false;
  }
  session.completionState = 'pending';
  const payload = {
    ...buildNowPlayingPayload(session.track, session),
    ended_at: session.ended_at,
    duration_seconds: session.duration_seconds,
    total_listened_seconds: Math.round(totalListenedSeconds(session) * 1000) / 1000,
    max_contiguous_seconds: Math.round(longestListenedSegmentSeconds(session) * 1000) / 1000,
    finished_fully: false,
    skipped: true,
    completion_reason: String(reason || 'unload'),
    scrobble_eligible: canScrobbleListenSession(session),
    scrobbled: Boolean(session.scrobbled),
    segments: session.segments.map((segment) => ({
      start_seconds: Number(segment.start_seconds || 0),
      end_seconds: Number(segment.end_seconds || 0),
    })),
  };
  try {
    if (navigator?.sendBeacon) {
      const body = new Blob([JSON.stringify(payload)], { type: 'application/json' });
      navigator.sendBeacon('/playback/session/complete', body);
      if (payload.scrobble_eligible && !payload.scrobbled) {
        navigator.sendBeacon('/playback/session/scrobble', new Blob([JSON.stringify(buildNowPlayingPayload(session.track, session))], { type: 'application/json' }));
      }
    }
  } catch (_error) {
    // Ignore unload delivery errors.
  }
  session.completionState = 'done';
  clearListenPauseMarker(session);
  state.player.listenSession = null;
  return true;
}

// END js/runtime/player-listen-session-helpers.js

// BEGIN js/runtime/gallery-cover-preview-cache.js

const GALLERY_COVER_PREVIEW_CACHE_PREFIX = 'album-haven-gallery-previews-';
const GALLERY_COVER_PREVIEW_CACHE_VERSION = 'v1';
const GALLERY_COVER_PREVIEW_CACHE_NAME = `${GALLERY_COVER_PREVIEW_CACHE_PREFIX}${GALLERY_COVER_PREVIEW_CACHE_VERSION}`;
const MAX_ACTIVE_GALLERY_COVER_OBJECT_URLS = 48;
const MAX_GALLERY_COVER_PREEMPTION_DIAGNOSTICS = 64;
const GALLERY_COVER_REQUEST_ID_HEADER = 'X-Album-Haven-Cover-Request-Id';
const GALLERY_COVER_PRIORITY_HEADER = 'X-Album-Haven-Cover-Priority';

class GalleryCoverPreviewCache {
  constructor(options = {}) {
    this.cacheStorage = options.cacheStorage ?? globalThis.caches ?? null;
    this.fetchImpl = options.fetchImpl ?? globalThis.fetch?.bind(globalThis) ?? null;
    this.urlApi = options.urlApi ?? globalThis.URL ?? null;
    this.locationOrigin = String(options.locationOrigin ?? globalThis.location?.origin ?? '').trim();
    this.cacheName = String(options.cacheName || GALLERY_COVER_PREVIEW_CACHE_NAME);
    this.maxActiveObjectUrls = Math.max(1, Number(options.maxActiveObjectUrls || MAX_ACTIVE_GALLERY_COVER_OBJECT_URLS));
    this.activeObjectUrls = new Map();
    this.inFlight = new Map();
    this.writeChains = new Map();
    this.liveFetches = new Map();
    this.keyGenerations = new Map();
    this.latestRequestedProductionUrls = new Map();
    this.openPromise = null;
    this.generation = 0;
    this.requestSequence = 0;
    this.preemptionSequence = 0;
    this.preemptionTransactionActive = false;
    this.requestSessionId = this.createRequestSessionId();
    this.diagnostics = {
      cacheName: this.cacheName,
      fallbackCount: 0,
      writeFailureCount: 0,
      lastFallback: null,
      lastWriteFailure: null,
      activeCount: 0,
      activeProductionUrls: [],
      preemptionCount: 0,
      preemptionSequence: 0,
      lastPreemption: null,
      preemptions: Object.freeze([]),
    };
  }

  createRequestSessionId() {
    const randomId = globalThis.crypto?.randomUUID?.();
    const fallback = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
    return String(randomId || fallback).replace(/[^a-z0-9-]/gi, '').slice(0, 32);
  }

  nextRequestId() {
    if (this.requestSequence >= Number.MAX_SAFE_INTEGER) {
      this.requestSequence = 0;
      this.requestSessionId = this.createRequestSessionId();
    }
    this.requestSequence += 1;
    return `gallery-cover-${this.requestSessionId}-${this.requestSequence.toString(36)}`.slice(0, 64);
  }

  diagnosticNormalizedUrl(productionUrl) {
    try {
      const url = new URL(productionUrl);
      return `${url.origin}${url.pathname}`;
    } catch (_error) {
      return '/cover';
    }
  }

  normalizeProductionUrl(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';
    try {
      const url = new URL(raw, this.locationOrigin || globalThis.location?.href || undefined);
      if (this.locationOrigin && url.origin !== this.locationOrigin) return '';
      const isGalleryCover = url.pathname === '/cover';
      const isRemoteCoverProxy = url.pathname === '/utilities/cover-lookup/remote-image';
      if (isRemoteCoverProxy && (!this.locationOrigin || url.origin !== this.locationOrigin)) return '';
      if (!isGalleryCover && !isRemoteCoverProxy) return '';
      return url.href;
    } catch (_error) {
      return '';
    }
  }

  keyGeneration(productionUrl) {
    return Number(this.keyGenerations.get(productionUrl) || 0);
  }

  snapshotGeneration(productionUrl) {
    return { global: this.generation, key: this.keyGeneration(productionUrl) };
  }

  generationMatches(productionUrl, snapshot) {
    return snapshot.global === this.generation && snapshot.key === this.keyGeneration(productionUrl);
  }

  throwIfAborted(signal) {
    if (!signal?.aborted) return;
    const error = new Error('Gallery cover request was cancelled.');
    error.name = 'AbortError';
    throw error;
  }

  normalizeRequestPriority(value) {
    return String(value || '').trim().toLowerCase() === 'background' ? 'background' : 'foreground';
  }

  awaitWithAbort(promise, signal) {
    if (!signal) return promise;
    this.throwIfAborted(signal);
    return new Promise((resolve, reject) => {
      let settled = false;
      const finish = (callback, value) => {
        if (settled) return;
        settled = true;
        signal.removeEventListener('abort', onAbort);
        callback(value);
      };
      const onAbort = () => {
        const error = new Error('Gallery cover request was cancelled.');
        error.name = 'AbortError';
        finish(reject, error);
      };
      signal.addEventListener('abort', onAbort, { once: true });
      promise.then(
        (value) => finish(resolve, value),
        (error) => finish(reject, error),
      );
    });
  }

  async openCache() {
    if (!this.cacheStorage || typeof this.cacheStorage.open !== 'function') {
      throw new Error('Cache Storage is unavailable.');
    }
    if (!this.openPromise) {
      this.openPromise = (async () => {
        if (typeof this.cacheStorage.keys === 'function' && typeof this.cacheStorage.delete === 'function') {
          const names = await this.cacheStorage.keys();
          await Promise.all(names
            .filter((name) => String(name).startsWith(GALLERY_COVER_PREVIEW_CACHE_PREFIX) && name !== this.cacheName)
            .map((name) => this.cacheStorage.delete(name)));
        }
        return this.cacheStorage.open(this.cacheName);
      })();
    }
    return this.openPromise;
  }

  responseContentType(response) {
    return String(response?.headers?.get?.('content-type') || '').trim().toLowerCase();
  }

  async validatedBlob(response) {
    if (!response || response.ok !== true || Number(response.status || 0) < 200 || Number(response.status || 0) >= 300) {
      throw new Error(`Cover response failed with HTTP ${Number(response?.status || 0)}.`);
    }
    const contentType = this.responseContentType(response);
    if (!contentType.startsWith('image/')) {
      throw new Error(`Cover response has invalid content type "${contentType || 'missing'}".`);
    }
    const blob = await response.blob();
    const blobType = String(blob?.type || contentType || '').trim().toLowerCase();
    if (!blob || Number(blob.size || 0) <= 0 || !blobType.startsWith('image/')) {
      throw new Error('Cover response body is empty or is not an image.');
    }
    return blob;
  }

  createCacheableResponse(response, blob) {
    if (typeof globalThis.Response !== 'function') return null;
    const contentType = String(blob?.type || this.responseContentType(response) || '').trim();
    return new globalThis.Response(blob, {
      status: Number(response?.status || 200),
      statusText: String(response?.statusText || ''),
      headers: contentType ? { 'Content-Type': contentType } : undefined,
    });
  }

  deferCacheWrite(callback) {
    return new Promise((resolve, reject) => {
      const run = () => {
        Promise.resolve().then(callback).then(resolve, reject);
      };
      if (typeof globalThis.requestIdleCallback === 'function') {
        globalThis.requestIdleCallback(run, { timeout: 250 });
        return;
      }
      globalThis.setTimeout(run, 0);
    });
  }

  baseCacheKey(productionUrl) {
    const url = new URL(productionUrl);
    url.searchParams.delete('v');
    url.hash = '';
    return url.href;
  }

  rememberLatestRequestedProductionUrl(productionUrl) {
    this.latestRequestedProductionUrls.set(this.baseCacheKey(productionUrl), productionUrl);
  }

  isLatestRequestedProductionUrl(productionUrl) {
    return this.latestRequestedProductionUrls.get(this.baseCacheKey(productionUrl)) === productionUrl;
  }

  async purgeSupersededEntries(cache, productionUrl, shouldContinue = () => true) {
    const baseKey = this.baseCacheKey(productionUrl);
    if (typeof cache?.keys !== 'function') return;
    const requests = await cache.keys();
    if (!shouldContinue()) return;
    for (const request of requests) {
      if (!shouldContinue()) return;
      const cachedUrl = String(request?.url || request || '');
      if (
        cachedUrl !== productionUrl
        && this.normalizeProductionUrl(cachedUrl)
        && this.baseCacheKey(cachedUrl) === baseKey
      ) {
        await cache.delete(request);
        if (!shouldContinue()) return;
      }
    }
  }

  rememberObjectUrl(productionUrl, objectUrl) {
    const previous = this.activeObjectUrls.get(productionUrl);
    if (previous && previous !== objectUrl) this.urlApi?.revokeObjectURL?.(previous);
    this.activeObjectUrls.delete(productionUrl);
    this.activeObjectUrls.set(productionUrl, objectUrl);
    while (this.activeObjectUrls.size > this.maxActiveObjectUrls) {
      const oldest = this.activeObjectUrls.entries().next().value;
      if (!oldest) break;
      this.activeObjectUrls.delete(oldest[0]);
      this.urlApi?.revokeObjectURL?.(oldest[1]);
    }
    this.syncActiveDiagnostics();
  }

  syncActiveDiagnostics() {
    this.diagnostics.activeCount = this.activeObjectUrls.size;
    this.diagnostics.activeProductionUrls = [...this.activeObjectUrls.keys()];
  }

  hasActive(productionUrl) {
    const normalizedUrl = this.normalizeProductionUrl(productionUrl);
    return Boolean(normalizedUrl && this.activeObjectUrls.has(normalizedUrl));
  }

  recordDiagnostic(kind, productionUrl, error) {
    const detail = {
      kind,
      productionUrl,
      message: String(error?.message || error || 'Gallery cover preview cache failed.'),
      timestamp: new Date().toISOString(),
    };
    if (kind === 'write-failure') {
      this.diagnostics.writeFailureCount += 1;
      this.diagnostics.lastWriteFailure = detail;
    } else {
      this.diagnostics.fallbackCount += 1;
      this.diagnostics.lastFallback = detail;
    }
    console.warn(`Gallery cover preview cache ${kind}`, detail);
    if (typeof globalThis.dispatchEvent === 'function' && typeof globalThis.CustomEvent === 'function') {
      globalThis.dispatchEvent(new CustomEvent(`album-haven:gallery-cover-cache-${kind}`, { detail }));
    }
  }

  async persistNetworkResponse(cache, productionUrl, cacheCandidate, blob, snapshot, signal = null) {
    const baseKey = this.baseCacheKey(productionUrl);
    const previousWrite = this.writeChains.get(baseKey) || Promise.resolve();
    const write = previousWrite.catch(() => null).then(async () => {
      if (!this.generationMatches(productionUrl, snapshot) || signal?.aborted) {
        return { blob, source: 'network', stale: true, cancelled: Boolean(signal?.aborted) };
      }
      if (!this.isLatestRequestedProductionUrl(productionUrl)) {
        return { blob, source: 'network', stale: true, obsolete: true };
      }
      try {
        let wroteCacheEntry = false;
        const shouldContinue = () => (
          this.generationMatches(productionUrl, snapshot)
          && !signal?.aborted
          && this.isLatestRequestedProductionUrl(productionUrl)
        );
        await this.deferCacheWrite(async () => {
          if (!shouldContinue()) return;
          try {
            await this.purgeSupersededEntries(cache, productionUrl, shouldContinue);
          } catch (error) {
            this.recordDiagnostic('superseded-entry-purge-failure', productionUrl, error);
          }
          if (!shouldContinue()) return;
          await cache.put(productionUrl, cacheCandidate);
          wroteCacheEntry = true;
        });
        if (!shouldContinue()) {
          if (wroteCacheEntry || !this.isLatestRequestedProductionUrl(productionUrl)) {
            await cache.delete(productionUrl);
          }
          return {
            blob,
            source: 'network',
            stale: true,
            cancelled: Boolean(signal?.aborted),
            obsolete: !this.isLatestRequestedProductionUrl(productionUrl),
          };
        }
        return { blob, source: 'network' };
      } catch (error) {
        this.recordDiagnostic('write-failure', productionUrl, error);
        return { blob, source: 'network', writeFailed: true };
      }
    });
    const trackedWrite = write.finally(() => {
      if (this.writeChains.get(baseKey) === trackedWrite) {
        this.writeChains.delete(baseKey);
      }
    });
    this.writeChains.set(baseKey, trackedWrite);
    return trackedWrite;
  }

  async loadBlob(productionUrl, snapshot, signal = null, abortController = null, priorityOwner = null) {
    this.throwIfAborted(signal);
    const cache = await this.openCache();
    const cachedResponse = await cache.match(productionUrl);
    this.throwIfAborted(signal);
    if (cachedResponse) {
      try {
        const blob = await this.validatedBlob(cachedResponse);
        this.throwIfAborted(signal);
        return { blob, source: 'cache', stale: !this.generationMatches(productionUrl, snapshot) };
      } catch (error) {
        if (signal?.aborted) this.throwIfAborted(signal);
        if (error?.name === 'AbortError') throw error;
        try {
          await cache.delete(productionUrl);
        } catch (deleteError) {
          this.recordDiagnostic('invalid-cache-delete-failure', productionUrl, deleteError);
        }
        this.recordDiagnostic('invalid-cache-entry', productionUrl, error);
      }
    }
    if (typeof this.fetchImpl !== 'function') throw new Error('Cover fetch is unavailable.');
    let cacheCandidate;
    let blob;
    while (true) {
      const requestId = this.nextRequestId();
      const requestPriority = this.normalizeRequestPriority(priorityOwner?.priority);
      const attemptController = typeof globalThis.AbortController === 'function'
        ? new globalThis.AbortController()
        : null;
      const attemptSignal = attemptController?.signal || signal;
      const abortAttemptFromOwner = () => attemptController?.abort();
      if (signal && attemptController) {
        if (signal.aborted) attemptController.abort();
        else signal.addEventListener('abort', abortAttemptFromOwner, { once: true });
      }
      const liveFetch = {
        requestId,
        normalizedUrl: this.diagnosticNormalizedUrl(productionUrl),
        abortController: attemptController || abortController,
        promotionSafe: Boolean(attemptController),
      };
      this.liveFetches.set(requestId, liveFetch);
      if (priorityOwner) {
        priorityOwner.liveRequestId = requestId;
        priorityOwner.dispatchedPriority = requestPriority;
      }
      let promotionRetry = false;
      try {
        const response = await this.fetchImpl(productionUrl, {
          credentials: 'same-origin',
          signal: attemptSignal,
          headers: {
            [GALLERY_COVER_REQUEST_ID_HEADER]: requestId,
            [GALLERY_COVER_PRIORITY_HEADER]: requestPriority,
          },
        });
        this.throwIfAborted(signal);
        blob = await this.validatedBlob(response);
        cacheCandidate = this.createCacheableResponse(response, blob);
        this.throwIfAborted(signal);
      } catch (error) {
        promotionRetry = Boolean(
          error?.name === 'AbortError'
          && priorityOwner?.promotionRequestId === requestId
          && !signal?.aborted
        );
        if (!promotionRetry) throw error;
      } finally {
        signal?.removeEventListener?.('abort', abortAttemptFromOwner);
        if (this.liveFetches.get(requestId) === liveFetch) this.liveFetches.delete(requestId);
        if (priorityOwner?.liveRequestId === requestId) {
          priorityOwner.liveRequestId = null;
          priorityOwner.dispatchedPriority = null;
        }
        if (priorityOwner?.promotionRequestId === requestId) {
          priorityOwner.promotionRequestId = null;
        }
      }
      if (promotionRetry) continue;
      break;
    }
    if (!this.generationMatches(productionUrl, snapshot)) {
      return { blob, source: 'network', stale: true };
    }
    if (cacheCandidate) {
      const cacheWritePromise = this.persistNetworkResponse(
        cache,
        productionUrl,
        cacheCandidate,
        blob,
        snapshot,
        signal,
      );
      return { blob, source: 'network', cacheWritePromise };
    }
    return { blob, source: 'network' };
  }

  ensureBlob(productionUrl, options = {}) {
    const callerSignal = options.signal || null;
    const requestedPriority = this.normalizeRequestPriority(options.priority);
    this.rememberLatestRequestedProductionUrl(productionUrl);
    const snapshot = this.snapshotGeneration(productionUrl);
    const current = this.inFlight.get(productionUrl);
    if (
      current
      && !current.signal?.aborted
      && current.snapshot.global === snapshot.global
      && current.snapshot.key === snapshot.key
    ) {
      if (requestedPriority === 'foreground') {
        current.priority = 'foreground';
        this.promoteDispatchedFetch(current);
      }
      return current;
    }
    const abortController = typeof globalThis.AbortController === 'function'
      ? new globalThis.AbortController()
      : null;
    const signal = abortController?.signal || callerSignal;
    const abortFromCaller = () => abortController?.abort();
    if (callerSignal && abortController) {
      if (callerSignal.aborted) abortController.abort();
      else callerSignal.addEventListener('abort', abortFromCaller, { once: true });
    }
    const entry = {
      snapshot,
      signal,
      abortController,
      callerSignal,
      abortFromCaller,
      priority: requestedPriority,
      liveRequestId: null,
      dispatchedPriority: null,
      promotionRequestId: null,
      blobPromise: null,
      completionPromise: null,
    };
    const releaseEntry = () => {
      entry.callerSignal?.removeEventListener?.('abort', entry.abortFromCaller);
      if (this.inFlight.get(productionUrl) === entry) this.inFlight.delete(productionUrl);
    };
    entry.blobPromise = this.loadBlob(productionUrl, snapshot, signal, abortController, entry).then(
      (result) => {
        entry.completionPromise = result.cacheWritePromise || Promise.resolve(result);
        entry.completionPromise.then(releaseEntry, releaseEntry);
        return result;
      },
      (error) => {
        releaseEntry();
        throw error;
      },
    );
    this.inFlight.set(productionUrl, entry);
    return entry;
  }

  normalizePreemptionReason(reason) {
    if (reason === 'utility-modal-preemption') return 'utility-modal-preemption';
    if (reason === 'foreground-promotion') return 'foreground-promotion';
    if (reason === 'render-generation-preemption') return 'render-generation-preemption';
    if (reason === 'cache-destroyed') return 'cache-destroyed';
    return 'intentional-preemption';
  }

  recordPreemption(entry, reason) {
    if (entry.preemptionDetail) return null;
    this.preemptionSequence += 1;
    const detail = Object.freeze({
      requestId: entry.requestId,
      normalizedUrl: entry.normalizedUrl,
      reason: this.normalizePreemptionReason(reason),
      sequence: this.preemptionSequence,
    });
    const retained = [...this.diagnostics.preemptions, detail]
      .slice(-MAX_GALLERY_COVER_PREEMPTION_DIAGNOSTICS);
    this.diagnostics.preemptionCount += 1;
    this.diagnostics.preemptionSequence = this.preemptionSequence;
    this.diagnostics.lastPreemption = detail;
    this.diagnostics.preemptions = Object.freeze(retained);
    entry.preemptionDetail = detail;
    return detail;
  }

  dispatchPreemption(detail) {
    if (!detail) return;
    if (typeof globalThis.dispatchEvent === 'function' && typeof globalThis.CustomEvent === 'function') {
      globalThis.dispatchEvent(new CustomEvent('album-haven:gallery-cover-cache-preemption', { detail }));
    }
  }

  recordInFlightPreemption(productionUrl, reason = 'intentional-preemption') {
    const normalizedUrl = this.normalizeProductionUrl(productionUrl);
    const entry = this.inFlight.get(normalizedUrl);
    const liveFetch = entry?.liveRequestId
      ? this.liveFetches.get(entry.liveRequestId)
      : null;
    if (
      this.preemptionTransactionActive
      || !liveFetch
      || liveFetch.abortController?.signal?.aborted
    ) return null;
    this.preemptionTransactionActive = true;
    try {
      const detail = this.recordPreemption(liveFetch, reason);
      this.dispatchPreemption(detail);
      return detail;
    } finally {
      this.preemptionTransactionActive = false;
    }
  }

  promoteDispatchedFetch(entry) {
    if (
      this.preemptionTransactionActive
      || entry?.dispatchedPriority !== 'background'
      || !entry.liveRequestId
      || entry.promotionRequestId
    ) return false;
    const liveFetch = this.liveFetches.get(entry.liveRequestId);
    if (!liveFetch?.promotionSafe || liveFetch.abortController?.signal?.aborted) return false;
    entry.promotionRequestId = liveFetch.requestId;
    entry.dispatchedPriority = 'promoting';
    this.preemptionTransactionActive = true;
    try {
      const detail = this.recordPreemption(liveFetch, 'foreground-promotion');
      liveFetch.abortController.abort();
      this.dispatchPreemption(detail);
      return true;
    } finally {
      this.preemptionTransactionActive = false;
    }
  }

  abortInFlight(reason = 'intentional-preemption') {
    if (this.preemptionTransactionActive) return Object.freeze([]);
    const normalizedReason = this.normalizePreemptionReason(reason);
    const liveEntries = [];
    this.liveFetches.forEach((entry, requestId) => {
      if (!entry.abortController?.signal?.aborted) liveEntries.push(entry);
      if (this.liveFetches.get(requestId) === entry) this.liveFetches.delete(requestId);
    });
    this.preemptionTransactionActive = true;
    try {
      const details = [];
      liveEntries.forEach((entry) => {
        const detail = this.recordPreemption(entry, normalizedReason);
        if (detail) details.push(detail);
        entry.abortController?.abort();
      });
      this.inFlight.forEach((entry) => entry.abortController?.abort());
      details.forEach((detail) => this.dispatchPreemption(detail));
      return Object.freeze([...details]);
    } finally {
      this.preemptionTransactionActive = false;
    }
  }

  async prefetch(productionUrl, options = {}) {
    const normalizedUrl = this.normalizeProductionUrl(productionUrl);
    if (!normalizedUrl) return { productionUrl: String(productionUrl || ''), cached: false };
    const snapshot = this.snapshotGeneration(normalizedUrl);
    try {
      const entry = this.ensureBlob(normalizedUrl, { ...options, priority: 'background' });
      const blobResult = await this.awaitWithAbort(entry.blobPromise, options.signal || null);
      const result = await this.awaitWithAbort(
        blobResult.cacheWritePromise || entry.completionPromise || Promise.resolve(blobResult),
        options.signal || null,
      );
      return {
        productionUrl: normalizedUrl,
        cached: !result.stale && !result.writeFailed && this.generationMatches(normalizedUrl, snapshot),
      };
    } catch (error) {
      if (error?.name === 'AbortError') {
        return { productionUrl: normalizedUrl, cached: false, cancelled: true };
      }
      this.recordDiagnostic('fallback', normalizedUrl, error);
      return { productionUrl: normalizedUrl, cached: false };
    }
  }

  async resolve(productionUrl, options = {}) {
    const normalizedUrl = this.normalizeProductionUrl(productionUrl);
    if (!normalizedUrl) {
      return { displayUrl: String(productionUrl || ''), productionUrl: String(productionUrl || ''), cached: false };
    }
    const signal = options.signal || null;
    this.throwIfAborted(signal);
    const active = this.activeObjectUrls.get(normalizedUrl);
    if (active) {
      this.activeObjectUrls.delete(normalizedUrl);
      this.activeObjectUrls.set(normalizedUrl, active);
      this.syncActiveDiagnostics();
      return { displayUrl: active, productionUrl: normalizedUrl, cached: true };
    }
    const snapshot = this.snapshotGeneration(normalizedUrl);
    try {
      const result = await this.awaitWithAbort(
        this.ensureBlob(normalizedUrl, { signal, priority: 'foreground' }).blobPromise,
        signal,
      );
      this.throwIfAborted(signal);
      if (result.stale || !this.generationMatches(normalizedUrl, snapshot)) {
        return { displayUrl: normalizedUrl, productionUrl: normalizedUrl, cached: false };
      }
      if (typeof this.urlApi?.createObjectURL !== 'function') {
        throw new Error('Object URL browser API is unavailable.');
      }
      const concurrentlyActivated = this.activeObjectUrls.get(normalizedUrl);
      if (concurrentlyActivated) {
        this.activeObjectUrls.delete(normalizedUrl);
        this.activeObjectUrls.set(normalizedUrl, concurrentlyActivated);
        this.syncActiveDiagnostics();
        return { displayUrl: concurrentlyActivated, productionUrl: normalizedUrl, cached: true };
      }
      const objectUrl = this.urlApi.createObjectURL(result.blob);
      if (!this.generationMatches(normalizedUrl, snapshot)) {
        this.urlApi?.revokeObjectURL?.(objectUrl);
        return { displayUrl: normalizedUrl, productionUrl: normalizedUrl, cached: false };
      }
      this.rememberObjectUrl(normalizedUrl, objectUrl);
      return { displayUrl: objectUrl, productionUrl: normalizedUrl, cached: true };
    } catch (error) {
      if (error?.name === 'AbortError') throw error;
      this.recordDiagnostic('fallback', normalizedUrl, error);
      return { displayUrl: normalizedUrl, productionUrl: normalizedUrl, cached: false };
    }
  }

  async invalidate(productionUrl) {
    const normalizedUrl = this.normalizeProductionUrl(productionUrl);
    if (!normalizedUrl) return false;
    this.keyGenerations.set(normalizedUrl, this.keyGeneration(normalizedUrl) + 1);
    const objectUrl = this.activeObjectUrls.get(normalizedUrl);
    if (objectUrl) {
      this.activeObjectUrls.delete(normalizedUrl);
      this.urlApi?.revokeObjectURL?.(objectUrl);
      this.syncActiveDiagnostics();
    }
    try {
      const cache = await this.openCache();
      return Boolean(await cache.delete(normalizedUrl));
    } catch (error) {
      this.recordDiagnostic('fallback', normalizedUrl, error);
      return false;
    }
  }

  destroy() {
    this.generation += 1;
    this.abortInFlight('cache-destroyed');
    this.activeObjectUrls.forEach((objectUrl) => this.urlApi?.revokeObjectURL?.(objectUrl));
    this.activeObjectUrls.clear();
    this.syncActiveDiagnostics();
    this.liveFetches.clear();
    this.inFlight.clear();
    this.latestRequestedProductionUrls.clear();
  }
}

const galleryCoverPreviewCache = new GalleryCoverPreviewCache();
globalThis.__ALBUM_HAVEN_GALLERY_COVER_CACHE__ = galleryCoverPreviewCache.diagnostics;
const galleryCoverImageRequestTokens = new WeakMap();

function beginGalleryCoverImageRequest(image, productionUrl) {
  if (!(image instanceof HTMLImageElement)) return null;
  if (typeof markAlbumDisplayCoverImagePending === 'function') {
    markAlbumDisplayCoverImagePending(image);
  }
  const requestToken = Number(galleryCoverImageRequestTokens.get(image) || 0) + 1;
  galleryCoverImageRequestTokens.set(image, requestToken);
  image.setAttribute('data-production-cover-src', productionUrl);
  return { image, productionUrl, requestToken };
}

function commitGalleryCoverImageRequest(request, result) {
  if (!request || galleryCoverImageRequestTokens.get(request.image) !== request.requestToken) return false;
  request.image.setAttribute('data-production-cover-src', result.productionUrl);
  request.image.src = result.displayUrl;
  return true;
}

function restoreGalleryCoverImageRequest(request) {
  if (!request || galleryCoverImageRequestTokens.get(request.image) !== request.requestToken) return null;
  galleryCoverImageRequestTokens.set(request.image, request.requestToken + 1);
  request.image.setAttribute('data-gallery-cover-src', request.productionUrl);
  request.image.removeAttribute('data-gallery-cover-loading');
  return request.image;
}

async function loadGalleryCoverPreviewImage(image, productionUrl, options = {}) {
  if (!(image instanceof HTMLImageElement)) return null;
  const requestedUrl = String(productionUrl || '').trim();
  if (!requestedUrl) return null;
  const request = beginGalleryCoverImageRequest(image, requestedUrl);
  const result = await galleryCoverPreviewCache.resolve(requestedUrl);
  if (typeof options.isCurrent === 'function' && !options.isCurrent()) return null;
  if (!commitGalleryCoverImageRequest(request, result)) return null;
  return result;
}

// END js/runtime/gallery-cover-preview-cache.js

// BEGIN js/runtime/gallery-cover-load-scheduler.js

const GALLERY_COVER_LOAD_CONCURRENCY = 2;
const GALLERY_COVER_BACKGROUND_CONCURRENCY = 2;
const GALLERY_COVER_PRIORITY_ORDER = Object.freeze({ visible: 0, near: 1, background: 2 });

class GalleryCoverLoadScheduler {
  constructor(options = {}) {
    this.cache = options.cache || galleryCoverPreviewCache;
    this.maxConcurrency = Math.max(1, Number(options.maxConcurrency || GALLERY_COVER_LOAD_CONCURRENCY));
    this.maxBackgroundConcurrency = Math.max(1, Math.min(
      this.maxConcurrency,
      Number(options.maxBackgroundConcurrency || GALLERY_COVER_BACKGROUND_CONCURRENCY),
    ));
    this.queues = { visible: [], near: [], background: [] };
    this.tasks = new Map();
    this.activeCount = 0;
    this.activeBackgroundCount = 0;
    this.generation = 0;
    this.familyPrefetchGeneration = 0;
    this.activeFamilyPrefetchGeneration = 0;
    this.completedFamilyPrefetchGeneration = 0;
    this.familyPrefetchPending = false;
    this.familyPrefetchPromise = null;
    this.familyPrefetchPromiseGeneration = 0;
    this.familyPrefetchReconciliationSequence = 0;
    this.familyPrefetchUrlKey = '';
    this.familyPrefetchTaskGeneration = -1;
    this.suspended = false;
    this.idleWaiters = [];
    this.foregroundIdleWaiters = [];
    this.diagnostics = {
      maxConcurrency: this.maxConcurrency,
      maxBackgroundConcurrency: this.maxBackgroundConcurrency,
      active: 0,
      activeBackground: 0,
      queuedVisible: 0,
      queuedNear: 0,
      queuedBackground: 0,
      activeForeground: 0,
      queuedForeground: 0,
      foregroundIdle: true,
      generation: 0,
      familyPrefetchGeneration: 0,
      activeFamilyPrefetchGeneration: 0,
      completedFamilyPrefetchGeneration: 0,
      familyPrefetchPending: false,
      suspended: false,
    };
  }

  updateDiagnostics() {
    this.diagnostics.active = this.activeCount + (this.familyPrefetchPending ? 1 : 0);
    this.diagnostics.activeBackground = this.activeBackgroundCount;
    this.diagnostics.queuedVisible = this.queues.visible.length;
    this.diagnostics.queuedNear = this.queues.near.length;
    this.diagnostics.queuedBackground = this.queues.background.length;
    this.diagnostics.activeForeground = this.activeForegroundCount();
    this.diagnostics.queuedForeground = this.queues.visible.length + this.queues.near.length;
    this.diagnostics.foregroundIdle = this.isForegroundIdle();
    this.diagnostics.generation = this.generation;
    this.diagnostics.familyPrefetchGeneration = this.familyPrefetchGeneration;
    this.diagnostics.activeFamilyPrefetchGeneration = this.activeFamilyPrefetchGeneration;
    this.diagnostics.completedFamilyPrefetchGeneration = this.completedFamilyPrefetchGeneration;
    this.diagnostics.familyPrefetchPending = this.familyPrefetchPending;
    this.diagnostics.suspended = this.suspended;
  }

  startGeneration() {
    this.generation += 1;
    Object.entries(this.queues).forEach(([priority, queue]) => {
      const retained = [];
      queue.splice(0).forEach((task) => {
        if (task.consumerOwned) {
          task.pendingGenerationValidation = this.generation;
          retained.push(task);
          return;
        }
        if (this.familyPrefetchPending && task.priority === 'background') {
          retained.push(task);
          return;
        }
        task.cancelled = true;
        this.tasks.delete(task.productionUrl);
        task.resolve({ cancelled: true, productionUrl: task.productionUrl });
      });
      this.queues[priority].push(...retained);
    });
    this.tasks.forEach((task) => {
      if (task.consumerOwned && task.generation !== this.generation) {
        task.pendingGenerationValidation = this.generation;
      }
      if (
        !this.familyPrefetchPending
        && !task.consumerOwned
        && task.priority === 'background'
        && task.generation !== this.generation
      ) {
        task.cancelled = true;
        task.abortController?.abort();
      }
    });
    this.updateDiagnostics();
    this.settleIdleWaiters();
    this.settleForegroundIdleWaiters();
    return this.generation;
  }

  requestHasConnectedConsumer(request) {
    const image = request?.image;
    if (!image) return false;
    return typeof image.isConnected !== 'boolean' || image.isConnected;
  }

  cancelTask(task) {
    if (!task || task.cancelled) return;
    task.cancelled = true;
    [task.imageRequests, task.drainingImageRequests].forEach((requests) => {
      requests.splice(0).forEach((request) => {
        if (typeof restoreGalleryCoverImageRequest === 'function') {
          restoreGalleryCoverImageRequest(request);
        }
      });
    });
    task.consumerOwned = false;
    if (task.started) {
      task.abortController?.abort();
      return;
    }
    Object.values(this.queues).forEach((queue) => {
      const index = queue.indexOf(task);
      if (index >= 0) queue.splice(index, 1);
    });
    if (this.tasks.get(task.productionUrl) === task) this.tasks.delete(task.productionUrl);
    const result = { cancelled: true, productionUrl: task.productionUrl };
    task.resolve(result);
    task.resolveDurability?.(result);
  }

  pruneObsoleteConsumerTasks(generation = this.generation) {
    const currentGeneration = Number(generation || this.generation);
    this.tasks.forEach((task) => {
      if (
        task.cancelled
        || !task.consumerOwned
        || task.generation === currentGeneration
        || task.pendingGenerationValidation !== currentGeneration
      ) return;
      [task.imageRequests, task.drainingImageRequests].forEach((requests) => {
        const connected = requests.filter((request) => this.requestHasConnectedConsumer(request));
        requests
          .filter((request) => !this.requestHasConnectedConsumer(request))
          .forEach((request) => {
            if (typeof restoreGalleryCoverImageRequest === 'function') {
              restoreGalleryCoverImageRequest(request);
            }
          });
        requests.splice(0, requests.length, ...connected);
      });
      task.suspendedImages = task.suspendedImages.filter((image) => (
        typeof image?.isConnected !== 'boolean' || image.isConnected
      ));
      if (task.imageRequests.length || task.drainingImageRequests.length || task.suspendedImages.length) {
        task.generation = currentGeneration;
        task.pendingGenerationValidation = 0;
        return;
      }
      if (task.started) {
        this.cache.recordInFlightPreemption?.(
          task.productionUrl,
          'render-generation-preemption',
        );
      }
      this.cancelTask(task);
    });
    this.updateDiagnostics();
    this.pump();
    this.settleIdleWaiters();
    this.settleForegroundIdleWaiters();
  }

  beginFamilyPrefetchReconciliation() {
    this.familyPrefetchGeneration += 1;
    this.activeFamilyPrefetchGeneration = this.familyPrefetchGeneration;
    this.familyPrefetchPending = true;
    this.updateDiagnostics();
    return this.familyPrefetchGeneration;
  }

  ensureFamilyPrefetchReconciliation() {
    return this.familyPrefetchPending
      ? this.activeFamilyPrefetchGeneration
      : this.beginFamilyPrefetchReconciliation();
  }

  cancelFamilyPrefetchReconciliation(familyPrefetchGeneration) {
    if (Number(familyPrefetchGeneration || 0) !== this.activeFamilyPrefetchGeneration) return false;
    this.activeFamilyPrefetchGeneration = 0;
    this.familyPrefetchReconciliationSequence += 1;
    this.familyPrefetchPending = false;
    this.updateDiagnostics();
    this.settleIdleWaiters();
    return true;
  }

  reconcileFamilyPrefetch(productionUrls, options = {}) {
    const familyPrefetchGeneration = Number(
      options.familyPrefetchGeneration || this.activeFamilyPrefetchGeneration,
    ) || this.beginFamilyPrefetchReconciliation();
    if (familyPrefetchGeneration !== this.activeFamilyPrefetchGeneration) {
      return Promise.resolve({ cancelled: true, familyPrefetchGeneration });
    }
    const taskGeneration = Number(options.generation || this.generation);
    const normalizedUrls = new Set(
      [...(productionUrls || [])]
        .map((productionUrl) => this.cache.normalizeProductionUrl(productionUrl))
        .filter(Boolean),
    );
    const urlKey = [...normalizedUrls].sort().join('\n');
    if (
      this.familyPrefetchPromise
      && this.familyPrefetchPromiseGeneration === familyPrefetchGeneration
      && this.familyPrefetchTaskGeneration === taskGeneration
      && this.familyPrefetchUrlKey === urlKey
    ) {
      return this.familyPrefetchPromise;
    }
    this.familyPrefetchTaskGeneration = taskGeneration;
    this.familyPrefetchUrlKey = urlKey;
    this.familyPrefetchReconciliationSequence += 1;
    const reconciliationSequence = this.familyPrefetchReconciliationSequence;
    const pending = [...normalizedUrls].map((productionUrl) => this.enqueue(productionUrl, {
      generation: taskGeneration,
      priority: 'background',
    }));
    this.tasks.forEach((task) => {
      if (
        task.consumerOwned
        || task.priority !== 'background'
        || normalizedUrls.has(task.productionUrl)
      ) return;
      task.cancelled = true;
      if (!task.started) {
        const queue = this.queues.background;
        const index = queue.indexOf(task);
        if (index >= 0) queue.splice(index, 1);
        if (this.tasks.get(task.productionUrl) === task) this.tasks.delete(task.productionUrl);
        task.resolve({ cancelled: true, productionUrl: task.productionUrl });
      } else {
        task.abortController?.abort();
      }
    });
    this.updateDiagnostics();
    this.pump();
    const reconciliationPromise = Promise.all(pending).then((results) => {
      if (
        familyPrefetchGeneration !== this.activeFamilyPrefetchGeneration
        || reconciliationSequence !== this.familyPrefetchReconciliationSequence
      ) {
        return { cancelled: true, familyPrefetchGeneration, results };
      }
      this.completedFamilyPrefetchGeneration = familyPrefetchGeneration;
      this.activeFamilyPrefetchGeneration = 0;
      this.familyPrefetchPending = false;
      this.updateDiagnostics();
      this.settleIdleWaiters();
      return { cancelled: false, familyPrefetchGeneration, results };
    });
    this.familyPrefetchPromise = reconciliationPromise;
    this.familyPrefetchPromiseGeneration = familyPrefetchGeneration;
    return reconciliationPromise;
  }

  normalizePriority(priority) {
    return Object.hasOwn(GALLERY_COVER_PRIORITY_ORDER, priority) ? priority : 'background';
  }

  promoteTask(task, priority) {
    if (GALLERY_COVER_PRIORITY_ORDER[priority] >= GALLERY_COVER_PRIORITY_ORDER[task.priority]) return;
    if (!task.started) {
      const queue = this.queues[task.priority];
      const index = queue.indexOf(task);
      if (index >= 0) queue.splice(index, 1);
      this.queues[priority].push(task);
    }
    task.priority = priority;
  }

  promote(productionUrl, priority = 'visible') {
    const normalizedUrl = this.cache.normalizeProductionUrl(productionUrl);
    const task = normalizedUrl ? this.tasks.get(normalizedUrl) : null;
    if (!task || task.cancelled) return false;
    this.promoteTask(task, this.normalizePriority(priority));
    this.updateDiagnostics();
    this.pump();
    return true;
  }

  activeForegroundCount() {
    return [...this.tasks.values()].filter((task) => (
      task.started
      && !task.cancelled
      && task.priority !== 'background'
    )).length;
  }

  hasActiveBackgroundOnlyWork() {
    return [...this.tasks.values()].some((task) => (
      task.started
      && task.startedAsBackground
      && !task.cancelled
      && task.priority === 'background'
    ));
  }

  isForegroundIdle() {
    return (
      this.queues.visible.length === 0
      && this.queues.near.length === 0
      && this.activeForegroundCount() === 0
    );
  }

  foregroundState() {
    return Object.freeze({
      active: this.activeForegroundCount(),
      queued: this.queues.visible.length + this.queues.near.length,
      idle: this.isForegroundIdle(),
    });
  }

  preemptActiveBackgroundTasksForForeground() {
    this.tasks.forEach((task) => {
      if (
        !task.started
        || !task.startedAsBackground
        || task.cancelled
        || task.priority !== 'background'
        || task.foregroundPreemptRequested
      ) return;
      task.foregroundPreemptRequested = true;
      this.cache.recordInFlightPreemption?.(task.productionUrl, 'foreground-promotion');
      task.abortController?.abort();
    });
  }

  suspend(reason = 'utility-modal-preemption') {
    if (this.suspended) return Object.freeze([]);
    this.suspended = true;
    const preemptedEntries = this.cache.abortInFlight?.(reason) || Object.freeze([]);
    this.tasks.forEach((task) => {
      if (!task.started || task.cancelled) return;
      task.suspendRequested = true;
      const suspendedRequests = [
        ...task.drainingImageRequests.splice(0),
        ...task.imageRequests.splice(0),
      ];
      const suspendedImages = suspendedRequests
        .map((request) => (
          typeof restoreGalleryCoverImageRequest === 'function'
            ? restoreGalleryCoverImageRequest(request)
            : request.image
        ))
        .filter(Boolean);
      suspendedImages.forEach((image) => {
        if (!task.suspendedImages.includes(image)) task.suspendedImages.push(image);
      });
      task.abortController?.abort();
    });
    this.updateDiagnostics();
    return preemptedEntries;
  }

  resume() {
    if (!this.suspended) return;
    this.suspended = false;
    this.tasks.forEach((task) => this.restoreSuspendedImageRequests(task));
    this.updateDiagnostics();
    this.pump();
  }

  restoreSuspendedImageRequests(task) {
    const images = task.suspendedImages.splice(0);
    images.forEach((image) => {
      const request = beginGalleryCoverImageRequest(image, task.productionUrl);
      if (!request) return;
      image.setAttribute('data-gallery-cover-loading', '1');
      image.removeAttribute('data-gallery-cover-src');
      task.imageRequests.push(request);
    });
  }

  async drainForegroundImageRequests(task, result) {
    while (!task.cancelled) {
      const requests = task.imageRequests.splice(0);
      if (!requests.length) {
        await Promise.resolve();
        if (!task.imageRequests.length) {
          task.acceptingImageRequests = false;
          break;
        }
        continue;
      }
      task.drainingImageRequests = requests;
      await Promise.resolve();
      if (!task.cancelled && !task.suspendRequested) {
        requests.forEach((request) => commitGalleryCoverImageRequest(request, result));
      }
      task.drainingImageRequests = [];
    }
  }

  resolveAttachedImageRequests(task) {
    if (task.consumerResolutionPromise) return task.consumerResolutionPromise;
    task.consumerResolutionPromise = (async () => {
      do {
        const result = await this.cache.resolve(task.productionUrl, {
          signal: task.abortController?.signal || null,
          priority: 'foreground',
        });
        task.consumerResult = result;
        if (task.cancelled) break;
        await this.drainForegroundImageRequests(task, result);
      } while (task.imageRequests.length);
      return task.consumerResult;
    })().catch((error) => {
      task.consumerError = error;
      return null;
    }).finally(() => {
      task.consumerResolutionPromise = null;
    });
    return task.consumerResolutionPromise;
  }

  enqueue(productionUrl, options = {}) {
    const requestedUrl = String(productionUrl || '').trim();
    const normalizedUrl = this.cache.normalizeProductionUrl(productionUrl);
    if (!normalizedUrl) {
      if (options.image && requestedUrl) {
        const request = beginGalleryCoverImageRequest(options.image, requestedUrl);
        commitGalleryCoverImageRequest(request, {
          displayUrl: requestedUrl,
          productionUrl: requestedUrl,
          cached: false,
        });
      }
      return Promise.resolve({ cancelled: false, cached: false, productionUrl: requestedUrl });
    }
    const priority = this.normalizePriority(options.priority);
    const generation = Number(options.generation || this.generation);
    const imageRequest = options.image ? beginGalleryCoverImageRequest(options.image, normalizedUrl) : null;
    let task = this.tasks.get(normalizedUrl);
    if (task && !task.cancelled && task.acceptingImageRequests !== false) {
      task.generation = generation;
      task.pendingGenerationValidation = 0;
      this.promoteTask(task, priority);
      if (imageRequest) {
        task.consumerOwned = true;
        task.imageRequests.push(imageRequest);
        if (!task.started && task.durabilityOnly) task.durabilityOnly = false;
        if (task.startedAsBackground) this.resolveAttachedImageRequests(task);
      } else if (priority === 'background' && task.consumerOwned) {
        task.durabilityRequested = true;
        if (!task.durabilityPromise) {
          task.durabilityPromise = new Promise((resolve) => { task.resolveDurability = resolve; });
        }
      }
      if (priority !== 'background') this.preemptActiveBackgroundTasksForForeground();
      this.updateDiagnostics();
      this.pump();
      return !imageRequest && priority === 'background' && task.consumerOwned
        ? task.durabilityPromise
        : task.promise;
    }
    let resolveTask;
    const promise = new Promise((resolve) => { resolveTask = resolve; });
    task = {
      productionUrl: normalizedUrl,
      priority,
      generation,
      imageRequests: imageRequest ? [imageRequest] : [],
      drainingImageRequests: [],
      consumerOwned: Boolean(imageRequest),
      started: false,
      startedAsBackground: false,
      cancelled: false,
      consumerResolutionPromise: null,
      consumerResult: null,
      consumerError: null,
      consumerSettled: false,
      durabilityRequested: false,
      durabilityPromise: null,
      resolveDurability: null,
      durabilityOnly: false,
      requeueForDurability: false,
      suspendedImages: [],
      suspendRequested: false,
      foregroundPreemptRequested: false,
      acceptingImageRequests: true,
      pendingGenerationValidation: 0,
      promise,
      resolve: resolveTask,
    };
    this.tasks.set(normalizedUrl, task);
    this.queues[priority].push(task);
    if (priority !== 'background') this.preemptActiveBackgroundTasksForForeground();
    this.updateDiagnostics();
    this.pump();
    return promise;
  }

  nextTask() {
    if (this.queues.visible.length || this.queues.near.length) {
      if (this.hasActiveBackgroundOnlyWork()) return null;
      if (this.queues.visible.length) return this.queues.visible.shift();
      return this.queues.near.shift();
    }
    if (!this.isForegroundIdle()) return null;
    if (this.activeBackgroundCount >= this.maxBackgroundConcurrency) return null;
    return this.queues.background.shift() || null;
  }

  pump() {
    if (this.suspended) {
      this.updateDiagnostics();
      return;
    }
    while (this.activeCount < this.maxConcurrency) {
      const task = this.nextTask();
      if (!task) break;
      if (task.cancelled || (task.generation !== this.generation && !task.consumerOwned)) {
        this.tasks.delete(task.productionUrl);
        task.resolve({ cancelled: true, productionUrl: task.productionUrl });
        continue;
      }
      this.runTask(task);
    }
    this.updateDiagnostics();
    this.settleIdleWaiters();
    this.settleForegroundIdleWaiters();
  }

  async runTask(task) {
    task.started = true;
    this.activeCount += 1;
    const startedAsBackground = task.priority === 'background';
    task.startedAsBackground = startedAsBackground;
    task.abortController = new AbortController();
    if (startedAsBackground) this.activeBackgroundCount += 1;
    this.updateDiagnostics();
    let result;
    try {
      if (task.durabilityOnly) {
        result = await this.cache.prefetch(task.productionUrl, {
          signal: task.abortController.signal,
          priority: 'background',
        });
        task.acceptingImageRequests = false;
        if (!task.cancelled && (task.imageRequests.length || task.consumerResolutionPromise)) {
          await this.resolveAttachedImageRequests(task);
        }
        if (task.consumerError) throw task.consumerError;
        task.resolveDurability?.({ ...result, cancelled: task.cancelled });
      } else if (task.imageRequests.length) {
        result = await this.cache.resolve(task.productionUrl, {
          signal: task.abortController.signal,
          priority: 'foreground',
        });
        await this.drainForegroundImageRequests(task, result);
        if (task.durabilityRequested && !task.cancelled) {
          task.resolve({ ...result, cancelled: false });
          task.consumerSettled = true;
          task.requeueForDurability = true;
        }
      } else {
        result = await this.cache.prefetch(task.productionUrl, {
          signal: task.abortController.signal,
          priority: 'background',
        });
        task.acceptingImageRequests = false;
        if (!task.cancelled && (task.imageRequests.length || task.consumerResolutionPromise)) {
          await this.resolveAttachedImageRequests(task);
        }
        if (task.consumerError) throw task.consumerError;
        if (task.consumerResult) result = task.consumerResult;
      }
      if ((!task.suspendRequested && !task.foregroundPreemptRequested) || task.cancelled) {
        if (!task.consumerSettled) task.resolve({ ...result, cancelled: task.cancelled });
        if (task.durabilityRequested && task.cancelled) {
          task.resolveDurability?.({ ...result, cancelled: true });
        }
      }
    } catch (error) {
      if ((!task.suspendRequested && !task.foregroundPreemptRequested) || task.cancelled) {
        const failure = { cached: false, cancelled: task.cancelled, error, productionUrl: task.productionUrl };
        if (!task.consumerSettled) task.resolve(failure);
        task.resolveDurability?.(failure);
      }
    } finally {
      this.activeCount -= 1;
      if (startedAsBackground) this.activeBackgroundCount -= 1;
      if (task.suspendRequested && !task.cancelled) {
        task.started = false;
        task.acceptingImageRequests = true;
        task.startedAsBackground = false;
        task.suspendRequested = false;
        task.abortController = null;
        task.consumerResolutionPromise = null;
        task.consumerResult = null;
        task.consumerError = null;
        task.consumerSettled = false;
        if (!this.queues[task.priority].includes(task)) this.queues[task.priority].push(task);
        if (!this.suspended) this.restoreSuspendedImageRequests(task);
      } else if (task.foregroundPreemptRequested && !task.cancelled) {
        task.started = false;
        task.acceptingImageRequests = true;
        task.startedAsBackground = false;
        task.foregroundPreemptRequested = false;
        task.abortController = null;
        task.consumerResolutionPromise = null;
        task.consumerResult = null;
        task.consumerError = null;
        task.consumerSettled = false;
        if (!this.queues[task.priority].includes(task)) this.queues[task.priority].push(task);
      } else if (task.requeueForDurability && !task.cancelled) {
        task.started = false;
        task.acceptingImageRequests = true;
        task.startedAsBackground = false;
        task.requeueForDurability = false;
        task.durabilityOnly = true;
        task.priority = 'background';
        task.abortController = null;
        if (!this.queues.background.includes(task)) this.queues.background.push(task);
      } else if (this.tasks.get(task.productionUrl) === task) {
        this.tasks.delete(task.productionUrl);
      }
      this.updateDiagnostics();
      this.pump();
    }
  }

  whenGenerationIdle(generation = this.generation) {
    if (this.isGenerationIdle(generation)) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push({ generation, resolve }));
  }

  whenForegroundIdle() {
    if (this.isForegroundIdle()) return Promise.resolve();
    return new Promise((resolve) => this.foregroundIdleWaiters.push(resolve));
  }

  isGenerationIdle(generation) {
    if (this.familyPrefetchPending) return false;
    return ![...this.tasks.values()].some((task) => task.generation === generation && !task.cancelled);
  }

  settleIdleWaiters() {
    this.idleWaiters = this.idleWaiters.filter((waiter) => {
      if (!this.isGenerationIdle(waiter.generation)) return true;
      waiter.resolve();
      return false;
    });
  }

  settleForegroundIdleWaiters() {
    if (!this.isForegroundIdle()) return;
    this.foregroundIdleWaiters.splice(0).forEach((resolve) => resolve());
  }
}

const galleryCoverLoadScheduler = new GalleryCoverLoadScheduler();
globalThis.__ALBUM_HAVEN_GALLERY_COVER_SCHEDULER__ = galleryCoverLoadScheduler.diagnostics;

// END js/runtime/gallery-cover-load-scheduler.js

// BEGIN js/runtime/virtual-artist-grid.js

function getAlbumCardVersionKey(album) {
  if (typeof getTrackModalAlbumVersionKey === 'function') {
    return getTrackModalAlbumVersionKey(album);
  }
  if (!album) return '';
  const normalize = (value) => String(value ?? '').trim().toLocaleLowerCase();
  return JSON.stringify([
    normalize(getAlbumRequestKey(album) || getAlbumIdentity(album)),
    normalize(album.album_artist || album.artist),
    normalize(album.name || album.album),
    normalize(album.year),
    normalize(album.edition),
  ]);
}

function albumCardHtml(album, options = {}) {
  const summary = getAlbumCardSummary(album);
  const rating = getAlbumCardRating(album);
  const ratingMarkup = `
        <div class="rating-row">
          <div class="stars" role="img" aria-label="${rating === null ? 'Album unrated' : `Album rating ${rating}/10`}">${renderStars(rating)}</div>
          ${rating === null ? '' : `<div class="rating-text">${rating}/10</div>`}
        </div>`;
  const year = album.year ? `<div class="album-year">${escapeHtml(album.year)}</div>` : '<div class="album-year"></div>';
  const length = summary.lengthDisplay ? `<div class="album-length">${escapeHtml(summary.lengthDisplay)}</div>` : '<div class="album-length"></div>';
  const albumKey = escapeHtml(getAlbumRequestKey(album));
  const albumVersionKey = escapeHtml(getAlbumCardVersionKey(album));
  const albumFallback = escapeHtml(JSON.stringify({
    key: getAlbumRequestKey(album),
    name: String(album?.name || ''),
    album_artist: String(album?.album_artist || ''),
    year: album?.year ?? '',
    edition: String(album?.edition || ''),
    preview_only: Boolean(album?.preview_only),
    track_count_preview: Number(album?.track_count_preview || 0),
    total_duration_seconds: Number(album?.total_duration_seconds || 0),
    total_duration_display: String(album?.total_duration_display || ''),
    cover_path: String(album?.cover_path || ''),
    cover_revision: String(album?.cover_revision || ''),
    remote_cover_url: String(album?.remote_cover_url || ''),
    remote_cover_thumbnail_url: String(album?.remote_cover_thumbnail_url || ''),
  }));
  const localCoverPath = escapeHtml(String(album?.cover_path || '').trim());
  const remoteCoverUrl = escapeHtml(String(album?.remote_cover_thumbnail_url || album?.remote_cover_url || '').trim());
  const cardIdentity = escapeHtml(getAlbumCardNodeIdentity(album));
  const cardRenderKey = escapeHtml(getAlbumCardRenderKey(album));
  return `
    <section class="album-card" data-gallery-card-key="${cardIdentity}" data-gallery-card-render-key="${cardRenderKey}">
      <button class="cover album-open-trigger" type="button" data-open-tracklist="1" data-album-key="${albumKey}" data-album-version-key="${albumVersionKey}" data-album="${albumFallback}" aria-label="Open ${escapeHtml(album.name)} tracklist">
        ${albumHasDisplayCover(album)
          ? buildAlbumCardCoverHtml(album, {
            coverPriority: options.coverPriority,
            localCoverPath,
            remoteCoverUrl,
          })
          : '<div class="cover-placeholder">No cover art</div>'}
      </button>
      <div class="album-body">
        <h3 class="album-title"><button class="album-open-trigger album-title-button" type="button" data-open-tracklist="1" data-album-key="${albumKey}" data-album-version-key="${albumVersionKey}" data-album="${albumFallback}">${escapeHtml(album.name)}</button></h3>
        <div class="album-meta-row">
          <div class="album-subtitle">${escapeHtml(album.album_artist)}</div>
          ${year}
        </div>
        ${ratingMarkup}
        <div class="chip-row">
          <span class="track-count">${summary.trackCount} track${summary.trackCount === 1 ? '' : 's'}</span>
          ${length}
        </div>
      </div>
    </section>
  `;
}

function getAlbumCardRating(album) {
  const rating = album?.album_preference?.rating;
  return Number.isInteger(rating) && rating >= 1 && rating <= 10 ? rating : null;
}

function getAlbumCardRenderKey(album) {
  const summary = getAlbumCardSummary(album);
  return JSON.stringify([
    getAlbumCardNodeIdentity(album),
    getAlbumCardVersionKey(album),
    String(album?.name || ''),
    String(album?.album_artist || ''),
    String(album?.year || ''),
    getAlbumCardRating(album),
    Number(summary.trackCount || 0),
    String(summary.lengthDisplay || ''),
    albumHasDisplayCover(album) ? buildAlbumDisplayCoverUrl(album) : '',
    String(album?.cover_path || '').trim(),
    String(album?.remote_cover_thumbnail_url || album?.remote_cover_url || '').trim(),
  ]);
}

function getAlbumCardNodeIdentity(album) {
  return getAlbumRequestKey(album) || getAlbumIdentity(album);
}

function getAlbumCardSummary(album) {
  const tracks = Array.isArray(album?.tracks) ? album.tracks : [];
  const previewTrackCount = Number(album?.track_count_preview || 0);
  const totalTrackCount = album?.preview_only === true
    ? Math.max(tracks.length, previewTrackCount)
    : (tracks.length || previewTrackCount);
  const totalSeconds = Number(album?.total_duration_seconds || 0);
  const totalLengthDisplay = album?.total_duration_display || formatAlbumDuration(totalSeconds);
  if (album?.preview_only === true || !tracks.length || typeof groupAlbumTracks !== 'function') {
    return {
      trackCount: totalTrackCount,
      lengthDisplay: totalLengthDisplay,
    };
  }
  const grouped = groupAlbumTracks(tracks);
  const groups = Array.isArray(grouped?.groups) ? grouped.groups : [];
  const mainGroups = groups.filter((group) => !group?.isBonus);
  const bonusGroups = groups.filter((group) => Boolean(group?.isBonus));
  if (!bonusGroups.length || !mainGroups.length) {
    return {
      trackCount: totalTrackCount,
      lengthDisplay: totalLengthDisplay,
    };
  }
  const trackCount = mainGroups.reduce((sum, group) => sum + ((Array.isArray(group?.tracks) ? group.tracks.length : 0)), 0);
  const seconds = mainGroups.reduce(
    (sum, group) => sum + (Array.isArray(group?.tracks)
      ? group.tracks.reduce((inner, track) => inner + (Number(track?.duration_seconds || 0) || 0), 0)
      : 0),
    0,
  );
  return {
    trackCount: trackCount || totalTrackCount,
    lengthDisplay: formatAlbumDuration(seconds) || totalLengthDisplay,
  };
}

function buildAlbumCardCoverHtml(album, options = {}) {
  if (!albumHasDisplayCover(album)) {
    return '<div class="cover-placeholder">No cover art</div>';
  }
  const coverPriority = options.coverPriority === 'visible' ? 'visible' : 'near';
  const loadingAttribute = coverPriority === 'visible' ? 'eager' : 'lazy';
  const fetchPriorityAttribute = coverPriority === 'visible' ? 'high' : 'low';
  const coverSrc = buildAlbumDisplayCoverUrl(album);
  const localCoverPath = typeof options.localCoverPath === 'string'
    ? options.localCoverPath
    : escapeHtml(String(album?.cover_path || '').trim());
  const remoteCoverUrl = typeof options.remoteCoverUrl === 'string'
    ? options.remoteCoverUrl
    : escapeHtml(String(album?.remote_cover_thumbnail_url || album?.remote_cover_url || '').trim());
  const coverAlt = escapeHtml(`Album cover for ${album.name}`);
  return `<img loading="${loadingAttribute}" fetchpriority="${fetchPriorityAttribute}" decoding="async" data-gallery-cover-priority="${coverPriority}" data-gallery-cover-src="${coverSrc}" data-production-cover-src="${coverSrc}" data-cover-visual-state="pending" aria-hidden="true" alt="${coverAlt}" data-cover-path="${localCoverPath}" data-remote-cover-url="${remoteCoverUrl}" onload="handleAlbumDisplayCoverImageLoad(this)" onerror="handleAlbumDisplayCoverImageError(this)">`;
}

function refreshRenderedAlbumCoverOnly(updatedAlbum) {
  if (!updatedAlbum) return;
  const updatedSignature = getAlbumIdentity(updatedAlbum);
  const updatedRequestKey = getAlbumRequestKey(updatedAlbum);
  if (!updatedSignature && !updatedRequestKey) return;
  document.querySelectorAll('.album-card').forEach((card) => {
    const trigger = card.querySelector('[data-open-tracklist="1"][data-album-key]');
    if (!(trigger instanceof HTMLElement)) return;
    const triggerAlbumKey = String(trigger.getAttribute('data-album-key') || '').trim();
    if (triggerAlbumKey !== updatedRequestKey && triggerAlbumKey !== updatedSignature) return;
    if (updatedSignature) {
      state.gallery.albumIndex.set(updatedSignature, updatedAlbum);
    }
    if (updatedRequestKey) {
      state.gallery.albumIndex.set(updatedRequestKey, updatedAlbum);
    }
    card.querySelectorAll('[data-album-key]').forEach((element) => {
      element.setAttribute('data-album-key', updatedRequestKey || updatedSignature);
    });
    const coverButton = card.querySelector('.cover.album-open-trigger');
    if (coverButton) {
      const previousImage = coverButton.querySelector('img[data-production-cover-src]');
      const previousProductionUrl = String(previousImage?.getAttribute('data-production-cover-src') || '').trim();
      if (
        previousProductionUrl
        && typeof galleryCoverPreviewCache !== 'undefined'
        && typeof galleryCoverPreviewCache.invalidate === 'function'
      ) {
        galleryCoverPreviewCache.invalidate(previousProductionUrl);
      }
      coverButton.innerHTML = buildAlbumCardCoverHtml(updatedAlbum);
      if (
        typeof virtualGrid !== 'undefined'
        && typeof virtualGrid.activateGalleryCoverImages === 'function'
      ) {
        virtualGrid.activateGalleryCoverImages(coverButton);
      }
    }
  });
}

function getAlbumRequestKey(album) {
  return String(album?.key || album?.album_ref || '').trim() || getAlbumPathSignature(album);
}

function getAlbumIdentity(album) {
  return getAlbumPathSignature(album) || getAlbumRequestKey(album);
}

function rebuildAlbumIndex(groupsList) {
  const nextIndex = new Map();
  (Array.isArray(groupsList) ? groupsList : []).forEach((group) => {
    (Array.isArray(group?.albums) ? group.albums : []).forEach((album) => {
      const key = getAlbumIdentity(album);
      const requestKey = getAlbumRequestKey(album);
      const versionKey = getAlbumCardVersionKey(album);
      if (key) nextIndex.set(key, album);
      if (requestKey) nextIndex.set(requestKey, album);
      if (versionKey) nextIndex.set(versionKey, album);
    });
  });
  state.gallery.albumIndex = nextIndex;
}

function getIndexedAlbum(albumKey) {
  return state.gallery.albumIndex.get(String(albumKey || '').trim()) || null;
}

var CARD_GALLERY_LAYOUT_CONFIG = Object.freeze({
  mode: 'cards',
  cardMinWidth: 240,
  measuredItemSelector: '.album-card',
  renderAlbumHtml: albumCardHtml,
});

const DEFAULT_GALLERY_SCALE_PERCENT = 100;
const MIN_GALLERY_SCALE_PERCENT = 80;
const MAX_GALLERY_SCALE_PERCENT = 140;

function resolveGalleryScalePercent(value) {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue)) return DEFAULT_GALLERY_SCALE_PERCENT;
  return Math.min(MAX_GALLERY_SCALE_PERCENT, Math.max(MIN_GALLERY_SCALE_PERCENT, numericValue));
}

function resolveGalleryCardWidth(layoutConfig = CARD_GALLERY_LAYOUT_CONFIG) {
  const baseWidth = Math.max(1, Number(layoutConfig?.cardMinWidth) || 240);
  const scalePercent = resolveGalleryScalePercent(state?.view?.gallery_scale_percent);
  return Math.max(1, Math.round(baseWidth * (scalePercent / 100)));
}

function buildAlbumRowGridTemplate(columns, cardTrackWidth) {
  const safeColumns = Math.max(1, Math.floor(Number(columns) || 1));
  const safeTrackWidth = Math.max(1, Math.round(Number(cardTrackWidth) || 1));
  return `repeat(${safeColumns}, minmax(0, ${safeTrackWidth}px))`;
}

const MAX_PRIORITY_VISIBLE_COVER_IMAGES = 4;
const MAX_RETAINED_ALBUM_CARD_NODES = 48;
const MAX_VIRTUAL_GRID_DIAGNOSTIC_EVENTS = 24;
const VIRTUAL_GRID_SCROLL_RENDER_FALLBACK_MS = 100;

class VirtualArtistGrid {
  constructor() {
    this.scrollEl = document.getElementById('albums-scroll');
    this.containerEl = document.getElementById('artist-groups');
    this.topSpacerEl = document.getElementById('albums-spacer-top');
    this.bottomSpacerEl = document.getElementById('albums-spacer-bottom');
    this.layoutConfig = CARD_GALLERY_LAYOUT_CONFIG;
    this.columnGap = 14;
    this.rowGap = 14;
    this.sectionHeaderHeight = 54;
    this.sectionMarginBottom = 28;
    this.labelHeight = 40;
    this.subsectionLabelHeight = 26;
    this.collapsedRowHeight = 420;
    this.trackLineHeight = 28;
    this.expandedRowBaseExtra = 30;
    this.expandedTrackCap = 12;
    this.overscanPx = 320;
    this.bufferSections = 1;
    this.bufferSectionsOverride = null;
    this.sections = [];
    this.albumCardNodeCache = new Map();
    this.sectionByKey = new Map();
    this.columns = 1;
    this.cardTrackWidth = CARD_GALLERY_LAYOUT_CONFIG.cardMinWidth;
    this.lastKey = '';
    this._raf = null;
    this._scrollRenderFallbackTimer = 0;
    this._measureRaf = null;
    this._scrollRestoreRaf = null;
    this._stabilizeRaf = null;
    this._stabilizeGeneration = 0;
    this._pendingStabilizationScroll = null;
    this._absoluteScrollRestore = null;
    this._activeRenderRafOwner = 0;
    this._activeMeasureRafOwner = 0;
    this._renderGeneration = 0;
    this._preserveExistingChildrenGeneration = -1;
    this._coverLoadGeneration = 0;
    this._familyPrefetchScheduledCoverLoadGeneration = -1;
    this._selectedFamilyCoverUrls = new Set();
    this._selectedFamilyCoverOwner = '';
    this._nextCoverLoadUserActionToken = 0;
    this._activeCoverLoadUserActionTokens = new Set();
    this._activeAlbumCardPointerId = null;
    this._albumCardPointerGestureActive = false;
    this._albumCardPointerReleaseRaf = 0;
    this._deferredPointerGestureRender = null;
    this._measureTimeout = 0;
    this._resetScrollAfterMeasure = false;
    this.isScrollSettled = true;
    this._diagnosticSequence = 0;
    this.diagnostics = {
      maxEvents: MAX_VIRTUAL_GRID_DIAGNOSTIC_EVENTS,
      events: [],
      latestScroll: null,
      latestRender: null,
      latestMeasurement: null,
    };
    globalThis.__ALBUM_HAVEN_VIRTUAL_GRID__ = this.diagnostics;
    this.onScroll = this.onScroll.bind(this);
    this.onUserScrollIntent = this.onUserScrollIntent.bind(this);
    this.onResize = this.onResize.bind(this);
    this.onPointerDown = this.onPointerDown.bind(this);
    this.onAlbumCardPointerGestureEnd = this.onAlbumCardPointerGestureEnd.bind(this);
    this.scrollEl.addEventListener('scroll', this.onScroll, { passive: true });
    this.scrollEl.addEventListener('wheel', this.onUserScrollIntent, { passive: true });
    this.scrollEl.addEventListener('touchstart', this.onUserScrollIntent, { passive: true });
    this.scrollEl.addEventListener('pointerdown', this.onUserScrollIntent, { capture: true });
    if (this.containerEl && typeof this.containerEl.addEventListener === 'function') {
      this.containerEl.addEventListener('pointerdown', this.onPointerDown, { capture: true });
    }
    if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
      document.addEventListener('pointerup', this.onAlbumCardPointerGestureEnd, { capture: true });
      document.addEventListener('pointercancel', this.onAlbumCardPointerGestureEnd, { capture: true });
    }
    window.addEventListener('resize', this.onResize);
  }

  recordDiagnosticEvent(type, details = {}) {
    const event = {
      sequence: ++this._diagnosticSequence,
      type: String(type || 'unknown'),
      renderGeneration: Number(this._renderGeneration || 0),
      scrollTop: Number(this.scrollEl?.scrollTop || 0),
      renderRafOwner: Number(this._activeRenderRafOwner || this._raf || 0),
      measureRafOwner: Number(this._activeMeasureRafOwner || this._measureRaf || 0),
      ...details,
    };
    this.diagnostics.events.push(event);
    if (this.diagnostics.events.length > this.diagnostics.maxEvents) {
      this.diagnostics.events.splice(0, this.diagnostics.events.length - this.diagnostics.maxEvents);
    }
    return event;
  }

  getLayoutConfig(layoutConfig = null) {
    if (layoutConfig && typeof layoutConfig === 'object') {
      return layoutConfig;
    }
    if (this.layoutConfig && typeof this.layoutConfig === 'object') {
      return this.layoutConfig;
    }
    return CARD_GALLERY_LAYOUT_CONFIG;
  }

  setLayoutConfig(layoutConfig = null) {
    this.layoutConfig = this.getLayoutConfig(layoutConfig);
  }

  destroy() {
    this._renderGeneration += 1;
    this.scrollEl.removeEventListener('scroll', this.onScroll);
    this.scrollEl.removeEventListener('wheel', this.onUserScrollIntent);
    this.scrollEl.removeEventListener('touchstart', this.onUserScrollIntent);
    this.scrollEl.removeEventListener('pointerdown', this.onUserScrollIntent, { capture: true });
    if (this.containerEl && typeof this.containerEl.removeEventListener === 'function') {
      this.containerEl.removeEventListener('pointerdown', this.onPointerDown, { capture: true });
    }
    if (typeof document !== 'undefined' && typeof document.removeEventListener === 'function') {
      document.removeEventListener('pointerup', this.onAlbumCardPointerGestureEnd, { capture: true });
      document.removeEventListener('pointercancel', this.onAlbumCardPointerGestureEnd, { capture: true });
    }
    window.removeEventListener('resize', this.onResize);
    if (this._scrollRestoreRaf) {
      cancelBrowserAnimationFrame(this._scrollRestoreRaf);
      this._scrollRestoreRaf = null;
    }
    this.invalidateScrollStabilization();
    if (this._raf) {
      cancelBrowserAnimationFrame(this._raf);
      this._raf = null;
    }
    if (this._scrollRenderFallbackTimer) {
      clearBrowserTimeout(this._scrollRenderFallbackTimer);
      this._scrollRenderFallbackTimer = 0;
    }
    if (this._albumCardPointerReleaseRaf) {
      cancelBrowserAnimationFrame(this._albumCardPointerReleaseRaf);
      this._albumCardPointerReleaseRaf = 0;
    }
    this._albumCardPointerGestureActive = false;
    this._activeAlbumCardPointerId = null;
    this._deferredPointerGestureRender = null;
    if (this._measureRaf) {
      cancelBrowserAnimationFrame(this._measureRaf);
      this._measureRaf = null;
    }
    if (this._measureTimeout) {
      clearBrowserTimeout(this._measureTimeout);
      this._measureTimeout = 0;
    }
    this.resumeSelectedArtistCoverLoadsAfterUserAction(0, { force: true });
    this.albumCardNodeCache.clear();
    if (typeof galleryCoverPreviewCache !== 'undefined' && typeof galleryCoverPreviewCache.destroy === 'function') {
      galleryCoverPreviewCache.destroy();
    }
  }

  onPointerDown(event) {
    const target = event?.target;
    const closest = typeof target?.closest === 'function'
      ? target.closest('[data-open-tracklist="1"][data-album-key], .album-card')
      : null;
    if (!closest) return;
    if (this._albumCardPointerReleaseRaf) {
      cancelBrowserAnimationFrame(this._albumCardPointerReleaseRaf);
      this._albumCardPointerReleaseRaf = 0;
    }
    this._albumCardPointerGestureActive = true;
    this._activeAlbumCardPointerId = Number.isFinite(Number(event?.pointerId))
      ? Number(event.pointerId)
      : null;
  }

  onAlbumCardPointerGestureEnd(event) {
    if (!this._albumCardPointerGestureActive) return;
    const pointerId = Number.isFinite(Number(event?.pointerId)) ? Number(event.pointerId) : null;
    if (
      this._activeAlbumCardPointerId !== null
      && pointerId !== null
      && pointerId !== this._activeAlbumCardPointerId
    ) {
      return;
    }
    this._albumCardPointerGestureActive = false;
    this._activeAlbumCardPointerId = null;
    if (this._albumCardPointerReleaseRaf) return;
    this._albumCardPointerReleaseRaf = scheduleBrowserAnimationFrame(() => {
      this._albumCardPointerReleaseRaf = 0;
      if (this._albumCardPointerGestureActive) return;
      const deferredRender = this._deferredPointerGestureRender;
      this._deferredPointerGestureRender = null;
      if (!deferredRender) return;
      const previousActiveRenderRafOwner = this._activeRenderRafOwner;
      try {
        this._activeRenderRafOwner = Number(deferredRender.renderRafOwner || 0);
        this.render(deferredRender.force, deferredRender.options);
      } finally {
        this._activeRenderRafOwner = previousActiveRenderRafOwner;
      }
    });
  }

  suspendSelectedArtistCoverLoadsForUserAction() {
    if (typeof galleryCoverLoadScheduler === 'undefined') return 0;
    this._nextCoverLoadUserActionToken += 1;
    const token = this._nextCoverLoadUserActionToken;
    const shouldSuspendScheduler = this._activeCoverLoadUserActionTokens.size === 0;
    this._activeCoverLoadUserActionTokens.add(token);
    if (shouldSuspendScheduler) {
      galleryCoverLoadScheduler.suspend?.('utility-modal-preemption');
    }
    return token;
  }

  resumeSelectedArtistCoverLoadsAfterUserAction(token = 0, options = {}) {
    const force = options?.force === true;
    const normalizedToken = Number(token);
    if (!force && (!normalizedToken || !this._activeCoverLoadUserActionTokens.has(normalizedToken))) {
      return false;
    }
    if (!this._activeCoverLoadUserActionTokens.size) return false;
    if (force) {
      this._activeCoverLoadUserActionTokens.clear();
    } else {
      this._activeCoverLoadUserActionTokens.delete(normalizedToken);
    }
    if (this._activeCoverLoadUserActionTokens.size) return true;
    if (
      typeof galleryCoverLoadScheduler !== 'undefined'
      && typeof galleryCoverLoadScheduler.resume === 'function'
    ) {
      galleryCoverLoadScheduler.resume();
    }
    return true;
  }

  captureScrollAnchor() {
    if (!this.scrollEl || !this.containerEl) return null;
    const scrollLeft = Number(this.scrollEl.scrollLeft || 0);
    const scrollTop = Number(this.scrollEl.scrollTop || 0);
    const scrollRect = typeof this.scrollEl.getBoundingClientRect === 'function'
      ? this.scrollEl.getBoundingClientRect()
      : null;
    if (!scrollRect) {
      return { scrollLeft, scrollTop };
    }
    const cardTriggers = Array.from(this.containerEl.querySelectorAll('[data-open-tracklist="1"][data-album-key]'));
    const anchorCardTrigger = cardTriggers.find((element) => element.getBoundingClientRect().bottom >= scrollRect.top + 1) || cardTriggers[0] || null;
    if (anchorCardTrigger instanceof HTMLElement) {
      const anchorRect = anchorCardTrigger.getBoundingClientRect();
      let albumName = '';
      let albumYear = '';
      try {
        const album = JSON.parse(anchorCardTrigger.getAttribute('data-album') || '{}');
        albumName = String(album?.name || '');
        albumYear = String(album?.year ?? '');
      } catch (_error) {
        albumName = '';
        albumYear = '';
      }
      return {
        scrollLeft,
        scrollTop,
        albumKey: String(anchorCardTrigger.getAttribute('data-album-key') || ''),
        albumName,
        albumYear,
        sectionOccurrenceKey: this.getRenderedSectionOccurrenceKey(anchorCardTrigger, this.containerEl),
        offsetTop: anchorRect.top - scrollRect.top,
      };
    }
    const rows = Array.from(this.containerEl.querySelectorAll('.album-row[data-section-key][data-block-index]'));
    const anchorRow = rows.find((rowEl) => rowEl.getBoundingClientRect().bottom >= scrollRect.top + 1) || rows[0] || null;
    if (!(anchorRow instanceof HTMLElement)) {
      return { scrollLeft, scrollTop };
    }
    const anchorRect = anchorRow.getBoundingClientRect();
    return {
      scrollLeft,
      scrollTop,
      sectionKey: String(anchorRow.getAttribute('data-section-key') || ''),
      blockIndex: String(anchorRow.getAttribute('data-block-index') || ''),
      offsetTop: anchorRect.top - scrollRect.top,
    };
  }

  restoreScrollAnchor(anchor) {
    if (!this.scrollEl || !anchor) return;
    this.scrollEl.scrollLeft = Number(anchor.scrollLeft || 0);
    const albumKey = String(anchor.albumKey || '');
    if (albumKey) {
      const sectionOccurrenceKey = String(anchor.sectionOccurrenceKey || '');
      const albumTriggers = Array.from(
        this.containerEl.querySelectorAll('[data-open-tracklist="1"][data-album-key]'),
      );
      const matchingAlbumTriggers = albumTriggers.filter((element) => (
        String(element.getAttribute('data-album-key') || '') === albumKey
      ));
      const anchorAlbumName = String(anchor.albumName || '');
      const anchorAlbumYear = String(anchor.albumYear ?? '');
      const matchesCapturedRelease = (element) => {
        if (!anchorAlbumName) return true;
        try {
          const album = JSON.parse(element.getAttribute('data-album') || '{}');
          return String(album?.name || '') === anchorAlbumName
            && (!anchorAlbumYear || String(album?.year ?? '') === anchorAlbumYear);
        } catch (_error) {
          return false;
        }
      };
      const anchorCardTrigger = (
        sectionOccurrenceKey
          ? matchingAlbumTriggers.find((element) => (
            this.getRenderedSectionOccurrenceKey(element, this.containerEl) === sectionOccurrenceKey
            && matchesCapturedRelease(element)
          ))
          : null
      );
      const capturedOccurrenceStillExists = Boolean(sectionOccurrenceKey) && this.sections.some((section) => (
        this.getRenderedSectionKey(section) === sectionOccurrenceKey
      ));
      const fallbackAlbumTrigger = !sectionOccurrenceKey || !capturedOccurrenceStillExists
        ? matchingAlbumTriggers[0] || null
        : null;
      const renamedKeyTrigger = !anchorCardTrigger && anchorAlbumName
        ? albumTriggers.find((element) => {
          if (this.getRenderedSectionOccurrenceKey(element, this.containerEl) !== sectionOccurrenceKey) {
            return false;
          }
          return matchesCapturedRelease(element);
        }) || null
        : null;
      const resolvedAnchorCardTrigger = anchorCardTrigger || renamedKeyTrigger || fallbackAlbumTrigger;
      if (resolvedAnchorCardTrigger instanceof HTMLElement && typeof this.scrollEl.getBoundingClientRect === 'function') {
        const scrollRect = this.scrollEl.getBoundingClientRect();
        const anchorRect = resolvedAnchorCardTrigger.getBoundingClientRect();
        const delta = (anchorRect.top - scrollRect.top) - Number(anchor.offsetTop || 0);
        this.scrollEl.scrollTop = Number(this.scrollEl.scrollTop || 0) + delta;
        return;
      }
      if (sectionOccurrenceKey && anchorAlbumName) {
        const modeledSection = this.sections.find((section) => (
          section.kind === 'artist'
          && this.getRenderedSectionKey(section) === sectionOccurrenceKey
        ));
        const modeledAlbums = Array.isArray(modeledSection?.group?.albums)
          ? modeledSection.group.albums
          : [];
        const modeledAlbumIndex = modeledAlbums.findIndex((album) => (
          String(album?.name || '') === anchorAlbumName
          && (!anchorAlbumYear || String(album?.year ?? '') === anchorAlbumYear)
        ));
        if (modeledAlbumIndex >= 0) {
          const blockIndex = Math.floor(modeledAlbumIndex / Math.max(1, Number(this.columns || 1)));
          const modeledBlockOffset = Number(modeledSection.blockOffsets?.[blockIndex]);
          const modeledSectionTop = Number(modeledSection.top);
          if (Number.isFinite(modeledBlockOffset) && Number.isFinite(modeledSectionTop)) {
            const modeledCardTop = modeledSectionTop + this.sectionHeaderHeight + modeledBlockOffset;
            this.scrollEl.scrollTop = Math.max(0, modeledCardTop - Number(anchor.offsetTop || 0));
            return;
          }
        }
      }
    }
    const sectionKey = String(anchor.sectionKey || '');
    const blockIndex = String(anchor.blockIndex || '');
    if (!sectionKey || !blockIndex) {
      this.scrollEl.scrollTop = Number(anchor.scrollTop || 0);
      return;
    }
    const anchorRow = Array.from(this.containerEl.querySelectorAll('.album-row[data-section-key][data-block-index]')).find((rowEl) => (
      String(rowEl.getAttribute('data-section-key') || '') === sectionKey
      && String(rowEl.getAttribute('data-block-index') || '') === blockIndex
    ));
    if (!(anchorRow instanceof HTMLElement) || typeof this.scrollEl.getBoundingClientRect !== 'function') {
      this.scrollEl.scrollTop = Number(anchor.scrollTop || 0);
      return;
    }
    const scrollRect = this.scrollEl.getBoundingClientRect();
    const anchorRect = anchorRow.getBoundingClientRect();
    const delta = (anchorRect.top - scrollRect.top) - Number(anchor.offsetTop || 0);
    this.scrollEl.scrollTop = Number(this.scrollEl.scrollTop || 0) + delta;
  }

  invalidateScrollStabilization(options = {}) {
    this._stabilizeGeneration += 1;
    this._pendingStabilizationScroll = null;
    if (this._stabilizeRaf) {
      cancelBrowserAnimationFrame(this._stabilizeRaf);
      this._stabilizeRaf = null;
    }
    if (options.preserveAbsoluteScroll === true || !this._absoluteScrollRestore) return;
    this._absoluteScrollRestore = null;
    if (!this._scrollRestoreRaf) return;
    cancelBrowserAnimationFrame(this._scrollRestoreRaf);
    this._scrollRestoreRaf = null;
  }

  isPendingStabilizationScroll() {
    const pending = this._pendingStabilizationScroll;
    return Boolean(
      pending
      && pending.generation === this._stabilizeGeneration
      && pending.scrollTop === Number(this.scrollEl?.scrollTop || 0)
      && pending.scrollLeft === Number(this.scrollEl?.scrollLeft || 0)
    );
  }

  restoreOwnedAbsoluteScrollPosition(position) {
    if (
      !this.scrollEl
      || !Number.isFinite(Number(position?.scrollTop))
      || !Number.isFinite(Number(position?.scrollLeft))
    ) return false;
    this.invalidateScrollStabilization();
    const preservedAbsoluteScroll = {
      renderGeneration: this._renderGeneration,
      scrollLeft: Math.max(0, Number(position.scrollLeft)),
      scrollTop: Math.max(0, Number(position.scrollTop)),
    };
    this._absoluteScrollRestore = preservedAbsoluteScroll;
    const restoreScroll = () => {
      if (this._absoluteScrollRestore !== preservedAbsoluteScroll) return;
      this.scrollEl.scrollLeft = preservedAbsoluteScroll.scrollLeft;
      this.scrollEl.scrollTop = preservedAbsoluteScroll.scrollTop;
      this._pendingStabilizationScroll = {
        generation: this._stabilizeGeneration,
        scrollLeft: preservedAbsoluteScroll.scrollLeft,
        scrollTop: preservedAbsoluteScroll.scrollTop,
      };
      this.primeVisibleCoverImages();
    };
    restoreScroll();
    this._scrollRestoreRaf = scheduleBrowserAnimationFrame(() => {
      this._scrollRestoreRaf = null;
      restoreScroll();
    });
    return true;
  }

  setGroups(primaryGroups, familyGroups, fallbackGroups = null, options = {}, layoutConfig = null) {
    const supersededScrollRenderRafOwner = Number(this._raf || 0);
    this._renderGeneration += 1;
    const renderGeneration = this._renderGeneration;
    this._preserveExistingChildrenGeneration = options.preserveMountedGalleryChildren
      ? renderGeneration
      : -1;
    if (typeof galleryCoverLoadScheduler !== 'undefined') {
      if (
        String(state?.view?.selected_artist || '').trim()
        && typeof galleryCoverLoadScheduler.ensureFamilyPrefetchReconciliation === 'function'
      ) {
        galleryCoverLoadScheduler.ensureFamilyPrefetchReconciliation();
      }
      this._coverLoadGeneration = galleryCoverLoadScheduler.startGeneration();
    }
    if (this._raf) {
      cancelBrowserAnimationFrame(this._raf);
      this._raf = null;
    }
    if (this._scrollRenderFallbackTimer) {
      clearBrowserTimeout(this._scrollRenderFallbackTimer);
      this._scrollRenderFallbackTimer = 0;
    }
    if (this._measureRaf) {
      cancelBrowserAnimationFrame(this._measureRaf);
      this._measureRaf = null;
    }
    if (this._scrollRestoreRaf) {
      cancelBrowserAnimationFrame(this._scrollRestoreRaf);
      this._scrollRestoreRaf = null;
    }
    this.invalidateScrollStabilization();
    if (this._measureTimeout) {
      clearBrowserTimeout(this._measureTimeout);
      this._measureTimeout = 0;
    }
    this.isScrollSettled = true;
    this.setLayoutConfig(layoutConfig);
    const preserveScroll = Boolean(options.preserveScroll)
      && options.resetScrollForUserArtistSelection !== true;
    this._resetScrollAfterMeasure = !preserveScroll;
    this.bufferSectionsOverride = !preserveScroll && Boolean(state.view?.selected_artist) ? 0 : null;
    const requestedAbsoluteScroll = options.absoluteScrollPosition
      && Number.isFinite(Number(options.absoluteScrollPosition.scrollTop))
      && Number.isFinite(Number(options.absoluteScrollPosition.scrollLeft))
      ? {
        scrollLeft: Math.max(0, Number(options.absoluteScrollPosition.scrollLeft)),
        scrollTop: Math.max(0, Number(options.absoluteScrollPosition.scrollTop)),
      }
      : null;
    const preservedAbsoluteScroll = preserveScroll && options.preserveAbsoluteScroll === true
      ? {
        renderGeneration,
        scrollLeft: requestedAbsoluteScroll?.scrollLeft ?? Number(this.scrollEl?.scrollLeft || 0),
        scrollTop: requestedAbsoluteScroll?.scrollTop ?? Number(this.scrollEl?.scrollTop || 0),
      }
      : null;
    const preservedAnchor = preserveScroll && !preservedAbsoluteScroll
      ? this.captureScrollAnchor()
      : null;
    this._absoluteScrollRestore = preservedAbsoluteScroll;
    const sections = [];
    const renderedPrimaryGroups = buildDisplayGroups(primaryGroups);
    const renderedFamilyGroups = buildDisplayGroups(familyGroups);
    const renderedFallbackGroups = buildDisplayGroups(fallbackGroups || state.view.artist_groups || []);
    const selectedFamilyCoverOwner = String(state?.view?.selected_artist || '').trim();
    if (selectedFamilyCoverOwner) {
      const selectedFamilyFilterActive = Boolean(state?.view?.primary_filter_active)
        || (Array.isArray(state?.view?.related_filter_artists)
          && state.view.related_filter_artists.length > 0);
      if (
        selectedFamilyCoverOwner !== this._selectedFamilyCoverOwner
        || !selectedFamilyFilterActive
      ) {
        this._selectedFamilyCoverUrls.clear();
        this._selectedFamilyCoverOwner = selectedFamilyCoverOwner;
      }
      [...renderedPrimaryGroups, ...renderedFamilyGroups].forEach((group) => {
        (Array.isArray(group?.albums) ? group.albums : []).forEach((album) => {
          const productionUrl = buildAlbumDisplayCoverUrl(album);
          if (productionUrl) this._selectedFamilyCoverUrls.add(productionUrl);
        });
      });
    } else {
      this._selectedFamilyCoverUrls.clear();
      this._selectedFamilyCoverOwner = '';
    }
    if (renderedPrimaryGroups.length) {
      sections.push({ kind: 'label', title: 'Primary Artist' });
      renderedPrimaryGroups.forEach((group) => sections.push({ kind: 'artist', group, sectionType: 'primary', sectionKey: '' }));
    }
    if (renderedFamilyGroups.length) {
      sections.push({ kind: 'label', title: 'Family' });
      renderedFamilyGroups.forEach((group) => sections.push({ kind: 'artist', group, sectionType: 'family', sectionKey: '' }));
    }
    if (!renderedPrimaryGroups.length && !renderedFamilyGroups.length) {
      renderedFallbackGroups.forEach((group) => sections.push({ kind: 'artist', group, sectionType: 'all', sectionKey: '' }));
    }
    const previousSectionsByMeasurementKey = new Map(
      this.sections
        .filter((section) => section.kind === 'artist' && section.measurementKey)
        .map((section) => [section.measurementKey, section]),
    );
    const measurementOccurrenceByArtist = new Map();
    sections.forEach((section) => {
      if (section.kind !== 'artist') return;
      const measurementArtistKey = `${section.sectionType}\u0000${String(
        section.group?.display_artist_key || section.group?.artist || '',
      )}`;
      const measurementOccurrence = Number(measurementOccurrenceByArtist.get(measurementArtistKey) || 0);
      measurementOccurrenceByArtist.set(measurementArtistKey, measurementOccurrence + 1);
      section.measurementKey = `${measurementArtistKey}\u0000${measurementOccurrence}`;
      section.sectionKey = `${section.sectionType}:${String(
        section.group?.display_artist_key || section.group?.artist || '',
      )}:${measurementOccurrence}`;
      const previousSection = previousSectionsByMeasurementKey.get(section.measurementKey);
      if (!previousSection) return;
      section.blockHeights = Array.isArray(previousSection.blockHeights)
        ? previousSection.blockHeights.slice()
        : [];
      section.blockMeasureKeys = Array.isArray(previousSection.blockMeasureKeys)
        ? previousSection.blockMeasureKeys.slice()
        : [];
      section.measuredBlockKeys = Array.isArray(previousSection.measuredBlockKeys)
        ? previousSection.measuredBlockKeys.slice()
        : [];
    });
    this.sections = sections;
    rebuildAlbumIndex(
      sections
        .filter((section) => section.kind === 'artist')
        .map((section) => section.group),
    );
    this.lastKey = '';
    this.recalculate();
    if (!preserveScroll && this.scrollEl) {
      this.scrollEl.scrollTop = 0;
    }
    if (preservedAbsoluteScroll && this.scrollEl) {
      this.scrollEl.scrollLeft = preservedAbsoluteScroll.scrollLeft;
      this.scrollEl.scrollTop = preservedAbsoluteScroll.scrollTop;
    }
    const previousActiveRenderRafOwner = this._activeRenderRafOwner;
    if (supersededScrollRenderRafOwner) {
      this._activeRenderRafOwner = supersededScrollRenderRafOwner;
      this.updateScrollDiagnostic(supersededScrollRenderRafOwner, true);
    }
    try {
      this.render(true, {
        preserveExistingChildren: Boolean(options.preserveMountedGalleryChildren),
      });
    } finally {
      this._activeRenderRafOwner = previousActiveRenderRafOwner;
    }
    const scheduleSettledScrollRestore = (restoreScroll) => {
      let scrollRestoreRafOwner = 0;
      scrollRestoreRafOwner = scheduleBrowserAnimationFrame(() => {
        if (
          this._scrollRestoreRaf !== scrollRestoreRafOwner
          || renderGeneration !== this._renderGeneration
        ) return;
        this._scrollRestoreRaf = null;
        restoreScroll();
        const latestRender = this.diagnostics.latestRender;
        if (
          Number(latestRender?.renderGeneration || 0) !== renderGeneration
          || Math.abs(
            Number(latestRender?.viewportTop || 0) - Number(this.scrollEl?.scrollTop || 0),
          ) > 2
        ) return;
        this.updateScrollDiagnostic(scrollRestoreRafOwner);
        this.diagnostics.latestRender = {
          ...latestRender,
          renderRafOwner: scrollRestoreRafOwner,
        };
        this.recordDiagnosticEvent('scroll-restore-settled', {
          renderGeneration,
          renderRafOwner: scrollRestoreRafOwner,
          scrollTop: Number(this.scrollEl?.scrollTop || 0),
        });
      });
      this._scrollRestoreRaf = scrollRestoreRafOwner;
    };
    if (!preserveScroll && this.scrollEl) {
      const resetScroll = () => {
        if (renderGeneration !== this._renderGeneration) return;
        this.scrollEl.scrollTop = 0;
        this.primeVisibleCoverImages();
      };
      resetScroll();
      scheduleSettledScrollRestore(resetScroll);
    } else if (preserveScroll && this.scrollEl) {
      const restoreScroll = () => {
        if (renderGeneration !== this._renderGeneration) return;
        if (preservedAbsoluteScroll) {
          if (this._absoluteScrollRestore !== preservedAbsoluteScroll) return;
          this.scrollEl.scrollLeft = preservedAbsoluteScroll.scrollLeft;
          this.scrollEl.scrollTop = preservedAbsoluteScroll.scrollTop;
          this._pendingStabilizationScroll = {
            generation: this._stabilizeGeneration,
            scrollLeft: preservedAbsoluteScroll.scrollLeft,
            scrollTop: preservedAbsoluteScroll.scrollTop,
          };
        } else {
          this.restoreScrollAnchor(preservedAnchor);
        }
        this.primeVisibleCoverImages();
      };
      restoreScroll();
      scheduleSettledScrollRestore(restoreScroll);
    }
  }

  getRowsForSection(section) {
    const albums = Array.isArray(section.group?.albums) ? section.group.albums : [];
    const rows = [];
    for (let start = 0; start < albums.length; start += this.columns) {
      rows.push(albums.slice(start, start + this.columns));
    }
    return rows;
  }

  getBlocksForSection(section) {
    const blocks = [];
    const normalRows = this.getRowsForSection(section);
    normalRows.forEach((albums) => blocks.push({ kind: 'row', albums }));
    return blocks.length ? blocks : [];
  }

  getBlockMeasureKey(block) {
    if (!block || block.kind !== 'row') {
      return `static:${block?.kind || 'unknown'}:${block?.title || ''}`;
    }
    const albumKey = Array.isArray(block.albums)
      ? block.albums.map((album) => getAlbumIdentity(album)).join('|')
      : '';
    return `row:${this.columns}:${albumKey}`;
  }

  recalculate() {
    const layoutConfig = this.getLayoutConfig();
    const selectedCardWidth = resolveGalleryCardWidth(layoutConfig);
    const width = Math.max(1, this.scrollEl.clientWidth - 8);
    this.cardTrackWidth = Math.min(selectedCardWidth, width);
    this.columns = Math.max(1, Math.floor((width + this.columnGap) / (selectedCardWidth + this.columnGap)));
    let offsetTop = 0;
    this.sectionByKey = new Map();
    this.sections.forEach((section) => {
      section.top = offsetTop;
      if (section.kind === 'label') {
        section.height = this.labelHeight;
        offsetTop += section.height;
        section.bottom = offsetTop;
        return;
      }

      const blocks = this.getBlocksForSection(section);
      const previousMeasureKeys = Array.isArray(section.blockMeasureKeys) ? section.blockMeasureKeys : [];
      const previousMeasuredKeys = Array.isArray(section.measuredBlockKeys) ? section.measuredBlockKeys : [];
      const nextMeasureKeys = blocks.map((block) => this.getBlockMeasureKey(block));
      section.blocksData = blocks;
      if (!Array.isArray(section.blockHeights) || section.blockHeights.length !== blocks.length) {
        const previousBlockHeights = Array.isArray(section.blockHeights)
          ? section.blockHeights
          : [];
        section.blockHeights = blocks.map((block, index) => {
          if (block.kind === 'subheading') return this.subsectionLabelHeight;
          const previousHeight = Number(previousBlockHeights[index] || 0);
          return previousHeight > 0 ? previousHeight : this.collapsedRowHeight;
        });
      } else {
        section.blockHeights = blocks.map((block, index) => (
          block.kind === 'subheading'
            ? this.subsectionLabelHeight
            : (section.blockHeights[index] || this.collapsedRowHeight)
        ));
      }
      section.blockMeasureKeys = nextMeasureKeys;
      section.measuredBlockKeys = nextMeasureKeys.map((key, index) => (
        previousMeasureKeys[index] === key ? String(previousMeasuredKeys[index] || '') : ''
      ));
      let blockOffset = 0;
      section.blockOffsets = blocks.map((_block, index) => {
        const top = blockOffset;
        blockOffset += section.blockHeights[index] || 0;
        if (index < blocks.length - 1) blockOffset += this.rowGap;
        return top;
      });
      section.blocksHeight = blockOffset;
      section.height = this.sectionHeaderHeight + section.blocksHeight + this.sectionMarginBottom;
      offsetTop += section.height;
      section.bottom = offsetTop;
      this.sectionByKey.set(section.sectionKey, section);
    });
    this.totalHeight = offsetTop;
  }

  updateScrollDiagnostic(renderRafOwner, coalesced = false) {
    const current = this.diagnostics.latestScroll;
    const shouldReuseCurrent = coalesced
      && current
      && Number(current.renderRafOwner || 0) === Number(renderRafOwner || 0);
    const event = shouldReuseCurrent
      ? current
      : this.recordDiagnosticEvent('scroll-event');
    event.renderGeneration = Number(this._renderGeneration || 0);
    event.scrollTop = Number(this.scrollEl?.scrollTop || 0);
    event.renderRafOwner = Number(renderRafOwner || 0);
    event.clientHeight = Number(this.scrollEl?.clientHeight || 0);
    event.pendingRenderRafOwner = Number(renderRafOwner || 0);
    event.pendingMeasureRafOwner = Number(this._measureRaf || 0);
    event.pendingMeasureTimeout = Number(this._measureTimeout || 0);
    event.coalescedScrollCount = shouldReuseCurrent
      ? Number(event.coalescedScrollCount || 0) + 1
      : 0;
    this.diagnostics.latestScroll = event;
  }

  onScroll() {
    const ownsPendingAbsoluteRestore = Boolean(
      this._absoluteScrollRestore,
    );
    const isOwnedStabilizationScroll = this.isPendingStabilizationScroll();
    if (!isOwnedStabilizationScroll && ownsPendingAbsoluteRestore) {
      this.scrollEl.scrollLeft = this._absoluteScrollRestore.scrollLeft;
      this.scrollEl.scrollTop = this._absoluteScrollRestore.scrollTop;
      this._pendingStabilizationScroll = {
        generation: this._stabilizeGeneration,
        scrollLeft: this._absoluteScrollRestore.scrollLeft,
        scrollTop: this._absoluteScrollRestore.scrollTop,
      };
    } else if (!isOwnedStabilizationScroll) {
      this.invalidateScrollStabilization();
    }
    this.isScrollSettled = false;
    if (this._measureTimeout) {
      clearBrowserTimeout(this._measureTimeout);
    }
    this._measureTimeout = scheduleBrowserTimeout(() => {
      this._measureTimeout = 0;
      this.isScrollSettled = true;
      this.scheduleMeasureRows(true);
    }, 96);
    if (this._raf) {
      this.updateScrollDiagnostic(this._raf, true);
      return;
    }
    let renderRafOwner = 0;
    const completeScrollRender = () => {
      if (this._raf !== renderRafOwner) return false;
      if (this._scrollRenderFallbackTimer) {
        clearBrowserTimeout(this._scrollRenderFallbackTimer);
        this._scrollRenderFallbackTimer = 0;
      }
      this._activeRenderRafOwner = renderRafOwner;
      this._raf = null;
      this.recordDiagnosticEvent('render-frame-started', { renderRafOwner });
      this.render();
      this._activeRenderRafOwner = 0;
      return true;
    };
    renderRafOwner = scheduleBrowserAnimationFrame(completeScrollRender);
    this._raf = renderRafOwner;
    this._scrollRenderFallbackTimer = scheduleBrowserTimeout(() => {
      this._scrollRenderFallbackTimer = 0;
      if (this._raf !== renderRafOwner) return;
      cancelBrowserAnimationFrame(renderRafOwner);
      this.recordDiagnosticEvent('scroll-render-fallback', { renderRafOwner });
      completeScrollRender();
    }, VIRTUAL_GRID_SCROLL_RENDER_FALLBACK_MS);
    this.updateScrollDiagnostic(renderRafOwner);
  }

  onUserScrollIntent() {
    this.invalidateScrollStabilization();
  }

  onResize() {
    this.lastKey = '';
    this.recalculate();
    this.render(true);
    this.scheduleMeasureRows(true);
  }

  render(force = false, options = {}) {
    if (this._albumCardPointerGestureActive || this._albumCardPointerReleaseRaf) {
      this._deferredPointerGestureRender = {
        force: Boolean(force),
        options: { ...options },
        renderRafOwner: Number(
          this._activeRenderRafOwner
          || this._deferredPointerGestureRender?.renderRafOwner
          || 0,
        ),
      };
      return;
    }
    const viewportTop = this.scrollEl.scrollTop;
    const latestScroll = this.diagnostics.latestScroll;
    const settledScrollRenderRafOwner = (
      Number(latestScroll?.renderGeneration || 0) === Number(this._renderGeneration || 0)
      && Math.abs(Number(latestScroll?.scrollTop || 0) - Number(viewportTop || 0)) <= 2
    )
      ? Number(latestScroll?.renderRafOwner || 0)
      : 0;
    const renderRafOwner = Number(
      this._activeRenderRafOwner || settledScrollRenderRafOwner || 0,
    );
    const viewportBottom = viewportTop + this.scrollEl.clientHeight;
    const start = Math.max(0, viewportTop - this.overscanPx);
    const end = viewportBottom + this.overscanPx;
    const configuredBufferSections = Number.isInteger(this.bufferSectionsOverride)
      ? this.bufferSectionsOverride
      : this.bufferSections;
    const effectiveBufferSections = String(state?.view?.selected_artist || '').trim()
      ? Math.max(3, configuredBufferSections)
      : configuredBufferSections;
    let firstIndex = this.sections.findIndex((section) => section.bottom >= start);
    if (firstIndex === -1) firstIndex = 0;
    let lastIndex = this.sections.length - 1;
    for (let i = firstIndex; i < this.sections.length; i += 1) {
      if (this.sections[i].top > end) {
        lastIndex = Math.max(firstIndex, i - 1);
        break;
      }
    }

    firstIndex = Math.max(0, firstIndex - effectiveBufferSections);
    lastIndex = Math.min(this.sections.length - 1, lastIndex + effectiveBufferSections);

    const visible = this.sections.slice(firstIndex, lastIndex + 1);
    const visibleRanges = visible
      .map((section) => {
        const range = this.getVisibleBlockRange(section, start, end);
        return range ? `${section.sectionKey}:${range.firstIndex}:${range.lastIndex}` : `${section.sectionKey}:label`;
      })
      .join('|');
    const rangeKey = `${firstIndex}:${lastIndex}:${this.columns}:${this.totalHeight}:${visibleRanges}`;
    if (!force && rangeKey === this.lastKey) {
      const skippedRender = {
        bottomSpacerHeight: Number.parseFloat(this.bottomSpacerEl?.style?.height || '0') || 0,
        end,
        firstIndex,
        force: false,
        lastIndex,
        rangeKey,
        renderGeneration: Number(this._renderGeneration || 0),
        renderRafOwner,
        start,
        topSpacerHeight: Number.parseFloat(this.topSpacerEl?.style?.height || '0') || 0,
        viewportBottom,
        viewportTop,
        visibleRanges,
      };
      this.diagnostics.latestRender = skippedRender;
      this.recordDiagnosticEvent('render-skipped-unchanged-range', skippedRender);
      return;
    }
    this.lastKey = rangeKey;

    this.topSpacerEl.style.height = `${visible.length ? visible[0].top : 0}px`;
    const bottomHeight = visible.length ? Math.max(0, this.totalHeight - visible[visible.length - 1].bottom) : 0;
    this.bottomSpacerEl.style.height = `${bottomHeight}px`;
    let foundFirstRenderedArtistSection = false;
    this.patchRenderedSections(visible.map((section) => {
      const isFirstRenderedArtistSection = section.kind === 'artist' && !foundFirstRenderedArtistSection;
      if (isFirstRenderedArtistSection) {
        foundFirstRenderedArtistSection = true;
      }
      return {
        key: this.getRenderedSectionKey(section),
        html: this.renderSection(section, start, end, {
          isFirstRenderedArtistSection,
          viewportTop,
          viewportBottom,
        }),
      };
    }), {
      preserveExistingChildren: Boolean(options.preserveExistingChildren),
    });
    this.activateGalleryCoverImages(this.containerEl);
    if (
      typeof galleryCoverLoadScheduler !== 'undefined'
      && typeof galleryCoverLoadScheduler.pruneObsoleteConsumerTasks === 'function'
    ) {
      galleryCoverLoadScheduler.pruneObsoleteConsumerTasks(this._coverLoadGeneration);
    }
    this.scheduleSelectedFamilyCoverPrefetch();
    this.primeVisibleCoverImages();
    this.scheduleMeasureRows(force);
    const completedRender = {
      bottomSpacerHeight: bottomHeight,
      end,
      firstIndex,
      force: Boolean(force),
      lastIndex,
      rangeKey,
      renderGeneration: Number(this._renderGeneration || 0),
      renderRafOwner,
      sections: visible.map((section) => {
        const range = this.getVisibleBlockRange(section, start, end);
        return {
          bottom: Number(section.bottom || 0),
          firstBlockIndex: range?.firstIndex ?? null,
          headerHeight: Number(section.headerHeight || this.sectionHeaderHeight || 0),
          key: String(section.sectionKey || section.title || ''),
          lastBlockIndex: range?.lastIndex ?? null,
          top: Number(section.top || 0),
        };
      }),
      start,
      topSpacerHeight: visible.length ? Number(visible[0].top || 0) : 0,
      viewportBottom,
      viewportTop,
      visibleRanges,
    };
    this.diagnostics.latestRender = completedRender;
    this.recordDiagnosticEvent('render-completed', completedRender);
  }

  primeVisibleCoverImages() {
    if (!(this.scrollEl instanceof HTMLElement) || !(this.containerEl instanceof HTMLElement)) {
      return;
    }
    if (String(state?.view?.selected_artist || '').trim()) {
      return;
    }
    const scrollRect = this.scrollEl.getBoundingClientRect();
    let promotedCoverCount = 0;
    this.containerEl.querySelectorAll('.cover img').forEach((image) => {
      if (!(image instanceof HTMLImageElement)) return;
      const rect = image.getBoundingClientRect();
      if (!(rect.width > 0 && rect.height > 0)) return;
      if (rect.bottom <= scrollRect.top || rect.top >= scrollRect.bottom) return;
      image.setAttribute('data-gallery-cover-priority', 'visible');
      const productionUrl = String(image.getAttribute('data-production-cover-src') || '').trim();
      if (
        productionUrl
        && typeof galleryCoverLoadScheduler !== 'undefined'
        && typeof galleryCoverLoadScheduler.promote === 'function'
      ) {
        galleryCoverLoadScheduler.promote(productionUrl, 'visible');
      }
      if (promotedCoverCount >= MAX_PRIORITY_VISIBLE_COVER_IMAGES) return;
      promotedCoverCount += 1;
      image.loading = 'eager';
      image.setAttribute('loading', 'eager');
      image.decoding = 'async';
      image.setAttribute('fetchpriority', 'high');
    });
  }

  isTrackModalOpenOrPending() {
    if (String(state?.ui?.pendingTrackModalLoadAlbumKey || '').trim()) {
      return true;
    }
    return Boolean(document?.body?.classList?.contains?.('modal-open'));
  }

  activateGalleryCoverImages(rootEl = this.containerEl) {
    if (!rootEl || typeof rootEl.querySelectorAll !== 'function') return;
    rootEl.querySelectorAll('img[data-gallery-cover-src]').forEach((image) => {
      if (!(image instanceof HTMLImageElement)) return;
      const productionUrl = String(image.getAttribute('data-gallery-cover-src') || '').trim();
      if (!productionUrl || image.getAttribute('data-gallery-cover-loading') === '1') return;
      image.setAttribute('data-gallery-cover-loading', '1');
      image.removeAttribute('data-gallery-cover-src');
      if (typeof galleryCoverLoadScheduler !== 'undefined') {
        galleryCoverLoadScheduler.enqueue(productionUrl, {
          generation: this._coverLoadGeneration,
          image,
          priority: String(image.getAttribute('data-gallery-cover-priority') || 'near'),
        });
      } else if (typeof loadGalleryCoverPreviewImage === 'function') {
        loadGalleryCoverPreviewImage(image, productionUrl);
      } else {
        image.setAttribute('src', productionUrl);
      }
    });
  }

  scheduleSelectedFamilyCoverPrefetch() {
    if (typeof galleryCoverLoadScheduler === 'undefined') return;
    if (this._familyPrefetchScheduledCoverLoadGeneration === this._coverLoadGeneration) return;
    this._familyPrefetchScheduledCoverLoadGeneration = this._coverLoadGeneration;
    const urls = new Set();
    if (String(state?.view?.selected_artist || '').trim()) {
      this._selectedFamilyCoverUrls.forEach((productionUrl) => urls.add(productionUrl));
    }
    if (typeof galleryCoverLoadScheduler.reconcileFamilyPrefetch === 'function') {
      galleryCoverLoadScheduler.reconcileFamilyPrefetch(urls, {
        generation: this._coverLoadGeneration,
      });
      return;
    }
    urls.forEach((productionUrl) => galleryCoverLoadScheduler.enqueue(productionUrl, {
      generation: this._coverLoadGeneration,
      priority: 'background',
    }));
  }

  getRenderedSectionKey(section) {
    if (section.kind === 'label') {
      return `label:${section.title || ''}`;
    }
    return `artist:${section.sectionKey || ''}`;
  }

  createRenderedSectionNode(record) {
    if (!record || !document?.createElement) return null;
    const scratch = document.createElement('div');
    scratch.innerHTML = String(record.html || '').trim();
    const node = scratch.firstElementChild || null;
    if (!node) return null;
    if (node.dataset) {
      node.dataset.virtualSectionKey = record.key;
    } else {
      node.setAttribute('data-virtual-section-key', record.key);
    }
    return node;
  }

  getRenderedSectionOccurrenceKey(element, rootEl = null) {
    const section = typeof element?.closest === 'function'
      ? element.closest('[data-virtual-section-key]')
      : null;
    return String(
      section?.dataset?.virtualSectionKey
      || section?.getAttribute?.('data-virtual-section-key')
      || rootEl?.dataset?.virtualSectionKey
      || rootEl?.getAttribute?.('data-virtual-section-key')
      || '',
    ).trim();
  }

  getAlbumCardNodeCacheKey(card, rootEl = null) {
    const identity = String(card?.getAttribute?.('data-gallery-card-key') || '').trim();
    if (!identity) return '';
    const sectionKey = this.getRenderedSectionOccurrenceKey(card, rootEl);
    return sectionKey ? `${sectionKey}\u0000${identity}` : identity;
  }

  rememberRenderedAlbumCards(rootEl) {
    if (!rootEl || typeof rootEl.querySelectorAll !== 'function') return;
    rootEl.querySelectorAll('.album-card[data-gallery-card-key]').forEach((card) => {
      const cacheKey = this.getAlbumCardNodeCacheKey(card, rootEl);
      const coverImage = typeof card?.querySelector === 'function' ? card.querySelector('.cover img') : null;
      const hasDecodedCover = coverImage instanceof HTMLImageElement
        && Boolean(coverImage.complete)
        && Number(coverImage.naturalWidth || 0) > 0;
      const hasPendingCover = coverImage instanceof HTMLImageElement
        && coverImage.getAttribute('data-cover-visual-state') === 'pending'
        && coverImage.getAttribute('data-gallery-cover-loading') === '1';
      if (!cacheKey || (!hasDecodedCover && !hasPendingCover)) return;
      this.albumCardNodeCache.delete(cacheKey);
      this.albumCardNodeCache.set(cacheKey, card);
      while (this.albumCardNodeCache.size > MAX_RETAINED_ALBUM_CARD_NODES) {
        const oldestIdentity = this.albumCardNodeCache.keys().next().value;
        if (!oldestIdentity) break;
        this.albumCardNodeCache.delete(oldestIdentity);
      }
    });
  }

  reuseRenderedAlbumCards(nextRoot) {
    if (!nextRoot || typeof nextRoot.querySelectorAll !== 'function') return;
    nextRoot.querySelectorAll('.album-card[data-gallery-card-key]').forEach((nextCard) => {
      const cacheKey = this.getAlbumCardNodeCacheKey(nextCard, nextRoot);
      const renderKey = String(nextCard?.getAttribute?.('data-gallery-card-render-key') || '');
      const retainedCard = cacheKey ? this.albumCardNodeCache.get(cacheKey) : null;
      if (
        !retainedCard
        || retainedCard === nextCard
        || String(retainedCard?.getAttribute?.('data-gallery-card-render-key') || '') !== renderKey
        || typeof nextCard.replaceWith !== 'function'
      ) {
        return;
      }
      nextCard.replaceWith(retainedCard);
      this.albumCardNodeCache.delete(cacheKey);
      this.albumCardNodeCache.set(cacheKey, retainedCard);
      const retainedImage = retainedCard.querySelector?.('img[data-production-cover-src]');
      const productionUrl = String(retainedImage?.getAttribute?.('data-production-cover-src') || '').trim();
      const retainedImageDecoded = retainedImage instanceof HTMLImageElement
        && Boolean(retainedImage.complete)
        && Number(retainedImage.naturalWidth || 0) > 0;
      const decodedObjectUrlEvicted = Boolean(productionUrl)
        && retainedImageDecoded
        && typeof galleryCoverPreviewCache !== 'undefined'
        && typeof galleryCoverPreviewCache.hasActive === 'function'
        && !galleryCoverPreviewCache.hasActive(productionUrl);
      if (productionUrl && (!retainedImageDecoded || decodedObjectUrlEvicted)) {
        retainedImage.setAttribute('data-gallery-cover-src', productionUrl);
        retainedImage.removeAttribute('data-gallery-cover-loading');
      }
    });
  }

  reuseMatchingMountedAlbumCards(existingRoot, nextRoot) {
    if (
      !existingRoot
      || !nextRoot
      || typeof existingRoot.querySelectorAll !== 'function'
      || typeof nextRoot.querySelectorAll !== 'function'
    ) {
      return;
    }
    const existingCardsByIdentity = new Map();
    existingRoot.querySelectorAll('.album-card[data-gallery-card-key]').forEach((card) => {
      const identity = String(card?.getAttribute?.('data-gallery-card-key') || '').trim();
      if (identity && !existingCardsByIdentity.has(identity)) {
        existingCardsByIdentity.set(identity, card);
      }
    });
    nextRoot.querySelectorAll('.album-card[data-gallery-card-key]').forEach((nextCard) => {
      const identity = String(nextCard?.getAttribute?.('data-gallery-card-key') || '').trim();
      const existingCard = identity ? existingCardsByIdentity.get(identity) : null;
      const renderKey = String(nextCard?.getAttribute?.('data-gallery-card-render-key') || '');
      if (
        !existingCard
        || existingCard === nextCard
        || typeof nextCard.replaceWith !== 'function'
      ) {
        return;
      }
      if (String(existingCard?.getAttribute?.('data-gallery-card-render-key') || '') !== renderKey) {
        if (existingCard.attributes && nextCard.attributes) {
          const nextAttributeNames = new Set(
            Array.from(nextCard.attributes).map((attribute) => attribute.name),
          );
          Array.from(existingCard.attributes).forEach((attribute) => {
            if (!nextAttributeNames.has(attribute.name)) {
              existingCard.removeAttribute(attribute.name);
            }
          });
          Array.from(nextCard.attributes).forEach((attribute) => {
            existingCard.setAttribute(attribute.name, attribute.value);
          });
        }
        if (typeof existingCard.replaceChildren === 'function' && nextCard.childNodes) {
          existingCard.replaceChildren(...Array.from(nextCard.childNodes));
        } else {
          existingCard.innerHTML = nextCard.innerHTML;
        }
      }
      nextCard.replaceWith(existingCard);
      existingCardsByIdentity.delete(identity);
    });
  }

  renderedSectionNodesMatch(existingNode, nextNode) {
    if (!existingNode || !nextNode) return false;
    if (typeof existingNode.isEqualNode === 'function') {
      return existingNode.isEqualNode(nextNode);
    }
    return (
      String(existingNode.tagName || '').toLowerCase() === String(nextNode.tagName || '').toLowerCase()
      && String(existingNode.innerHTML || '') === String(nextNode.innerHTML || '')
    );
  }

  updateRenderedSectionNode(existingNode, nextNode, record) {
    if (
      !existingNode
      || !nextNode
      || String(existingNode.tagName || '').toLowerCase()
        !== String(nextNode.tagName || '').toLowerCase()
    ) {
      return false;
    }
    this.reuseMatchingMountedAlbumCards(existingNode, nextNode);
    this.reuseRenderedAlbumCards(nextNode);
    if (existingNode.attributes && nextNode.attributes) {
      const nextAttributeNames = new Set(
        Array.from(nextNode.attributes).map((attribute) => attribute.name),
      );
      Array.from(existingNode.attributes).forEach((attribute) => {
        if (!nextAttributeNames.has(attribute.name)) {
          existingNode.removeAttribute(attribute.name);
        }
      });
      Array.from(nextNode.attributes).forEach((attribute) => {
        existingNode.setAttribute(attribute.name, attribute.value);
      });
    } else if (existingNode.dataset) {
      existingNode.dataset.virtualSectionKey = record.key;
    } else if (typeof existingNode.setAttribute === 'function') {
      existingNode.setAttribute('data-virtual-section-key', record.key);
    }
    if (
      typeof existingNode.replaceChildren === 'function'
      && nextNode.childNodes
    ) {
      existingNode.replaceChildren(...Array.from(nextNode.childNodes));
    } else {
      existingNode.innerHTML = nextNode.innerHTML;
    }
    return true;
  }

  patchRenderedSections(records, options = {}) {
    if (
      !this.containerEl
      || typeof this.containerEl.appendChild !== 'function'
      || !('children' in this.containerEl)
      || typeof document?.createElement !== 'function'
    ) {
      this.containerEl.innerHTML = records.map((record) => record.html).join('');
      return;
    }
    this.rememberRenderedAlbumCards(this.containerEl);
    const preserveExistingChildren = Boolean(
      options.preserveExistingChildren
      || this._preserveExistingChildrenGeneration === this._renderGeneration
    );
    const existingChildren = Array.from(this.containerEl.children || []);
    const existingByKey = new Map();
    existingChildren.forEach((child) => {
      const key = child?.dataset?.virtualSectionKey || child?.getAttribute?.('data-virtual-section-key') || '';
      if (key) existingByKey.set(key, child);
    });
    const usedExistingChildren = new Set();
    const nextChildren = [];
    records.forEach((record, index) => {
      const existing = existingByKey.get(record.key);
      const nextNode = this.createRenderedSectionNode(record);
      if (
        existing
        && !usedExistingChildren.has(existing)
        && this.renderedSectionNodesMatch(existing, nextNode)
      ) {
        usedExistingChildren.add(existing);
        nextChildren.push(existing);
        return;
      }
      if (preserveExistingChildren) {
        const preservedNode = (
          existing && !usedExistingChildren.has(existing)
            ? existing
            : existingChildren[index]
        );
        if (
          !usedExistingChildren.has(preservedNode)
          && this.updateRenderedSectionNode(preservedNode, nextNode, record)
        ) {
          usedExistingChildren.add(preservedNode);
          nextChildren.push(preservedNode);
          return;
        }
      }
      if (nextNode) {
        this.reuseRenderedAlbumCards(nextNode);
        nextChildren.push(nextNode);
      }
    });
    if (!nextChildren.length && records.length) {
      this.containerEl.innerHTML = records.map((record) => record.html).join('');
      return;
    }
    Array.from(this.containerEl.children || []).forEach((child) => {
      if (!nextChildren.includes(child) && typeof child.remove === 'function') {
        child.remove();
      }
    });
    nextChildren.forEach((child) => {
      this.containerEl.appendChild(child);
    });
    this.rememberRenderedAlbumCards(this.containerEl);
  }

  scheduleMeasureRows(force = false) {
    if (!force && !this.isScrollSettled) {
      this.recordDiagnosticEvent('measure-request-skipped-scrolling', { force: false });
      return;
    }
    if (this._measureRaf) {
      this.recordDiagnosticEvent('measure-request-coalesced', {
        force: Boolean(force),
        pendingMeasureRafOwner: Number(this._measureRaf || 0),
      });
      return;
    }
    let measureRafOwner = 0;
    measureRafOwner = scheduleBrowserAnimationFrame(() => {
      this._activeMeasureRafOwner = measureRafOwner;
      this._measureRaf = null;
      this.recordDiagnosticEvent('measure-frame-started', { measureRafOwner });
      this.measureRenderedRows();
      this._activeMeasureRafOwner = 0;
    });
    this._measureRaf = measureRafOwner;
    this.recordDiagnosticEvent('measure-requested', {
      force: Boolean(force),
      measureRafOwner,
    });
  }

  stabilizeScrollAfterMeasurement(anchor) {
    const preservedAbsoluteScroll = (
      this._absoluteScrollRestore?.renderGeneration === this._renderGeneration
    )
      ? this._absoluteScrollRestore
      : null;
    this.invalidateScrollStabilization({
      preserveAbsoluteScroll: Boolean(preservedAbsoluteScroll),
    });
    const stabilizeGeneration = this._stabilizeGeneration;
    const renderGeneration = this._renderGeneration;
    const resetScroll = this._resetScrollAfterMeasure;
    this._resetScrollAfterMeasure = false;
    const stabilize = () => {
      if (
        stabilizeGeneration !== this._stabilizeGeneration
        || renderGeneration !== this._renderGeneration
      ) return;
      if (resetScroll) {
        this.scrollEl.scrollTop = 0;
      } else if (
        preservedAbsoluteScroll
        && this._absoluteScrollRestore === preservedAbsoluteScroll
      ) {
        this.scrollEl.scrollLeft = preservedAbsoluteScroll.scrollLeft;
        this.scrollEl.scrollTop = preservedAbsoluteScroll.scrollTop;
      } else {
        this.restoreScrollAnchor(anchor);
      }
      this._pendingStabilizationScroll = {
        generation: stabilizeGeneration,
        scrollLeft: Number(this.scrollEl?.scrollLeft || 0),
        scrollTop: Number(this.scrollEl?.scrollTop || 0),
      };
      this.primeVisibleCoverImages();
    };
    stabilize();
    this._stabilizeRaf = scheduleBrowserAnimationFrame(() => {
      if (stabilizeGeneration !== this._stabilizeGeneration) return;
      this._stabilizeRaf = null;
      stabilize();
    });
  }

  measureRenderedRows() {
    const absoluteScrollActive = (
      this._absoluteScrollRestore?.renderGeneration === this._renderGeneration
    );
    const preservedAnchor = absoluteScrollActive ? null : this.captureScrollAnchor();
    let changed = false;
    const rowMeasurements = [];
    const rows = this.containerEl.querySelectorAll('.album-row[data-section-key][data-block-index]');
    rows.forEach((rowEl) => {
      const sectionKey = rowEl.getAttribute('data-section-key');
      const blockIndex = Number(rowEl.getAttribute('data-block-index'));
      const section = this.sectionByKey.get(sectionKey);
      if (!section || !Array.isArray(section.blockHeights) || Number.isNaN(blockIndex)) return;
      const measureKey = Array.isArray(section.blockMeasureKeys) ? String(section.blockMeasureKeys[blockIndex] || '') : '';
      if (measureKey && Array.isArray(section.measuredBlockKeys) && section.measuredBlockKeys[blockIndex] === measureKey) {
        rowMeasurements.push({
          blockIndex,
          measureKeyPresent: Boolean(measureKey),
          measuredHeight: null,
          modeledHeight: Number(section.blockHeights[blockIndex] || 0),
          sectionKey: String(sectionKey || ''),
          skipped: true,
        });
        return;
      }
      const measured = Math.ceil(rowEl.getBoundingClientRect().height);
      rowMeasurements.push({
        blockIndex,
        measureKeyPresent: Boolean(measureKey),
        measuredHeight: measured,
        modeledHeight: Number(section.blockHeights[blockIndex] || 0),
        sectionKey: String(sectionKey || ''),
        skipped: false,
      });
      if (!Array.isArray(section.measuredBlockKeys)) {
        section.measuredBlockKeys = [];
      }
      section.measuredBlockKeys[blockIndex] = measureKey;
      if (measured > 0 && Math.abs((section.blockHeights[blockIndex] || 0) - measured) > 1) {
        section.blockHeights[blockIndex] = measured;
        changed = true;
      }
    });
    const measurement = {
      changed,
      renderGeneration: Number(this._renderGeneration || 0),
      rowMeasurements: rowMeasurements.slice(0, 32),
      scrollTop: Number(this.scrollEl?.scrollTop || 0),
      topSpacerHeight: Number.parseFloat(this.topSpacerEl?.style?.height || '0') || 0,
      bottomSpacerHeight: Number.parseFloat(this.bottomSpacerEl?.style?.height || '0') || 0,
    };
    this.diagnostics.latestMeasurement = measurement;
    this.recordDiagnosticEvent('measure-completed', measurement);
    if (!changed) {
      this._resetScrollAfterMeasure = false;
      return;
    }
    if (
      typeof startupMetrics !== 'undefined'
      && startupMetrics
      && typeof startupMetrics.markOnce === 'function'
    ) {
      startupMetrics.markOnce('startup_grid_reconcile_started', {
        rowCount: rows.length,
      });
    }
    this.lastKey = '';
    this.recalculate();
    const latestScroll = this.diagnostics.latestScroll;
    const measurementRenderRafOwner = (
      Number(latestScroll?.renderGeneration || 0) === Number(this._renderGeneration || 0)
      && Math.abs(Number(latestScroll?.scrollTop || 0) - Number(this.scrollEl?.scrollTop || 0)) <= 2
    )
      ? Number(latestScroll?.renderRafOwner || 0)
      : 0;
    const previousActiveRenderRafOwner = this._activeRenderRafOwner;
    if (measurementRenderRafOwner) {
      this._activeRenderRafOwner = measurementRenderRafOwner;
    }
    try {
      this.render(true);
    } finally {
      this._activeRenderRafOwner = previousActiveRenderRafOwner;
    }
    if (
      typeof startupMetrics !== 'undefined'
      && startupMetrics
      && typeof startupMetrics.markOnce === 'function'
    ) {
      startupMetrics.markOnce('startup_grid_reconcile_complete', {
        rowCount: rows.length,
      });
      if (typeof startupMetrics.schedulePaintMark === 'function') {
        startupMetrics.schedulePaintMark('startup_grid_reconcile_paint', () => ({
          renderedSectionCount: document.querySelectorAll('#artist-groups .artist-section').length,
        }));
      }
    }
    this.stabilizeScrollAfterMeasurement(preservedAnchor);
  }

  getVisibleBlockRange(section, start, end) {
    if (section.kind !== 'artist') return null;
    const blocks = Array.isArray(section.blocksData) ? section.blocksData : [];
    if (!blocks.length) {
      return {
        firstIndex: 0,
        lastIndex: -1,
        topSpacerHeight: 0,
        bottomSpacerHeight: 0,
      };
    }
    const contentTop = section.top + this.sectionHeaderHeight;
    const localStart = Math.max(0, start - contentTop);
    const localEnd = Math.max(0, end - contentTop);
    let firstIndex = 0;
    while (
      firstIndex < blocks.length
      && ((section.blockOffsets[firstIndex] || 0) + (section.blockHeights[firstIndex] || 0)) < localStart
    ) {
      firstIndex += 1;
    }
    let lastIndex = Math.max(firstIndex, 0);
    while (
      lastIndex < blocks.length - 1
      && (section.blockOffsets[lastIndex + 1] || 0) <= localEnd
    ) {
      lastIndex += 1;
    }
    firstIndex = Math.max(0, Math.min(firstIndex, blocks.length - 1));
    lastIndex = Math.max(firstIndex, Math.min(lastIndex, blocks.length - 1));
    const topSpacerHeight = section.blockOffsets[firstIndex] || 0;
    const lastBlockBottom = (section.blockOffsets[lastIndex] || 0) + (section.blockHeights[lastIndex] || 0);
    const bottomSpacerHeight = Math.max(0, (section.blocksHeight || 0) - lastBlockBottom);
    return { firstIndex, lastIndex, topSpacerHeight, bottomSpacerHeight };
  }

  renderSection(section, start, end, options = {}) {
    const layoutConfig = this.getLayoutConfig();
    const renderAlbumHtml = typeof layoutConfig.renderAlbumHtml === 'function'
      ? layoutConfig.renderAlbumHtml
      : albumCardHtml;
    if (section.kind === 'label') {
      return `<div class="section-split-label">${escapeHtml(section.title)}</div>`;
    }
    const group = section.group;
    const blocks = Array.isArray(section.blocksData) ? section.blocksData : [];
    const visibleRange = this.getVisibleBlockRange(section, start, end);
    const startIndex = visibleRange ? visibleRange.firstIndex : 0;
    const endIndex = visibleRange ? visibleRange.lastIndex : (blocks.length - 1);
    const topSpacer = visibleRange?.topSpacerHeight
      ? `<div class="artist-rows-spacer" style="height:${visibleRange.topSpacerHeight}px;"></div>`
      : '';
    const bottomSpacer = visibleRange?.bottomSpacerHeight
      ? `<div class="artist-rows-spacer" style="height:${visibleRange.bottomSpacerHeight}px;"></div>`
      : '';
    const rowBlocks = blocks.slice(startIndex, endIndex + 1).map((block, visibleIndex) => {
      const blockIndex = startIndex + visibleIndex;
      if (block.kind === 'subheading') {
        return `<div class="artist-subsection-label">${escapeHtml(block.title || 'Non-Album Tracks')}</div>`;
      }
      const blockTop = Number(section.top || 0) + Number(section.blockOffsets?.[blockIndex] || 0);
      const blockBottom = blockTop + Number(section.blockHeights?.[blockIndex] || 0);
      const coverPriority = blockBottom >= Number(options.viewportTop || 0)
        && blockTop <= Number(options.viewportBottom || 0)
        ? 'visible'
        : 'near';
      return `
        <div class="album-row" data-section-key="${escapeHtml(section.sectionKey)}" data-block-index="${blockIndex}" style="grid-template-columns:${buildAlbumRowGridTemplate(this.columns, this.cardTrackWidth)};justify-content:start;">
          ${Array.isArray(block.albums) ? block.albums.map((album) => (
            renderAlbumHtml(album, { coverPriority })
          )).join('') : ''}
        </div>
      `;
    }).join('');

    return `
      <section class="artist-section ${section.sectionType}">
        <div class="artist-header">
          <h2 class="artist-name">${escapeHtml(group.artist_display || group.artist)}</h2>
          <div class="artist-meta">${group.albums.length} ${group.albums.length === 1 ? 'album' : 'albums'}</div>
        </div>
        <div class="artist-rows">${topSpacer}${rowBlocks}${bottomSpacer}</div>
      </section>
    `;
  }
}

const virtualGrid = new VirtualArtistGrid();

function buildArtistSectionRowsHtml(
  albums,
  columns,
  layoutConfig = CARD_GALLERY_LAYOUT_CONFIG,
  cardTrackWidth = resolveGalleryCardWidth(layoutConfig),
) {
  const safeAlbums = Array.isArray(albums) ? albums : [];
  if (!safeAlbums.length) {
    return '';
  }
  const renderAlbumHtml = typeof layoutConfig?.renderAlbumHtml === 'function'
    ? layoutConfig.renderAlbumHtml
    : albumCardHtml;
  const rows = [];
  const safeColumns = Math.max(1, Number(columns) || 1);
  for (let start = 0; start < safeAlbums.length; start += safeColumns) {
    rows.push(safeAlbums.slice(start, start + safeColumns));
  }
  return rows.map((rowAlbums) => `
    <div class="album-row" style="grid-template-columns:${buildAlbumRowGridTemplate(safeColumns, cardTrackWidth)};justify-content:start;">
      ${rowAlbums.map((album) => renderAlbumHtml(album)).join('')}
    </div>
  `).join('');
}

function buildArtistSectionHtml(
  group,
  sectionType,
  columns,
  layoutConfig = CARD_GALLERY_LAYOUT_CONFIG,
  cardTrackWidth = resolveGalleryCardWidth(layoutConfig),
) {
  const safeGroup = group && typeof group === 'object' ? group : {};
  const albums = Array.isArray(safeGroup.albums) ? safeGroup.albums : [];
  return `
    <section class="artist-section ${sectionType}">
      <div class="artist-header">
        <h2 class="artist-name">${escapeHtml(safeGroup.artist_display || safeGroup.artist || 'Artist')}</h2>
        <div class="artist-meta">${albums.length} ${albums.length === 1 ? 'album' : 'albums'}</div>
      </div>
      <div class="artist-rows">${buildArtistSectionRowsHtml(albums, columns, layoutConfig, cardTrackWidth)}</div>
    </section>
  `;
}

function renderArtistGroupsMarkupFallback(
  primaryGroups,
  familyGroups,
  fallbackGroups,
  columns,
  layoutConfig = CARD_GALLERY_LAYOUT_CONFIG,
  cardTrackWidth = resolveGalleryCardWidth(layoutConfig),
) {
  const renderedPrimaryGroups = buildDisplayGroups(primaryGroups);
  const renderedFamilyGroups = buildDisplayGroups(familyGroups);
  const renderedFallbackGroups = buildDisplayGroups(fallbackGroups);
  const renderedGroups = renderedPrimaryGroups.length || renderedFamilyGroups.length
    ? [...renderedPrimaryGroups, ...renderedFamilyGroups]
    : [...renderedFallbackGroups];
  rebuildAlbumIndex(renderedGroups);
  if (virtualGrid.topSpacerEl?.style) {
    virtualGrid.topSpacerEl.style.height = '0px';
  }
  if (virtualGrid.bottomSpacerEl?.style) {
    virtualGrid.bottomSpacerEl.style.height = '0px';
  }
  return [
    ...(renderedPrimaryGroups.length ? ['<div class="section-split-label">Primary Artist</div>'] : []),
    ...renderedPrimaryGroups.map((group) => buildArtistSectionHtml(group, 'primary', columns, layoutConfig, cardTrackWidth)),
    ...(renderedFamilyGroups.length ? ['<div class="section-split-label">Family</div>'] : []),
    ...renderedFamilyGroups.map((group) => buildArtistSectionHtml(group, 'family', columns, layoutConfig, cardTrackWidth)),
    ...(!renderedPrimaryGroups.length && !renderedFamilyGroups.length
      ? renderedFallbackGroups.map((group) => buildArtistSectionHtml(group, 'all', columns, layoutConfig, cardTrackWidth))
      : []),
  ].join('');
}

function resolveGalleryRendererMode(mode) {
  const normalized = String(mode || '').trim().toLowerCase();
  return normalized === 'covers' || normalized === 'list' ? normalized : 'cards';
}

function getGalleryModeConfig(mode) {
  const normalizedMode = resolveGalleryRendererMode(mode);
  switch (normalizedMode) {
    case 'covers':
      return { mode: 'covers', renderer: renderArtistGroupsCardMode, layoutConfig: CARD_GALLERY_LAYOUT_CONFIG };
    case 'list':
      return { mode: 'list', renderer: renderArtistGroupsCardMode, layoutConfig: CARD_GALLERY_LAYOUT_CONFIG };
    case 'cards':
    default:
      return { mode: 'cards', renderer: renderArtistGroupsCardMode, layoutConfig: CARD_GALLERY_LAYOUT_CONFIG };
  }
}

function renderArtistGroupsCardMode(displayGroupState = {}, fallbackGroups = [], options = {}, layoutConfig = CARD_GALLERY_LAYOUT_CONFIG) {
  const primaryGroups = Array.isArray(displayGroupState.primaryGroups) ? displayGroupState.primaryGroups : [];
  const familyGroups = Array.isArray(displayGroupState.familyGroups) ? displayGroupState.familyGroups : [];
  const safeFallbackGroups = Array.isArray(fallbackGroups) ? fallbackGroups : [];
  const hasRenderableGroups = Boolean(
    primaryGroups.length
    || familyGroups.length
    || safeFallbackGroups.length
  );

  try {
    virtualGrid.setGroups(
      primaryGroups,
      familyGroups,
      safeFallbackGroups,
      options,
      layoutConfig,
    );
  } catch (_error) {
    if (!hasRenderableGroups || !virtualGrid.containerEl) {
      throw _error;
    }
  }

  if (!hasRenderableGroups || !virtualGrid.containerEl) {
    return;
  }
  const renderedChildCount = Array.isArray(virtualGrid.containerEl.children)
    ? virtualGrid.containerEl.children.length
    : Number(virtualGrid.containerEl.childElementCount || 0);
  const existingMarkup = String(virtualGrid.containerEl.innerHTML || '').trim();
  if (renderedChildCount > 0 || existingMarkup) {
    return;
  }
  virtualGrid.containerEl.innerHTML = renderArtistGroupsMarkupFallback(
    primaryGroups,
    familyGroups,
    safeFallbackGroups,
    virtualGrid.columns,
    layoutConfig,
    virtualGrid.cardTrackWidth,
  );
}

function getGalleryModeRenderer(mode) {
  return getGalleryModeConfig(mode).renderer;
}

function renderArtistGroups(options = {}) {
  const selectedArtist = String(state.view.selected_artist || '').trim();
  const selectedArtistFamilyDisplayMode = String(
    state.view.selected_artist_family_display_mode
      ?? state.view.artist_page?.family_display_mode
      ?? 'grouped',
  ).trim().toLowerCase();
  const displayGroupState = typeof buildSelectedArtistDisplayGroups === 'function'
    ? buildSelectedArtistDisplayGroups(
      state.view.primary_artist_groups || [],
      state.view.family_artist_groups || [],
      selectedArtist,
    )
    : {
      primaryGroups: state.view.primary_artist_groups || [],
      familyGroups: state.view.family_artist_groups || [],
    };
  const fallbackGroups = state.view.artist_groups || [];
  const renderState = selectedArtist && selectedArtistFamilyDisplayMode === 'chronological'
    ? {
      primaryGroups: [],
      familyGroups: [],
    }
    : displayGroupState;
  const modeConfig = getGalleryModeConfig(state.view.gallery_display_mode);
  modeConfig.renderer(renderState, fallbackGroups, options, modeConfig.layoutConfig);
}

// END js/runtime/virtual-artist-grid.js

// BEGIN js/runtime/player-loop-playback.js

function clampLoopTimes() {
  const duration = getPlayerDuration() || 0;
  const max = duration > 0 ? duration : Math.max(state.player.loopEnd, 30);
  state.player.loopStart = Math.max(0, Math.min(Number(state.player.loopStart) || 0, Math.max(0, max - 0.1)));
  state.player.loopEnd = Math.max(state.player.loopStart + 0.1, Math.min(Number(state.player.loopEnd) || max, max));
}

function isoNow() {
  return new Date().toISOString();
}

function unixNowSeconds() {
  return Math.floor(Date.now() / 1000);
}

function getPlayerDuration() {
  const editDuration = Number(state.player.loopEditDurationSeconds);
  if (state.player.loopActive && Number.isFinite(editDuration) && editDuration > 0) return editDuration;
  const playbackDuration = Number(getPlayerPlaybackSnapshot().duration);
  if (Number.isFinite(playbackDuration) && playbackDuration > 0) {
    if (state.player.current) state.player.current.durationSeconds = playbackDuration;
    return playbackDuration;
  }
  const currentDuration = Number(state.player.current?.durationSeconds);
  return Number.isFinite(currentDuration) && currentDuration > 0 ? currentDuration : 0;
}

function getTimelineSecondsFromClientX(clientX) {
  const els = getPlayerElements();
  const wrap = els.timeline?.getBoundingClientRect();
  const duration = getPlayerDuration() || Math.max(state.player.loopEnd, 0.1);
  if (!wrap || wrap.width <= 0) return 0;
  const ratio = Math.max(0, Math.min(1, (clientX - wrap.left) / wrap.width));
  return ratio * duration;
}

function updateLoopInputsFromState() {
  const els = getPlayerElements();
  const duration = getPlayerDuration() || Math.max(state.player.loopEnd, 30);
  const max = Math.max(0.1, duration);
  const reconciledRange = els.loopRange?._loopRangeController?.render({
    startSeconds: state.player.loopStart,
    endSeconds: state.player.loopEnd,
  });
  if (reconciledRange) {
    state.player.loopStart = reconciledRange.startSeconds;
    state.player.loopEnd = reconciledRange.endSeconds;
  }
  if (els.timeline) els.timeline.max = String(max);
  if (els.loopStartInput && document.activeElement !== els.loopStartInput) {
    els.loopStartInput.value = formatLoopTime(state.player.loopStart, true);
  }
  if (els.loopEndInput && document.activeElement !== els.loopEndInput) {
    els.loopEndInput.value = formatLoopTime(state.player.loopEnd, true);
  }
}

function updatePlayerUi() {
  const els = getPlayerElements();
  const playback = getPlayerPlaybackSnapshot();
  const lockedByAnotherTab = typeof isPlaybackLockedByAnotherTab === 'function' && isPlaybackLockedByAnotherTab();
  const mirroredTrack = lockedByAnotherTab && typeof getMirroredPlaybackTrack === 'function'
    ? getMirroredPlaybackTrack()
    : null;
  const displayTrack = mirroredTrack || state.player.current;
  state.player.lastKnownWasPlaying = Boolean(!lockedByAnotherTab && !playback.paused && !playback.ended);
  const hasTrack = Boolean(displayTrack && (lockedByAnotherTab || playback.src || state.player.current?.src));
  const duration = getPlayerDuration();
  const dragPreview = Number(state.player.timelineDragPreviewSeconds);
  const current = state.player.timelineDragging && Number.isFinite(dragPreview)
    ? dragPreview
    : Number(playback.currentTime) || 0;
  if (els.timeline) {
    els.timeline.max = String(Math.max(duration, 0.1));
    els.timeline.value = String(Math.min(current, duration || current));
    els.timeline.disabled = !hasTrack || lockedByAnotherTab;
  }
  if (els.time) {
    els.time.textContent = state.player.loopActive
      ? `${formatLoopTime(state.player.loopStart, true)} - ${formatLoopTime(state.player.loopEnd, true)}`
      : lockedByAnotherTab
      ? 'Playing in another tab'
      : `${formatLoopTime(current)} / ${formatLoopTime(duration)}`;
  }
  els.loopActions?._loopActionController?.update({
    enabled: Boolean(getPlayerPlaybackSnapshot().src || state.player.current?.src),
    active: state.player.loopActive,
    busy: state.player.saveBusy || lockedByAnotherTab,
  });
  if (els.play) {
    els.play.textContent = lockedByAnotherTab ? 'Locked' : (playback.paused ? '\u25B6' : '\u23F8');
    els.play.setAttribute('aria-label', lockedByAnotherTab ? 'Playback locked in another tab' : (playback.paused ? 'Play' : 'Pause'));
    els.play.disabled = lockedByAnotherTab || !hasTrack;
  }
  els.timeline?.parentElement?.classList.toggle('is-looping', state.player.loopActive);
  if (els.timeline?.parentElement) {
    els.timeline.parentElement.classList.toggle('is-idle', !hasTrack || lockedByAnotherTab);
    els.timeline.parentElement.setAttribute('data-idle-label', lockedByAnotherTab ? 'Playing in another tab' : 'Nothing is playing');
  }
  if (els.loopRegion) els.loopRegion.hidden = !state.player.loopActive;
  if (els.loopStartHandle) els.loopStartHandle.hidden = !state.player.loopActive;
  if (els.loopEndHandle) els.loopEndHandle.hidden = !state.player.loopActive;
  const loopRangeSurface = els.loopRange?.querySelector('[data-loop-range-surface]');
  if (loopRangeSurface) loopRangeSurface.hidden = !state.player.loopActive;
  if (els.title) {
    const titleParts = [displayTrack?.artist, displayTrack?.title].filter(Boolean);
    els.title.textContent = titleParts.length
      ? `${titleParts.join(' - ')}${displayTrack?.album ? ' /' : ''}`
      : '';
  }
  if (els.albumLink) {
    els.albumLink.textContent = displayTrack?.album || '';
    els.albumLink.hidden = !displayTrack?.album;
  }
  updateLoopInputsFromState();
  updateWaveformAppearance();
  const compactPeaks = state.player.waveform?.compactPeaks?.data;
  if (state.player.loopActive && els.waveformCanvas && compactPeaks) {
    const progress = duration > 0 ? current / duration : 0;
    drawWaveformOnCanvas(els.waveformCanvas, compactPeaks, progress);
  }
  refreshTrackModalPlaybackState();
  refreshNonAlbumModalPlaybackState();
  persistPlayerState();
}

function setCurrentPlayerTrack(track, options = {}) {
  const els = getPlayerElements();
  const previousTrack = state.player.current;
  const previousTrackId = getTrackIdentity(previousTrack);
  const nextTrackId = getTrackIdentity(track);
  const previousSession = state.player.listenSession;
  const previousPlaybackSnapshot = options.previousPlaybackSnapshot || null;
  if (previousTrack && previousTrackId && previousTrackId !== nextTrackId && previousSession) {
    void finalizeListenSession('track-change', {
      session: previousSession,
      currentTime: Number(previousPlaybackSnapshot?.currentTime) || undefined,
      duration: Number(previousPlaybackSnapshot?.duration) || undefined,
    });
  }
  state.player.current = track;
  if (typeof probeCachedWaveformPeaks === 'function') {
    const cachedWaveformProbe = probeCachedWaveformPeaks(
      String(track?.path || ''),
      Number(state.player.streaming?.generation) || 0,
    );
    if (cachedWaveformProbe && typeof cachedWaveformProbe.catch === 'function') {
      void cachedWaveformProbe.catch(() => {});
    }
  }
  state.player.waveform.renderToken += 1;
  clearWaveformCanvas();
  loopEditSessionExpiryController.stop('global-player');
  state.player.loopActive = false;
  state.player.loopStart = 0;
  state.player.loopEnd = 30;
  state.player.loopEditDurationSeconds = 0;
  const titleParts = [track?.artist, track?.title].filter(Boolean);
  if (els.title) {
    els.title.textContent = titleParts.length
      ? `${titleParts.join(' - ')}${track?.album ? ' /' : ''}`
      : '';
  }
  if (els.albumLink) {
    els.albumLink.textContent = track?.album || '';
    els.albumLink.hidden = !track?.album;
  }
  if (els.coverButton) {
    const coverPath = track?.coverPath || '';
    const loadId = (state.player.coverLoadId || 0) + 1;
    state.player.coverLoadId = loadId;
    els.coverButton.hidden = false;
    els.coverButton.classList.toggle('is-idle-placeholder', !track);
    els.coverButton.style.backgroundImage = '';
    els.coverButton.textContent = '';
    if (!track) {
      els.coverButton.textContent = '';
    } else if (coverPath) {
      const coverSrc = `/cover?path=${encodeURIComponent(coverPath)}`;
      const probe = new Image();
      probe.onload = () => {
        if (state.player.coverLoadId !== loadId) return;
        els.coverButton.classList.remove('is-idle-placeholder');
        els.coverButton.style.backgroundImage = `url("${coverSrc}")`;
        els.coverButton.hidden = false;
      };
      probe.onerror = () => {
        if (state.player.coverLoadId !== loadId) return;
        els.coverButton.style.backgroundImage = '';
        els.coverButton.hidden = false;
        els.coverButton.classList.remove('is-idle-placeholder');
      };
      probe.src = coverSrc;
    } else {
      els.coverButton.classList.remove('is-idle-placeholder');
    }
  }
  updatePlayerUi();
  if (options.persist !== false) {
    persistPlayerState(true);
  }
}

function beginStreamingPlayerListenSession(track, startSeconds = 0) {
  if (typeof resumeListenSessionPlayback !== 'function') return;
  const sessionPromise = resumeListenSessionPlayback(track, startSeconds);
  if (!sessionPromise || typeof sessionPromise.then !== 'function') return;
  void sessionPromise.then((session) => (
    typeof maybeSendNowPlaying === 'function'
      ? maybeSendNowPlaying(track, session)
      : null
  ));
}

let playerTrackSelectionToken = 0;

async function playTrackFromPayload(track, options = {}) {
  const shouldAutoplay = options.autoplay !== false;
  if (shouldAutoplay && typeof canStartPlaybackInThisTab === 'function' && !canStartPlaybackInThisTab(track)) {
    return false;
  }
  if (!track?.path) return false;
  const resetTime = options.resetTime !== false;
  const previousPlaybackSnapshot = getPlayerPlaybackSnapshot();
  if (typeof startStreamingTrack !== 'function') {
    throw new Error('Streaming playback engine is unavailable');
  }
  const selectionToken = ++playerTrackSelectionToken;
  let startedRole;
  try {
    startedRole = await startStreamingTrack(track, {
      startSeconds: resetTime ? 0 : Number(previousPlaybackSnapshot.currentTime) || 0,
      autoplay: shouldAutoplay,
    });
  } catch (error) {
    if (selectionToken !== playerTrackSelectionToken) return false;
    throw error;
  }
  if (selectionToken !== playerTrackSelectionToken) return false;
  if (startedRole === null) {
    throw new Error('Streaming playback did not start');
  }
  const startedTrackPath = String(startedRole?.track?.path || '');
  if (startedTrackPath && startedTrackPath !== String(track.path)) {
    throw new Error('Streaming playback started an unexpected track identity');
  }
  setCurrentPlayerTrack(track, { previousPlaybackSnapshot });
  if (startedRole?.firstFrameNotified) {
    const reconciliation = handleStreamingPlaybackFirstFrame({
      generation: startedRole.generation,
      streamId: startedRole.streamId,
      trackPath: String(startedRole.track?.path || track.path),
    });
    if (typeof observeStreamingFacadeCallback === 'function') {
      observeStreamingFacadeCallback(reconciliation, 'first-frame-reconciliation-error');
    } else {
      void reconciliation.catch((error) => {
        console.warn('[AlbumHaven][Playback] First-frame reconciliation failed.', error);
      });
    }
  }
  if (shouldAutoplay) {
    beginStreamingPlayerListenSession(track, resetTime ? 0 : previousPlaybackSnapshot.currentTime);
  }
  updatePlayerUi();
  return true;
}

let handledStreamingFirstFrameIdentity = '';
let pendingStreamingFirstFrameIdentity = '';
let pendingStreamingFirstFrameSchedule = null;

async function handleStreamingPlaybackFirstFrame(event = {}) {
  const selectedTrackPath = String(state.player.current?.path || '');
  const renderedTrackPath = String(event.trackPath || '');
  if (renderedTrackPath && renderedTrackPath !== selectedTrackPath) return;
  const identity = [
    Number(event.generation) || 0,
    Number(event.streamId) || 0,
    renderedTrackPath || selectedTrackPath,
  ].join(':');
  if (identity === handledStreamingFirstFrameIdentity) return;
  if (identity === pendingStreamingFirstFrameIdentity) {
    return pendingStreamingFirstFrameSchedule;
  }
  const nextTrack = typeof peekNextQueuedTrack === 'function'
    ? peekNextQueuedTrack()
    : null;
  if (!nextTrack || typeof scheduleStreamingContinuity !== 'function') {
    handledStreamingFirstFrameIdentity = identity;
    return;
  }
  pendingStreamingFirstFrameIdentity = identity;
  const scheduling = Promise.resolve().then(() => scheduleStreamingContinuity(nextTrack));
  pendingStreamingFirstFrameSchedule = scheduling;
  try {
    await scheduling;
    handledStreamingFirstFrameIdentity = identity;
  } finally {
    if (pendingStreamingFirstFrameSchedule === scheduling) {
      pendingStreamingFirstFrameIdentity = '';
      pendingStreamingFirstFrameSchedule = null;
    }
  }
}

async function handleStreamingPlaybackPosition(event = {}) {
  const trackPath = String(state.player.current?.path || '');
  if (!trackPath || String(event.trackPath || '') !== trackPath) return;
  const playback = getPlayerPlaybackSnapshot();
  if (state.player.listenSession) {
    state.player.listenSession.duration_seconds = Math.round(
      (Number(playback.duration) || 0) * 1000,
    ) / 1000;
    if (typeof maybeScrobbleListenSession === 'function') {
      await maybeScrobbleListenSession(state.player.listenSession);
    }
  }
  updatePlayerUi();
}

let handledStreamingEndedIdentity = '';

async function handleStreamingPlaybackEnded(event = {}) {
  const track = state.player.current;
  const trackPath = String(track?.path || '');
  if (!trackPath || String(event.trackPath || '') !== trackPath) return;
  const identity = [event.generation, event.streamId, trackPath].join(':');
  if (identity === handledStreamingEndedIdentity) return;
  handledStreamingEndedIdentity = identity;
  const playback = getPlayerPlaybackSnapshot();
  const session = state.player.listenSession;
  if (typeof releasePlaybackOwnership === 'function') {
    releasePlaybackOwnership('stopped', track);
  }
  if (typeof finalizeListenSession === 'function') {
    await finalizeListenSession('ended', {
      session,
      currentTime: Number(event.currentTime) || Number(playback.currentTime) || 0,
      duration: Number(playback.duration) || 0,
      finishedFully: true,
    });
  }
  updatePlayerUi();
}

async function handleStreamingPlaybackBoundary(event = {}) {
  const boundaryIdentity = [
    Number(event.generation) || 0,
    Number(event.outgoingStreamId) || 0,
    Number(event.incomingStreamId) || 0,
  ].join(':');
  if (state.player.lastStreamingBoundaryIdentity === boundaryIdentity) return;
  const currentPath = String(state.player.current?.path || '');
  const outgoingPath = String(event.outgoingTrackPath || '');
  if (outgoingPath && currentPath !== outgoingPath) {
    throw new Error('Streaming boundary outgoing track identity mismatch');
  }
  const queuedPreview = typeof peekNextQueuedTrack === 'function'
    ? peekNextQueuedTrack()
    : null;
  const incomingPath = String(event.incomingTrackPath || '');
  if (event.continuityKind && event.continuityKind !== 'queued-next') {
    if (outgoingPath && currentPath !== outgoingPath) {
      throw new Error('Streaming loop boundary outgoing track identity mismatch');
    }
    if (incomingPath && currentPath !== incomingPath) {
      throw new Error('Streaming loop boundary incoming track identity mismatch');
    }
    state.player.lastStreamingBoundaryIdentity = boundaryIdentity;
    if (event.continuityKind === 'whole-track-repeat' && state.player.loopActive) {
      loopEditSessionExpiryController.noteUntouchedWholeRangeWrap('global-player');
    }
    updatePlayerUi();
    return;
  }
  if (incomingPath && queuedPreview?.path
      && String(queuedPreview.path) !== incomingPath) {
    throw new Error('Streaming boundary incoming track identity mismatch');
  }
  const promotedTrack = getNextQueuedTrack();
  if (!promotedTrack) {
    throw new Error('Streaming boundary promotion has no queued track');
  }
  if (incomingPath && String(promotedTrack.path || '') !== incomingPath) {
    throw new Error('Streaming boundary promoted track identity mismatch');
  }
  state.player.lastStreamingBoundaryIdentity = boundaryIdentity;
  const previousPlaybackSnapshot = event.outgoingPlaybackSnapshot
    || getPlayerPlaybackSnapshot();
  const outgoingSession = state.player.listenSession;
  if (outgoingSession) {
    if (state.player.listenSession === outgoingSession) {
      state.player.listenSession = null;
    }
    const finalization = finalizeListenSession('ended', {
      session: outgoingSession,
      currentTime: Number(previousPlaybackSnapshot.currentTime) || 0,
      duration: Number(previousPlaybackSnapshot.duration) || 0,
      finishedFully: true,
    });
    if (typeof observeStreamingFacadeCallback === 'function') {
      observeStreamingFacadeCallback(finalization, 'listen-session-boundary-finalization-error');
    } else if (finalization && typeof finalization.catch === 'function') {
      void finalization.catch((error) => {
        console.warn('[AlbumHaven][Playback] Boundary listen-session finalization failed.', error);
      });
    }
  }
  setCurrentPlayerTrack(promotedTrack, { previousPlaybackSnapshot });
  if (typeof resumeListenSessionPlayback === 'function') {
    const incomingSessionStart = Promise.resolve(resumeListenSessionPlayback(promotedTrack, 0)).then((incomingSession) => (
      typeof maybeSendNowPlaying === 'function'
        ? maybeSendNowPlaying(promotedTrack, incomingSession)
        : null
    ));
    if (typeof observeStreamingFacadeCallback === 'function') {
      observeStreamingFacadeCallback(incomingSessionStart, 'listen-session-boundary-start-error');
    } else {
      void incomingSessionStart.catch((error) => {
        console.warn('[AlbumHaven][Playback] Boundary listen-session start failed.', error);
      });
    }
  }
  updatePlayerUi();
  const subsequentTrack = typeof peekNextQueuedTrack === 'function'
    ? peekNextQueuedTrack()
    : null;
  if (subsequentTrack && typeof scheduleStreamingContinuity === 'function') {
    await scheduleStreamingContinuity(subsequentTrack);
  }
  if (typeof promoteWaveformPeaks === 'function') {
    try {
      void Promise.resolve(promoteWaveformPeaks(
        outgoingPath || currentPath,
        String(promotedTrack.path || ''),
        Number(event.generation) || 0,
      )).catch((error) => {
        console.warn('[AlbumHaven][Waveform] Optional peak promotion failed.', error);
      });
    } catch (error) {
      console.warn('[AlbumHaven][Waveform] Optional peak promotion failed.', error);
    }
  }
}

let streamingLoopScheduleToken = 0;
let pendingPlayerPlaybackHandoff = null;

function renewPlayerLoopExpiryAfterBoundaryEdit(range) {
  const nextStart = Number(range?.startSeconds);
  const nextEnd = Number(range?.endSeconds);
  const changed = Number.isFinite(nextStart) && Number.isFinite(nextEnd)
    && (nextStart !== Number(state.player.loopStart) || nextEnd !== Number(state.player.loopEnd));
  if (changed) loopEditSessionExpiryController.renewAfterBoundaryEdit('global-player');
  return changed;
}

function expirePlayerLoopCreation() {
  if (!state.player.loopActive) return false;
  setLoopActive(false);
  if (typeof pauseStreamingPlayback === 'function') {
    const pause = pauseStreamingPlayback();
    if (typeof observeStreamingFacadeCallback === 'function') {
      observeStreamingFacadeCallback(pause, 'loop-edit-expiry-pause-error');
    } else if (pause && typeof pause.catch === 'function') {
      void pause.catch(() => {});
    }
  }
  updatePlayerUi();
  return true;
}

function startPlayerLoopExpirySession() {
  loopEditSessionExpiryController.start({
    ownerId: 'global-player',
    onExpire: expirePlayerLoopCreation,
  });
}

function getGlobalPlayerLoopControlOptions() {
  const action = {
      enabled: Boolean(getPlayerPlaybackSnapshot().src || state.player.current?.src),
      active: state.player.loopActive,
      busy: state.player.saveBusy,
      disabledLabel: 'Start playing the track to edit the loop',
      onEnter: () => setLoopActive(true),
      onCreate: saveCurrentLoop,
      onCancel: () => setLoopActive(false),
  };
  const range = {
      getDuration: () => getPlayerDuration() || Math.max(state.player.loopEnd, 0.1),
      getRange: () => ({ startSeconds: state.player.loopStart, endSeconds: state.player.loopEnd }),
      onRangeInteractionStart: () => {
        startPlayerLoopExpirySession();
        loopEditSessionExpiryController.renewAfterBoundaryEdit('global-player');
      },
      onRangePreview: (range) => {
        renewPlayerLoopExpiryAfterBoundaryEdit(range);
        state.player.loopStart = range.startSeconds;
        state.player.loopEnd = range.endSeconds;
        updateLoopInputsFromState();
        const time = getPlayerElements().time;
        if (time) time.textContent = `${formatLoopTime(state.player.loopStart, true)} - ${formatLoopTime(state.player.loopEnd, true)}`;
      },
      onRangeCommit: (range) => {
        loopEditSessionExpiryController.renewAfterBoundaryEdit('global-player');
        state.player.loopStart = range.startSeconds;
        state.player.loopEnd = range.endSeconds;
        scheduleActiveStreamingLoop();
        updatePlayerUi();
      },
      onSeek: (seconds) => setPlayerPlaybackHead(seconds, { clampToLoop: false }),
      onCancel: () => setLoopActive(false),
  };
  return {
    action,
    range,
    buildActionMarkup: () => buildLoopEditActionControl({ ownerId: 'global-player' }),
    mountAction: (root) => mountLoopEditActionControl({
      root,
      enabled: action.enabled,
      active: action.active,
      busy: action.busy,
      disabledLabel: action.disabledLabel,
      onEnter: action.onEnter,
      onCreate: action.onCreate,
      onCancel: action.onCancel,
    }),
    mountRange: (root) => createLoopRangeController({ root, ...range }),
  };
}

function dispatchActiveStreamingLoop() {
  const track = state.player.current;
  if (!track || typeof scheduleStreamingContinuity !== 'function') return null;
  const startSeconds = Math.max(0, Number(state.player.loopStart) || 0);
  const endSeconds = Math.max(startSeconds, Number(state.player.loopEnd) || 0);
  const loopSeconds = Math.max(0, endSeconds - startSeconds);
  const durationSeconds = Math.max(0, Number(track.durationSeconds) || 0);
  const wholeTrack = startSeconds === 0 && durationSeconds > 0 && endSeconds >= durationSeconds;
  const kind = wholeTrack ? 'whole-track-repeat' : (loopSeconds <= 5 ? 'short-loop' : 'long-loop');
  return scheduleStreamingContinuity(track, { kind, startSeconds, endSeconds });
}

function scheduleActiveStreamingLoop() {
  const token = ++streamingLoopScheduleToken;
  Promise.resolve().then(() => {
    if (token !== streamingLoopScheduleToken || !state.player.loopActive) return;
    return dispatchActiveStreamingLoop();
  }).catch((error) => {
    if (typeof observeStreamingFacadeCallback === 'function') {
      observeStreamingFacadeCallback(Promise.reject(error), 'loop-control-error');
    }
  });
}

function setLoopActive(active) {
  const playback = getPlayerPlaybackSnapshot();
  if (active && (!state.player.current || !(playback.src || state.player.current?.src))) {
    showToast('Play a track before selecting a loop.', 'error', 2600);
    return;
  }
  const willActivate = Boolean(active);
  if (willActivate) {
    const duration = getPlayerDuration();
    if (!(duration > 0)) {
      showToast('Wait for the full track to finish loading before editing a loop.', 'error', 2600);
      return;
    }
    const currentTime = Math.max(0, Number(playback.currentTime) || 0);
    state.player.loopReturnTime = currentTime;
    state.player.loopWasPlaying = !playback.paused && !playback.ended;
    state.player.loopStart = 0;
    state.player.loopEnd = duration;
    state.player.loopEditDurationSeconds = duration;
    state.player.loopActive = true;
    clampLoopTimes();
    startPlayerLoopExpirySession();
    scheduleActiveStreamingLoop();
  } else {
    loopEditSessionExpiryController.stop('global-player');
    const startSeconds = Number(state.player.loopStart) || 0;
    const endSeconds = Number(state.player.loopEnd) || 0;
    if (state.player.loopActive) {
      const finalLoop = dispatchActiveStreamingLoop();
      if (typeof observeStreamingFacadeCallback === 'function') {
        observeStreamingFacadeCallback(finalLoop, 'loop-control-error');
      }
    }
    state.player.loopActive = false;
    state.player.loopEditDurationSeconds = 0;
    streamingLoopScheduleToken += 1;
    if (typeof setStreamingLoop === 'function') {
      setStreamingLoop(false, startSeconds, endSeconds);
    }
    const nextTrack = typeof peekNextQueuedTrack === 'function'
      ? peekNextQueuedTrack()
      : null;
    if (nextTrack && typeof scheduleStreamingContinuity === 'function') {
      const result = scheduleStreamingContinuity(nextTrack, {
        kind: 'queued-next', startSeconds: 0,
      });
      if (typeof observeStreamingFacadeCallback === 'function') {
        observeStreamingFacadeCallback(result, 'loop-disable-continuity-error');
      }
    }
  }
  updatePlayerUi();
}

function setLoopBoundary(which, value) {
  const next = Math.max(0, Number(value) || 0);
  if (which === 'start') {
    state.player.loopStart = next;
  } else {
    state.player.loopEnd = next;
  }
  clampLoopTimes();
  if (state.player.loopActive) scheduleActiveStreamingLoop();
  updatePlayerUi();
}

function setLoopPlaybackHead(value) {
  if (!state.player.loopActive) return;
  const next = Math.max(state.player.loopStart, Math.min(state.player.loopEnd, Number(value) || 0));
  if (typeof seekStreamingPlayback !== 'function') return;
  const seek = seekStreamingPlayback(next);
  if (typeof observeStreamingFacadeCallback === 'function') {
    observeStreamingFacadeCallback(seek, 'seek-control-error');
  } else if (seek && typeof seek.catch === 'function') {
    void seek.catch(() => {});
  }
  updatePlayerUi();
}

function setPlayerPlaybackHead(value, options = {}) {
  const next = Math.max(0, Number(value) || 0);
  const playback = getPlayerPlaybackSnapshot();
  const shouldResumeSegment = !playback.paused;
  closeListenSegment();
  if (state.player.loopActive && options.clampToLoop !== false) {
    setLoopPlaybackHead(next);
    if (shouldResumeSegment) void resumeListenSessionPlayback(state.player.current, next);
    return;
  }
  if (typeof seekStreamingPlayback !== 'function') return;
  const seek = seekStreamingPlayback(next);
  if (typeof observeStreamingFacadeCallback === 'function') {
    observeStreamingFacadeCallback(seek, 'seek-control-error');
  } else if (seek && typeof seek.catch === 'function') {
    void seek.catch(() => {});
  }
  if (shouldResumeSegment) void resumeListenSessionPlayback(state.player.current, next);
  updatePlayerUi();
}

function isTextEntryElement(element) {
  if (!(element instanceof HTMLElement)) return false;
  const tagName = String(element.tagName || '').toUpperCase();
  if (tagName === 'TEXTAREA') return true;
  if (element.isContentEditable) return true;
  if (tagName !== 'INPUT') return false;
  const type = String(element.getAttribute('type') || element.type || '').toLowerCase();
  return !['button', 'checkbox', 'color', 'file', 'hidden', 'radio', 'range', 'reset', 'submit'].includes(type);
}

function focusPlayerTimeline() {
  const els = getPlayerElements();
  const timeline = els.timeline;
  const playback = getPlayerPlaybackSnapshot();
  if (!(timeline instanceof HTMLElement) || timeline.disabled || !(playback.src || state.player.current?.src)) return;
  timeline.focus({ preventScroll: true });
}

function handlePlayerTimelineKeydown(event) {
  if (!event || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
  if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
  const playback = getPlayerPlaybackSnapshot();
  if (!(playback.src || state.player.current?.src)) return;
  const direction = event.key === 'ArrowLeft' ? -1 : 1;
  const stepSeconds = event.shiftKey ? 5 : 1;
  event.preventDefault();
  event.stopPropagation?.();
  setPlayerPlaybackHead((Number(playback.currentTime) || 0) + (direction * stepSeconds));
}

function handlePlayerKeyboardSeek(event) {
  if (!event || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
  if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
  const target = event.target instanceof HTMLElement ? event.target : null;
  if (isTextEntryElement(target)) return;
  const insidePlayer = target?.closest?.('.global-player');
  if (!insidePlayer) return;
  handlePlayerTimelineKeydown(event);
  focusPlayerTimeline();
}

function isPlayerSurfaceVisible() {
  const player = getPlayerElements().player;
  if (!(player instanceof HTMLElement) || player.hidden) return false;
  const style = getComputedStyle(player);
  const bounds = player.getBoundingClientRect();
  const opacity = Number.parseFloat(style.opacity);
  return style.display !== 'none'
    && style.visibility !== 'hidden'
    && style.visibility !== 'collapse'
    && (!Number.isFinite(opacity) || opacity > 0)
    && bounds.width > 0
    && bounds.height > 0;
}

function togglePlayerPlayback(options = {}) {
  const focusTimelineOnResume = options.focusTimelineOnResume !== false;
  const playback = getPlayerPlaybackSnapshot();
  if (!(playback.src || state.player.current?.src)) return false;
  if (typeof resumeStreamingPlayback !== 'function'
      || typeof pauseStreamingPlayback !== 'function') return false;
  if (playback.paused) {
    if (typeof canStartPlaybackInThisTab === 'function' && !canStartPlaybackInThisTab(state.player.current)) {
      return false;
    }
    const restart = playback.ended && typeof seekStreamingPlayback === 'function'
      ? seekStreamingPlayback(0)
      : null;
    Promise.resolve(restart).then(() => resumeStreamingPlayback()).then((resumed) => {
      if (resumed === false) return;
      beginStreamingPlayerListenSession(
        state.player.current,
        playback.ended ? 0 : (Number(playback.currentTime) || 0),
      );
      updatePlayerUi();
      if (focusTimelineOnResume) focusPlayerTimeline();
    }).catch(() => {});
  } else {
    pausePlayerPlaybackForHandoff(playback);
  }
  return true;
}

function pausePlayerPlaybackForHandoff(playback = getPlayerPlaybackSnapshot()) {
  if (pendingPlayerPlaybackHandoff) return pendingPlayerPlaybackHandoff;
  if (playback.paused || typeof pauseStreamingPlayback !== 'function') return Promise.resolve(false);
  const pauseEffects = Promise.resolve(pauseStreamingPlayback()).then(() => {
    closeListenSegment();
    markListenSessionPaused(Number(playback.currentTime) || 0);
    if (typeof maybeScrobbleListenSession === 'function') {
      void maybeScrobbleListenSession(state.player.listenSession);
    }
    if (typeof releasePlaybackOwnership === 'function') {
      releasePlaybackOwnership('paused', state.player.current);
    }
    updatePlayerUi();
    return true;
  });
  const trackedPause = pauseEffects.finally(() => {
    if (pendingPlayerPlaybackHandoff === trackedPause) pendingPlayerPlaybackHandoff = null;
  });
  pendingPlayerPlaybackHandoff = trackedPause;
  if (typeof observeStreamingFacadeCallback === 'function') {
    observeStreamingFacadeCallback(trackedPause, 'pause-control-error');
  } else {
    void trackedPause.catch(() => {});
  }
  return trackedPause;
}

function handlePlayerKeyboardPlayback(event) {
  if (
    !event
    || event.defaultPrevented
    || event.isComposing
    || event.repeat
    || event.altKey
    || event.ctrlKey
    || event.metaKey
    || event.shiftKey
  ) return false;
  if (event.key !== ' ' && event.key !== 'Spacebar' && event.code !== 'Space') return false;
  const target = event.target instanceof HTMLElement ? event.target : null;
  if (isTextEntryElement(target)) return false;
  if (
    typeof handleUtilityLoopSpacePlayback === 'function'
    && handleUtilityLoopSpacePlayback(event)
  ) {
    event.preventDefault();
    event.stopPropagation?.();
    return true;
  }
  const playback = getPlayerPlaybackSnapshot();
  if (!(playback.src || state.player.current?.src)) return false;
  if (!isPlayerSurfaceVisible()) return false;
  if (!togglePlayerPlayback({ focusTimelineOnResume: false })) return false;
  event.preventDefault();
  event.stopPropagation?.();
  return true;
}

async function saveCurrentLoop() {
  if (state.player.saveBusy) return;
  const current = state.player.current;
  if (!current || !state.player.loopActive) return;
  state.player.saveBusy = true;
  try {
    const name = String(await showLoopNameDialog() || '').trim();
    if (!name) return;
    const response = await fetch('/loops/create', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name,
        source_path: current.path,
        start_seconds: state.player.loopStart,
        end_seconds: state.player.loopEnd,
        artist: current.artist || '',
        title: current.title || '',
        album: current.album || '',
        cover_path: current.coverPath || '',
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) {
      throw new Error(data.error || 'Failed to save loop');
    }
    state.utility.loops = Array.isArray(data.loops) ? data.loops : [data.loop, ...(state.utility.loops || [])].filter(Boolean);
    state.utility.loopsLoaded = true;
    state.utility.selectedLoopId = String(data.loop?.id || state.utility.selectedLoopId || '');
    state.utility.selectedLoopGroupKey = data.loop ? buildUtilityLoopGroupKey(data.loop) : state.utility.selectedLoopGroupKey;
    state.utility.selectedLoopDetailMode = 'group';
    setLoopActive(false);
    showToast('Loop saved.', 'success', 2600);
    if (state.utility.activeTab === 'loops') renderUtilityModalContent();
  } catch (error) {
    console.error('[AlbumHaven][Loops] Failed to save loop.', error);
    showToast(error.message || 'Failed to save loop.', 'error', 4200);
  } finally {
    state.player.saveBusy = false;
    updatePlayerUi();
  }
}

function handlePlayerLoopEditKeydown(event) {
  if (!event || !state.player.loopActive) return false;
  if (event.key === 'Escape') {
    setLoopActive(false);
    return true;
  }
  if (
    event.key !== 'Enter'
    || event.defaultPrevented
    || event.isComposing
    || event.repeat
    || event.altKey
    || event.ctrlKey
    || event.metaKey
    || event.shiftKey
  ) return false;
  const target = event.target instanceof HTMLElement ? event.target : null;
  if (isTextEntryElement(target) || target?.closest?.('[role="dialog"], dialog, [aria-modal="true"]')) {
    return false;
  }
  event.preventDefault();
  event.stopPropagation?.();
  void saveCurrentLoop();
  return true;
}

function attachSharedPlayer() {
  document.querySelectorAll('.play-track-button').forEach((btn) => {
    if (btn.dataset.bound === '1') return;
    btn.dataset.bound = '1';
    btn.addEventListener('click', () => {
      const src = btn.getAttribute('data-src');
      if (!src) return;
      const trackPath = btn.getAttribute('data-track-path') || decodeURIComponent((src.split('path=')[1] || '').split('&')[0] || '');
      const isCurrentTrack = String(state.player.current?.path || '') === String(trackPath || '');
      const playback = getPlayerPlaybackSnapshot();
      const isLoadedCurrentTrack = isCurrentTrack && String(playback.src || '') === String(src);
      if (isLoadedCurrentTrack) {
        togglePlayerPlayback();
        updatePlayerUi();
        return;
      }
      const currentAlbum = !document.getElementById('track-modal')?.hidden
        ? state.modalReleases[state.modalReleaseIndex] || null
        : null;
      const playbackStart = playTrackFromPayload({
        src,
        path: trackPath,
        title: btn.getAttribute('data-track-title') || 'Track',
        artist: btn.getAttribute('data-track-artist') || '',
        albumArtist: btn.getAttribute('data-track-album-artist') || '',
        album: btn.getAttribute('data-track-album') || '',
        coverPath: btn.getAttribute('data-track-cover') || '',
        durationSeconds: Number(btn.getAttribute('data-track-duration-seconds')) || 0,
      });
      if (currentAlbum) {
        setAlbumPlaybackQueue(currentAlbum, trackPath);
      } else {
        state.player.playbackQueue = null;
      }
      if (typeof observeStreamingFacadeCallback === 'function') {
        observeStreamingFacadeCallback(playbackStart, 'track-selection-start-error');
      } else {
        void playbackStart.catch((error) => {
          console.warn('[AlbumHaven][Playback] Track selection failed.', error);
        });
      }
      focusPlayerTimeline();
    });
  });
}

function claimGlobalPlayerSpaceOwnership() {
  if (typeof clearUtilityLoopSpaceOwner === 'function') {
    clearUtilityLoopSpaceOwner();
  }
}

function attachPlayerEvents() {
  const els = getPlayerElements();

  if (typeof mountGlobalPlayerLoopControls === 'function') mountGlobalPlayerLoopControls();

  els.player?.addEventListener('pointerdown', claimGlobalPlayerSpaceOwnership);
  els.player?.addEventListener('focusin', claimGlobalPlayerSpaceOwnership);
  els.play?.addEventListener('click', () => togglePlayerPlayback());
  els.albumLink?.addEventListener('click', () => {
    const album = resolveAlbumForPlayerTrack(state.player.current);
    if (album) openTrackModal(album);
  });
  els.coverButton?.addEventListener('click', () => {
    const album = resolveAlbumForPlayerTrack(state.player.current);
    if (album) openTrackModal(album, { coverLightboxGallery: false });
  });
  els.timeline?.addEventListener('keydown', handlePlayerTimelineKeydown);
  els.timeline?.addEventListener('input', () => {
    const next = Number(els.timeline.value) || 0;
    if (state.player.timelineDragging) return;
    setPlayerPlaybackHead(next);
  });
  els.timeline?.parentElement?.addEventListener('pointerdown', (event) => {
    if (state.player.loopActive || event.target?.closest('.player-loop-handle')) return;
    if (!state.player.current) return;
    const next = getTimelineSecondsFromClientX(event.clientX);
    event.preventDefault();
    state.player.timelineDragging = true;
    state.player.timelineDragPreviewSeconds = next;
    if (els.timeline) els.timeline.value = String(next);
  });
  document.addEventListener('pointermove', (event) => {
    if (!state.player.timelineDragging) return;
    const next = getTimelineSecondsFromClientX(event.clientX);
    state.player.timelineDragPreviewSeconds = next;
    if (els.timeline) els.timeline.value = String(next);
  });
  document.addEventListener('pointerup', () => {
    if (state.player.timelineDragging) {
      const next = Number(state.player.timelineDragPreviewSeconds);
      if (Number.isFinite(next)) setPlayerPlaybackHead(next);
    }
    state.player.timelineDragging = false;
    state.player.timelineDragPreviewSeconds = null;
  });
  document.addEventListener('keydown', handlePlayerKeyboardSeek);
  document.addEventListener('keydown', handlePlayerKeyboardPlayback, { capture: true });
  els.loopStartInput?.addEventListener('change', () => {
    const value = parseLoopTime(els.loopStartInput.value);
    if (Number.isFinite(value)) setLoopBoundary('start', value);
    else updateLoopInputsFromState();
  });
  els.loopEndInput?.addEventListener('change', () => {
    const value = parseLoopTime(els.loopEndInput.value);
    if (Number.isFinite(value)) setLoopBoundary('end', value);
    else updateLoopInputsFromState();
  });
  document.addEventListener('keydown', handlePlayerLoopEditKeydown);
  window.addEventListener('resize', () => {
    updateWaveformAppearance();
  });
  if (!state.player.current) {
    setCurrentPlayerTrack(null, { persist: false });
  }
  updatePlayerUi();
  restorePlayerState();
}

// END js/runtime/player-loop-playback.js

// BEGIN js/runtime/track-modal-and-gallery.js

﻿function attachCoverLookupModalEvents() {
  const els = getCoverLookupModalElements();
  if (!els.overlay || els.overlay.dataset.bound === '1') return;
  els.overlay.dataset.bound = '1';
  bindOverlayPointerOrigin(els.overlay);
  els.overlay.addEventListener('click', (event) => {
    if (overlayClickStartedOnOverlay(els.overlay, event)) {
      closeCoverLookupModal();
    }
  });
}

function attachCoverLookupDeleteConfirmEvents() {
  const els = getCoverLookupDeleteConfirmElements();
  if (!els.overlay || els.overlay.dataset.bound === '1') return;
  els.overlay.dataset.bound = '1';
  bindOverlayPointerOrigin(els.overlay);
  els.overlay.addEventListener('click', (event) => {
    if (overlayClickStartedOnOverlay(els.overlay, event) || event.target.closest('[data-close-cover-lookup-delete-confirm="1"]')) {
      closeCoverLookupDeleteConfirm();
    }
  });
}

function attachUtilityModalEvents() {
  const els = getUtilityModalElements();
  if (!els.overlay || els.overlay.dataset.bound === '1') return;
  els.overlay.dataset.bound = '1';
  bindOverlayPointerOrigin(els.overlay);
  els.close?.addEventListener('click', closeUtilityModal);
  els.search?.addEventListener('input', () => {
    if (state.utility.activeTab !== 'problematic-files') return;
    state.utility.searchQuery = els.search.value || '';
    renderUtilityModalContent();
  });
  els.search?.addEventListener('search', () => {
    if (state.utility.activeTab !== 'problematic-files') return;
    state.utility.searchQuery = els.search.value || '';
    renderUtilityModalContent();
  });
  els.overlay.addEventListener('click', (event) => {
    if (overlayClickStartedOnOverlay(els.overlay, event) || event.target.closest('[data-close-utility-modal="1"]')) {
      closeUtilityModal();
    }
  });
}

function attachRepairConfirmEvents() {
  const els = getRepairConfirmElements();
  if (!els.overlay || els.overlay.dataset.bound === '1') return;
  els.overlay.dataset.bound = '1';
  bindOverlayPointerOrigin(els.overlay);
  els.overlay.addEventListener('click', (event) => {
    if (overlayClickStartedOnOverlay(els.overlay, event) || event.target.closest('[data-close-repair-confirm="1"]')) {
      closeRepairConfirmModal();
    }
  });
}

